INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e6728afe4931', 'en', 'US', 'Beef & Lentil Soup with vegetables', 'Recipe video above. Here''s a different way to use beef mince - a hearty Beef & Lentil Soup loaded with vegetables! Flavoured with spices and low on effort thanks to the ground beef, lentil soups can be so boring - but not this one. :)Healthy, hearty, economical - it''s a complete dinner made in one pot. 100% perfect for freezing, use any veg you want and switch up the spicing to your taste!', 'https://www.recipetineats.com/tachyon/2020/11/Beef-and-Lentil-Soup_9.jpg', 10, 30, 40, 6, '[{"id": "ing_moroccan_spice_mix", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_lentils", "quantity": {"value": 0.469, "unit": "can of 400g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 100.0, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}]', '[{"ingredients":["2 1/2 tbsp Moroccan spice mix (store-bought)","1 tsp allspice (mixed spice will work too)","2 tsp cumin powder","2 tsp paprika","3/4 tsp black pepper","1/2 tsp salt (Note 2)"],"purpose":"My Moroccan Spice Mix (or change it up! Note 1):"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely chopped)","1 onion (, finely chopped (brown, white, or yellow))","500g / 1lb beef mince (ground beef) (I use lean)","1 1/4 cups dried lentils (or 2 cans, drained, Note 3)","2 carrots (*, cut into 1cm / 1/3” dice)","2 celery stalks (*, chopped into 1cm / 1/3”pieces)","2 zucchinis (*(small, or 1 large), cut into 1cm / 1/3” dice)","100g / 4 oz green beans (*, trimmed, cut into 1.5cm / 1/2” pieces)","800g / 28 oz crushed canned tomato","4 cups / 1 litre beef stock (, low sodium (Note 4))","3 cups water"],"purpose":"Soup:"},{"ingredients":["Yogurt (plain or Greek)","1/4 cup Coriander/cilantro leaves, or sliced green onions"],"purpose":"Serving:"}]', '[{"description":"Mix spices in a small bowl.","images":[],"step":1},{"title":"Saute onion & garlic","description":"Heat oil in a large pot over medium high heat. Cook onion and garlic for 3 minutes until golden on the edges.","duration":3,"images":[],"step":2},{"title":"Brown & spice beef","description":"Turn heat up to high, add beef and cook until it''s no longer red, breaking it up as you go. Add 2 tablespoons of the Spice Mix and cook it for a further 2 minutes - it will smell so good!","images":[],"step":3},{"title":"Carrot & celery","description":"Add carrot and celery, then stir for 1 minute. (If using your own veg mix, add the veg in this step that will hold up to full 25 min simmer time)","duration":1,"images":[],"step":4},{"title":"Make broth","description":"Add water, beef stock, canned tomato, lentils and remaining Spice Mix too. Give it a stir, bring to simmer, then place lid on and reduce to medium low so it''s simmering gently. Lentils will take 25 - 30 minutes to cook until soft. Very old lentils can take 5 - 10 minutes longer.","images":[],"step":5},{"description":"Simmer 15 minutes then add zucchini & green beans.","images":[],"step":6},{"description":"Simmer 10 minutes longer or until lentils are soft (ie. 25 minutes total).","images":[],"step":7},{"description":"Serve! Taste and add more salt if desired. Ladle into bowls and serve with yogurt and coriander.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Any flavour you want!","Western"],"categories":["beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","one-pot-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3a0f4afca90a', 'en', 'US', 'One Pot Pasta Bolognese', 'Recipe video above. For One-Pot-Pasta Cynics (and Italian cooking pursists), there''s a special message for you at the top of the post! :)This recipe is everything you love about Spaghetti Bolognese - the rich, thick tomato sauce, full flavoured (never bland!), made from scratch WITH the pasta in one pot! Excellent big batch cooking, keeps well. Tomato passata (aka tomato puree) is the key here for an instant thick, rich sauce rather than cooking down crushed tomato.Pasta types - long, short or tiny, but read recipe note 4 for adjustments.', 'https://www.recipetineats.com/tachyon/2020/09/One-Pot-Pasta-Bolognese_6.jpg', 10, 20, 30, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","500g / 1 lb beef mince (ground beef) (, I use lean)","700g / 24.5 oz tomato passata (tomato puree) (Note 1)","3 cups beef broth (or stock cubes + water, Note 2)","2 tsp Italian mixed herbs (options, see Note 3)","1/4 - 1/2 tsp chilli flakes (red pepper flakes) (, adjust to taste)","2 tsp Worcestershire Sauce","2 tbsp tomato paste","3/4 tsp each salt and pepper","350g / 12 oz spaghetti (, uncooked (other pasta - Note 4))"]},{"ingredients":["Parmesan"],"purpose":"For serving"}]', '[{"title":"Saute onion & garlic","description":"Heat oil in a large pot over high heat. Cook garlic and onion for 2 minutes until translucent.","duration":2,"images":[],"step":1},{"title":"Cook beef","description":"Add beef and cook, breaking it up as you go.","images":[],"step":2},{"title":"Add tomato","description":"Once beef has all changed from red to brown, add tomato passata.","images":[],"step":3},{"title":"Rinse out bottle","description":"Pour some beef stock into the empty bottle, shake, then pour into the pot.","images":[],"step":4},{"title":"Add everything else","description":"Add remaining beef stock and all remaining ingredients except spaghetti. Give it a good stir, then let it come up to the boil.","images":[],"step":5},{"title":"Add spaghetti","description":"Add pasta, fanning it out around the pot. Leave for 30 seconds to start softening, then start pushing it in under the liquid.","duration":0.5,"images":[],"step":6},{"title":"Cook pasta","description":"Once fully submerged, cook for 12 minutes, stirring every minute or so, and more towards the end. At about the 8 minute mark, lower the heat to medium otherwise the base might catch (but ensure it is still bubbling gently - you don''t want pasta just bloating in warm water).","duration":12,"images":[],"step":7},{"title":"Remove from stove, toss well","description":"Take it off the stove once the pasta is JUST cooked, the tiniest bit firmer than you want, and when still saucy. Toss it for about 30 seconds or so - the sauce will reduce further, the pasta will finish cooking.","images":[],"step":8},{"description":"Serve immediately, garnished with parmesan.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["beef-mince-recipes","beef-recipes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e42c79327ae1', 'en', 'US', 'Meatloaf recipe', 'Recipe video above. Meatloaf is so much more than a giant hunk of ground beef in a loaf shape. It should ooze with flavour, be moist and tender yet not crumble apart when sliced. And the caramelised glaze is the crowning glory!', 'https://www.recipetineats.com/tachyon/2019/10/Meatloaf_3a.jpg', 15, 75, 90, 8, '[{"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["1 cup panko breadcrumbs (Note 1)","1 large onion (, grated (brown, yellow))","1 kg / 2 lb ground beef (mince) (, preferably not lean)","2 eggs","3 garlic cloves (, minced)","1 tsp Worcestershire Sauce","1/4 cup tomato ketchup","1/4 cup chopped parsley ((optional), or 2 tsp dried parsley or basil)","1 tsp dried thyme","2 beef bouillon cubes (, crumbled or 2 tsp beef powder (Note 2))","1 tsp black pepper"]},{"ingredients":["1/2 cup tomato ketchup","2 tbsp cider vinegar","1 tbsp brown sugar (, lightly packed)"],"purpose":"Meatloaf Glaze:"}]', '[{"description":"Preheat oven to 180C/350F. Oil or spray a loaf tin. (Note 3)","images":[],"step":1},{"title":"Glaze","description":"Mix together in a small bowl. Set aside.","images":[],"step":2},{"title":"Meatloaf","description":"Place breadcrumbs in a very large bowl. Grate over onion. Mix so the breadcrumbs are all wet. (Note 4)","images":[],"step":3},{"description":"Add remaining ingredients. Mix well using your hands. Form into a loaf shape, pinching together then smoothing over creases and cracks (helps prevent cracks during baking).","images":[],"step":4},{"description":"Transfer into loaf tin. Brush generously with glaze, using about 1/2.","images":[],"step":5},{"description":"Bake for 45 minutes. Remove from oven and brush with most of the remaining glaze. If there is excess fat pooling, scoop/pour it off.","duration":45,"images":[],"step":6},{"description":"Bake for a further 30 minutes. Remove from oven.","images":[],"step":7},{"description":"Stand for 10 minutes before turning out and cutting into thick slices. You will probably get a bit of crumbling just on the edges of the first couple of slices, this is normal and indicative of the tenderness of the meatloaf (zero crumble indicates firm packed harder meatloaf which isn''t as enjoyable!).","duration":10,"images":[],"step":8},{"description":"Ideal served with a dollop of ketchup, creamy mashed potatoes and steamed vegetables.","images":[],"step":9}]', '["egg"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","beef-recipes","main-dishes","nagis-picks","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b632459db6e4', 'en', 'US', 'Cottage Pie', 'Recipe video above. One of the greatest comfort foods of all time! A ground beef (mince) filling in a tasty gravy, topped with mashed potato. Make it a Shepherd''s Pie simply by swapping the beef for lamb.', 'https://www.recipetineats.com/tachyon/2016/10/Cottage-Pie_5.jpg', 15, 75, 90, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 1.2, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 carrot (, finely chopped*)","1 celery (, finely chopped*)","750g / 1.5 lb beef mince (ground beef)","1/4 cup (40g) flour (plain / all purpose)","1/4 cup (55g) tomato paste","2 cups (500 ml) beef stock / broth (, low sodium)","1/2 cup (125 ml) red wine (or water)","1 beef bouillon cube (, crumbled (stock cube, or 1 tsp stock powder))","2 tbsp Worcestershire sauce","1 tsp dried thyme (or 3 sprigs fresh thyme)","2 dried bay leaves","3/4 tsp salt","1/2 tsp black pepper"]},{"ingredients":["1.2 kg / 2.5 lb potatoes (, peeled and cut into 2.5cm / 1\" cubes)","2/3 cup (165 ml) milk (, warmed)","2 tbsp (30g) butter"],"purpose":"Topping"},{"ingredients":["2 tbsp (30g) butter","2 tbsp (20g) parmesan, grated"],"purpose":"Parmesan Crust (optional)"}]', '[{"description":"Heat oil in a large skillet over medium high heat. Add onion and garlic, cook for 1 minute. Then add carrots and celery. Cook for 3 minutes or until softened and sweet.","duration":1,"images":[],"step":1},{"description":"Turn heat up to high. Add beef and cook, breaking it up as you go, until browned.","images":[],"step":2},{"description":"Add flour and mix in. Add tomato paste, broth, red wine, bouillon cube, Worcestershire sauce, thyme, bay leaves, salt and pepper.","images":[],"step":3},{"description":"Bring to simmer, then turn down heat so it is simmering rapidly - I have it on medium high. Cook for 30 minutes, stirring occasionally, until it reduces down to a gravy consistency (Note 1) (see video). Taste then add more salt if desired.","duration":30,"images":[],"step":4},{"description":"Transfer to 6 cup pie dish (1.5 litre / quart). Cover, cool if you have time (even overnight). Cool filling = easier to top with mash (Note 2)","images":[],"step":5},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":6},{"description":"Cook potatoes in boiling water for 15 minutes or until soft. Drain then return to pot on turned off stove. Shake briefly and allow to steam dry for 30 seconds or so (Note 3).","duration":15,"images":[],"step":7},{"description":"Add butter and mash until melted, then add milk and salt. Mash until smooth.","images":[],"step":8},{"description":"Spread onto pie, use a fork to rough up the surface (rougher surface = more golden bits). Sprinkle with paremsan, drizzle with butter (or skip this and just drizzle with olive oil)","images":[],"step":9},{"title":"Bake for 25","description":"30 minutes or until golden on top and bubbling on the edges. Stick a knife into the middle to ensure it is piping hot.","duration":27.5,"images":[],"step":10},{"description":"Stand for 5 minutes before serving, garnished with fresh thyme leaves if desired.","duration":5,"images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["English","South Western"],"categories":["beef-mince-recipes","beef-recipes","lamb-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a1a938a59fa0', 'en', 'US', 'Swedish Meatballs (homemade Ikea Meatballs)', 'Recipe video above. Juicy meatballs smothered in a beautiful creamy gravy, with a hint of spicing that Swedish Meatballs are known for. Made extra soft and extra tasty by soaking fresh bread in grated onion - tried and tested technique used in my most of my meatball recipes, highly approved by readers! (See Italian Meatball reviews as an example)', 'https://www.recipetineats.com/tachyon/2017/01/Swedish-Meatballs_8.jpg', 20, 30, 50, 5, '[{"id": "ing_bread", "quantity": {"value": 0.1, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 300.0, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 slices white sandwich bread (, crusts removed, chopped into small cubes (Note 1))","1 onion (, small (brown, white or yellow))","300g / 10 oz ground beef (mince)","300g / 10 oz ground pork (mince) (, or sub with more beef (Note 2))","1 egg","1/4 tsp ground nutmeg (, preferably freshly grated)","1/4 tsp All Spice powder (Note 3)","1/4 tsp black pepper","3/4 tsp salt","1 tbsp oil"],"purpose":"Meatballs"},{"ingredients":["40g / 3 tbsp butter (, unsalted)","3 tbsp flour","2 cups beef broth/stock ((salt reduced), or sub with chicken)","1/2 cup heavy / thickened cream (Note 4)"],"purpose":"Gravy"}]', '[{"description":"Grate onion using a standard box grater (see video).","images":[],"step":1},{"description":"Scrape onion and juices into bowl. Add bread and mix well - onion juice should make bread soggy (if not, add a tiny splash of milk). Set aside to soak for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add remaining Meatball ingredients EXCEPT oil. Mix well.","images":[],"step":3},{"description":"Using a tablespoon measure and measure out a heaped tablespoon (or use ice cream scooper which is what I do), dollop on work surface. Repeat with remaining mixture: 25 - 30 meatballs. Then roll into shape.","images":[],"step":4},{"description":"Cooking","images":[],"step":5},{"description":"Heat 1 tbsp oil in a skillet over medium high heat. Add half the meatballs and brown all over (but raw inside still) - about 3 minutes. Remove onto plate, then brown the remaining batch.","images":[],"step":6},{"description":"If there is lots of oil, pour off excess and discard. Lower heat to medium.","images":[],"step":7},{"description":"Add butter into skillet and melt. Add flour and stir in. Cook for 1 minute.","duration":1,"images":[],"step":8},{"title":"While mixing, add about 1/4 of the beef broth","description":"it will thicken quickly. Then gradually add remaining beef broth, stirring as you go. Switch to whisk if required to make it lump free.","images":[],"step":9},{"description":"When the liquid is simmering, add meatball and juices pooled on plate.","images":[],"step":10},{"description":"Turn up heat slightly to keep it at a rapid simmer. Cook for 8 - 10 minutes or until the liquid thickens into a thin gravy, stirring occasionally.","duration":9,"images":[],"step":11},{"description":"Add cream, simmer for a further 2 minutes then remove from stove.","images":[],"step":12},{"description":"Serve over mashed potato (or Cauliflower Mash for low carb). For a truly authentic experience, add a dollop of ligonberry jam on the side!","images":[],"step":13}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["swedish"],"categories":["beef-mince-recipes","beef-recipes","meatball-recipes","mediterranean-recipes","pork-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c23684436d63', 'en', 'US', 'Baked Ziti', 'Recipe video above. A big, juicy pasta bake! It’s meaty, cheesy, and loaded with flavour from a healthy dose of seasonings. This great American classic may well be the mother of all pasta bakes....', 'https://www.recipetineats.com/tachyon/2018/10/Baked-Ziti_0.jpg', 10, 60, 70, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_ricotta", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}]', '[{"ingredients":["300g / 10oz ziti or penne pasta ( (Note 1))","1 tbsp olive oil","3 garlic cloves (, minced)","1 small onion ((brown, white or yellow), finely chopped)","500g / 1 lb ground beef or pork (OR 50/50 combo (Note 2))","700g / 24 oz tomato passata (pureed tomato, Note 3)","1/2 cup water","1 tsp EACH dried basil, oregano, sugar","1 cup ricotta (, optional (Note 4))","1 cup grated mozzarella cheese (or other melting cheese)","1 cup parmesan (, freshly grated (optional))","Finely chopped parsley or basil (optional garnish)"]},{"ingredients":["2 tsp fennel seeds (optional, Note 5)","1 tbsp paprika (plain or sweet)","1/4 tsp cayenne pepper OR 3/4 tsp chilli flakes (adjust to taste)","2 tsp onion powder","1 tsp EACH salt and black pepper"],"purpose":"Seasonings:"}]', '[{"description":"Cook ziti for the recommended cooking time on the packet MINUS 2 minutes. (Note 5) Drain, then return to pot.","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"title":"Make Sauce","description":"Heat oil in a large skillet over high heat. Add onion and garlic and cook for 2 minutes or until onion is translucent.","duration":2,"images":[],"step":3},{"description":"Add meat and cook, breaking it up as you go. When it is just cooked, add Seasonings and cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add passata, water, basil, oregano and sugar. Bring to simmer, reduce heat to low and cook for 10 minutes. Adjust salt and pepper to taste (remember it gets spread across lots of pasta).","duration":10,"images":[],"step":5},{"title":"Toss Ziti with Sauce","description":"Pour about 2 cups of sauce into the pot with the ziti. Toss.","images":[],"step":6},{"title":"Assemble","description":"Spread ziti into baking dish (23x33cm / 9x13\"). Dollop with ricotta. Pour over remaining sauce. Top with cheese and parmesan.","images":[],"step":7},{"title":"Bake","description":"Cover loosely with foil. Bake 20 minutes. Remove foil, bake further 10 to 15 minutes until cheese is golden.","images":[],"step":8},{"title":"Serve","description":"Sprinkle with parsley or basil if desired, then serve!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","italian-recipes","main-dishes","most-popular","pasta-bakes","pasta-recipes","pork-recipes","quick-and-easy","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_52381cf58f4e', 'en', 'US', 'Spaghetti Bolognese', 'Recipe video above. My everyday Bolognese recipe I make over and over again. This Meat Sauce has terrific depth of flavour for such a quick recipe - though if you have the time, it''s stellar cooked slowly for a couple of hours. My 3 "secret" tips are: Worcestershire Sauce, Beef Bouillon Cubes and a touch of sugar.', 'https://www.recipetineats.com/tachyon/2018/07/Spaghetti-Bolognese.jpg', 10, 30, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped (brown, yellow or white))","1 lb / 500g beef mince (ground beef) (OR half pork, half beef (Note 1))","1/2 cup (125 ml) dry red wine (sub water or beef broth/stock)","2 beef bouillon cubes (, crumbled OR granulated beef bouillon (Note 2))","800g / 28 oz can crushed tomato (or tomato passata)","2 tbsp tomato paste","2 tsp white sugar (, if needed (Note 3))","2 tsp Worcestershire sauce","2 dried bay leaves","2 sprigs fresh thyme (or 1/2 tsp dried thyme or oregano)","3/4 tsp cooking salt (kosher salt)","1/2 tsp black pepper"]},{"ingredients":["400 g / 13 oz spaghetti (, dried)","Parmesan cheese (and finely chopped parsley (optional))"],"purpose":"To Serve"}]', '[{"title":"Sauté","description":"Heat oil in a large pot or deep skillet over medium high heat. Add onion and garlic, cook for 3 minutes or until light golden and softened.","duration":3,"images":[],"step":1},{"title":"Cook beef","description":"Turn heat up to high and add beef. Cook, breaking it up as your go, until browned.","images":[],"step":2},{"title":"Reduce wine","description":"Add red wine. Bring to simmer and cook for 1 minute, scraping the bottom of the pot, until the alcohol smell is gone.","duration":1,"images":[],"step":3},{"title":"Simmer","description":"Add the remaining ingredients. Stir, bring to a simmer then turn down to medium so it bubbles gently. Cook for 20 - 30 minutes (no lid), adding water if the sauce gets too thick for your taste. Stir occasionally.","duration":25,"images":[],"step":4},{"title":"Slow simmer option","description":"really takes this to another level, if you have the time! Add 3/4 cup of water, cover with lid and simmer on very low for 2 - 2.5 hours, stirring every 30 minutes or so. (Note 5) Uncover, simmer 20 minutes to thicken sauce. (Note 6 for slow cooker)","images":[],"step":5},{"description":"Taste and add more salt it desired. Serve over spaghetti - though if you have the time, I recommend tossing the sauce and pasta per steps below.","images":[],"step":6},{"description":"Tossing Sauce and Spaghetti (optional, Note 4)","images":[],"step":7},{"description":"Bring a large pot of salted water to boil. Add pasta and cook per packet directions MINUS 1 minute.","images":[],"step":8},{"description":"Scoop out a mug of pasta cooking water and set aside, then drain the pasta.","images":[],"step":9},{"description":"Add pasta into the bolognese sauce with about 1/2 cup (125 ml) of reserved pasta water over medium heat. Toss gently for 1 1/2 - 2 minutes, or until the spaghetti turns red and the sauce thickens.","images":[],"step":10},{"description":"Divide between bowls. Garnish with parmesan and parsley if desired.","images":[],"step":11}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fa5b824fb3d6', 'en', 'US', 'Spinach Beef Cannelloni (Manicotti)', 'Recipe video above. You will love how flavourful the juicy beef filling and sauce is! Too many recipes disappoint by using plain canned tomato - the sauce needs flavour! It will seem like there''s a lot of sauce (and there is) and that it''s too thin (and it is!) BUT you need it because the cannelloni sucks up a lot when it''s cooking!!! Serves 4 very hungry people, 5 normal people.', 'https://www.recipetineats.com/tachyon/2019/11/Beef-Cannelloni_8.jpg', 30, 45, 75, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_nelloni_tubes", "quantity": {"value": 21.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","1 carrot (, small, finely chopped (optional))","1 celery rib (, finely chopped (optional))","800g / 28oz crushed tomato (, canned)","2 cups (500ml) chicken stock / broth (, low sodium (or vegetable))","1/2 tsp EACH thyme, oregano, salt, pepper","1/4 tsp chilli flakes (, optional)"],"purpose":"Cannelloni Sauce:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","500g / 1lb beef mince (, lean)","250g / 8oz frozen spinach, chopped (, thawed, excess liquid squeezed out (Note 1))","1 beef bouillon cube (, crumbled (Note 2))","1/2 tsp pepper","1 tsp Worcestershire Sauce"],"purpose":"Spinach Beef Filling:"},{"ingredients":["21 - 24 cannelloni tubes (220g/7oz) (OR 10 Manicotti tubes (Note 3))","2 cups mozzarella cheese (, freshly grated (or other melting cheese))","Chopped parsley (, garnish (optional))"],"purpose":"Cannelloni:"}]', '[{"description":"Cannelloni Sauce:","images":[],"step":1},{"description":"Heat oil in a large saucepan or pot over medium high heat. Add garlic and onion, cook 2 minutes. Add carrot and celery, cook 5 minutes.","images":[],"step":2},{"description":"Add remaining Sauce ingredients then stir. Bring to simmer, lower heat to medium, cover with lid and simmer for 10 minutes.","duration":10,"images":[],"step":3},{"description":"Use a stick blender to blitz until smooth (or cool slightly and use blender or food processor). Set aside.","images":[],"step":4},{"description":"Spinach Beef Filling:","images":[],"step":5},{"description":"Heat oil in a large skillet over high heat. Add onion and garlic, cook 2 minutes.","images":[],"step":6},{"description":"Add beef and cook, breaking it up as you go, until it all changes from red to brown.","images":[],"step":7},{"description":"Stir in spinach, then add crumbled beef cube, Worcestershire sauce, pepper and 1 cup of Cannelloni Sauce. Stir, cook 2 minutes.","images":[],"step":8},{"description":"Remove and cool slightly.","images":[],"step":9},{"description":"Assembly and Baking:","images":[],"step":10},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":11},{"description":"Transfer Beef Filling into a piping bag with a wide nozzle. Stand cannelloni tubes upright in a container, then pipe filling in. (Or do this step with teaspoon/finger/dinner knife!).","images":[],"step":12},{"description":"Spread about 1 1/4 cups Sauce in a 23x33cm / 9x13\" dish. Lay the cannelloni on top, then pour over remaining Sauce.","images":[],"step":13},{"description":"Sprinkle with cheese, loosely cover with foil.","images":[],"step":14},{"description":"Bake 25 minutes, remove foil then bake a further 10 minutes until the cheese is bubbly with some golden spots.","images":[],"step":15},{"description":"Remove from oven, sprinkle with parsley if using then serve!","images":[],"step":16}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","italian-recipes","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a0e55a1c3079', 'en', 'US', 'One Pot Chili Mac and Cheese', 'Recipe video above. A homemade Chili with the addition of macaroni and cheese = Chili Mac ‘n Cheese! This is terrifically moorish and a fabulous one pot meal. Super quick too! The key with this recipe is to turn the stove off as soon as the pasta is just cooked - it will keep cooking in the residual heat. Spice level with 1/2 tsp cayenne pepper = warm hum. Dial up or down as you please!', 'https://www.recipetineats.com/tachyon/2017/10/Chilli-Mac_0.jpg', 10, 15, 25, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.05, "unit": "can of 400g"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 red capsicum / bell pepper (, chopped)","500g / 1 lb ground beef (mince) (, I use lean)","800g / 28 oz crushed canned tomato","420g / 14 oz can red kidney beans (, drained)","2 1/2 cups (625 ml) beef broth (chicken broth also ok)","250g / 8 oz elbow macaroni pasta ((elbow pasta), uncooked)","2 cups (200g) shredded cheese (cheddar, Monterey Jack, tasty cheese)","1/4 cup coriander / cilantro ( finely chopped, for garnish)"]},{"ingredients":["1/2 tsp cayenne pepper ( or pure chilli powder (adjust spiciness to taste) (Note 1))","2 tsp paprika powder","2 tsp cumin powder","1 1/2 tsp onion powder (can sub garlic powder)","1 tsp dried oregano","1/2 tsp black pepper","1 1/4 tsp salt"],"purpose":"Spices (Homemade Chili Powder):"}]', '[{"description":"Heat oil in large pot over high heat. Add garlic and onion, cook for 1 minute. Then add capsicum and cook until onion is translucent.","duration":1,"images":[],"step":1},{"description":"Add beef and cook, breaking it up as you go.","images":[],"step":2},{"description":"Once the beef turns from red to brown, add remaining ingredients except cheese. Stir, bring to simmer, then turn the heat down to medium.","images":[],"step":3},{"description":"Cover and cook for 12 minutes or until the macaroni is al dente, meaning just cooked, still a tiny bit on the firm side. It should be saucy but not tons of liquid (see video).","duration":12,"images":[],"step":4},{"description":"Turn the stove OFF but leave the pot on the stove. Stir through half the cheese – it should be a bit saucy. Adjust salt and pepper to taste. Top with remaining cheese, put the lid back on and leave until the cheese melts - about 2 minutes (sauce will absorb further during this period).","images":[],"step":5},{"description":"Sprinkle with coriander, if desired, and serve immediately.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e28f756a4177', 'en', 'US', 'Mexican Ground Beef Casserole with Rice (Beef mince!)', 'Recipe video above. A big juicy pot of beef and rice loaded with Mexican flavours! The rice is tender and perfectly cooked, and the tomato sauce is generously flavoured with a Mexican Spice mix. A quick dinner made in one pot with not much prep!', 'https://www.recipetineats.com/tachyon/2019/09/Mexican-Ground-Beef-Casserole-with-Rice_0.jpg', 10, 20, 30, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, finely chopped)","3 garlic cloves (, minced)","500g (1 lb) ground beef ((mince), lean)","1/3 cup tomato paste","1 1/4 cup long grain white rice (, uncooked (Note 1))","2.5 cups (625 ml) chicken broth/stock (, low sodium)","400g (14oz) can corn kernels (, drained (Note 2))","400g (14oz) can black beans (, drained (or other beans))","1 capsicum/bell pepper (, diced)","1 cup green onions/shallots","2 cups (200g) cheese (, shredded (anything that melts! Note 3))"]},{"ingredients":["0.5 tsp cayenne pepper (Note 4)","1.5 tbsp dried oregano","3 tsp cumin","3 tsp coriander","3 tsp onion powder","2 tsp paprika","1.5 tsp salt"],"purpose":"MEXICAN SPICES:"}]', '[{"description":"Heat oil in a large pot over high heat. Add garlic and onion, cook 1 1/2 minutes until onion is translucent.","images":[],"step":1},{"description":"Add beef and cook, breaking it up as you go, until you no longer see raw meat (about 2 minutes).","images":[],"step":2},{"description":"Add Mexican Spices and cook for 30 seconds.","duration":0.5,"images":[],"step":3},{"description":"Add capsicum and cook for 1 minute.","duration":1,"images":[],"step":4},{"description":"Add tomato paste and broth, stir to mix in.","images":[],"step":5},{"description":"Add rice, corn and black beans.","images":[],"step":6},{"description":"Stir, bring to simmer then cover and lower heat to medium low (simmering gently). Cook 15 minutes.","images":[],"step":7},{"description":"Remove lid, quickly stir through green onion and HALF the cheese.","images":[],"step":8},{"description":"Smooth top then sprinkle on remaining cheese. Cover and leave for 1 minute just to melt cheese.","duration":1,"images":[],"step":9},{"description":"Remove from stove and serve immediately, garnished with more green onion if desired.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","mexican-recipes","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c1b7bdfa33cd', 'en', 'US', 'Beef Enchiladas', 'Recipe video above. Moreishly delish! These beef enchiladas are made extra tasty with a juicy filling made with beef, refried beans and a homemade Enchilada spice mix. The refried beans are excellent here - fills it out, makes the Filling juicy and adds flavour!', 'https://www.recipetineats.com/tachyon/2016/06/Beef-Enchiladas_main.jpg', 10, 35, 45, 4, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.5, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_refried_beans", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tsp each onion & garlic powder (Note 1)","1 tbsp each cumin powder, paprika and dried oregano","1/2 - 1 tsp cayenne pepper (optional, spiciness)"],"purpose":"Spice Mix"},{"ingredients":["2 tbsp olive oil","3 tbsp flour (, plain/all purpose)","2 cups (500ml) chicken stock / broth (, low sodium)","1 1/2 cups (375 ml) tomato passata OR US 1 can (8 oz) canned tomato sauce (eg Hunts) (Note 2)","1/4 tsp each salt and pepper"],"purpose":"Enchilada Sauce"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped (~1 cup))","1 lb / 500g ground beef (mince)","400g / 14oz refried beans (1 can, I use Old El Paso)","400g / 14oz black beans, drained (1 can, Note 3)"],"purpose":"Beef"},{"ingredients":["8 tortillas (or burrito wraps)","1.5 cups (150g) grated melting cheese, or more (I like Monterey Jack, tasty or cheddar cheese)","Cilantro/coriander leaves (, roughly chopped (optional garnish))"],"purpose":"Enchiladas"}]', '[{"description":"Mix together Spice Mix ingredients. Set aside.","images":[],"step":1},{"description":"Enchilada Sauce","images":[],"step":2},{"description":"Heat oil in a large saucepan over medium heat. Add flour and mix to combine into a paste. Cook for 1 minute, stirring constantly.","duration":1,"images":[],"step":3},{"description":"Add 1/2 cup chicken broth, whisk straight away then it will turn into a thick smooth paste quite quickly.","images":[],"step":4},{"description":"Add remaining chicken broth, passata, salt, pepper and 2 tablespoons of SPICE MIX. Whisk","images":[],"step":5},{"description":"Increase heat slightly to medium high. Cook for 3 to 5 minutes, whisking regularly, until the sauce thickens to the consistency of thick syrup (see video). Remove from stove.","duration":4,"images":[],"step":6},{"description":"Preheat oven to 180C/350F.","images":[],"step":7},{"description":"Heat oil in a skillet over high heat. Add garlic and onion, cook for 2 minutes.","duration":2,"images":[],"step":8},{"description":"Add beef and cook for 2 minutes, breaking it up as you go. Add remaining Spice Mix. Cook for a further 2 minutes or until completely brown.","duration":2,"images":[],"step":9},{"description":"Add refried beans, black beans, about 1/4 cup of Enchilada Sauce + salt & pepper. Mix (Note 4) and cook for 2 minutes then remove from stove (see video).","duration":2,"images":[],"step":10},{"description":"Smear a bit of Sauce on the bottom of a baking dish (stops sliding).","images":[],"step":11},{"description":"Place filling on the lower third of a tortilla. Roll up then place in the baking dish, seam side down. Repeat with remaining Filling & Tortillas.","images":[],"step":12},{"description":"Pour Sauce over the Enchiladas, top with cheese, bake for 10 minutes covered (Note 5) then 10 minutes uncovered. Serve hot!","duration":10,"images":[],"step":13}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","enchiladas","main-dishes","mexican-recipes","most-popular","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1efdb2577c3a', 'en', 'US', 'Mexican Stuffed Peppers', 'Recipe video above. That moment when you cut into these Mexican Stuffed Peppers and the cheesy, flavour loaded juicy beef and rice filling comes oozing out.....THEN you find out it''s only 387 calories for a giant stuffed capsicum?? It''s a little food miracle, right there. 🙌🏼', 'https://www.recipetineats.com/tachyon/2019/08/Mexican-Stuffed-Peppers_3.jpg', 20, 90, 110, 5, '[{"id": "ing_capsicum", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 75.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["5 capsicum / peppers (, large about 12cm/4.5\" tall (Note 1))","1 tbsp olive oil","1 onion (, chopped (brown, white, yellow))","3 garlic cloves (, minced)","350g (12oz) ground beef ((mince), lean)","1/4 cup tomato paste","1 1/4 cups (315 ml) chicken broth/stock (, low sodium)","1/2 cup long or medium grain rice (, uncooked (Note 2))","1 cup corn kernels (Note 3)","1 cup green onions (, finely sliced (or red onion))","1 1/2 cups (150g) mozzarella (, shredded)","1/2 cup (125 ml) water"]},{"ingredients":["1/2 tsp cayenne pepper","1 tbsp dried oregano","2 tsp cumin","2 tsp coriander","1.5 tsp onion powder","3/4 tsp salt"],"purpose":"Mexican Spices:"},{"ingredients":["Guacamole (Note 5 Quick Guac)","Sour Cream","1 tbsp fresh coriander/cilantro (, finely chopped)"],"purpose":"For serving (optional):"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Hollow Peppers:","images":[],"step":2},{"description":"Using a small knife, cut around the top of the capsicum at downwards 45 degree angle. Remove top, empty seeds. If capsicum bottoms aren''t quite level, cut so they''ll sit flat. (Be careful to cut off as little as possible so you don'''' accidentally cut a hole in the bottom.)","images":[],"step":3},{"description":"Place capsicums in a baking dish that will fit them snugly (Note 4)","images":[],"step":4},{"description":"Heat oil in a large skillet over high heat,","images":[],"step":5},{"description":"Add onion and garlic, cook for 2 minutes.","duration":2,"images":[],"step":6},{"description":"Add beef and cook, breaking it up as you go, until it''s all changed from pink to brown.","images":[],"step":7},{"description":"Add Spices, stir through. Then add Tomato paste and cook for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add rice, corn and chicken broth. Stir, bring to simmer, place lid on and lower heat to medium low.","images":[],"step":9},{"title":"Cook for 13","description":"15 minutes until rice is JUST cooked - mixture should be fairly loose still at this stage, not thick and stodgy (see video).","duration":14,"images":[],"step":10},{"description":"Stir in green onion.","images":[],"step":11},{"description":"Spoon half the filling into the prepared capsicums.","images":[],"step":12},{"description":"Top with half the cheese, then fill to top with remaining beef rice.","images":[],"step":13},{"description":"Place capsicum lids back on, pour 1/2 cup water into the pan.","images":[],"step":14},{"description":"Cover tightly with foil, bake 45 minutes.","images":[],"step":15},{"description":"Remove foil and capsicum lids. Top with remaining cheese. Bake further 5 to 10 minutes, just until cheese is melted.","images":[],"step":16},{"title":"Serve with sour cream and Guacamole! Quick Guac","description":"Note 5.","images":[],"step":17}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican","Western"],"categories":["beef-mince-recipes","dietary","low-calorie-recipes","mexican-recipes","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_84fd03d8fe70', 'en', 'US', 'Baked Spaghetti', 'Recipe video above. It''s your favourite Bolognese - in the form of a juicy pasta bake! Do a quick simmer - or go all out and slow cook for a couple of hours for a richer sauce and melt-in-your-mouth beef. **FREEZER BEAUTY!** Can even bake from frozen (see notes).', 'https://www.recipetineats.com/tachyon/2019/07/Baked-Spaghetti_1.jpg', 15, 90, 105, 10, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.25, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}]', '[{"ingredients":["2 tbsp olive oil","3 garlic cloves (, minced)","1 onion (, finely chopped)","1 carrot (, finely diced (optional))","1 stick celery (, finely diced (optional))","750g / 1.5lb ground beef (mince)","3/4 cup (185ml) dry red wine (or sub with water or beef broth/stock)","3 beef bouillon cubes (, crumbled (Note 1))","1.2kg / 2.4 lb crushed tomato (, canned)","1/4 cup tomato paste","1 - 3 tsp white sugar (, if needed (Note 2))","2 tsp Worcestershire sauce","3 dried bay leaves","2 sprigs fresh thyme (or 1/2 tsp dried thyme or oregano)","Salt and pepper"],"purpose":"Bolognese Sauce:"},{"ingredients":["500g/ 1lb spaghetti","8 - 10 slices Swiss cheese ((or other type), enough for a layer)","2 cups (200g) mozzarella cheese, shredded"],"purpose":"Spaghetti Bake:"}]', '[{"description":"Heat oil in a large, heavy based pot over medium high heat.","images":[],"step":1},{"description":"Add garlic and onion, cook 2 minutes.","images":[],"step":2},{"description":"Add celery and carrot, cook 3 minutes.","images":[],"step":3},{"description":"Turn heat up to high, add beef and cook, breaking it up as you go.","images":[],"step":4},{"description":"Once beef is brown, add wine. Simmer rapidly for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Add remaining Sauce ingredients, stir.","images":[],"step":6},{"description":"Bring to simmer, lower heat, cover with lid. Simmer for 45 minutes (minimum) or 1.5 - 2 hours (best!).","duration":45,"images":[],"step":7},{"title":"If liquid evaporates too much, add water","description":"should be saucy (see video/pics). Adjust salt and pepper to taste.","images":[],"step":8},{"description":"Assemble & Bake:","images":[],"step":9},{"description":"Preheat oven to 180C/350F.","images":[],"step":10},{"description":"Cook pasta per packet directions, minus 1 minute.","images":[],"step":11},{"description":"Drain, then return into pot.","images":[],"step":12},{"description":"Add just over half the Sauce, toss.","images":[],"step":13},{"description":"Spread half the pasta in a casserole pan, spread with half remaining Sauce.","images":[],"step":14},{"description":"Top with cheese slices, then remaining pasta, remaining Sauce, finish with mozzarella.","images":[],"step":15},{"description":"Cover loosely with foil (so cheese doesn''t stick), bake 25 minutes.","images":[],"step":16},{"description":"Remove foil (reserve), bake further 10 minutes than remove.","images":[],"step":17},{"title":"Cover loosely with foil, stand 10","description":"15 minutes. Then cut slices with a knife and use a spatula to serve pieces like lasagna!","images":[],"step":18}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","casseroles-and-cosy-bakes","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_34a71665f297', 'en', 'US', 'Moussaka (Greek Eggplant Lasagna)', 'Recipe video above. A traditional recipe for an iconic Greek dish from a wonderful cookbook called The Food And Cooking Of Greece by Sara Nassopoulos. Layers of soft eggplant, rich beef or lamb filling lightly spiced with oregano and cinnamon, topped with a thick layer of bechamel sauce. It looks like a lot of steps but the recipe has a nice flow to it - I''ve popped prompts in the steps. 🙂', 'https://www.recipetineats.com/tachyon/2019/03/Greek-Moussaka_3-re-edited-SQ.jpg', 40, 30, 70, 6, '[{"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_lamb", "quantity": {"value": 0.635, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.635, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.635, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_nutmeg", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.006, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.062, "unit": "loaf"}}]', '[{"ingredients":["1 kg / 2 lb eggplant (aubergines) (, 0.75cm / 0.3\" thick slices)","1 tsp salt","2 - 3 tbsp olive oil"],"purpose":"Eggplant"},{"ingredients":["1 tbsp olive oil","1 onion (, diced (brown, white, yellow))","3 garlic cloves (, minced)","1.4 lb / 700 g ground beef or lamb (mince) (Note 1)","1/2 cup red wine (, dry (optional))","14 oz /400g crushed tomatoes","3 tbsp tomato paste","1 cup beef broth/stock (Note 2)","1 beef bouillon cube (, crumbled (or 1 tsp powder))","2 bay leaves","1.5 tsp sugar (any)","2 tsp dried oregano","1/2 tsp cinnamon (or 1 stick, use whole)","3/4 tsp salt"],"purpose":"Filling"},{"ingredients":["4 tbsp (60g) butter","5 tbsp plain flour","2 1/2 cups milk (any fat %)","1/4 tsp nutmeg, freshly grated (optional)","1/2 cup parmesan cheese, grated (or Kefalotiri Cheese) (Note 3)","1 egg","1 egg yolk","1 1/4 tsp Vegeta, vegetable or chicken stock powder (or salt) (Note 4)","1/4 tsp pepper"],"purpose":"Bechamel Sauce"},{"ingredients":["1/3 cup panko breadcrumbs (Note 5)"],"purpose":"Topping"}]', '[{"description":"Eggplant (Note 6)","images":[],"step":1},{"description":"Place eggplant slightly overlapping in a large colander. Sprinkle with some salt. Repeat with remaining eggplant.","images":[],"step":2},{"description":"Leave to sweat for 30 minutes. Meanwhile, make Meat Sauce and Béchamel Sauce.","duration":30,"images":[],"step":3},{"description":"Preheat oven to 240C/450F.","images":[],"step":4},{"title":"Pat eggplant dry","description":"make sure to do this well, otherwise it''s too salty. Lay on parchment paper lined trays (you might need 3 trays, work in batches), brush with oil.","images":[],"step":5},{"title":"Bake 15","description":"20 minutes or until lightly browned and softened . Remove and set aside to cool slightly.","images":[],"step":6},{"description":"Heat olive oil in a large skillet or pot over high heat, then cook the garlic and onion for 2 minutes.","duration":2,"images":[],"step":7},{"description":"Add the beef or lamb and cook until it changes from pink to brown, breaking it up as you go.","images":[],"step":8},{"description":"Add wine, cook for 1.5 minutes or until alcohol smell is gone.","images":[],"step":9},{"description":"Add remaining ingredients and stir to combine. Bring to a simmer, then lower heat to medium low and cook for 15 minutes, or until reduced to a thick sauce.","duration":15,"images":[],"step":10},{"description":"Melt butter in a pan over medium heat. Add flour and cook for 1 minute, stirring constantly.","duration":1,"images":[],"step":11},{"description":"Stirring constantly, slowly add the milk. Then stir regularly for 3 to 5 minutes or until it thickens so that it thickly coats the back of a wooden spoon (see video / step photos).","duration":4,"images":[],"step":12},{"description":"Remove from the stove and whisk in cheese, nutmeg, Vegeta/stock powder (or salt) and pepper.","images":[],"step":13},{"description":"Allow to cool for 5 minutes, then whisk the eggs in. Cover with lid until required.","duration":5,"images":[],"step":14},{"description":"Lower oven to 180C/350F (all oven types).","images":[],"step":15},{"description":"Place half the eggplant in the bottom of a baking dish (I used my 26cm/9\" Lodge skillet), then top with all the Filling.","images":[],"step":16},{"description":"Top with remaining eggplant, then pour over the Béchamel Sauce, sprinkle with breadcrumbs.","images":[],"step":17},{"title":"Bake for 30","description":"40 minutes or until golden brown. Allow to stand for 10 minutes before serving.","duration":35,"images":[],"step":18}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","greek-recipes","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c9b653ea691c', 'en', 'US', 'Cheeseburger Casserole (Homemade Hamburger Helper)', 'Recipe video above. It''s beefy, cheesy and saucy. If you love Cheeseburgers and Mac and Cheese, then you will LOVE this Cheeseburger Casserole! A homemade version of Hamburger Helper, the boxed pasta. One pot, 30 minutes start to finish!', 'https://www.recipetineats.com/tachyon/2016/08/Cheeseburger-Casserole_Hamburger-Helper_0.jpg', 10, 20, 30, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.68, "unit": "pack of 500g"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_hot_sauce", "quantity": {"value": 0.1, "unit": "bottle of 150ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion, chopped","1 small carrot * (, chopped (optional))","1 celery stalk * (, chopped (optional))","500 g/ 1 lb ground beef (mince) (, preferably lean)","12 oz / 340g dried macaroni (, uncooked)","1/2 cup frozen corn * (, optional)","2 cups chicken broth/stock, low sodium","1 tbsp hot sauce or Sriracha sauce (, adjust to taste)","1 tsp American chili powder (Note 1)","1 tsp dried oregano","1 tsp garlic powder (, or sub onion powder)","800 g / 28 oz crushed tomato","2 tbsp tomato paste","1 1/4 tsp salt","1/2 tsp black pepper","1.5 - 2 cups (150 - 200g) cheddar or tasty cheese, shredded (Note 3)","1 cup (100g) mozzarella cheese (, for topping)"]},{"ingredients":["1 green onion (, sliced)"],"purpose":"Garnish (optional)"}]', '[{"description":"Heat oil in a dutch oven or large deep skillet over medium high heat.","images":[],"step":1},{"description":"Add onion and garlic, cook 1 minute.","images":[],"step":2},{"description":"Add celery and carrot, cook 3 minutes until soft.","images":[],"step":3},{"description":"Increase heat to high and add beef. Cook, breaking it up as you go, until no longer pink - 3 minutes.","images":[],"step":4},{"description":"Add remaining ingredients EXCEPT cheese. Stir to combine, add macaroni, then turn down to medium or medium low so it''s simmering gently.","images":[],"step":5},{"description":"Cover, cook 8 minutes. Pasta should be just about cooked, and still nice and saucy.","images":[],"step":6},{"description":"Add cheddar cheese, stir. Top with mozzarella cheese.","images":[],"step":7},{"description":"Cover with lid, cook for a further 2 minutes.","images":[],"step":8},{"title":"Remove from stove. The pasta should now be cooked","description":"tender but firm, not mushy, slick with sauce, not dried out.","images":[],"step":9},{"description":"Serve immediately, garnished with green onions, if using.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7d3ada56b5c4', 'en', 'US', 'Beef Burritos', 'Recipe video above. Simple, super tasty everyday beef burritos made with a homemade beef mince filling (ground beef), rice and your choice of fillings. One of the best freezer meals ever!', 'https://www.recipetineats.com/tachyon/2017/06/Beef-Burritos.jpg', 15, 20, 35, 6, '[{"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_tortillas", "quantity": {"value": 6.0, "unit": "pack of 8"}}, {"id": "ing_rice", "quantity": {"value": 450.0, "unit": "pack"}}, {"id": "ing_cabbage", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}]', '[{"ingredients":["1 tsp each onion powder (, dried oregano, salt)","2 tsp each dried cumin powder (, paprika)","1/4 tsp black pepper","¼ tsp cayenne pepper (, or to taste (optional))"],"purpose":"Burrito Seasoning:"},{"ingredients":["1/2 tbsp olive oil","2 garlic cloves","½ onion (, finely chopped)","500g / 1 lb beef mince (ground beef), I use lean","2 tbsp tomato paste","3 tbsp water"],"purpose":"Beef:"},{"ingredients":["6 - 8 large soft flour tortillas or round wraps (~25cm/10”+) (Note 1)","3 cups cooked rice (, warm not piping hot (I use white long grain))","3 cups iceberg lettuce or cabbage (, finely sliced (use cabbage if freezing))","1 cup corn kernels (I use canned, drained)","1 cup black beans (I use canned, drained)","3 tomatoes, deseeded and diced","1/2 red onion (, finely chopped)","Finely chopped coriander / cilantro (optional)","1 1/2 cups / 150g shredded cheese of choice (melting kind)"],"purpose":"Burritos:"}]', '[{"description":"Heat oil in a skillet over high heat. Add garlic and onion, cook for 2 minutes until onion is lightly browned. Add beef and cook, breaking it up as you go, until it turns from red to brown.","duration":2,"images":[],"step":1},{"description":"Add Taco Seasoning (or use 1 packet store bought) and cook for 1 minute. Then add tomato paste and water, cook for 3 minutes until the water is mostly evaporated but the beef is still juicy, not dried out. Set aside to cool for 10 minutes – piping hot filling will steam the burrito, making the tortilla soggy.","duration":1,"images":[],"step":2},{"title":"Optional","description":"If not warming rolled burrito, warm the tortillas before rolling (per packet directions).","images":[],"step":3},{"title":"Place a burrito on a work surface. Place 1/4","description":"1/3 cup of rice just below the centre. Top with 1/4 - 1/3 cup beef, then some lettuce, corn, black beans, tomato, a sprinkle of red onion, coriander and cheese.","images":[],"step":4},{"description":"Fold up the bottom to cover the filling then fold the edges in (video helpful to see how to do this). Roll up tightly, then wrap in foil. Serve as is or heat per below.","images":[],"step":5},{"title":"HEATING","description":"To warm through, pan fry (dry pan) in the foil over medium high heat for a few minutes on each side to slightly crisp and warm the outside. Or for 10+ minutes on a medium low heat if you want to melt the cheese. Or they can be baked at 180C/350F for 20 minutes in the foil – this will warm them all the way through and crisp up the tortilla slightly. If they are straight from the fridge, they will take around 30 minutes to warm through.","duration":20,"images":[],"step":6},{"description":"Burritos are best served with something to dollop/dip - sour cream (or yoghurt) and some sort of chilli sauce are my usual because it''s easy. When I''m making more of an effort, I use Restaurant Style Salsa or Guacamole.","images":[],"step":7}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["beef-mince-recipes","beef-recipes","burritos","dinner-tonight","main-dishes","mexican-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a35df47910fa', 'en', 'US', 'Easy Taco Soup', 'Recipe video above. All the fixings of a taco - in soup form! Don''t skip the toppings - they totally make it! At least cheese and sour cream or yoghurt are essential.', 'https://www.recipetineats.com/tachyon/2017/02/Taco-Soup-5-1.jpg', 10, 20, 30, 4, '[{"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.312, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chilli", "quantity": {"value": 1.2, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 tsp EACH garlic powder, onion powder and cayenne pepper","2 tsp EACH dried oregano and paprika","2 1/2 tsp cumin powder","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Homemade Taco Seasoning (Note 1)"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped (brown or yellow))","500 g / 1 lb ground beef ((mince), lean)","400 g/ 14 oz can black beans (1 can) (, drained and rinsed (Note 2))","400g / 14oz can corn kernels (1 can) (, drained and rinsed)","120 g / 4.5 oz canned green chili (Note 3)","800 g / 28 oz canned crushed tomato","2 cups beef broth"],"purpose":"Soup"},{"ingredients":["Shredded cheese (essential!)","Sour cream (or yoghurt (essential!))","Fresh coriander/cilantro leaves or shallots/scallions (, finely sliced)","Corn chips","Other options: diced avocado, squeeze of lime juice"],"purpose":"Toppings (Don’t skip these!)"}]', '[{"description":"Heat oil in a pot over medium high heat. Add garlic and onion, cook until softened (3 min).","images":[],"step":1},{"description":"Add beef and turn up the heat to high. Cook, breaking it up as you go, until it all changes from pink to brown.","images":[],"step":2},{"description":"Add remaining Soup ingredients and Taco Seasoning. Bring to a simmer then turn heat down to medium.","images":[],"step":3},{"description":"Simmer for 10 minutes to bring the flavours together. Adjust thickness with water if desired.","duration":10,"images":[],"step":4},{"title":"This is how I like to serve it","description":"place a handful of corn chips in the bowl. Ladle in soup. Top with sour cream, cheese, coriander and a few crushed corn chips. For a healthier option, skip the corn chips in the bowl and/or serve more on the top / side of the soup.","images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1dd67641236b', 'en', 'US', 'Chilli Con Carne', 'Recipe video above. Everybody''s favourite Chili, nice and saucy! Made with a from-scratch Chili Powder rather than a store bought mix - it''s so much more reliable and you just need pantry staples. Don''t skip the beef bouillon cubes (stock cube) - it adds so much more flavour into the sauce than using just salt, or even liquid beef stock.Make a quick midweek version though when you''ve got the time, it''s well worth slow cooking. See notes for Serving and Topping options!', 'https://www.recipetineats.com/tachyon/2016/06/Chili-Con-Carne_8.jpg', 10, 30, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 0.992, "unit": "can of 400g"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 1.0, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.625, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1 tbsp olive oil","3 garlic cloves (, minced)","1 onion (, diced (brown, white, yellow))","1 red capsicum ((bell pepper), diced)","1 lb / 500g beef mince / ground beef","3 tbsp tomato paste","800g / 28 oz can crushed tomato","14 oz / 420g can red kidney beans (, drained (or other beans))","2 beef bouillon cubes (stock cubes), crumbled (Note 1)","1 1/2 tsp sugar (any type)","1/2 - 1 1/2 cups water"]},{"ingredients":["1 - 2 tsp cayenne pepper (adjust to taste) (Note 2)","4 tsp paprika powder","5 tsp cumin powder","2 tsp garlic powder (or onion powder)","2 tsp onion powder","2 tsp oregano","1 1/2 tsp cooking salt / kosher salt"],"purpose":"Chili Spice Mix:"},{"ingredients":["Rice, corn chips, tortillas (Note 5 for more)","Sour cream, yoghurt, grated cheese, coriander./cilantro (Note 6 for more)"],"purpose":"To Serve"}]', '[{"description":"Heat oil in a large skillet over medium high heat. Add garlic and onion, cook for 1 minute, then add capsicum and cook for 2 minutes until onion is translucent.","duration":1,"images":[],"step":1},{"description":"Turn heat up to high and add beef. Cook, breaking it up as you go, until mostly browned.","images":[],"step":2},{"description":"Add Chili Spice Mix. Cook until beef is browned all over. (This step helps release extra flavour from the spices)","images":[],"step":3},{"description":"Add remaining ingredients, with 1/2 cup of water for Quick Cook or 1 1/2 cups for Slow Cook. Bring to simmer, then adjust heat per step below:","images":[],"step":4},{"title":"Quick Cook","description":"20 to 40 minutes, uncovered, on medium low heat so it''s bubbling gently; OR","images":[],"step":5},{"title":"Slow Cook","description":"1.5 hours to 2 hours, covered, on low heat so it''s bubbling very gently. (Note 3 Slow Cooker)","images":[],"step":6},{"description":"Adjust salt to taste just before serving.","images":[],"step":7},{"description":"Serve over rice, or ladle into bowls and serve with corn chips or warm tortillas on the side with Toppings of choice (Note 6). See Note 7 for more serving options. My usual: Either over rice or with corn chips, always with sour cream, cheese and coriander.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f436429c6149', 'en', 'US', 'Beef and Rice with Veggies', 'Recipe video above. Ground beef cooked with seasoned rice and plenty of veggies - kind of like a pilaf or fried rice! This dish is not spicy - the cayenne pepper just adds a touch of warmth, not spiciness.', 'https://www.recipetineats.com/tachyon/2018/02/Beef-Rice_7.jpg', 5, 20, 25, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_white_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 33.333, "unit": "carton of 12"}}, {"id": "ing_baby_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, diced (any type))","1 red capsicum / bell pepper (, diced (large))","2 garlic cloves (, minced)","500g (1 lb) ground beef (mince) (, lean)","2 1/2 tbsp tomato paste","1 1/4 tsp salt","1/2 tsp EACH cumin, black pepper","1 tsp each onion powder, dried oregano (or other herb of choice)","1/4 tsp cayenne pepper (optional)","1 dried bay leaf","1 1/4 cups (225g) long grain white rice (, uncooked (Note 1))","2 cups (500 ml) beef broth (, low sodium)","2 cups (300g) diced frozen veggies (, I used corn, pea, carrot mix (Note 2))","3 big handfuls baby spinach (~ 90g/3 oz) (, or other leafy greens (Note 3))"]}]', '[{"description":"Heat oil in large pot over high heat. Add onion, capsicum and garlic. Cook for 1 minute.","duration":1,"images":[],"step":1},{"description":"Add beef, cook until brown, breaking it up as you go.","images":[],"step":2},{"description":"Add tomato paste, salt, pepper, onion powder, oregano, cumin and cayenne pepper. Cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Turn heat down to medium. Add rice and beef broth, mix well. Add frozen veggies and bay leaf, then stir.","images":[],"step":4},{"description":"Place lid on, lower heat to medium low so it''s simmering gently. Cook for 12 - 15 minutes (might even take longer) until all liquid is absorbed (tilt pot to check). The rice should be just cooked, but will be wet.","duration":13.5,"images":[],"step":5},{"description":"Remove from heat. Quickly toss spinach on top of the rice and put the lid back on. Leave to rest for 10 minutes.","duration":10,"images":[],"step":6},{"description":"Fluff rice and mix through wilted spinach with a fork. Adjust salt if desired. Serve!","images":[],"step":7}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_40339b8e866e', 'en', 'US', 'Salisbury Steak with Mushroom Gravy', 'Recipe VIDEO above. Salisbury steak is a totally scrumptious way to transform the humble ground beef / mince into something amazing! The onion grating / soaking breadcrumbs will make your patties extra tasty and tender, and the Mushroom Gravy is made extra delicious by cooking the Salisbury Steaks IN the gravy.And next time - try Salisbury Steak Meatballs!', 'https://www.recipetineats.com/tachyon/2015/12/Salisbury-Steak-2.jpg', 15, 15, 30, 5, '[{"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1/2 onion (white, brown or yellow)","1/2 cup panko breadcrumbs (or 1/3 cup ordinary breadcrumbs)","1 lb/500g ground beef (mince)","1 garlic clove (, minced)","1 egg","2 tbsp ketchup","1 beef bouillon cube (, crumbled)","1/2 tsp Worcestershire sauce","3 tsp dijon mustard (OR 2 tsp dry mustard powder)"],"purpose":"Salisbury Steak"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","5 oz/150g mushrooms (, sliced)","30g / 2 tbsp unsalted butter","3 tbsp flour (all purpose / plain)","2 cups beef broth / stock (, low sodium)","1/2 cup water","2 tsp dijon mustard","2 tsp Worcestershire sauce","Salt and pepper"],"purpose":"Gravy"}]', '[{"description":"Salisbury Steaks","images":[],"step":1},{"title":"Onion grating","description":"Place breadcrumbs in a bowl. Use a box grater and grate the onion over the breadcrumbs. Mix with fingers, leave to soak for a few minutes.","images":[],"step":2},{"title":"Mix","description":"Add remaining Salisbury Steak ingredients into the large bowl. Use your hands to mix until just combined. Mix well for a couple of minutes until the mixture becomes a bit \"pasty\" which will ensure your patties hold together well.","images":[],"step":3},{"title":"Form patties","description":"Divide into 5 and pat very firmly into oval patties around 3/4\" / 1 2/3 cm thick.","images":[],"step":4},{"description":"Cooking and Gravy","images":[],"step":5},{"title":"Brown patties","description":"Heat oil in a skillet over high heat. Add the steaks and cook the first side for 1 minute or until browned, then gently flip and brown the other side (they will still be raw inside). Remove onto plate.","duration":1,"images":[],"step":6},{"title":"Cook aromatics","description":"If skillet is looking dry, add a touch more oil. Add chopped onion and garlic and cook for 2 minute until onions are a bit translucent.","duration":2,"images":[],"step":7},{"title":"Cook mushrooms","description":"Add the mushrooms into the skillet and cook for 2 - 3 minutes until golden.","duration":2.5,"images":[],"step":8},{"title":"Make gravy roux","description":"Turn heat down to medium. Add butter. Once melted, add flour and cook for 30 seconds, stirring constantly.","duration":0.5,"images":[],"step":9},{"title":"Gravy","description":"Gradually add in beef broth, stirring as you go. Once mostly lump free, whisk in remaining Gravy ingredients.","images":[],"step":10},{"title":"Finish cooking steaks","description":"Add steaks along with the juices on the plate. Cook for 5 - 7 minutes, or until gravy is thickened, stirring occasionally around the steaks. If the gravy thickens too quickly, add more water.","duration":6,"images":[],"step":11},{"title":"Season gravy","description":"Remove steaks onto a plate. Taste gravy and adjust salt and pepper to taste.","images":[],"step":12},{"description":"Serve salisbury steaks topped with the mushroom gravy - over mashed potato is ideal! Sprinkle with a bit of parsley if desired.","images":[],"step":13}]', '["egg","gluten","milk","mustard"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","main-dishes","most-popular","mushroom-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5d01e8557124', 'en', 'US', 'Rissoles!', 'Recipe video above. Plump, extra juicy, extra tasty rissoles - an Aussie favourite! I usually make Beef Rissoles but these can be made with lamb, pork, chicken or turkey. Makes 10 - 12 rissoles. (PS For those who are unfamiliar with rissoles, they are basically squashed meatballs. A classic Aussie family favourite :) )', 'https://www.recipetineats.com/tachyon/2017/09/Beef-Rissoles-1_-2.jpg', 15, 15, 30, 4, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 small brown onion","1/2 cup panko breadcrumbs (or normal)","500 g / 1 lb beef mince (ground beef) (Note 1)","1 small zucchini","1 small carrot","1 egg","1 large garlic clove (, minced)","1/2 tsp dried thyme","1/2 tsp oregano (or sub with other favourite herbs)","1/2 tsp each salt and pepper","2 tsp Worcestershire Sauce"],"purpose":"Rissoles:"},{"ingredients":["1 - 2 tbsp oil"],"purpose":"Cooking:"},{"ingredients":["Tomato Ketchup!"],"purpose":"Serving:"}]', '[{"description":"Grate the onion into a large bowl using a box grater (see video). Add panko, mix briefly to coat in the onion juices.","images":[],"step":1},{"description":"Grate zucchini and carrot into the bowl. Add remaining Rissoles ingredients. Mix well. Scoop up about 1/4 cup of mixture, form a 1.7cm / 2/3\" thick pattie. Indent the middle slightly (Note 2, see photos in post). Repeat with remaining mixture - you should make 10 - 12.","images":[],"step":2},{"description":"Heat oil in a skillet over medium heat. Add half the patties and cook for 4 minutes or until dark golden. Press LIGHTLY with spatula, if you press hard, you''ll press the juices out!","duration":4,"images":[],"step":3},{"title":"Flip and cook the other side for 3","description":"4 minutes until golden.","duration":3.5,"images":[],"step":4},{"description":"Transfer to plate, repeat with remaining rissoles.","images":[],"step":5},{"description":"Serve with tomato ketchup!","images":[],"step":6}]', '["egg"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a87cd55d2a4f', 'en', 'US', 'Lasagna', 'Recipe video above. One of my signature recipes! This is a lasagna made the traditional Italian way, with a slow cooked ragu and a béchamel sauce ("Besciamella"). No ricotta - that''s the American-Italian version. Though it requires patience to make, it is worth every minute. The ragu bolognese is melt-in-you-mouth tender and the sauce is rich and thick. Makes 8 giant or 10 normal servings. This lasagna has 4 layers of lasagna sheets with 3 layers of meat and cheese sauce, then finished with a cheese sauce topping. You could stretch it to 4 ragu layers. If making 5 layers, scale up the recipe by 25% (click on servings and slide) and use a very deep pan!', 'https://www.recipetineats.com/tachyon/2025/03/Lasagna_6-1.jpg', 20, 240, 260, 10, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 2.0, "unit": "block of 200g"}}, {"id": "ing_pinch_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sheets_lasagna", "quantity": {"value": 350.0, "unit": "pack"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","1 onion (, finely chopped (white, yellow or brown))","1 medium carrot (, peeled and very finely diced)","1 celery stick (, very finely diced)","2 garlic cloves (, minced)","1 kg / 2 lb beef mince (ground beef) (Note 1)","800g / 28 oz canned crushed tomato","1/4 cup tomato paste","1 cup pinot noir red wine (, or other dry red wine (Note 2))","3 beef bouillon cubes (, crumbled)","2 bay leaves (, dried or fresh)","1/2 tsp EACH dried thyme and oregano","2 tsp Worcestershire Sauce","1 - 2 tsp sugar (if needed - Note 3)","1/2 tsp salt and black pepper"],"purpose":"Ragu Bolognese:"},{"ingredients":["60g / 4 tbsp butter","1/2 cup flour","4 cups milk (, preferably full fat but low fat ok)","2 cups gruyere or Colby cheese (, shred yourself (or cheddar, Monterey Jack, OR 1 cup / 100g shredded parmesan) (Note 4))","Pinch of freshly ground nutmeg","Salt and pepper"],"purpose":"Cheese Sauce (Besciamella):"},{"ingredients":["350g/ 12 oz fresh lasagna sheets (or 250g/8oz dried) (Note 5)","1 1/2 cups (tightly packed) mozzarella cheese (, shred yourself (Note 4))","Finely chopped basil or parsley (, for garnish (optional))"],"purpose":"Lasagna:"}]', '[{"description":"Heat oil in a large heavy based pot over medium heat. Add garlic, onion, celery and carrots. Cook for 10 minutes until softened and sweet - they should not brown (if they do, turn heat down).","duration":10,"images":[],"step":1},{"description":"Add beef, turn heat up and cook the beef, breaking it up as you go.","images":[],"step":2},{"description":"Once the beef has all turned brown, add the remaining Ragu ingredients EXCEPT the sugar.","images":[],"step":3},{"description":"Stir then adjust the heat so it is bubbling very gently. Place the lid on and cook for 1.5 - 2 hours, stirring every now and then, then remove the lid and simmer for 30 minutes.","duration":30,"images":[],"step":4},{"description":"The ragu is ready when the meat is really tender and the sauce has thickened and is rich - see video for consistency (Note 6). Adjust salt and pepper to taste, and add sugar if required (Note 3)","images":[],"step":5},{"title":"Warm milk up in a saucepan (optional","description":"just makes sauce thicken faster).","images":[],"step":6},{"description":"In a large saucepan, melt butter over medium low heat. Add flour and mix constantly for 1 minute.","duration":1,"images":[],"step":7},{"description":"Pour about 1 cup of the milk in, mixing as you go to incorporate into the flour mixture. Once mostly lump free, add remaining milk. Use a whisk if needed to make it lump free.","images":[],"step":8},{"description":"Turn heat up to medium high. Stir occasionally at first then regularly after a few minutes until sauce thickens - about 5 - 8 minutes. It should coat the back of the wooden spoon.","images":[],"step":9},{"description":"Remove from heat, add cheese, nutmeg, salt and pepper. Mix until the cheese is melted. The Sauce should be thick but still easily pourable - the consistency of heavy cream (you need to be able to drizzle it over the Ragu when layering - see video). If it''s too thick, add a splash of water or milk.","images":[],"step":10},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":11},{"description":"Use a 33 x 22 x 7 cm / 13 x 9 x 2.5\" baking dish.","images":[],"step":12},{"description":"Smear a bit of Ragu on the base, then cover with lasagna sheets. Tear sheets to fit.","images":[],"step":13},{"description":"Spread over 2 1/2 cups of Ragu (enough to cover sheets), then drizzle over 1 cup of Cheese Sauce.","images":[],"step":14},{"description":"Top with lasagna sheets (Note 7). Spread with another 2 1/2 cups of Ragu, then 1 cup of Cheese Sauce. Top with lasagna sheets then repeat 1 more time.","images":[],"step":15},{"description":"Top with a 4th layer of lasagna sheets, then pour over the remaining Cheese Sauce.","images":[],"step":16},{"description":"Sprinkle with Mozzarella, then bake for 25 minutes or until golden and bubbling.","duration":25,"images":[],"step":17},{"description":"Stand for 5 to 10 minutes before cutting and serving, garnished with basil or parsley if desired.","duration":7.5,"images":[],"step":18}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","iconic-dishes","italian-recipes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_652e35409965', 'en', 'US', 'Greek Meatballs', 'Juicy Greek Meatballs (Keftedes), beautifully flavoured with red onion, parsley, a hint of mint and dried oregano with a slightly crispy surface. See recipe video below.', 'https://www.recipetineats.com/tachyon/2017/03/Greek-Meatballs-6-hero.jpg', 20, 12, 32, 5, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 120.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["1 red onion, grated","500g / 1 lb beef mince (ground beef) (or lamb!)","200g / 6.5oz pork mince (ground pork), or more beef","2 garlic cloves, minced","1 cup / 60g panko breadcrumbs (or use normal)","1 egg","1/4 cup fresh parsley, finely chopped","6 large mint leaves, finely chopped (spearmint if you can, it''s authentic)","1/2 tsp dried oregano","1 tbsp extra virgin olive oil","3/4 tsp salt","Black pepper"],"purpose":"Meatballs:"},{"ingredients":["1/2 cup flour (any white)","3 tbsp olive oil","Finely chopped parsley (optional, for garnish)","Tzatziki (Note 5) or Greek yoghurt"],"purpose":"Cooking / Serving:"}]', '[{"description":"Grate the onion straight into a large bowl, then add remaining Meatball ingredients. Use your hands to mix well for a few minutes until the mixture is quite smooth and very well combined.","images":[],"step":1},{"title":"Optional: Refrigerate for 1 hour","description":"makes them easier to roll + retains round shape when cooking.","images":[],"step":2},{"description":"Measure out heaped tablespoons and dollop onto a work surface - should make around 32 - 35. Then roll into balls.","images":[],"step":3},{"description":"Heat most of the oil in a large skillet over medium high heat (medium if you have a strong gas stove). Use enough oil to cover the surface of the skillet.","images":[],"step":4},{"title":"Cook in 2 to 3 batches","description":"Dredge meatballs lightly in flour, shaking off excess, then place in the skillet. Roll them around and cook for 5 - 6 minutes, until nicely browned all over. Remove onto plate, cover to keep warm and repeat with remaining meatballs.","duration":5.5,"images":[],"step":5},{"title":"BAKING","description":"Alternatively, spray generously with oil (preferably olive oil) then bake at 180C/350F for 20 minutes or until browned. The pan frying method is the traditional way and the meatballs are slightly juicier.","duration":20,"images":[],"step":6},{"description":"Serve as a starter as part of a mezze platter with pita bread and tzatziki, or make dinner plates by adding a salad like a Greek Salad!","images":[],"step":7}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["beef-mince-recipes","beef-recipes","finger-food","greek-recipes","meatball-recipes","mediterranean-recipes","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1e11cde4fa1a', 'en', 'US', 'Italian Meatball Soup', 'My Classic Italian Meatballs are one of the most popular recipes on my site. They''re extra soft and juicy, and extra tasty thanks to just a couple of little but key extra steps - using bread soaked in grated onion, and using a mix of ground beef and pork (mince). And now by popular demand, here is my Meatball Soup made using my Classic Italian Meatballs! This soup is really thick and hearty, and the tomato broth is extra tasty thanks to the meatballs!', 'https://www.recipetineats.com/tachyon/2016/04/Meatball-Soup_4.jpg', 25, 30, 55, 5, '[{"id": "ing_bread", "quantity": {"value": 1.25, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.454, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.5, "unit": "pack of 125g"}}]', '[{"ingredients":["1 lightly packed cup of sliced white sandwich bread (, torn into small pieces, crusts removed (Note 1))","1/2 cup grated onion (brown, white or yellow)","14 oz / 400 g ground beef (beef mince)","3 oz / 100g ground pork (mince) or more ground beef (Note 2)","1 egg","1/4 cup fresh parsley (, finely chopped (Note 3))","2 garlic cloves (, minced)","1/4 cup Parmigiano-Reggiano ((or parmesan), freshly grated)","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Meatballs"},{"ingredients":["1 1/2 tbsp olive oil","1 cup onion (, finely chopped (white, brown or yellow))","2 garlic cloves (, minced)","2 cups chicken broth / stock (or water)","1 cup water","24 oz / 700g passata (pureed tomato) (Note 4)","28 oz / 800g canned tomato","1 tbsp Italian mixed herbs (Note 5)","2 tsp garlic powder (or onion powder)","1 - 2 tsp red pepper / chilli flakes (optional)","8 oz / 250g spaghetti (dried, not fresh or cooked)"],"purpose":"Soup"},{"ingredients":["1/4 cup fresh basil leaves (, torn)","1/2 - 3/4 cup shredded mozzarella cheese","Parmigiano-Reggiano ((or parmesan), freshly grated)"],"purpose":"Garnish (optional)"}]', '[{"description":"Place the bread and onion in a large bowl. Mix to combine so the onion juice soaks the bread.","images":[],"step":1},{"description":"Add all the remaining Meatball ingredients. Use you hands to mix well.","images":[],"step":2},{"description":"Roll a slightly heaped tablespoon of mixture into a ball. Repeat with remaining mixture. Should make around 24. (Note 6) Refrigerate meatballs for 30 minutes (Note 7)","duration":30,"images":[],"step":3},{"description":"Heat 1 1/2 tbsp olive oil in a large pot over medium high heat. Add the meatballs in a single layer and brown all over (still raw inside) - I do this in 2 batches. Remove meatballs onto a plate and set aside.","images":[],"step":4},{"description":"If the pot is looking dry, add a touch more olive oil. Add onion and garlic and cook for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Add chicken broth, bring to simmer and scrape the bottom of the pot to mix the brown bits into the liquid.","images":[],"step":6},{"description":"Add remaining Soup ingredients except spaghetti. Bring to simmer, turn heat down to medium and cook for 5 minutes, stirring occasionally, scraping the bottom of the pot.","duration":5,"images":[],"step":7},{"description":"Take the lid off and add spaghetti. Use tongs to push it all under the liquid as it starts to soften. Once the spaghetti is submerged, add the meatballs. Cook for around 12 minutes, or until spaghetti is just cooked but still firm (al dente). Remove from stove.","images":[],"step":8},{"description":"If using cheese, sprinkle on the surface of the soup after you take it off the stove, put the lid back on and let the heat melt the cheese (~2 minutes).","images":[],"step":9},{"description":"Ladle soup, spaghetti and meatballs into bowls. Garnish with basil leaves and serve with Parmigiano-Reggiano, if using.","images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["beef-mince-recipes","beef-recipes","italian-recipes","main-dishes","meatball-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e3d8e83202bc', 'en', 'US', 'Italian Meatloaf with Marinara Sauce', 'My Italian meatloaf is made extra juicy by soaking bread in grated onion instead of using breadcrumbs. The seasonings for the meatloaf are the same as what is used for homemade Italian sausages, so this really tastes like an Italian meatloaf! And the sauce is made extra tasty by adding the loaf pan juices and cooking the meatloaf IN the sauce for part of the time.', 'https://www.recipetineats.com/tachyon/2015/12/Italian-Meatloaf_4.jpg', 15, 60, 75, 6, '[{"id": "ing_capsicum", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.375, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cream", "quantity": {"value": 0.12, "unit": "carton of 250ml"}}, {"id": "ing_pork", "quantity": {"value": 0.369, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.726, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 12.5, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.5, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_canned_tomatoes", "quantity": {"value": 1.588, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_mixed_italian_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.5, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.5, "unit": "jar of 50g"}}]', '[{"ingredients":["1 1/2 cups diced red bell pepper / capsicum (1 large)","1 tbsp olive oil","2 cups stale white bread (, crusts removed, roughly diced (about 3 slices))","1 small onion","2 tbsp cream (or milk)","13 oz / 400 g ground pork (mince)","1.6lb / 800 g ground beef (mince)","2 eggs","2 1/2 tsp fennel seeds","3 tsp paprika (sweet or smoked)","1 3/4 tsp salt","Pepper"]},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped (brown, white, yellow))","1.4 lb / 700 g tomato passata or crushed tinned tomatoes (Note 1)","3/4 cup water","2 tsp dried Mixed Italian Herbs","1 - 3 tsp red pepper flakes (optional)","Salt and pepper"],"purpose":"Sauce"}]', '[{"description":"Preheat oven to 180C/350F. Spray a 28cm/11\" loaf pan, then line with parchment / baking paper, leaving overhang (Note 2).","images":[],"step":1},{"description":"Heat oil over high heat. Add capsicum, leave for 1 minute without stirring so it starts to char (burn) then stir and continue cooking to char it more (about 2 minutes in total). Remove and set aside.","duration":1,"images":[],"step":2},{"description":"Place bread in a large bowl. Grate onion into the bowl, using a normal box cutter (Note 3). Add cream, then use your hands to squidge the mixture together so the bread is completely soaked and starts to disintegrate.","images":[],"step":3},{"description":"Add remaining meatloaf ingredients, including capsicum. Use your hands to mix it together until JUST combined. Do not over mix otherwise it will become dense.","images":[],"step":4},{"description":"Press into the loaf pan (Note 4). Drizzle with olive oil then bake for 30 minutes. Meanwhile, make the Sauce.","duration":30,"images":[],"step":5},{"description":"Take the meatloaf out of the oven. Carefully lift the meatloaf out of the loaf pan (using the paper overhang) onto a work surface. Then transfer the meatloaf into the skillet with the Sauce.","images":[],"step":6},{"description":"Pour juices in the loaf pan into the skillet. Return to the oven for a further 30 to 40 minutes, or until cooked to your liking.","images":[],"step":7},{"description":"Take it out of the oven and let it rest for 5 minutes before slicing. Serve the meatloaf with the Sauce, garnished with parmesan if desired.","duration":5,"images":[],"step":8},{"description":"I like to serve this with mashed potatoes but it is also lovely with pasta.","images":[],"step":9},{"description":"Heat oil in a ovenproof skillet over medium heat. Add onion and garlic and cook for 3 minutes until translucent.","duration":3,"images":[],"step":10},{"description":"Add remaining ingredients. Bring to a simmer and cook for 5 minutes on the stove, adjusting salt and pepper to taste.","duration":5,"images":[],"step":11},{"description":"Take it off the stove. Follow the steps above to place the meatloaf in and bake it.","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","italian-recipes","main-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_211a911cd221', 'en', 'US', 'Nachos Pie', 'Nachos - in lasagne form! This is how to get your midweek Nachos fix with far less guilt! You can substitute the spices for a packet Nachos mix if you prefer. The Pico De Gallo adds freshness but is not essential! It is still scrumptious without it. You could make this even healthier by reducing the beef in this and adding more vegetables, like corn, diced zucchini and bell peppers (capsicum).', 'https://www.recipetineats.com/tachyon/2015/07/Nacos-Pie_600px_2a_Featured.jpg', 10, 40, 50, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.369, "unit": "kg"}}, {"id": "ing_packet_taco_seasoning_or_make_your_own_see_note_1", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_kidney_beans", "quantity": {"value": 0.992, "unit": "can of 400g"}}, {"id": "ing_tortillas", "quantity": {"value": 3.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_corn", "quantity": {"value": 3.0, "unit": "can of 400g"}}, {"id": "ing_avocado", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1 tbsp olive oil","1 onion (, diced (brown, yellow, white))","2 garlic cloves","13 oz / 400 g ground/mince beef (use lean!)","1 oz / 28 g packet Taco Seasoning OR make your own - see Note 1","1/2 tsp black pepper","700 g / 24oz tomato passata or pureed canned tomatoes (Note 2)","1/2 cup water","14 oz / 400 g canned red kidney beans ((or any other beans), drained)","3 - 4 soft tortillas ((flour or corn) - for layering)","1 cup grated cheese (I used mozzarella, but any melting cheese is fine)","2 oz / 70 g corn chips"]},{"ingredients":["1/2 avocado (, diced)","1 large tomato (, deseeded and diced (Note 3))","1/4 spanish ((red) onion, diced)","2 tbsp lime juice (fresh or bottled)","3 tbsp fresh coriander leaves","1/2 tbsp olive oil","Salt and pepper"],"purpose":"Pico de Gallo (optional)"},{"ingredients":["Sour cream"],"purpose":"To serve"}]', '[{"description":"Preheat the over to 350F/180C.","images":[],"step":1},{"description":"Heat the oil in a large skillet over high heat.","images":[],"step":2},{"description":"Add the garlic and onion, and cook until translucent.","images":[],"step":3},{"description":"Add the beef and cook, breaking up into pieces, until browned. Add the Taco Seasoning and pepper about halfway through browning the beef.","images":[],"step":4},{"description":"Add the tomato passata, water and beans. Cook for 5 minutes, stirring occasionally until thickened but still very saucy. Remove from heat.","duration":5,"images":[],"step":5},{"description":"Assemble & Bake","images":[],"step":6},{"description":"Lay a tortilla in a pie dish (24 cm / 9 inch diameter). Use a slotted spoon to top with just under 1/2 the meat. Try to avoid using too much sauce so sort of \"shake\" each spoonful to drain out sauce.","images":[],"step":7},{"description":"Top with another tortilla + torn/cut pieces of another tortilla to cover completely.","images":[],"step":8},{"description":"Top with the remaining meat, again avoiding the sauce.","images":[],"step":9},{"description":"Top with remaining tortillas, then pour over all the sauce (and any residual meat).","images":[],"step":10},{"description":"Place in the oven and bake for 20 minutes. If you''re worried about overspill, place it on a baking tray.","duration":20,"images":[],"step":11},{"description":"Remove from the oven, cover with corn chips then scatter with cheese. Bake until the chips are a bit golden and the cheese is melted - 10 to 15 minutes.","images":[],"step":12},{"description":"Serve, topped with Pico De Gallo and Sour Cream on the side, if using.","images":[],"step":13},{"description":"Combine ingredients in a bowl. Toss and adjust salt/pepper to taste.","images":[],"step":14}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican-esque"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","nachos-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_94aae0a6fbf0', 'en', 'US', 'One Pot Orzo / Risoni Bolognaise', 'Dinner all made in one pot in just 20 minutes! A yummy bolognaise sauce made with orzo/risoni instead of spaghetti. Great couch food - and for kids too, less mess!', 'https://www.recipetineats.com/tachyon/2015/06/One-Pot-Bolognaise-Orzo-Risoni_680px_1.jpg', 3, 18, 21, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_italian_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2 cloves of garlic (, minced)","1 small onion (, peeled and diced (brown, white or yellow))","1 lb / 500g ground beef (mince)","24 oz / 700g tomato passata (Note 3)","2 tsp Worcestershire sauce","2 tsp dried Italian Herbs (, or any combination of dried parsley, oregano, basil)","2 beef bouillon cubes (Note 1)","1/2 to 1 tsp salt (to taste)","Black pepper","3 cups water","1 1/2 cups dried orzo / risoni"]},{"ingredients":["Freshly grated parmesan cheese","Finely chopped parsley"],"purpose":"To serve (optional)"}]', '[{"description":"Heat the oil in a large skillet/fry pan (or pot) over medium high heat. Add the onion and garlic and cook for 3 minutes or until translucent.","duration":3,"images":[],"step":1},{"description":"Add the mince and turn the heat up to high. Cook the mince, breaking it up as you go.","images":[],"step":2},{"description":"When the mince is browned, add the remaining ingredients except the orzo. When the liquid comes to a simmer (it might bubble and spit slightly) add the orzo/risoni.","images":[],"step":3},{"description":"Give it a quick stir then turn the heat down to medium low.","images":[],"step":4},{"description":"Cook for 10 minutes, stirring frequently towards the end to ensure the orzo/risoni doesn''t stick to the bottom of the pan. If your liquid is evaporating too quickly, just add a slosh of hot water (tap or boiling).","duration":10,"images":[],"step":5},{"description":"Remove the risoni from the heat. The risoni should be a teeny bit hard still and it should be very saucy when you take it off the stove. (Note 2)","images":[],"step":6},{"description":"Check for seasoning (salt), then give it a good stir.","images":[],"step":7},{"description":"Serve immediately, while it''s piping hot and nice and saucy, garnished with freshly grated parmesan and parsley, if desired.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian-esque"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","italian-recipes","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_98fb4edc94a6', 'en', 'US', 'Meatloaf Cupcakes With Mashed Potato', 'Everything tastes better in miniature form! These Meatloaf Cupcakes are made extra irresistible by piling on mashed potato. These freeze very well. They are also great for hiding vegetables. I only added grated carrot, but you can mix in whatever vegetables you want. Finely chopped spinach or cabbage would blend in well, as would grated zucchini.', 'https://www.recipetineats.com/tachyon/2014/10/Meatloaf-Cupcakes-2.jpg', 15, 25, 40, 8, '[{"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_panko", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g beef mince (ground beef)","1 onion (, grated (brown, white or yellow))","2 small carrots (, grated)","2 eggs","1/4 cup grated parmesan cheese","1/4 cup tomato ketchup (or tomato sauce)","1 cup panko (or breadcrumbs)","1 tsp garlic powder","1 tsp dried oregano","1 tsp dried thyme","1 tsp salt","Pepper"],"purpose":"Meatloaf Cupcakes"},{"ingredients":["2 large or 3 medium potatoes","1 tbsp butter (optional)","1/2 - 1 cup milk"],"purpose":"Mashed Potato"},{"ingredients":["Tomato ketchup or sauce","Parsley (, finely chopped (optional))"],"purpose":"Garnish"}]', '[{"description":"Meatloaf Cupcakes","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"description":"Spray 8 holes of a muffin tin.","images":[],"step":3},{"description":"Grate the onion and carrot straight into a large bowl.","images":[],"step":4},{"description":"Add remaining meatloaf ingredients and use your hands to mix and combine well.","images":[],"step":5},{"description":"Scoop up 1/2 cup of mince and use your hands to form a rough ball shape. Press into the muffin tin. The surface should be a slight dome shape.","images":[],"step":6},{"description":"Repeat with remaining mince. It should make about 8.","images":[],"step":7},{"title":"Bake for 20","description":"25 minutes until browned on top. Remove from oven.","duration":22.5,"images":[],"step":8},{"description":"Peel and dice the potato. Steam or boil until soft but not waterlogged.","images":[],"step":9},{"description":"Drain, then add butter and 1/2 cup of milk. Mash using a potato masher until smooth or to your liking. Add extra milk if you need it. The mash needs to be creamy but stiff enough to hold its shape when piped or piled onto the Meatloaf Cupcakes.","images":[],"step":10},{"description":"Smear a dollop of tomato ketchup on the Meatloaf Cupcakes.","images":[],"step":11},{"description":"Top with mashed potato, either by piping it or just dolloping it on with a spoon.","images":[],"step":12},{"description":"Serve with a sprinkle of parsley, if using.","images":[],"step":13}]', '["egg","milk"]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","most-popular","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d37889fcde81', 'en', 'US', 'Shepherd''s Pie Potato Skins', 'Don''t save the potato you scoop out for another dish - mash it and pile it on top to make these irresistible Shepherd''s Pie Potato Skins!', 'https://www.recipetineats.com/tachyon/2014/09/Shepherds-Pie-Potato-Skins-1.jpg', 5, 10, 15, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_frozen_mixed_vegetables", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 4.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["250 g / 8 oz lamb or beef mince (ground meat)","1 tbsp olive oil","½ onion ((brown, white or yellow), diced)","1 clove garlic (, minced)","1 1/2 cups frozen mixed vegetables (pea, corn, carrots) (or fresh)","2 tbsp flour","1 cup beef stock/broth (or 1 stock / bouillon cube dissolved in hot water)","½ cup water","½ tsp salt","½ tsp dried thyme","½ tsp dried oregano","Black pepper"]},{"ingredients":["4 large potatoes (, scrubbed clean (about 400g/13oz each))","½ to 1 cup milk (full or low fat)","2 tbsp butter (optional – but highly recommended)","Salt to taste"],"purpose":"Potatoes and Mash"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Prepare the Potatoes and Mash","images":[],"step":2},{"description":"Prick the potatoes with a fork (about 6 times on each potato) and microwave on high for 5 minutes. Then turn and microwave for a further 5 minutes. Pierce with a knife to check if they are cooked.","duration":5,"images":[],"step":3},{"description":"Remove from microwave (use a dish cloth). Cut off the tops and scoop out the center using a spoon, leaving a fairly thin skin (about 0.5 cm / 0.2”).","images":[],"step":4},{"description":"Place the potato scooped out in a bowl. Add milk, butter and salt and mash with a potato masher until smooth, or to your liking.","images":[],"step":5},{"description":"If you want to pipe the filling, place the mashed potato into a piping back with a large star tip nozzle.","images":[],"step":6},{"description":"Meanwhile, make the filling. Heat the olive oil in a large fry pan over medium high heat.","images":[],"step":7},{"description":"Add onion and garlic, sauté for 2 minutes until softened.","duration":2,"images":[],"step":8},{"description":"Turn up heat to high. Add mince beef (ground beef) and cook, breaking up the mince as you go, until nicely browned and cooked – about 3 minutes.","images":[],"step":9},{"description":"Sprinkle over flour and stir to combine.","images":[],"step":10},{"description":"Add remaining ingredients and stir to combine. Bring to simmer and continue to stir until the sauce is thick and glossy – around 2 minutes.","images":[],"step":11},{"description":"Remove from heat.","images":[],"step":12},{"description":"Assemble Potatoes","images":[],"step":13},{"description":"Fill each potato with the Filling so it is slightly heaped. Push down lightly to pack the filling in well.","images":[],"step":14},{"description":"Pipe over the mashed potato, or scoop it on with a spoon then fluff it up with a fork. You probably won’t use all of it – save the remainder or serve it on the side.","images":[],"step":15},{"description":"Place in the oven and bake for 15 to 20 minutes until the mashed potato is starting to brown on the ridges.","duration":17.5,"images":[],"step":16},{"description":"Serve immediately!","images":[],"step":17}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","most-popular","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0b052606b4c6', 'en', 'US', 'Goulash (Hungarian beef stew)', 'Recipe video above. The national dish of Hungary! Boldly flavoured with stacks of paprika, lots of onion, garlic and capsicum/bell peppers, with fall apart hunks of beef. It''s sort of a stew, sort of a soup. The broth is not supposed to be as thick as typical stews. It''s naturally thickened slightly using fresh tomatoes that break down into the sauce.Serve like soup in bowls with bread for dunking. (Try cheese bread. Obsessed!).', 'https://www.recipetineats.com/tachyon/2023/06/Hungarian-Goulash-_7.jpg', 15, 140, 155, 5, '[{"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.938, "unit": "jar of 40g"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 kg/2 lb beef chuck (, cut in 3.5cm / 1.5\" cubes (Note 1))","1 3/4 tsp cooking salt / kosher salt","1 tsp black pepper","1 tbsp extra virgin olive oil","2 tbsp/ 30g unsalted butter","2 brown onions (, cut into 1cm / 1/2\" squares)","5 garlic cloves (, finely minced)","2 capsicum/bell peppers ((1 red + 1 yellow), cut into 2 cm / 0.8\" squares)","2 tomatoes (, cut into 8 wedges then in half)","1/4 cup Hungarian-style paprika (sub ordinary paprika, Note 2)","1 tsp caraway seeds (, optional (Note 3))","1 bay leaf","1 litre / 4 cups beef stock/broth (, low-sodium)","2 carrots (, peeled, cut in quarters lengthwise then into 1cm / 0.4\" pieces)","2 potatoes (, cut into 1.2cm / 1/2\" cubes)","1 tbsp finely chopped parsley (, optional garnish)"]}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan), though you can use your slow cooker or stove instead (oven easiest! Note 4).","images":[],"step":1},{"title":"Season beef","description":"Toss the beef with half the salt and pepper.","images":[],"step":2},{"title":"Cook onion","description":"Heat the oil and melt the butter in a large oven-proof dutch oven over high heat. Cook onion for 6 minutes until the edges are light golden.","duration":6,"images":[],"step":3},{"title":"Cook beef","description":"Add the beef and stir until the outside changes from red to brown, about 2 minutes. It won''t go golden brown, it''s not supposed to.","images":[],"step":4},{"title":"Add vegetables","description":"Add garlic, capsicum and tomato. Stir for 3 minutes - the tomato will mostly breakdown.","duration":3,"images":[],"step":5},{"description":"Add paprika, caraway and bay leaf. Stir for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Slow cook","description":"Add beef stock, stir, bring to simmer. Cover with a lid and transfer to the oven for 1 1/2 hours.","images":[],"step":7},{"title":"Add potato","description":"The beef should be pretty tender but not quite \"fall-apart\". Stir in carrot and potatoes. Return to oven, covered, for another 30 minutes. Beef should now be \"fall-apart\" - if not, return to the oven for 10 minutes at a time.","duration":10,"images":[],"step":8},{"title":"Serve","description":"Ladle goulash into bowls and sprinkle with parsley. Eat as is, with optional bread for dunking! (Pictured with cheese bread)","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["European","Hungarian"],"categories":["beef-recipes","slow-cooked-fall-apart","soup-recipes","stews","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_46a7ff96a1d0', 'en', 'US', 'Beef Standing Rib Roast (Prime Rib)', 'Recipe video above. The juiciest, tastiest, BEST roast beef in the world is Prime Rib!! Also known as Standing Rib Roast, this is slathered in a herb and garlic butter, then roasted to juicy perfection. By using a lower but not super low oven temperature, we can be assured of a beautiful even cook throughout the whole roast, yet still have it on the table in a couple of hours. Bonus: lower temp = more forgiving! Meat thermometer is a MUST!', 'https://www.recipetineats.com/tachyon/2018/11/Standing-Rib-Roast_Prime-Rib_0.jpg', 10, 120, 130, 6, '[{"id": "ing_standing_rib_roast_prime_rib", "quantity": {"value": 2.5, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_beef", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.833, "unit": "bottle of 750ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}]', '[{"ingredients":["2.5 kg / 5 lb standing rib roast / prime rib (, bone in (Note 1))","1 onion (, unpeeled, quartered (brown, yellow, white))","1 head of garlic (, unpeeled, halved horizontally)","5 sprigs thyme","3 sprigs rosemary"]},{"ingredients":["150g/ 10 tbsp unsalted butter (, softened)","5 garlic cloves (, minced)","2 tsp finely chopped fresh rosemary (or 1 tsp dried)","2 tsp finely chopped fresh thyme (or 1 tsp dried)","2 tsp salt","1 tsp black pepper"],"purpose":"Garlic Herb Butter:"},{"ingredients":["1 1/2 cups beef broth/stock (, low salt)","2 1/2 cups dry red wine (Note 2)","1 tbsp cornflour/cornstarch (optional, Note 3)"],"purpose":"Red Wine Sauce:"}]', '[{"title":"Bring Beef to room temp","description":"Take beef out of the fridge 2 - 3 hours before cooking to bring to room temp (key tip for even cooking). Pat dry with paper towel.","images":[],"step":1},{"description":"Preheat oven to 240°C/460°F (220°C fan). Adjust shelf so beef will be sitting in the middle of the oven.","images":[],"step":2},{"title":"Garlic Herb Butter","description":"Mix together.","images":[],"step":3},{"title":"Roasting bed","description":"Place onion, garlic and herbs in a heavy based oven proof skillet (or use a roasting pan).","images":[],"step":4},{"title":"Slather 1","description":"Spread a thin layer of butter on the underside of the beef (ie the bone side). Place beef on onion etc, butter side down. Spread about 2/3 of the butter on the top and sides (reserve some for Slather 2).","images":[],"step":5},{"title":"Hot oven","description":"Roast 20 minutes.","images":[],"step":6},{"title":"Slather 2","description":"Remove, spread over remaining butter. Turn oven down to 120°C/250°F (100°C fan).","images":[],"step":7},{"title":"Slow roast","description":"Roast for a further 1 1/2 hours, basting every 30 minutes with the juices in the pan, until the internal temperature is 51°C / 123.8°F in the centre (for medium rare, Note 4). Start checking the internal temp early.","images":[],"step":8},{"title":"Rest","description":"Transfer beef to plate. Cover loosely with foil and rest for 20 - 30 minutes. Internal temperature will rise to 56-58°C / 133-136.4°F (which is medium rare).","duration":25,"images":[],"step":9},{"description":"Slice beef and serve with Sauce! For a classic high-end Steakhouse experience, serve with Paris Mash and Garlic Sautéed Spinach.","images":[],"step":10},{"description":"Red Wine Sauce:","images":[],"step":11},{"description":"Place skillet with onion and garlic left in it on the stove over high heat. Add wine and beef stock, rapidly simmer for 10 minutes until it reduces by 2/3 or so, down to 1 1/2 cups or liquid.","duration":10,"images":[],"step":12},{"description":"Lower heat to medium. Mix cornflour with 2 tbsp water. Drizzle in half and stir. Sauce will thicken in 1 minute or so. Add more cornflour water mixture if you want it thicker.","images":[],"step":13},{"description":"Strain into bowl, pour into sauce jug.","images":[],"step":14}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","iconic-dishes","main-dishes","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9cf1897bf5c6', 'en', 'US', 'Beef and Guinness Stew', 'RECIPE VIDEO ABOVE. The iconic Irish Beef and Guinness Stew is easy to make but requires patience while it slow cooks! The Guinness Beer is the secret weapon ingredient in this, creating a sauce that has wonderful deep complex flavours.', 'https://www.recipetineats.com/tachyon/2019/03/Irish-Beef-Guinness-Stew_6.jpg', 10, 180, 190, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.851, "unit": "pack of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 1.333, "unit": "bottle of 330ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 40.0, "unit": "head"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp olive oil","2.5 lb / 1.25 kg beef chuck (, boneless short rib or any other slow cooking beef (no bone))","3/4 tsp each salt and black pepper","3 garlic cloves (, minced)","2 onions (, chopped (brown, white or yellow))","6 oz / 180g bacon (, speck or pancetta, diced)","3 tbsp flour (all purpose/plain, Note 3 for GF)","440ml / 14.9 oz Guinness Beer (Note 1)","4 tbsp tomato paste","3 cups (750 ml) chicken stock/broth (or beef broth - Note 4)","3 carrots (, peeled and cut into 1.25 cm / 1/2\" thick pieces)","2 large celery stalks (, cut into 2cm / 1\" pieces)","2 bay leaves","3 sprigs thyme (or sub with 1 tsp dried thyme leaves)"]}]', '[{"description":"Cut the beef into 5cm/2\" chunks. Pat dry then sprinkle with salt and pepper.","images":[],"step":1},{"description":"Heat oil in a heavy based pot over high heat. Add beef in batches and brown well all over. Remove onto plate. Repeat with remaining beef.","images":[],"step":2},{"description":"Lower heat to medium. If the pot is looking dry, add oil.","images":[],"step":3},{"description":"Cook garlic and onion for 3 minutes until softening, then add bacon.","duration":3,"images":[],"step":4},{"description":"Cook until bacon is browned, then stir through carrot and celery.","images":[],"step":5},{"description":"Add flour, and stir for 1 minute to cook off the flour.","duration":1,"images":[],"step":6},{"description":"Add Guinness, chicken broth/stock and tomato paste. Mix well (to ensure flour dissolves well), add bay leaves and thyme.","images":[],"step":7},{"description":"Return beef into the pot (including any juices). Liquid level should just cover - see video or photos.","images":[],"step":8},{"description":"Cover, lower heat so it is bubbling gently. Cook for 2 hours - the beef should be pretty tender by now. Remove lid then simmer for a further 30 - 45 minutes or until the beef falls apart at a touch, the sauce has reduced and thickened slightly.","images":[],"step":9},{"description":"Skim off fat on surface, if desired. Adjust salt and pepper to taste. Remove bay leaves and thyme.","images":[],"step":10},{"description":"Serve with creamy mashed potatoes!!","images":[],"step":11}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Irish"],"categories":["beef-recipes","iconic-dishes","main-dishes","most-popular","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4030ba105eb5', 'en', 'US', 'Slow Cooker Beef Stroganoff', 'Recipe video above. The slow cooked version of Beef Stroganoff! Fall apart beef smothered in a creamy Stroganoff sauce with buttery garlic mushrooms, it''s made with economical stewing beef yet tastes like a million dollars! 3 cook methods provided: stove, slow cooker or pressure cooker/instant pot* Recipe update: pursuant to some readers having difficulties with flour lumps, the steps have been updated to make it easier!', 'https://www.recipetineats.com/tachyon/2020/02/Slow-Cooked-Beef-Stroganoff-Stew_9.jpg', 15, 510, 525, 6, '[{"id": "ing_beef", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 20.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.105, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.3, "unit": "jar of 200g"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.9, "unit": "tub of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_chives_for_garnish", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1.75kg/ 3.5lb beef chuck or other stewing beef (, cut in 4cm / 1.5” cube (Note 1))","1.5 tsp each salt and pepper","2 tbsp oil","20 g/ 1 tbsp butter (, unsalted)","1 large onion (, halved then sliced into 1 cm / 2/5\" slices)","4 garlic cloves (, minced)","7 tbsp flour (, plain / all purpose)","4 tbsp Dijon Mustard","1 litre / 1 quart beef stock/broth (, reduced salt)","1 1/2 cups sour cream (, full fat best)"]},{"ingredients":["3 tbsp/ 45 g butter (, unsalted)","700 g / 1.2 lb mushrooms (, sliced into 0.5cm thick slices)","3 garlic cloves (, finely minced)","1/2 tsp salt and pepper"],"purpose":"Garlic Butter Mushrooms:"},{"ingredients":["Pasta, wide egg noodles, mashed potato","Chives for garnish"],"purpose":"Serving:"}]', '[{"title":"Season beef","description":"Pat beef dry then sprinkle with all the salt and pepper.","images":[],"step":1},{"title":"Brown beef","description":"Heat 1 tbsp oil in a large heavy based pot or skillet* over high heat. Add beef in a single layer (not squished) and brown aggressively all over - 4 minutes or so. Remove and repeat with rest of beef, adding more oil as needed.","images":[],"step":2},{"title":"Sauté aromatics","description":"Let the pot cool down a bit then return to stove. Melt half the butter, then cook garlic and onion for 3 minutes until softened.","duration":3,"images":[],"step":3},{"title":"Add flour","description":"Sprinkle the flour across the surface, then stir. Add the mustard, and stir - it will look gluey, that''s ok, it will dissolve.","images":[],"step":4},{"title":"Add stock","description":"While stirring, pour in about half the beef stock then mix so the flour mixture dissolves into the liquid. It will thicken quite quickly into a gravy-like consistency .Switch to a whisk if needed, to make it lump free. Then add remaining stock, stir well, scraping the bottom of the pot, and bring to simmer. Cook using chosen method below.","images":[],"step":5},{"title":"SLOW COOKING","description":"choose method:","images":[],"step":6},{"title":"Slow cooker","description":"Transfer all liquid into slow cooker. Add beef, then slow cook 8 hours on LOW or 5 hours on HIGH.","images":[],"step":7},{"title":"Stove","description":"Add beef into pot. Cover with lid and adjust heat to low/medium low so the it''s simmering gently. Simmer 2 hrs (check at 1.5 hrs) until beef beef falls apart easily.","images":[],"step":8},{"title":"Instant pot","description":"SKIP FLOUR, follow Note 5 Gluten Free option. 40 minutes on high, same method as slow cooker.","images":[],"step":9},{"title":"Other pressure cookers","description":"40 minutes on high, same method as slow cooker.","images":[],"step":10},{"description":"Melt half the butter in a large skillet over high heat. Add half the mushrooms and cook until almost golden (~3 minutes). Add half the garlic, salt and pepper, cook until golden. Remove, repeat with remaining butter, mushrooms and garlic.","images":[],"step":11},{"description":"Mix sour cream with 1.5 cups of liquid from slow cooker (Note 2), then gently stir into stew - careful, the beef is delicate!","images":[],"step":12},{"description":"Gently stir in mushrooms.","images":[],"step":13},{"description":"Serve over noodles, pasta or mashed potato, sprinkled with chives!","images":[],"step":14}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Russian(ish)","Western"],"categories":["beef-recipes","slow-cooked-fall-apart","slow-cooker-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca60c453049b', 'en', 'US', 'Pot Roast', 'Recipe VIDEO above. The ultimate one-pot family meal! Meltingly tender slow cooker beef and vegetables smothered in a gravy like sauce - because it''s so much tastier than just a watery broth! I like to make this in my slow cooker but I''ve also added directions for pressure cooker, stove and oven.', 'https://www.recipetineats.com/tachyon/2018/09/Slow-Cooker-Beef-Pot-Roast-4.jpg', 15, 500, 515, 8, '[{"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 750.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["2 kg / 4 lb beef chuck roast , rolled (Note 1)","1 tsp each salt and pepper","2 tbsp olive oil","1 onion ((large), cut into large dice)","5 garlic cloves (, peeled and smashed (Note 2a))","5 carrots (, peeled and cut into 2.5cm/1\" pieces)","3 celery stalks (, cut into 4 cm / 1.5\" pieces)","1 cup (250ml) dry red wine (sub with beef broth)","3 cups (750ml) beef broth (, salt reduced)","1/3 cup (50g) flour (plain / all purpose) (GF - Note 2b)","1 tsp dried rosemary","1 1/2 tsp dried thyme","750g / 1.5 lb potatoes (, peeled and cut into 2.5 cm / 1\" pieces)"]}]', '[{"description":"Pat beef dry with paper towels. Sprinkle generously with salt and pepper all over.","images":[],"step":1},{"description":"Heat oil in a skillet over high heat. Brown aggressively all over - a deep dark brown crust is essential for flavour base! Should take about 7 minutes.","images":[],"step":2},{"description":"Transfer beef to slow cooker.","images":[],"step":3},{"description":"In the same skillet, add onion and garlic. Cook for 2 minutes until onion is browned.","duration":2,"images":[],"step":4},{"description":"Add wine, reduce by half. Transfer to slow cooker.","images":[],"step":5},{"description":"Mix together flour and about 1 cup of the broth. Lumps is fine. Pour into slow cooker.","images":[],"step":6},{"description":"Add remaining broth, carrots, celery, rosemary and thyme into slow cooker.","images":[],"step":7},{"description":"Cover and slow cook on LOW for 5 hours. (45 min pressure cook on HIGH, Note 3a for Oven and Stove)","images":[],"step":8},{"description":"Add potato, slow cook on LOW for 3 hours. (10 min pressure cooker on HIGH, Note 3b)","images":[],"step":9},{"description":"Remove beef. Rest for 5 minutes, then slice thickly.","duration":5,"images":[],"step":10},{"description":"Adjust salt and pepper of Sauce to taste.","images":[],"step":11},{"description":"Serve beef with vegetables and plenty of sauce! Bread also terrific for mopping up sauce - try these No Knead Dinner Rolls, No Yeast Irish Soda Bread or these fabulous Cheese Muffins.","images":[],"step":12}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","main-dishes","nagis-picks","one-pot-recipes","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39a03d526671', 'en', 'US', 'How to cook steak - like a chef!', 'Recipe video above. Here''s a cheffy way to cook steak that really makes the most of a good steak - or fancies up economical steaks! Basting with garlic-thyme infused butter as the steak is cooking adds flavour and luxury to the steak. You''ll feel like a total pro cooking it and it''ll rival the best steakhouse in town!', 'https://www.recipetineats.com/tachyon/2019/07/Cheffy-Garlic-Butter-Steak_9.jpg', 5, 6, 11, 1, '[{"id": "ing_fish_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.24, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 - 2 boneless ribeye or scotch fillet (, 2.5 cm / 1\" thick, approx 300g/10 oz each (Note 1))","1 tbsp vegetable oil","Salt and pepper","75g / 5 tbsp unsalted butter (, cut into 1.25cm / 1/2\" cubes (Note 2))","6 sprigs fresh thyme or 3 sprigs rosemary","5 garlic cloves (, peeled and smashed to split (Note 3))"]}]', '[{"title":"Bring to room temp","description":"Take the steak out of the fridge 30 minutes prior to bring to room temperature.","images":[],"step":1},{"title":"Dry steaks","description":"Pat dry with paper towels.","images":[],"step":2},{"title":"Heat skillet","description":"Heat oil in a heavy based skillet over high heat until it is very hot - you should see smoke!","images":[],"step":3},{"title":"Season","description":"Sprinkle each side of the steak generously with salt and pepper, then immediately place in the skillet.","images":[],"step":4},{"title":"Sear Side 1: Cook for 2","description":"2.5 minutes until you get a great crust, then turn.","images":[],"step":5},{"title":"Garlic Butter","description":"Leave for 1 minute, then push steaks to one side and toss in butter, garlic and thyme. BE CAREFUL - the thyme will sputter!","duration":1,"images":[],"step":6},{"title":"Baste","description":"As soon as the butter is melted, continuously spoon the butter over the steak until it''s cooked to your liking - 2 minutes in total for the 2nd side for medium rare (52C/125F, chart below for other doneness temps)","images":[],"step":7},{"title":"Basting also renders fat on the side of the steak","description":"use tongs to sear the edges at the end if you want it browned more.","images":[],"step":8},{"title":"Rest","description":"Transfer steak to a plate and cover loosely with foil, rest for 5 to 10 minutes.","duration":7.5,"images":[],"step":9},{"description":"Serve steak with a bit of the butter from the skillet drizzled on top. Pictured in post with Crispy Smashed Potatoes.","images":[],"step":10}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","dinner-tonight","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c2328cd05d7d', 'en', 'US', 'Mexican Shredded Beef (and Tacos)', 'Recipe video above. This is how I make Mexican Shredded Beef. The sauce is rich, thick and full of flavor, and the beef is very tender and juicy. I use this shredded beef for tacos, burritos, enchiladas, quesadillas and even to make sliders - see in post for list of ideas and directions!', 'https://www.recipetineats.com/tachyon/2015/09/Mexican-Shredded-Beef_1.jpg', 20, 180, 200, 20, '[{"id": "ing_chipotle", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.361, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 10.0, "unit": "pack of 1kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}]', '[{"ingredients":["1 1/2 tbsp chipotle powder (, adjust spiciness to taste (Note 5))","1 tbsp paprika","1 tbsp dried oregano","1 tsp All Spice powder (ground All Spice)","1 tsp coriander powder","2 tsp onion powder or garlic powder (OR 1 tsp of each)","1 tsp salt and pepper (, each)"],"purpose":"Spice Mix"},{"ingredients":["1 - 2 tbsp olive oil","3 lb / 1.5kg beef chuck or brisket ((or gravy or any other slow cooking beef) cut into 4 pieces)","5 garlic cloves, minced","1 onion (, diced (yellow, brown or white))","3/4 cup (185 ml) orange juice","2 tbsp lime juice","14 oz / 400g can crushed tomatoes","2 cups (500 ml) beef or chicken broth/stock","1/2 cup (125ml) water","Salt and pepper"],"purpose":"Beef"}]', '[{"description":"Combine the Spice Mix ingredients in a bowl. Sprinkle 4 teaspoons over the beef and pat so it sticks.","images":[],"step":1},{"description":"Heat the olive oil in a large heavy based pot over high heat. Add the beef (in batches if necessary) and brown well on all sides. Remove onto a plate.","images":[],"step":2},{"description":"Turn the stove down to medium. If the pot looks dry, add more olive oil.","images":[],"step":3},{"description":"Add the garlic and onion and cook for 3 minutes until soft.","duration":3,"images":[],"step":4},{"description":"Add the orange juice and lime juice, and scrape the bottom of the pot so the brown bits mix into the liquid.","images":[],"step":5},{"description":"Add tomato, beef stock, water and remaining spice mix. Mix, then return beef into pot.","images":[],"step":6},{"description":"Put the lid on, bring to a simmer then turn the stove down so it is bubbling gently, not rapidly.","images":[],"step":7},{"description":"Cook for 2 hours, then remove lid and simmer for another 30 minutes until beef is tender enough to shred. (Note 2 other cook methods).","images":[],"step":8},{"description":"Remove the beef from sauce, shred with 2 forks.","images":[],"step":9},{"description":"Leave the sauce to simmer with the lid off for 10 to 15 minutes to reduce and thicken to your taste. Adjust salt to taste. Optional: puree with stick blender to make it smooth (I do this for company)","duration":12.5,"images":[],"step":10},{"description":"Toss beef back into the sauce (can reserve some Sauce for drizzling on tacos if you want, there''s plenty).","images":[],"step":11},{"description":"Transfer beef into large dish and serve. See notes for suggestions.","images":[],"step":12},{"description":"To make tacos, serve the beef with warmed small tortillas, avocado slices, Pico de Gallo, shredded cheese, sour cream, lime wedges and extra cilantro/coriander leaves.","images":[],"step":13}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-recipes","dietary","gluten-free-recipes","main-dishes","mexican-recipes","quick-and-easy","slow-cooker-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b81fef89157c', 'en', 'US', 'Marinated Roast Beef', 'Recipe video above. Use this marinade to transform economical roast beef into something special! It will infuse with flavour, add juiciness and make the beef tender. KEY TIP: internal temp of beef rises by 8C/14F while resting, so must take out of oven BEFORE desired internal temp, see Note 4. Marinade 2 - 3 days.', 'https://www.recipetineats.com/tachyon/2019/05/Marinated-Roast-Beef_7-1.jpg', 10, 70, 80, 6, '[{"id": "ing_bolar_blade_top_blade_roast_eye_of_round_roast_oyster_blade_roast", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 3.0, "unit": "bag of 2kg"}}, {"id": "ing_carrot", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.375, "unit": "kg"}}]', '[{"ingredients":["1.5kg / 3 lb Bolar Blade (pictured in post), Top Blade Roast, Eye of Round Roast, Oyster Blade Roast","1 tbsp olive oil"]},{"ingredients":["3 garlic cloves (, minced (2.5 tsp jar))","1 tbsp Worcestershire Sauce","2 tbsp dijon mustard","2 1/2 tbsp balsamic vinegar","1/2 cup soy sauce","1/4 cup olive oil","1 tbsp white sugar","2 tsp onion powder","1 tsp black pepper","2 tsp dried thyme","1 tsp dried rosemary"],"purpose":"Marinade (Note 2):"},{"ingredients":["3 potatoes (, cut into 5cm/2\" chunks)","4 carrots (, peeled cut into 4cm/1.7\" pieces)","Salt and pepper"],"purpose":"Vegetables (optional):"},{"ingredients":["1/4 cup flour","2 1/2 cups beef broth ((stock), low sodium)","3/4 tsp black pepper (, coarsely ground)"],"purpose":"Gravy (optional, Note 4)"}]', '[{"description":"Mix Marinade ingredients in a large ziplock bag.","images":[],"step":1},{"description":"Add beef, marinade for 2 days (24 hrs min, 3 days max).","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"title":"De-chill","description":"Take beef out of fridge 1 hour prior.","images":[],"step":4},{"description":"Preheat oven to 240C/450F (both fan and regular ovens).","images":[],"step":5},{"title":"Toss vegetables","description":"Put the vegetables in an ovenproof skillet. Remove beef from marinade. Pour all the marinade onto the vegetables and toss. Top with the beef.","images":[],"step":6},{"title":"High temp roast","description":"Drizzle beef with oil, roast 20 minutes.","images":[],"step":7},{"title":"Keep roasting","description":"Turn oven down to 180C/350F (160C fan-forced), roast for a further 35 - 40 minutes or until a meat thermometer inserted into the centre registers 44°C / 111°F for medium rare (Note 3 for other doneness). Note - thinner and smaller pieces than pictured / per ingredients will cook faster, so check earlier!","images":[],"step":8},{"title":"Rest","description":"Remove beef onto plate, cover loosely in foil and rest for 20 - 30 minutes (internal temp will rise to 52°C / 125°F which is perfect medium rare!).","duration":25,"images":[],"step":9},{"title":"Brown vegetables","description":"Return vegetables to oven to brown a bit, if needed.","images":[],"step":10},{"description":"To serve, slice beef thinly. Serve roast veg and juices in the skillet OR make gravy (below)!","images":[],"step":11},{"description":"Gravy (optional)","images":[],"step":12},{"description":"Remove vegetables, leave juices in skillet. Skim excess off fat from surface, leave behind 2 tbsp.","images":[],"step":13},{"title":"Flour","description":"Place on medium high heat on stove. Add flour and stir for 1 minute.","duration":1,"images":[],"step":14},{"title":"Stock","description":"Slowly add beef stock while stirring. If needed, use whisk to remove lumps.","images":[],"step":15},{"title":"Thicken","description":"Bring to simmer for 2 minutes until thickens to gravy consistency. Stir in pepper and salt, if needed (taste to check). Serve with beef.","duration":2,"images":[],"step":16}]', '["gluten","mustard","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","iconic-dishes","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1203f6abcbd2', 'en', 'US', 'Schnitzel!', 'Recipe VIDEO above. Golden brown and extra crunchy schnitzel. No need to deep fry, just shallow fry it. Make schnitzel with pork, chicken, veal, beef or turkey! These are quite big - about 22 cm/ 9" long, but they are thin.', 'https://www.recipetineats.com/tachyon/2017/08/Schnitzel-11.jpg', 10, 15, 25, 4, '[{"id": "ing_pork", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_turkey_breast_cutlets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["600g / 1.2 lb boneless pork (4 steaks / boneless chops, about 150 g/5 oz each)","600g / 1.2 lb large chicken breasts (2 pieces,300g / 10 oz each)","600g / 1.2 lb veal or beef steaks (4 pieces, 150g / 5 oz each)","600g / 1.2 lb turkey breast cutlets (4 pre sliced pieces, 150g / 5 oz each)"],"purpose":"Choose ONE of these:"},{"ingredients":["Salt and pepper","3/4 cup flour","2 eggs","1 1/2 cups panko breadcrumbs (Note 1)","Oil for frying (canola, vegetable)"],"purpose":"Schnitzel:"}]', '[{"title":"Chicken breast prep","description":"cut in half horizontally to create two steaks.","images":[],"step":1},{"description":"Place the protein of choice on a work surface and cover with a sheet of baking paper or cling wrap. Use a rolling pin to pound to even thickness about 0.8 cm / 1/3\" thick (don''t pound too thin, hard to handle / might tear).","images":[],"step":2},{"description":"Sprinkle both sides of meat with salt and pepper.","images":[],"step":3},{"description":"Place flour in one dish, panko in another (or use a large tray for both like I did, see photos), and whisk eggs in a bowl.","images":[],"step":4},{"description":"Coat meat in flour, shake off excess. Dip into egg, shake off excess. Press into breadcrumbs, and turn, pressing to adhere, then transfer to plate. Repeat.","images":[],"step":5},{"description":"Heat 1.5cm / 3/5\" oil in a heavy based deep skillet over medium high heat.","images":[],"step":6},{"description":"Dip the end of a schnitzel in to check if the oil is hot enough - it should sizzle straight away (see video).","images":[],"step":7},{"description":"Carefully place 2 schnitzels in the oil and cook for 3 minutes until deep golden, turn then cook the other side for 3 minutes.","duration":3,"images":[],"step":8},{"description":"Transfer to a paper towel lined plate to drain excess oil. Repeat with remaining schnitzel.","images":[],"step":9},{"title":"Serve with lemon wedges","description":"I usually serve schnitzel plain like this. Or see note for Mushroom Gravy recipe. Also see note for potato rosti, pictured in post.","images":[],"step":10}]', '["egg","gluten"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Austrian","German","Western"],"categories":["beef-recipes","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","dinner-tonight","main-dishes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a62f6300e01c', 'en', 'US', 'Braised Beef Short Ribs in Red Wine Sauce', 'Recipe video above. This is the sort of food you''ll pay top dollar for at fine dining restaurants but is actually very easy to make at home. Wine provides complexity and depth of flavour so you only need a few ingredients! Oven is best but stove/slow cooker/pressure cooker/IP also work, directions in notes.', 'https://www.recipetineats.com/tachyon/2019/02/Slow-Cooked-Braised-Beef-Short-Ribs_3.jpg', 15, 180, 195, 5, '[{"id": "ing_beef_steak", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.667, "unit": "bottle of 750ml"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["5 - 6 beef short ribs (, 300-400g/10-14oz each (Note 1))","1.5 tsp each salt and pepper","2 tbsp olive oil","3 garlic cloves (, crushed)","1 large onion (, chopped (brown, yellow or white))","2 celery ribs (, chopped)","2 carrots (, chopped)","2 tbsp tomato paste","2 cups (500ml) dry red wine (Note 2)","2 cups (500ml) beef stock/broth, low sodium","2 sprigs thyme (optional)","2 bay leaves"]}]', '[{"description":"Preheat oven to 160°C/325°F.","images":[],"step":1},{"description":"Sprinkle beef all over with salt and pepper.","images":[],"step":2},{"description":"Heat oil in a large ovenproof pot over high heat. Add half the ribs and brown aggressively all over (~5 - 7 min in total). Remove and repeat with remaining ribs, then remove.","images":[],"step":3},{"description":"Turn heat down to medium. Add onion and garlic into the same pot and cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add carrot and celery, cook for 5 minutes until carrot is softened and sweet.","duration":5,"images":[],"step":5},{"description":"Add tomato paste and cook for 1 minute.","duration":1,"images":[],"step":6},{"description":"Add wine, broth, thyme and bay leaves. Stir until tomato paste is dissolved.","images":[],"step":7},{"description":"Return beef into liquid, arranging them so they are submerged (Note 3).","images":[],"step":8},{"description":"Cover with lid and transfer to oven for 3 hours, or until the meat can easily be pried apart with forks. (Note 4 Other cook methods)","images":[],"step":9},{"description":"Remove beef carefully, keeping the meat on the bone. (Note 4) Cover to keep warm.","images":[],"step":10},{"description":"Strain all liquid in the pot, pressing juices out of the onion, carrot etc. (Optional - can skip if you don''t mind chunky sauce) Return sauce into pot, bring to simmer and stir. Adjust as necessary - simmer to reduce/thicken, add water to thin, season with salt and pepper if needed.","images":[],"step":11},{"description":"Place beef on serving plate, spoon over sauce. Serve!","images":[],"step":12}]', '[]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-recipes","iconic-dishes","slow-cooker-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0fc950cea8d9', 'en', 'US', 'Beef Stew', 'Recipe VIDEO above. Just a great, classic beef stew with meltingly tender beef smothered in a rich sauce. Be sure to brown the beef well - it''s key for the deep rich colour and flavour of the sauce! Great on the day, but even better the next day so make ahead if you can. Stove, oven, slow cooker or pressure cooker.', 'https://www.recipetineats.com/tachyon/2018/04/Beef-Stew_0.jpg', 15, 160, 165, 6, '[{"id": "ing_beef", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.667, "unit": "bottle of 750ml"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.16, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 400.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}]', '[{"ingredients":["1.2 kg / 2.4lb chuck beef (, cut into 3.5 cm / 1.5\" cubes (Note 1))","1 tsp each salt and pepper","3 tbsp olive oil (, divided)","1 large onion (, halved then cut into 1 cm / 2/5\" slices)","4 garlic cloves (, minced)","3 carrots (, cut into 2.5cm / 1\" pieces on the diagonal)","2 celery stalks (, cut into 2.5 cm / 1\" pieces)","1/3 cup / 50g flour","3 cups / 750ml beef broth / stock (, salt reduced)","2 cups / 500 ml red wine (, bold and dry (Cab Sauv, Burgundy, Merlot) (Note 2))","2 tsp Worcestershire Sauce","2 tbsp tomato paste","2 bay leaves (, fresh or dried)","4 sprigs thyme","400 g / 14 oz baby potatoes (, halved)","More salt and pepper (, to taste.)"]}]', '[{"description":"Sprinkle beef with salt and pepper.","images":[],"step":1},{"description":"Heat 1 1/2 tbsp oil in a large, heavy based casserole pot over high heat until just starting to smoke.","images":[],"step":2},{"description":"Add 1/3 of the beef and brown aggressively all over - about 4 minutes. Remove to bowl, repeat with remaining beef, adding more oil if required.","images":[],"step":3},{"description":"Turn down heat to medium high. Add 1 tbsp oil if required. Add onion and garlic, cook for 2 minutes until onion is softened slightly and golden on the edge.","duration":2,"images":[],"step":4},{"description":"Add carrot and celery, stir for 1 minute to coat in flavours.","duration":1,"images":[],"step":5},{"description":"Sprinkle flour evenly across surface, then stir to coat.","images":[],"step":6},{"description":"Add broth, red wine, tomato paste and Worcestershire sauce. Stir to dissolve tomato paste and flour into liquid.","images":[],"step":7},{"description":"Add cooked beef (including any juices), thyme, bay leaf and potato. Stir. Water level should almost fully cover everything (see video), if not, add a touch of water.","images":[],"step":8},{"description":"Bring to simmer, then adjust heat to low / medium low so it''s simmering gently. (Note 3 for other cooking methods)","images":[],"step":9},{"description":"Cover and cook for 1 hour 45 minutes or until beef is pretty tender (check with 2 forks at 1.5 hrs).","images":[],"step":10},{"description":"Remove lid and simmer for further 30 minutes or until sauce reduces slightly. It should be like a thin gravy (see video) and beef should now be very tender.","images":[],"step":11},{"description":"Season to taste with salt and pepper.","images":[],"step":12},{"description":"Serve over creamy mashed potato with a sprig of fresh thyme for decoration or a sprinkle of parsley (Note 4).","images":[],"step":13}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-recipes","dinner-tonight","main-dishes","one-pot-recipes","quick-and-easy","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2c740108b09', 'en', 'US', 'Homemade Pastrami Without a Smoker', 'Recipe video above. This is an easy homemade Pastrami for all the poor sods like myself who don''t live around the corner from a New York Jewish deli. Tender, juicy and with the signature pastrami spice crust, this is astonishingly straight forward to make - and is outrageously good!ALSO - use the pastrami to make homemade Rebuen sandwiches!', 'https://www.recipetineats.com/tachyon/2014/05/Homemade-Pastrami-slices.jpg', 20, 660, 680, 6, '[{"id": "ing_beef", "quantity": {"value": 1.814, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.2, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_liquid_smoke", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["4 lbs / 2kg good corned beef, with a thick fat cap (Note 1)"]},{"ingredients":["4 tbsp fresh coarsely ground black pepper","2 tbsp coriander powder","1 1/2 tsp mustard powder","1 tbsp brown sugar","1 tbsp smoked paprika","2 tsp garlic powder","2 tsp onion powder","2 tbsp liquid smoke (optional)"],"purpose":"Spice Mix:"}]', '[{"description":"Mix Spice Mix and spread out on a tray. Pat beef dry then roll in Spice Mix, coating well all over. Sprinkle with liquid smoke it using (I rarely use this).","images":[],"step":1},{"description":"Place beef fat cap side down and wrap in a large sheet of foil. Repeat again with another sheet of foil and flip the beef so the fat cap is on the top.","images":[],"step":2},{"description":"Place rack in slow cooker (Note 2), place beef on rack. Slow cook for 10 hours on low or electric pressure cook for 1 hour 40 minutes (see notes for oven).","images":[],"step":3},{"description":"Remove beef, cool then refrigerate for 6 hours +. Reserve juices in slow cooker.","images":[],"step":4},{"description":"Unwrap beef. Place rack on tray, place beef on rack. Bake 30 minutes at 180C/350F until spice crust is set.","images":[],"step":5},{"title":"Remove from oven, slice thinly","description":"pastrami will be tender. Place some pastrami in a dish, spoon over a bit of reserved juices. Cover and microwave to warm (I like to add a slice of Swiss cheese).","images":[],"step":6},{"title":"New York Deli style Pastrami Sandwich","description":"Pile high on toasted rye bread slathered with plenty of mustard of choice. Serve with pickles on the side! Plus plain potato crisps (for the full deli experience!)","images":[],"step":7},{"title":"Rebuen sandwiches","description":"see this recipe.","images":[],"step":8}]', '["mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["American"],"categories":["beef-recipes","iconic-dishes","main-dishes","quick-and-easy","sandwiches-and-sliders","slow-cooker-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_46e230f6c472', 'en', 'US', 'Epic Chunky Beef and Mushroom Pie', 'Tender, fall apart chunks of beef with mushrooms in the most incredible gravy ever. The secret ingredient - Dried Porcini Mushrooms! They add a savoury earthiness that can''t be replicated and takes this pie to the next level.', 'https://www.recipetineats.com/tachyon/2017/06/Beef-Mushroom-Pie-6.jpg', 15, 150, 165, 6, '[{"id": "ing_mushroom", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_dark_ale", "quantity": {"value": 300.0, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.3, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}]', '[{"ingredients":["20 g / 0.7 oz dried porcini mushrooms (slices, whole or chopped) (Note 1)","1 ¼ cups / 312 ml boiled water","1 kg / 2 lb chuck beef (, cut into 2.5cm/1” cubes (Note 2))","1 - 2 tbsp vegetable oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 celery (, finely chopped)","1 carrot (, finely chopped)","3 carrots (, halved lengthwise then cut into 1.5cm/ 3/5” chunks)","1/3 cup flour (any)","300 ml / 10 oz dark ale (or substitute with red wine, Guinness or more beef stock)","2 cups / 500 ml beef stock","3 sprigs thyme or 1 tsp dried thyme leaves","2 bay leaves (, fresh or dried)","200 g / 7 oz bacon (, diced)","300 - 400g / 10 – 13 oz Swiss brown mushrooms (, larger ones halved)","1 – 2 sheets puff pastry (enough to cover pie)","1 egg yolk"]}]', '[{"description":"Place porcini in a bowl and add hot water. Leave to soak for at least 30 minutes. Strain mushrooms and reserve soaking liquid. Roughly chop porcini.","images":[],"step":1},{"description":"Sprinkle beef with salt and pepper.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large heavy based pot. Add half the beef and brown all over, then remove and repeat with remaining beef. Set beef aside.","images":[],"step":3},{"description":"Turn stove down to medium low. If the pot is looking dry, add more oil. Add onion and garlic, cook for 2 minutes. Add finely chopped carrots and celery, cook for 6 minutes or until softened and sweet (taste test!). Add carrot chunks and cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add flour and stir through.","images":[],"step":5},{"description":"Add ale, beef stock, and stir to dissolve the flour.","images":[],"step":6},{"description":"Add thyme, bay leaves, porcini, reserved porcini soaking liquid (don’t tip in gritty bits settled at bottom) and cooked beef. Turn heat up slightly, mix, bring to simmer, then cover. Adjust heat so it is simmering gently, not energetically.","images":[],"step":7},{"description":"Cook for 1 hr 45 minutes or until beef is tender. (See video)","duration":60,"images":[],"step":8},{"description":"Meanwhile, cook bacon in a skillet over high heat until golden. Remove and reserve bacon drippings in pan. Add mushrooms and cook for 5 minutes until golden all over. Return bacon into skillet, toss to coat mushrooms, then stir through stew.","duration":5,"images":[],"step":9},{"description":"Simmer stew, uncovered, for 15 minutes until mushrooms are tender. Then remove from stove and cool.","duration":15,"images":[],"step":10},{"description":"To cook:","images":[],"step":11},{"description":"Preheat oven to 200C/390F.","images":[],"step":12},{"description":"Pour stew into a pie dish, even out surface. Pictured pie dish is 24 x 20 x 4.5 cm / 10 x 8 x 1.8\" (1.5L / 1.5 Qt) - see Notes for more conversions.","images":[],"step":13},{"description":"Top with puff pastry (if too big, just fold the ends in), brush with egg yolk. Cut a few slits in the surface then bake for 30 – 35 minutes until deep golden and the filling is piping hot in the middle (stick a knife in to check).","duration":32.5,"images":[],"step":14},{"description":"Rest for 5 minutes before serving!","duration":5,"images":[],"step":15}]', '["egg","gluten"]', '[]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-recipes","iconic-dishes","main-dishes","mushroom-recipes","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eea747ed0c94', 'en', 'US', 'Shredded Beef Burritos', 'Crispy burritos filled with juicy Mexican Shredded Beef with a rich sauce, Mexican red rice and cheese. These are MADE for freezing - perfect standby meal! This recipe is for 8 burritos. However, 1 batch of Mexican Shredded Beef makes enough for around 15 burritos. If you aren''t freezing the burritos, feel free to add other things inside such as avocado, fresh salsa, pico de gallo, lettuce and tomato! (These are not suitable for freezing which is why I don''t use them)', 'https://www.recipetineats.com/tachyon/2015/09/Beef-Burritos_600px_1-Featured.jpg', 15, 10, 25, 8, '[{"id": "ing_tortillas", "quantity": {"value": 1000.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_beef", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}]', '[{"ingredients":["8 large extra soft flour tortillas (10\"/26cm)","1 1/2 to 2 cups shredded cheese (I used Monterey Jack)","3 to 4 cups Mexican Shredded Beef plus sauce (, tossed or separated (Note 1))","2 cups Mexican Red Rice","400g/14oz can corn kernels (, drained)","400g/14oz can black beans (, drained)"]}]', '[{"description":"Microwave half the tortillas very briefly to warm them up (15 seconds or so). This ensures they don''t crack when you roll them.","images":[],"step":1},{"title":"Place 1 tortilla on a workbench","description":"cover the rest with a tea towel to keep them warm.","images":[],"step":2},{"description":"Place cheese down the middle of the tortilla, then top with 1/3 cup of beef, some corn, beans, then 1/4 cup rice.","images":[],"step":3},{"description":"Roll the burrito up. (Note 2) Wrap in foil to hold it together.","images":[],"step":4},{"description":"If you are serving it immediately, heat a skillet over medium heat. Cook the burritos for around 4 to 5 minutes on each side to make the tortilla brown and heat the inside through.","images":[],"step":5},{"description":"If freezing, place in the freezer. To reheat, you can either bake from frozen (with foil on) at 350F/180C for about 40 to 45 minutes, or thaw and cook in the skillet per above. You could microwave it (remove the foil) but I like my burritos a bit crispy!","images":[],"step":6}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-recipes","burritos","dietary","gluten-free-recipes","mexican-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_763a53d45d79', 'en', 'US', 'Pide - Turkish Flat Bread / Pizza', 'Recipe video above. It''s hard to get great pide outside of Turkey. It''s hit and miss, even at many Turkish places. Solution: make it yourself! Pide is easier than you think, and it will tick all your pide boxes: pillowy soft bread inside with a crispy base, generous on the toppings. SO GOOD!Makes 2 pide around 40cm / 16" long. A generous meal for 2 people, normal meal for 3 people!TOPPINGS – Choose only 1. Each batch is enough to top 2 pides.', 'https://www.recipetineats.com/tachyon/2021/05/Platter-of-pide.jpg', 30, 30, 60, 2, '[{"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.375, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_semolina", "quantity": {"value": 2.5, "unit": "pack"}}, {"id": "ing_topping_of_choice", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_sprinkling_finishes_of_choice", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 280.0, "unit": "bag of 250g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sausages", "quantity": {"value": 0.25, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baharat_spice_mix", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_sumac", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}]', '[{"ingredients":["1 tsp rapid rise / instant yeast (sub active dry yeast, Note 1)","1/2 tsp white sugar","2 tbsp + 2/3 cups very warm water (, (~40℃ /104℉, Note 2))","2 cups bread flour (sub all purpose/plain flour, Note 3)","3/4 tsp salt","1 1/2 tsp olive oil"],"purpose":"Dough (Makes 2 pide):"},{"ingredients":["150g / 5oz Turkish kasar cheese or mozzarella (Note 4)","1/2 tsp semolina (, optional (Note 10))","1 Topping of choice (each makes enough for 2 pides)","1 egg (optional, Note 13)","Sprinkling finishes of choice (listed below)"],"purpose":"Pide Assembling:"},{"ingredients":["2 tsp olive oil","1/2 onion (, finely diced)","280g / 10oz baby spinach","1/2 tsp cumin","1/2 tsp pepper","1/4 tsp salt (kosher / cooking salt)"],"purpose":"Spinach Topping:"},{"ingredients":["125g / 4oz Turkish sujuk sausage (sub chorizo, Note 5)"],"purpose":"Turkish Sausage Topping (Sujuk):"},{"ingredients":["1 tbsp olive oil","1/2 onion (, finely diced)","1 garlic cloves (, finely minced)","250g / 8oz lamb mince (or beef)","1 tsp tomato paste","1 tsp baharat spice mix (Note 6)","1/2 tsp cumin","1/8 tsp each salt and pepper","1/2 red capsicum / bell pepper (, finely diced)","1/2 tomato (, finely chopped)","1 tsp lemon juice"],"purpose":"Lamb Topping:"},{"ingredients":["4 tbsp Turkish tulum cheese or feta (, crumbled (Note 7))","Dried oregano","Sesame seeds (, toasted)","Sumac","Fresh coriander/cilantro leaves","Extra virgin olive oil"],"purpose":"Sprinkling Finishes – Choose (Note 11):"}]', '[{"title":"Bloom yeast","description":"Mix yeast with 2 tbsp warm water and sugar in a small bowl. Cover with cling wrap, leave for 10 minutes until foamy.","duration":10,"images":[],"step":1},{"title":"Make dough","description":"Mix together flour and salt in a large bowl or stand mixer bowl. Add the yeast mixture, olive oil and remaining 2/3 cups water. Mix together with a wooden spoon. Once the flour is mostly incorporated, switch to your hands and bring it together into a dough.","images":[],"step":2},{"title":"Knead","description":"Sprinkle work surface with 1 tbsp flour, then knead for 8 to 10 minutes by hand OR 3 minutes on speed 6 of a stand mixer. Dough is kneaded enough when it''s smooth and does not break when stretched - see photos video for before/after comparison. (Note 8)","duration":9,"images":[],"step":3},{"title":"Rise 1","description":"Shape into a ball. Smear inside of used bowl with a bit of olive oil, place dough inside. Cover with cling wrap and rise in warm place for 1.5 hours, or until doubled in size. (Note 9)","images":[],"step":4},{"title":"Rise 2","description":"Punch dough down to fully deflate, then divide into 2 equal pieces. Pull the sides down and tuck underneath so the top is smooth, underside is bunched up. Shape into ball and place on a lightly floured tray, smooth side up. Sprinkle surface with flour, then cover with damp tea towel. Rise 1 hour until doubled in size.","images":[],"step":5},{"description":"Assembling & Baking Pide:","images":[],"step":6},{"description":"Preheat oven to 240°C/465°F (220°C fan). Place shelf on the top and middle.","images":[],"step":7},{"title":"Roll","description":"Roll dough out on a lightly floured surface into an oval shape 40cm/16\" long and 20cm/8\" wide (widest point).","images":[],"step":8},{"title":"Prepare 2 trays","description":"Sprinkle 1/4 tsp semolina on each tray, 40cm/16\" long and 15cm/6\" wide. (Note 10)","images":[],"step":9},{"title":"Top Pide","description":"Place a rolled out dough on the semolina. Sprinkle with cheese, then sprinkle chosen Topping evenly across the surface, leaving a 2cm / 4/5\" border all around.","images":[],"step":10},{"title":"Fold dough","description":"Brush the ends with water. Pinch ends together to seal then fold the sides of the pide in.","images":[],"step":11},{"title":"Bake","description":"Bake 15 minutes, switching trays halfway, until the crust is golden.","images":[],"step":12},{"title":"Egg option","description":"Bake pide for 10 minutes, then crack the egg on top and return to oven for 5 minutes. This applies to all Pide - egg can be added for any of them!","duration":10,"images":[],"step":13},{"title":"Top & Serve","description":"Sprinkle with toppings of choice. (Note 11 for combos I used). Cut into 3cm / 1.3\" slices and serve!","images":[],"step":14},{"description":"Spinach Topping:","images":[],"step":15},{"description":"Heat oil in a skillet over medium heat. Cook onion for 3 minutes until translucent. Add spinach, cook until just wilted (add in batches if necessary). Stir in cumin, salt & pepper. Cool before using.","duration":3,"images":[],"step":16},{"description":"Turkish Sausage Topping:","images":[],"step":17},{"description":"Roughly chop, then turn the sausage into mince (ground meat) by using a Nutribullet or food processor.","images":[],"step":18},{"description":"Heat oil in a skillet over medium high heat. Cook garlic and onion for 3 minutes until soft. Add lamb and cook until it changes from pink to brown. Add tomato paste, Baharat, cumin, salt, pepper and cook for 3 minutes.","duration":3,"images":[],"step":19},{"description":"Add capsicum, tomato and lemon juice, then cook over medium heat until most of the liquid evaporates (a couple of minutes usually, though depends on juiciness of tomato). Cool before using.","images":[],"step":20}]', '["egg","gluten","milk","sesame"]', '["high_protein"]', '{"mealType":["dinner","snack"],"cuisine":["Middle Eastern","Turkish"],"categories":["breads","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9bbbfe4c3804', 'en', 'US', 'Homemade sausage patties', 'Recipe video above. This is your favourite pork sausage in patty form. It''s so easy - just pork mince (ground pork) mixed with a spice blend. Great to make ahead and freeze, then cook up on demand.Serve for dinner with garlic rice and steamed green beans tossed with French Dressing. O make burgers! Also great for breakfast with scrambled eggs on toast. (I''d still use ketchup :) )', 'https://www.recipetineats.com/tachyon/2023/09/Homemade-pork-sausage-patties_1.jpg', 10, 10, 20, 8, '[{"id": "ing_pork_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_sage", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_ketchup", "quantity": {"value": 1.0, "unit": "bottle of 500g"}}]', '[{"ingredients":["500g/ 1 lb pork mince (ground pork) (sub chicken, turkey)","1 tsp dried ground sage (secret ingredient! Note 1)","1/2 tsp dried thyme (, crushed with fingers (Note 2))","1 tsp onion powder (sub more garlic powder)","1/2 tsp garlic powder (sub more onion powder)","1 tsp black pepper","3/4 tsp cooking / kosher salt (or 1/2 tsp table salt)","1/2 tsp sugar (optional)"],"purpose":"Sausage patties:"},{"ingredients":["2 tbsp olive oil","Ketchup for serving"],"purpose":"Cooking & serving:"}]', '[{"title":"Make patties","description":"Place sausage pattie ingredients in a bowl and mix well with your hands. Divide into 8 and form 1 cm / 0.4\" thick patties. Make a shallow dent in the middle of the surface - this prevents the patties from doming as they cook.","images":[],"step":1},{"title":"Cook 4 minutes","description":"Heat 1 tablespoon of oil in a large non stick pan over medium high heat. Cook half the patties for 2 minutes on each side until golden. Transfer to a paper towel lined plate. Heat remaining oil and cook remaining patties.","duration":2,"images":[],"step":2},{"description":"Serve with ketchup! (See recipe card intro for serving ideas)","images":[],"step":3}]', '[]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["breakfast","dinner"],"cuisine":["Western"],"categories":["breakfast-recipes","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9ac49af702b7', 'en', 'US', 'Extra Crispy Corn Fritters', 'Recipe video above. Sweet pops of fresh corn on the inside, very crispy on the outside. These heavenly fritters are light on batter, heavy on the corn – just the way they should be! Makes a lovely meal for 2 with a leafy green salad on the side, or a starter for 4.', 'https://www.recipetineats.com/tachyon/2020/05/Crispy-Corn-Fritters_0-copy.jpg', 10, 20, 30, 8, '[{"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_corn", "quantity": {"value": 0.75, "unit": "can of 400g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1/4 cup flour (, plain / all purpose)","1/4 cup cornflour / cornstarch","1/4 tsp baking soda (or 3/4 tsp baking powder)","1 egg","2 tbsp milk (any type)","2 cups fresh corn kernels (, raw (2 cobs) (canned or frozen also fine - Note 1))","1/2 cup parmesan (, finely grated)","3/4 cup green onions (, sliced)","1/2 cup coriander/cilantro (, roughly chopped (sub more green onion))"]},{"ingredients":["1/2 cup vegetable oil","Oil spray"],"purpose":"For cooking:"},{"ingredients":["Avocado sauce","Sour cream, ketchup (don’t judge until you’ve tried it!)"],"purpose":"Serving – choose:"}]', '[{"description":"Preheat oven to 120°C / 250°F and set a wire rack on a baking tray.","images":[],"step":1},{"description":"Place flour, cornflour and baking soda in a bowl, mix to combine.","images":[],"step":2},{"description":"Add egg and milk, mix until incorporated (batter will be lumpy and thick).","images":[],"step":3},{"description":"Add corn, parmesan, green onions and coriander. Mix until all the corn is evenly coated in batter.","images":[],"step":4},{"description":"Add enough oil into the skillet so it just covers the base. Heat over medium high heat.","images":[],"step":5},{"description":"Spray the underside of a spatula with oil (so batter won’t stick when you flatten).","images":[],"step":6},{"description":"Place 1/4 cup batter into skillet (ice cream scooper with lever is handy), then flatten to 1cm thick. Repeat with 2 or 3 more, but don’t crowd the skillet.","images":[],"step":7},{"description":"Cook 3 minutes until deep golden and crisp, then flip and cook the other side for 2 – 3 minutes.","duration":2.5,"images":[],"step":8},{"description":"Transfer to rack and keep warm in oven. Repeat with remaining fritters, using more oil as necessary.","images":[],"step":9},{"description":"Serve with sauce of choice for dunking!","images":[],"step":10}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast","dinner","snack"],"cuisine":["Western"],"categories":["breakfast-recipes","fritters-tots-and-similar","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_082af9008802', 'en', 'US', 'Really Quick Broccoli Pasta', 'Recipe video above. This is a great emergency meal OR carb + veg side for all those times when your cupboards are bare except for broccoli, pasta, and some kind of cheese. It''s saucy without using tons of oil, and there''s loads of sub options. Quick and utterly scrumptious - loaded with tons of broccoli!', 'https://www.recipetineats.com/tachyon/2019/04/Broccoli-Pasta_5.jpg', 5, 10, 15, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_broccoli", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_mixed_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}]', '[{"ingredients":["350g / 12 oz dried short pasta (I used small shells)","2 broccoli heads (BIG!)","1 cup shredded cheese (or more!)"]},{"ingredients":["2 tsp lemon zest","2 tbsp lemon juice (or more!)","5 tbsp extra virgin olive oil","1/3 cup parmesan (, finely grated)","2 garlic cloves (, minced)","1 tsp mixed dried herbs (or fresh!)","1/2 tsp+ red pepper flakes (add more if you want spicy!)","1 tsp sugar","3/4 tsp salt","1/2 tsp pepper"],"purpose":"Pasta Sauce (Notes for subs):"},{"ingredients":["More parmesan"],"purpose":"Serving:"}]', '[{"title":"Cook pasta","description":"Boil a large pot of water with 2 tsp salt, add pasta.","images":[],"step":1},{"description":"While pasta is cooking:","images":[],"step":2},{"title":"Chop broccoli","description":"Chop broccoli into small florets.","images":[],"step":3},{"title":"Cook broccoli: Add broccoli into water 1","description":"2 minutes before pasta is cooked.","images":[],"step":4},{"title":"Sauce ingredients in jar","description":"Place Sauce ingredients in a jar with lid.","images":[],"step":5},{"title":"Reserve pasta water","description":"SCOOP OUT 1 cup pasta cooking water just before draining. Then drain and return pasta back into same pot on turned off stove.","images":[],"step":6},{"title":"Add pasta water into Sauce","description":"Add 1/2 cup pasta water to Pasta Sauce jar, shake well.","images":[],"step":7},{"title":"Add Sauce & Cheese to pasta","description":"Pour Sauce and add cheese into pot with pasta.","images":[],"step":8},{"description":"Stir then serve! Stir vigorously, adding more pasta water if required. Add more salt and pepper if required. Serve immediately, garnished with parmesan.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["broccoli-recipes","dinner-tonight","emergency-recipes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8986b538e293', 'en', 'US', 'Broccoli Chicken Fritters', 'Recipe video above. This combination of juicy chicken pieces and tender broccoli inside a fritter with a crispy golden crust is seriously delicious! For a version made with ground chicken (mince), try these Baked Chicken Broccoli Patties.', 'https://www.recipetineats.com/tachyon/2019/04/Broccoli-Chicken-Fritters_1.jpg', 10, 20, 30, 16, '[{"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.2, "unit": "tub of 500g"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 large head broccoli (, cut into florets)","500g / 1lb chicken breast or thigh (, cut into 0.8cm / 1/3\" pieces)","1/2 cup (75g) flour (any type)","1/2 cup (50g) parmesan cheese (, grated or shredded)","2 eggs","2 garlic cloves (, minced)","3/4 tsp salt","Pepper"],"purpose":"Fritters:"},{"ingredients":["3 - 4 tbsp olive oil"],"purpose":"Cooking:"},{"ingredients":["2/3 cup (165g) sour cream or Greek yogurt","2 tbsp ketchup","Squeeze of lemon (, plus more for serving (optional))"],"purpose":"Pink Sauce – mix:"}]', '[{"description":"Preheat oven to 100C/210F.","images":[],"step":1},{"description":"Steam broccoli until tender, then roughly chop. (Note 1)","images":[],"step":2},{"description":"Add broccoli and remaining Fritter ingredients in a bowl and mix well.","images":[],"step":3},{"description":"Add enough oil in skillet to cover base. Heat to medium high.","images":[],"step":4},{"description":"Dollop 1/4 cup mixture into skillet, then pat down. (Note 2)","images":[],"step":5},{"description":"Cook 2.5 minutes until deep golden, then flip and cook for 2 minutes.","duration":2,"images":[],"step":6},{"description":"Transfer to rack, keep warm in oven.","images":[],"step":7},{"description":"Serve with Pink Sauce!","images":[],"step":8}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["broccoli-recipes","chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","fritters-tots-and-similar","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6f18a4b4bf95', 'en', 'US', 'One Pot Broccoli, Chicken and Rice Casserole', 'Recipe VIDEO above. Made from scratch, this tastes like a risotto but is so much more straight forward to make! A complete meal in one pot.', 'https://www.recipetineats.com/tachyon/2018/01/One-Pot-Chicken-Broccoli-Rice_7.jpg', 10, 20, 30, 5, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp (30g ) unsalted butter","1 tbsp olive oil","1 onion (, finely chopped)","2 garlic cloves (, minced)","500g (1 lb) chicken thigh (, cut into bite size pieces (Note 1))","2.5 tbsp flour (or 1 ½ tbsp. cornflour / cornstarch)","2 cups (500 ml) milk (any, I use low fat)","2 cups (500 ml) chicken broth","1 1/4 cups (225g) long grain white rice (, uncooked (Note 2))","1 tsp dried thyme (or other herb of choice)","Salt and pepper","1 large head of broccoli, broken / cut into small florets (~400 - 500g / 14 oz - 1 lb) (Note 3)","2 cups (200g) shredded mozzarella or cheddar (or other cheese of choice) (Note 4)","Finely chopped parsley (, optional garnish)"]}]', '[{"description":"Melt butter and heat oil in a pot over high heat. Add onion and garlic, cook for 1 minute. Add chicken and cook until it changes from pink to white. (Note 5)","duration":1,"images":[],"step":1},{"description":"Turn stove DOWN to medium. Add flour and stir for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add half the milk, stirring as you go, and once incorporated into the flour add the rest of the milk and stir.","images":[],"step":3},{"description":"Add broth, rice, thyme and a just pinch of salt and pepper.","images":[],"step":4},{"description":"Stir, bring to simmer, then cover. Turn down to medium low and cook for 12 minutes.","duration":12,"images":[],"step":5},{"title":"Remove lid","description":"there should still be liquid on the surface. Working quickly, add broccoli, push down so it’s partly submerged, cover and cook for a further 3 minutes until broccoli is just cooked.","images":[],"step":6},{"description":"Preheat grill/broiler. Remove lid and stir through half the cheese – don’t worry if it looks a bit too saucy, excess liquid gets sucked up in minutes (see video). Smooth surface, top with remaining cheese. Grill/broil until melted (or just put lid on and allow to melt with residual heat on turned off stove).","images":[],"step":7},{"description":"Serve immediately, garnished with parsley if desired.","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","one-pot-recipes","quick-and-easy","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f93451a7e231', 'en', 'US', 'Cheesy Chicken Mince Fritters with Broccoli', 'Recipe video above. It''s hard to believe these fritters made with chicken mince are BAKED not FRIED! With almost an entire head of broccoli in them, these are juicy, cheesy and so irresistible. This makes 15 fritters about 6 cm / 2.25" wide, 1cm / 2/5" thick. Trying making burgers or meatballs!', 'https://www.recipetineats.com/tachyon/2017/08/Cheesy-Broccoli-Chicken-Fritters-6.jpg', 15, 25, 40, 4, '[{"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_broccoli", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.5, "unit": "pack of 125g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_yogurt", "quantity": {"value": 0.2, "unit": "tub of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.013, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["500 g / 1 lb chicken mince (ground chicken) (, or turkey or pork (Note 1))","1 garlic clove, (minced)","1 egg","¾ cup panko breadcrumbs","2 packed cups broccoli (, soft cooked & finely chopped (1 head)(Note 2))","¾ cup finely chopped shallots","1 1/2 - 2 cups shredded mozzarella (or other cheese of choice)","3/4 tsp salt (reduce to 1/2 tsp if using a flavoured cheese)(Note 3)","Black pepper"],"purpose":"Fritters:"},{"ingredients":["Oil spray"],"purpose":"Cooking:"},{"ingredients":["2/3 cup plain yoghurt","1/8 tsp EACH dried dill, parsley and chives","¼ tsp onion powder","½ garlic clove, minced","1 - 2 tsp extra virgin olive oil","Squeeze of lemon juice, (optional)"],"purpose":"Yoghurt Ranch Sauce (optional):"}]', '[{"description":"Preheat oven to 200C/390F. Line a baking tray with baking paper (or spray with oil).","images":[],"step":1},{"description":"Place Fritter ingredients in a bowl, mix to combine.","images":[],"step":2},{"description":"Measure out about ¼ cup of mixture and pat into fritter shapes about 6 cm / 2.25\" wide, 1cm / 2/5\" thick (they shrink a bit and become thicker).","images":[],"step":3},{"description":"Place on tray. Spray the top (generously) with oil.","images":[],"step":4},{"description":"Bake for 15 minutes, flip, spray with oil again then bake for a further 8 - 10 minutes until golden on top. Serve immediately with Sauce.","duration":15,"images":[],"step":5},{"title":"Sauce","description":"Mix ingredients together. Add salt and pepper to taste. Set aside for 20+ minutes.","images":[],"step":6}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["broccoli-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_09f462259731', 'en', 'US', 'Ultra Lazy Creamy Chicken and Broccoli Pasta Bake', 'Recipe video above. One for all those busy nights - a complete HEALTHY meal all made in one baking dish. 5 minutes prep, pop it in the oven, then out comes perfectly cooked chicken and broccoli pasta bake smothered in a creamy sauce. Serves 4 - 5.', 'https://www.recipetineats.com/tachyon/2017/07/Ultra-Lazy-Creamy-Chicken-Pasta-Bake-2.jpg', 10, 35, 45, 5, '[{"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}]', '[{"ingredients":["400g / 14 oz chicken tenderloin (raw) (, breast or thigh, cut into 1.5cm / 3/5\" pieces)","Salt and pepper","1 tsp dried thyme (or other herbs and/or spices of choice)","250g / 8 oz spiral pasta, uncooked (See Note 1 for other shapes)","1/4 cup flour (all purpose / plain)","1 1/2 cups chicken broth/stock (, warmed)","2 cups milk (, warmed (any fat %))","1 large garlic clove (, minced)","2 tbsp / 30g unsalted butter (, recommended but optional)","1 large broccoli ( or 2 medium broccoli or cauliflower, broken into small to medium florets (Note 2 for subs))","1 1/2 cups (tightly packed) shredded cheddar or colby cheese (or tasty cheese, pizza mix etc, Note 3)"]}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan-forced).","images":[],"step":1},{"description":"Sprinkle chicken with salt (be generous), pepper and thyme, toss to coat.","images":[],"step":2},{"description":"Spread pasta in a 23 x 33cm / 9 x 13\" baking dish. Sprinkle flour all across the surface (don''t dump in clump else it won''t dissolve). Pour over milk and broth, add garlic and butter. Stir.","images":[],"step":3},{"description":"Spread chicken over the top, then broccoli.","images":[],"step":4},{"description":"Cover with foil, bake for 15 minutes (or 20 minutes if milk & broth were cold).","duration":15,"images":[],"step":5},{"description":"Remove foil, STIR WELL. Add most of the cheese, then STIR WELL again. Top with remaining cheese.","images":[],"step":6},{"title":"Return to oven. Bake for 15","description":"20 minutes until top is golden and sauce is thickened (See note 4 for troubleshooting).","duration":17.5,"images":[],"step":7},{"description":"Stand for a few minutes then serve immediately!","images":[],"step":8}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","emergency-recipes","low-calorie-recipes","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1a81fbb46188', 'en', 'US', 'Baked Macaroni Cheese with Chicken & BROCCOLI', 'EASY baked Mac and Cheese loaded with chicken and broccoli - a COMPLETE meal all made in one pot! This recipe requires the specific ratio of water, milk and macaroni that I''ve specified in the recipe. Don''t be alarmed at how much liquid there is when you take it out of the oven before broiling/grilling the top. You will be surprised how quickly the liquid evaporates into a thick sauce. Watch the VIDEO to see how easy this is to make!', 'https://www.recipetineats.com/tachyon/2016/02/Baked-Macaroni-Cheese-Chicken-Broccoli_1.jpg', 15, 30, 45, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_panko", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}]', '[{"ingredients":["1 tbsp olive oil","1 lb / 500g skinless chicken breast or thigh fillets (, cut into bite size pieces)"]},{"ingredients":["3 tbsp butter","2 garlic cloves (, minced)","1 small onion (, finely chopped)","4 tbsp plain flour","2 1/2 cups milk (, low fat)","1 cup water","1 tsp salt","Black pepper","2 cups macaroni / elbow pasta (Note 1)","1 large head of broccoli (, broken into florets (or 1 1/2 smaller ones))","1 1/2 - 2 cups grated cheese (cheddar, tasty or gruyere)"],"purpose":"Mac N Cheese"},{"ingredients":["1/4 cup panko (or ordinary breadcrumbs)","2 tbsp parmesan cheese"],"purpose":"Topping"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat oil in a deep heavy based skillet or dutch oven over high heat. Add chicken and cook until just cooked - it''s fine if it''s still raw inside. Remove chicken into a bowl. (Note 2)","images":[],"step":2},{"description":"Reduce heat to medium and melt butter. Add garlic and onion and saute for 5 minutes until onion is translucent. Add flour and cook for 1 minute.","duration":5,"images":[],"step":3},{"description":"Pour in half the milk and whisk it in so the flour butter mixture melts. It should thicken quite quickly - around 30 seconds. Pour the remaining milk in, whisking constantly, then add the water, salt and pepper.","images":[],"step":4},{"description":"Turn the heat up to medium high and cook, whisking occasionally, for around 3 to 5 minutes until you start seeing steam rising from the white sauce when you whisk it.","images":[],"step":5},{"description":"Add the macaroni and chicken, stir, then top with broccoli.","images":[],"step":6},{"description":"Place the lid on and bake for 20 minutes.","duration":20,"images":[],"step":7},{"description":"Remove from the oven, switch oven to broiler/grill on high.","images":[],"step":8},{"description":"Remove lid (Note 3), stir through cheese, then sprinkle over panko and parmesan. (Will still look bit watery at this stage).","images":[],"step":9},{"description":"Place pot under the broiler/grill for 5 minutes, or until top is golden.","duration":5,"images":[],"step":10},{"description":"Remove, then let it stand for 5 minutes before serving (sauce thickens quickly).","duration":5,"images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ce2d27eb46ee', 'en', 'US', 'Creamy Bacon, Chicken and Broccoli Strata (Bread Bake)', 'A creamy chicken and broccoli bake made from scratch topped with bread and panko to make it extra crunchy! It''s like a pasta bake / strata (savoury bread pudding), just as filling but with a lot less carbs.', 'https://www.recipetineats.com/tachyon/2014/08/Creamy-Bacon-Chicken-Broccoli-Bake-1.jpg', 15, 40, 55, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_broccoli", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 3.0, "unit": "loaf"}}, {"id": "ing_panko", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["250 g / 8 oz chicken breast fillet (, cut into small bite size pieces)","2 bacon rashers (, diced)","1 small brown onion ((or 1/2 large), diced)","4 packed cups (300g/10oz) broccoli florets","1 garlic clove (, minced)","1/2 tbsp olive oil"]},{"ingredients":["40 g / 1.3 oz / 3 tbsp butter","1/2 cup flour","1/2 cup grated cheese (tasty, cheddar, gruyere or any other good melting cheese)","3 cups low fat milk","1 tsp garlic powder","1/2 tsp salt","Black pepper"],"purpose":"Béchamel Sauce"},{"ingredients":["3 to 4 slices of thick slice white sandwich bread (, cut into 1cm / 1/3\" cubes (note 1))","1/4 cup panko (or breadcrumbs)","2 tbsp parmesan cheese (, grated)","Fresh parsley (, finely chopped, to garnish (optional))"],"purpose":"Topping"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Chicken Mixture","images":[],"step":2},{"description":"Heat olive oil in a deep non stick fry pan over high heat. Add onion, minced garlic and bacon. Saute for 2 to 3 minutes until onion is translucent and bacon is starting to brown.","duration":2.5,"images":[],"step":3},{"description":"Add chicken and cook just until the outside of the chicken turns white (do not cook through). By this time, the onion should be caramelised and bacon should be crisp.","images":[],"step":4},{"description":"Remove from pan onto paper towel to drain.","images":[],"step":5},{"description":"Make the Béchamel Sauce (see notes for tips)","images":[],"step":6},{"description":"Lower heat to medium. Wipe pan clean and return to heat.","images":[],"step":7},{"description":"Melt butter, then add flour and whisk constantly for 1 1/2 minutes.","images":[],"step":8},{"description":"Add 1 1/2 cups of milk, whisking constantly, until it is well combined and lump free. It should be very thick.","images":[],"step":9},{"description":"Add remaining milk and whisk to combine well. Cook for 2 minutes or so, whisking constantly, until it thickens to the consistency of pouring cream (not whipped cream).","duration":2,"images":[],"step":10},{"description":"Remove from heat and add garlic powder, cheese, salt and pepper. Whisk until the cheese is melted and the sauce is smooth. Do a taste test and add more salt if you want.","images":[],"step":11},{"description":"Assemble and Bake","images":[],"step":12},{"description":"Place broccoli in baking dish (see notes for size), then top with chicken onion mixture. Pour over half the béchamel sauce.","images":[],"step":13},{"description":"Top with bread cubes, then drizzle over the remaining béchamel sauce as evenly as possible over the bread cubes. Use an egg flip to squash the bread cubes down - this helps disperse the béchamel sauce throughout the bake.","images":[],"step":14},{"description":"Sprinkle over panko and parmesan cheese.","images":[],"step":15},{"description":"Place in oven and bake for 20 to 25 minutes, until golden brown.","duration":22.5,"images":[],"step":16},{"description":"To Serve","images":[],"step":17},{"description":"Let stand for 5 minutes before serving. Garnish with finely chopped parsley, if desired.","duration":5,"images":[],"step":18}]', '["fish","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a9b826ec5de', 'en', 'US', 'Crispy Prawn Burgers (Shrimp)', 'Recipe video above.', 'https://www.recipetineats.com/tachyon/2025/09/Prawn-burgers_5.jpg', 16, 4, 20, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_gherkins", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bang_bang_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["400g / 14oz fresh OR 500g/1lb frozen raw peeled prawns (shrimp) (Note 1)","1 garlic (, minced)","1/4 cup green onion (, finely sliced)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Prawn patties"},{"ingredients":["1 egg (, lightly whisked with a fork)","1/2 cup plain flour (all-purpose flour)","1 1/4 cups panko breadcrumbs","1/2 cup olive oil (, or any neutral flavoured oil (vegetable, canola etc))"],"purpose":"Crumbing:"},{"ingredients":["4 brioche buns (10-12cm / 4-5\" wide) (or other soft white buns, lightly toasted)","1 1/2 cups shredded iceberg lettuce (or cos lettuce (romaine))","Gherkins (, finely sliced)","1 1/2 cups shredded iceberg lettuce (or cos lettuce (romaine))"],"purpose":"Burgers:"}]', '[{"description":"Blitz half prawns and garlic, mix with rest of pattie ingredients. Roll into balls, dredge in flour, egg, then flatten into patty in panko, flip to coat. Fry 4 minutes until golden, assemble burgers.","images":[],"step":1},{"title":"Thaw","description":"If using frozen prawns, thaw thoroughly and discard excess water (you lose ~20% in weight in water), then chop into 8mm / 1/3\" pieces.","images":[],"step":2},{"title":"Blitz","description":"Put half the prawns and garlic in a jug large enough to fit the head of a stick blender. Blitz until it becomes a paste (no need to puree 100% perfectly).","images":[],"step":3},{"title":"Prawn patties mixture","description":"Scrape into a bowl. Mix in the chopped prawns green onion, salt and pepper. The mix will be sloppy, but don’t worry - it firms up as it cooks, and the shaping method handles the softness. :)","images":[],"step":4},{"title":"Dredging station","description":"Put the egg and flour in separate shallow bowls, and the panko on a plate (need squishing space).","images":[],"step":5},{"title":"Crumb","description":"Using slightly wet hands, roll mixture into 4 balls. Coat ball in flour, then egg (let the excess drip off), then press down into a patty in the panko. Make it a smidge larger than the size of your bun (it shrinks a wee bit). Flip using a spatula, press down to adhere panko and make sure to coat the sides. Remove with a spatula onto a plate, repeat with remaining balls.","images":[],"step":6},{"title":"Cook","description":"Heat the oil in a large non-stick pan over medium high heat. Cook patties for 2 minutes on each side until golden, then remove onto a paper towel lined tray.","duration":2,"images":[],"step":7},{"title":"Assemble burgers as follows","description":"smear base with sauce. Top with prawn patty, cover with gherkins, pile on lettuce. Smear lid with sauce, place on top, EAT! (Homemade fries on the side are the ultimate sidekick but were out of reach today, so I used frozen).","images":[],"step":8}]', '["egg","gluten","shellfish"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["burger-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cf4281819efc', 'en', 'US', 'Ultra Crunchy Fried Chicken Burger', 'Recipe video above. KFC, eat your heart out! Our Fried Chicken Burger is way crunchier than yours, the chicken is way juicier and it tastes way better! The trick is to mix a bit of marinade into the flour coating - this creates lumps that fries up into an awesome ultra crunchy crust. See my Fried Chicken recipe for ravings and musings about this method. (Thanks Kenji!)', 'https://www.recipetineats.com/tachyon/2023/09/Crispy-fried-chicken-burgers_5.jpg', 15, 15, 210, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_herkins_dill_pickles", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.25, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 1.25, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_celery", "quantity": {"value": 0.025, "unit": "head"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.006, "unit": "jar of 200g"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.75, "unit": "L"}}]', '[{"ingredients":["2 x 250g/8oz chicken breast (I use this)","4 boneless thigh fillets"],"purpose":"Chicken choices:"},{"ingredients":["3/4 cup buttermilk (Note 1 for sub)","1 1/2 tsp cooking / kosher salt","1 large egg"],"purpose":"Marinade:"},{"ingredients":["4 soft buns (, split and lightly toasted (mine are 10cm/4\"))","2 - 3 cups iceberg lettuce (, finely sliced (or other leafy greens of choice))","2 tomatoes (, sliced (optional, sometimes I do))","2 gherkins / dill pickles (, sliced on an angle)"],"purpose":"Burgers:"},{"ingredients":["2/3 cup mayonnaise (, preferably whole egg)","3/4 tsp garlic (, finely grated (1 clove))"],"purpose":"Garlic mayo:"},{"ingredients":["3/4 cup flour (, plain / all purpose)","1/4 cup corn flour / cornstarch"],"purpose":"Crunchy coating:"},{"ingredients":["1/4 tsp celery salt (or heaped 1/8 tsp celery seed)","1/2 tsp sweet paprika","1/8 tsp cayenne pepper (inc to 1/2 tsp for spicy ZINGER burger!)","1/2 tsp onion powder","1 tsp garlic powder","1/4 tsp mustard powder","1/4 tsp ginger powder","1/2 tsp dried thyme","1/2 tsp dried oregano","1/2 tsp cooking salt / kosher salt","1 1/2 tsp black pepper"],"purpose":"Fried chicken seasoning:"},{"ingredients":["3 cups vegetable oil (or canola or peanut) (2.5cm/1\" depth in cooking vessel)"],"purpose":"To fry:"}]', '[{"description":"Shortform recipe:","images":[],"step":1},{"description":"Pound chicken to 1cm / 0.4\" thickness, trim, marinade 3 - 24 hrs. Mix coating and seasoning, mix in 2 tbsp marinade. Coat chicken, fry at 180°C/350°F for 4 min (don''t touch for first 90 sec). Assemble!","duration":4,"images":[],"step":2},{"description":"Full instructions:","images":[],"step":3},{"title":"Chicken","description":"Cover the chicken with a freezer bag or plastic sheet and pound to 1cm / 0.4\" even thickness. Trim to just a touch larger than the size of your bun. Save off-cuts for another use (stir fry - or Dozer, in my case!).","images":[],"step":4},{"title":"Marinade","description":"Whisk Marinade ingredients in a bowl. Add chicken, toss. Marinate in the fridge for 3 hours minimum, to overnight (don''t go beyond 24 hrs).","images":[],"step":5},{"title":"Garlic mayo","description":"Mix in a small bowl and refrigerate until required.","images":[],"step":6},{"title":"Prepare crunchy coating","description":"Mix flour, cornflour and Seasoning ingredients in a bowl. Drizzle over 2 tablespoons of the marinade, then use fingers to mix through to form lumps - when this sticks to the chicken, it fries up into awesome crunchy bits!!","images":[],"step":7},{"description":"Heat oil in a large heavy based pot over medium high heat to 180°C/350°F (Note 2).","images":[],"step":8},{"title":"Coat chicken","description":"Pick up a piece of chicken and allow excess marinade to drip off. Press to coat in flour coating. Shake off excess, then fry for 2 minutes on each side until golden. DO NOT TOUCH for the first 90 seconds to allow the coating to adhere. I fry 2 at a time. Drain on paper towels, cook remaining chicken.","duration":2,"images":[],"step":9},{"title":"Assemble","description":"Smear garlic mayo on the top and bottom of the buns. Pile lettuce on the base, top with tomato if using. Then chicken, gherkins and put the lid on. Sink your teeth into it immediately and enjoy!","images":[],"step":10}]', '["egg","gluten","mustard","peanuts"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","chicken","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e2cec46ff1a0', 'en', 'US', 'Homemade Filet-O-Fish Burger (BAKED!)', 'Recipe video above. Tastes remarkably similar to McDonald''s with the added bonus that it''s bigger, it''s healthier and you know exactly what goes in it! Toasting the breadcrumbs guarantees beautiful golden, truly crunchy fish fillets even though these are baked. Fry option - follow the dredge / crumbing / fry steps in this Schnitzel recipe.', 'https://www.recipetineats.com/tachyon/2018/08/Homemade-Filet-O-Fish_3.jpg', 15, 20, 35, 4, '[{"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_fish_fillets", "quantity": {"value": 400.0, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_corn", "quantity": {"value": 0.037, "unit": "can of 400g"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_capers", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 cups panko breadcrumbs (Note 1)","400 - 500 g / 0.8 - 1 lb white fish fillets (, flat / thin (I used Ling, Note 2))","4 soft buns (, brioche recommended (Note 3))","4 slices processed cheese (Note 4)","Oil spray (I use olive oil)"]},{"ingredients":["1 egg","1 tbsp mayonnaise","1 tbsp dijon mustard (or other mustard)","1 tbsp flour","1/2 tsp salt","Black pepper"],"purpose":"Dredge Batter (Note 5):"},{"ingredients":["1 cup / 220g mayonnaise","1 tbsp dill pickle / gherkin/ cornichon (, very finely chopped)","1 tsp fresh parsley (, chopped*)","1 tsp capers (, drained and finely chopped*)","1.5 tbsp lemon juice (, fresh (or cider vinegar))","1 tsp white sugar","1/4 tsp salt"],"purpose":"Tartare Sauce:"}]', '[{"description":"Mix ingredients in a bowl. Set aside for 10 minutes+.","duration":10,"images":[],"step":1},{"description":"Toast Breadcrumbs:","images":[],"step":2},{"description":"Preheat oven to 180C/350F.","images":[],"step":3},{"description":"Spread breadcrumbs on a tray. Spray with oil directly down, not from side.","images":[],"step":4},{"title":"Bake for 3","description":"5 minutes until golden. Immediately transfer to bowl.","duration":4,"images":[],"step":5},{"description":"Brush tray clean, spray with oil.","images":[],"step":6},{"description":"Crumbing / baking:","images":[],"step":7},{"description":"Cut fish fillets into square-ish shapes slightly larger than the buns (they shrink when cooked).","images":[],"step":8},{"description":"Mix Batter ingredients in a bowl.","images":[],"step":9},{"description":"Carefully coat fish in batter (handle with care, fish fillets can be delicate).","images":[],"step":10},{"description":"Place in breadcrumbs. Use other hand to cover top and sides with breadcrumbs, pressing to adhere. Transfer to tray. Repeat with remaining fish.","images":[],"step":11},{"title":"Bake 12","description":"15 minutes until fish is cooked through. Immediately top with cheese - allow residual heat to make it semi melt (do not oven melt processed cheese, you get a plasticy film!).","images":[],"step":12},{"description":"Cut buns in half, microwave for 20 seconds to warm through (microwave = stays soft).","duration":0.3333333333333333,"images":[],"step":13},{"description":"Top with fish and cheese, dollop with tartare sauce. Devour!","images":[],"step":14}]', '["egg","fish","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["burger-recipes","dinner-tonight","fish-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c25cefd99053', 'en', 'US', 'Veggie Burgers', 'Recipe video above. A Veggie Burger created by a carnivore, for carnivores. It is not a vegetarian burger pretending to be a meat burger, packed with obscure ingredients. This is just a flavour packed, juicy vegetarian burger that''s satisfyingly meaty! Chilling time: 1 hour', 'https://www.recipetineats.com/tachyon/2018/04/Veggie-Burgers_9a.jpg', 20, 35, 30, 4, '[{"id": "ing_mushroom", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_cannellini_beans_drained", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_cashews", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_rice", "quantity": {"value": 112.5, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["250g/8oz mushrooms, sliced","2 tsp olive oil","400g / 14 oz can cannellini beans, drained (Note 1)","1 large carrot , grated"],"purpose":"Beans and Veggies:"},{"ingredients":["1/2 cup (70g) cashews, raw unsalted (Note 2)","1/2 cup (55g) panko breadcrumbs (Note 3)","1/2 cup (50g) grated parmesan","1 egg","2 tbsp mayonnaise","1 garlic clove (, minced)","1/2 tsp each paprika, salt and pepper","3/4 cup (150g) cooked brown rice (Note 4)","3/4 cup green onions (, sliced)"],"purpose":"Patties:"},{"ingredients":["2 - 3 tbsp olive oil (or other)","Soft buns, lettuce, tomato, cheese, pickles, sauces, avocado, beetroot"],"purpose":"Burger:"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Beans and Veggies:","images":[],"step":1},{"description":"Preheat oven to 180C/350F (standard) or 160C/320F (fan/convection).","images":[],"step":2},{"description":"Pile mushrooms on a baking tray. Drizzle over oil, toss, then spread on the tray.","images":[],"step":3},{"description":"Spread beans on another tray, sprinkle carrots all over.","images":[],"step":4},{"description":"Put beans on top shelf and mushrooms on the shelf underneath.","images":[],"step":5},{"description":"Bake for 15 minutes or until surface of beans is dried out and splitting and they look thoroughly unappetising, and the carrots around the edge of the tray are a bit golden. (Note 5) Remove tray with beans from oven.","duration":15,"images":[],"step":6},{"description":"Move mushrooms to top shelf, bake for further 10 minutes until dried out and wrinkly. Remove from oven, cool.","images":[],"step":7},{"description":"Patties:","images":[],"step":8},{"description":"Place cashews in food processor. Blitz until they are breadcrumb size, don''t blitz to powder.","images":[],"step":9},{"description":"Add beans, mushrooms and carrot. Blitz on high for 10 seconds or until chopped to large crumb size (see video and photos).","duration":0.16666666666666666,"images":[],"step":10},{"description":"Add breadcrumbs, egg, parmesan, garlic, paprika, mayonnaise, salt and pepper. Blitz for 15 - 30 seconds until it comes together like meat burger mixture but you can still see bits in it. (Note 6)","duration":0.375,"images":[],"step":11},{"description":"Add rice and shallots, blitz for 2 seconds until just dispersed (over blitzed rice = gluey).","duration":0.03333333333333333,"images":[],"step":12},{"description":"Mixture should hold together well to form patties, but not stick to hands. If too wet, add breadcrumbs. If too crumbly, blitz more.","images":[],"step":13},{"title":"Shape into 4","description":"6 patties, between 1.5 - 1.8cm / 0.6 - 0.7\" thick and 10cm / 4\" wide (Note 7). Refrigerate for at least 1 hour.","images":[],"step":14},{"title":"To Cook","description":"Stove:","images":[],"step":15},{"description":"Cook burgers cold, straight from the fridge.","images":[],"step":16},{"title":"Heat 2","description":"3 tbsp olive oil skillet on the stove over medium to medium-high heat.","images":[],"step":17},{"title":"Add 3","description":"4 patties and cook until deep golden and crispy, 4 minutes. Carefully flip then cook the other side for 4 minutes until golden, then transfer to paper towel lined plate to drain.","duration":4,"images":[],"step":18},{"description":"Cook cold, straight from fridge. Brush BBQ and Veggie patties with oil. Heat BBQ to medium high. Cook 4 minutes each side until a nice dark crust forms.","images":[],"step":19},{"description":"Toast buns, spread top bun with relish or sauce of choice. Top with your choice of burger fillings and the Veggie Burger, then more sauce if desired.","images":[],"step":20}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_19f53b412df9', 'en', 'US', 'Chicken Burrito', 'Recipe video above. This is a chicken burrito stuffed with a juicy seasoned chicken filling, refried beans, corn, cheese and Mexican Red Rice. The refried beans makes it juicy inside without being soggy, adds flavour and holds it all together so the filling doesn''t come tumbling out when you pick it up!', 'https://www.recipetineats.com/tachyon/2020/02/Chicken-Burritos_2.jpg', 15, 15, 30, 5, '[{"id": "ing_tortillas", "quantity": {"value": 5.0, "unit": "pack of 8"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_refried_beans", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 375.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_salsa", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["5 tortillas (, flour (approx 20cm/8\" wide))"]},{"ingredients":["1 tsp each onion powder, dried oregano, salt","2 tsp each dried cumin powder, paprika","1/4 tsp black pepper","3/4 tsp cayenne pepper (optional, adjust to taste)"],"purpose":"Burrito Seasoning:"},{"ingredients":["600g / 1.2 lb chicken breast (, sliced in half horizontally (Note 1))","2 tbsp olive oil (, separated)","1/2 onion (, chopped)","2 garlic cloves (, finely minced)","1 red capsicum/bell pepper (, diced)","400g/14oz refried beans (, canned (Note 2))","1/4 cup water"],"purpose":"Chicken Filling:"},{"ingredients":["2.5 cups white rice (, plain (cooked, Note 3))","2.5 cups Mexican Red Rice (the best for Burritos!)"],"purpose":"Rice – CHOOSE one:"},{"ingredients":["400g/14oz canned corn (, drained (or 280g/9oz frozen thawed))","1.5 cups (150g) cheese (, shredded (Mexican blend, cheddar, tasty, Montery Jack))","1/4 cup coriander/cilantro (, finely chopped)"],"purpose":"Other Stuffings:"},{"ingredients":["Avocado sauce","Sour cream","Salsa (restaurant style, smooth)"],"purpose":"Sauce for dunking – choose:"}]', '[{"title":"Burrito Seasoning","description":"Mix Seasoning ingredients. Drizzle 1 tbsp oil over chicken, mix to coat. Sprinkle with Seasoning, toss to coat.","images":[],"step":1},{"title":"Cook chicken","description":"Heat 1 tbsp oil in a large skillet over high heat. Add chicken, cook 2 minutes. Turn and cook 1.5 minutes. Remove, rest 2 minutes then chop.","images":[],"step":2},{"title":"Saute onion","description":"In the same skillet, add onion and garlic, cook 1 minute. Add capsicum, cook 2 minutes until onion is translucent.","images":[],"step":3},{"title":"Finish Filling","description":"Add refried beans, diced chicken and water. Stir and cook for 2 minutes until reduces slightly. Should be thick and juicy, not watery and not dry/stodgy! Let cool 5 minutes - will thicken.","duration":2,"images":[],"step":4},{"description":"Assemble burritos:","images":[],"step":5},{"description":"Gently warm tortillas in microwave (makes them pliable), lay on work surface.","images":[],"step":6},{"description":"Place rice on lower third, top with Chicken Filling, corn, cheese then sprinkle with coriander. Fold up, burrito style.","images":[],"step":7},{"title":"Toasting","description":"Either pan fry over medium high heat (no oil) for 2 minutes each side to make tortilla crispy and melt cheese a bit OR wrap tightly in foil and bake in oven 10 minutes at 180°C/350°F.","duration":2,"images":[],"step":8},{"description":"Dunk in sauce(s) of choice or douse with hot sauce of choice, and devour! Suggestions: Avocado Sauce, Guacamole, sour cream, Restaurant Style Salsa, Queso, Nacho Cheese Dip.","images":[],"step":9},{"description":"Freezer friendly! Note 4 for directions.","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["burritos","chicken-breast-recipes","chicken-recipes","main-dishes","mexican-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2317689a85d3', 'en', 'US', 'Taco Slaw', 'A slaw designed for use in tacos. A limey sour cream dressing that does so well with Mexican flavours, bit of crunch from the cabbage with signature slaw “juiciness” which acts like a sauce so you don''t need to bother with a salsa or taco sauce.Ideal for things like Crunchy Chicken Taco Fingers, Fish Tacos, Chipotle Prawn Tacos, Baja Fish Tacos, Grilled Chicken for Tacos (ie pieces of protein) rather than things that are shredded and saucy (too same-same). You can also serve it as a side salad, like regular slaw!', 'https://www.recipetineats.com/tachyon/2025/01/Taco-slaw_8.jpg', 15, 0, 15, 12, '[{"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["6 tightly packed cups green cabbage (, finely shredded (about 1/4 head))","1 cup green onion (, finely sliced on the diagonal)","1/2 cup finely chopped coriander/cilantro leaves"]},{"ingredients":["1/2 cup sour cream (sub plain yogurt)","2 tbsp mayonnaise (OR 1 tbsp olive oil (ie halve amount))","2 tsp lime zest","1 tbsp lime juice","1/2 tsp cooking salt / kosher salt (halve for table salt)"],"purpose":"Taco Slaw Dressing:"}]', '[{"description":"Mix the dressing ingredients in a large bowl.","images":[],"step":1},{"title":"Toss","description":"Add the Slaw ingredients then toss well with hands or tongs.","images":[],"step":2},{"description":"Set aside for at least 1 hour until the cabbage becomes wilted and floppy. Toss again then use in tacos!","images":[],"step":3}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["cabbage","mexican-recipes","side-salads","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a0a9eb1cc38', 'en', 'US', 'The most amazing canned tuna pasta!', 'Recipe video above. One of the pantry-pasta greats. I love this recipe because it really showcases what great food you can make using canned tuna! Fabulous flavour beyond just canned tuna thanks to the anchovies, the freshness of lemon and tangy capers. The oil from the can of tuna is used as the sauce so don''t be tempted to use tuna in brine!', 'https://www.recipetineats.com/tachyon/2023/04/Canned-tuna-pasta_0-copy.jpg', 10, 15, 25, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 285.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_baby_capers", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["200g / 7oz spaghetti (, or other thin long pasta)","1 tbsp cooking salt (, for cooking pasta)"]},{"ingredients":["285g/ 10 oz (approx) canned tuna in oil (, drained, oil reserved (I use 3 x 95g/3.5oz cans, Note 1))","2 clove garlic (, finely minced)","2 anchovy fillets (, minced (Note 2))","1/2 tsp chilli flakes / red pepper flakes (can skip, Note 3)","2 tsp baby capers (or finely chopped pickles)","1 tbsp parsley (, finely chopped (ok to skip))","1 tsp lemon zest","2 tbsp lemon juice (sub 1 tbsp apple cider or sherry vinegar)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Tuna sauce:"}]', '[{"title":"Cook pasta","description":"Bring 3 litres / 3 quarts of water to the boil with the 1 tablespoon of salt. Cook pasta per the packet time minus 1 minute. Just before draining, scoop out ~1 cup pasta cooking water, then drain the pasta.","images":[],"step":1},{"title":"Sauté aromatics","description":"In the same pot, heat the reserved oil from the tuna cans over medium heat. Add the garlic, anchovies and chilli flakes. Cook and stir for 1 minute.","duration":1,"images":[],"step":2},{"title":"Toss pasta","description":"Add the pasta, capers and 1/3 cup of reserved pasta water. Toss using 2 spatulas for 2 minutes.","duration":2,"images":[],"step":3},{"title":"Add tuna","description":"Turn off the heat. Add tuna, parsley, lemon zest, juice, salt and pepper. Toss gently to mix through - try to keep some tuna chunks.","images":[],"step":4},{"description":"Serve immediately!","images":[],"step":5}]', '["fish","gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["canned-tuna","dinner-tonight","emergency-recipes","fish-recipes","mains","other","pasta-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1bed0cbe1403', 'en', 'US', 'Tuna Mornay (Creamy Tuna Casserole Pasta Bake)', 'Recipe video above. Tuna Mornay is how you elevate canned tuna above a glum pantry staple into a delish family meal! It’s a tuna casserole pasta bake with a creamy sauce, sweet pops of corn and crunchy topping, baked until golden and bubbly. Simple to make, economical and oh-so-delish!', 'https://www.recipetineats.com/tachyon/2019/11/Tuna-Mornay_6.jpg', 10, 35, 45, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_tuna", "quantity": {"value": 0.425, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["350g / 12oz penne pasta (or other short pasta)","40g / 3 tbsp butter","3 garlic cloves (, finely minced)","4 tbsp (50g) flour (, plain/all purpose)","4 cups (1 litre) milk (, any fat %, dairy or non dairy (1 quart))","2 tsp Vegeta, or chicken or veg stock powder/granulated bouillon (Note 1)","1/2 cup (50g) parmesan (, finely shredded)","1/2 tsp each mustard powder, onion and garlic powder (Note 2)","425g / 15 oz canned tuna (, preferably in oil, drained (sub salmon))","400g / 14 oz canned corn (, drained (or other veg, Note 3))"]},{"ingredients":["25g / 1.5 tbsp butter (, melted)","1/2 cup (60g) panko breadcrumbs","1/4g (25g) parmesan (, finely grated)","1/4 tsp salt","Chives or parsley (, optional garnish)"],"purpose":"Crunchy Topping:"}]', '[{"description":"Preheat oven to 180°C/350°F.","images":[],"step":1},{"title":"Crunchy Topping","description":"Mix together.","images":[],"step":2},{"description":"Cook pasta per packet directions MINUS 1 minute. Drain then allow to cool slightly, then return into pot.","images":[],"step":3},{"title":"White Sauce","description":"Melt butter in a large pot over medium heat. Add garlic and cook for 30 seconds.","duration":0.5,"images":[],"step":4},{"description":"Add flour and stir into melted butter. While whisking, gradually pour in about 1/3 of the milk. Once the flour-butter mixture is incorporated into the milk, pour in remaining milk and whisk.","images":[],"step":5},{"description":"Add Vegeta, mustard, onion and garlic powder, whisk.","images":[],"step":6},{"description":"When the milk starts to heat up, whisk constantly to make sure the white sauce doesn’t catch on the base.","images":[],"step":7},{"title":"After 4","description":"5 minutes, the sauce should be thick enough that you can draw a path across the back of a spoon (see video). Remove from stove and stir in parmesan.","images":[],"step":8},{"title":"Assemble & Bake","description":"Add tuna into pasta and flake into large chunks with fork (not too much, don''t want it to turn to mush when stirred). Add corn, pour over sauce, then gently stir.","images":[],"step":9},{"description":"Scrape into baking dish, top with Crunchy Topping.","images":[],"step":10},{"description":"Bake 25 minutes until top is golden and edges are bubbling. Sprinkle with chives if desired then serve!","images":[],"step":11}]', '["fish","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["canned-tuna","casseroles-and-cosy-bakes","pasta-bakes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eabda0665deb', 'en', 'US', 'Tuna Pasta Bake', 'Recipe video above. When the cupboards are bare, and all you have is canned tuna, pasta and canned tomato, you can still make a wickedly delicious dinner! Customise to your hearts content - add vegetables, fresh herbs, chilli flakes, stir through cheese, olives, capers, sun dried tomatoes - get creative! See note 9 for a lower cal version, and Tuna Mornay for a CREAMY version!', 'https://www.recipetineats.com/tachyon/2017/06/Tuna-Pasta-Bake-2.jpg', 10, 30, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_can_chunk_tuna_drained", "quantity": {"value": 0.425, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 small onion (, finely diced)","800g / 28 oz crushed tomato (Note 1)","1 tbsp tomato paste (optional, thickens sauce slightly)","3/4 cup (185ml) water (Note 2)","1 tbsp Italian mixed herbs (, or other dried herbs of choice)","1 tsp salt","1/2 tsp black pepper","425g / 15 oz can chunk tuna (preferably in oil), drained (Note 3)","200g / 7 oz spiral pasta (or other pasta of choice)","1 1/2 cups (150g) shredded mozzarella cheese (Note 4)","Olive Oil (, for drizzling)"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cook pasta per packet directions, minus 1 minute. Drain, rinse under tap water to stop it sticking together, set aside.","images":[],"step":2},{"description":"Meanwhile, make the sauce. Heat an ovenproof skillet over medium high heat. Add garlic and onion, cook for 3 minutes until golden.","duration":3,"images":[],"step":3},{"description":"Add tomato, water, herbs, salt and pepper and tomato paste if using. Stir, bring to simmer, lower heat to medium and simmer energetically for 5 minutes (stir every now and then) until it thickens.","duration":5,"images":[],"step":4},{"description":"Adjust salt to taste. Also add a touch of sugar if it tastes a bit sour (depends on quality of tomato).","images":[],"step":5},{"description":"Turn the stove off, add pasta, stir in.","images":[],"step":6},{"title":"Add tuna and GENTLY stir it in","description":"don''t break up the tuna so it disintegrates into mush. Leave some chunks on the surface (nice when it is golden).","images":[],"step":7},{"description":"Drizzle with oil, top with cheese then bake for 20 minutes until golden and you get those nice crusty bits you see in the photos.","duration":20,"images":[],"step":8},{"description":"Stand for 3 minutes then serve!","duration":3,"images":[],"step":9}]', '["fish","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australia","Western"],"categories":["canned-tuna","casseroles-and-cosy-bakes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4633d5dffedc', 'en', 'US', 'Chicken Mushroom Pie with Duchess Potato lid', 'Recipe video above. I want to rave about the rich, savoury filling but all anyone can talk about is the Duchess Potato topping.....😅 Fluffy and buttery inside with crispy parmesan crusted ridges, I want to pick them off one by one and eat them all by myself!As for the filling - think, rich Guinness Stew, but with chicken, and 2 hours faster to make. Guinness beer adds instant depth of flavour, and beef rather than chicken broth has a richer flavour and makes the sauce an enticing deep brown colour.Make one big pie as I''ve done, or single serve size. Excellent for making ahead to bake later! (See note 6 if you don''t have a piping bag for star tip)', 'https://www.recipetineats.com/tachyon/2025/07/Duchess-potato-chicken-pie_9.jpg', 20, 60, 80, 6, '[{"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.5, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 0.568, "unit": "bottle of 330ml"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["60 g / (4 tbsp) unsalted butter (, approximately divided into 4 (no need to be accurate))","4 garlic cloves (, finely minced)","1 1/2 tsp cooking salt / kosher salt (, divided (Note 1))","1 tsp black pepper (, divided)"]},{"ingredients":["750 g / 1.5 lb chicken thighs (, boneless skinless (Note 2))","500 g/1 lb button mushrooms - very small ones whole (, larger ones halved or quartered)","100 g / 3.5 oz thick cut streaky bacon (, cut into 2.5cm/1\" squares)","1 1/2 onions (, cut into 2cm/1\" square or thick wedges)","2 sprigs fresh thyme (or 1/2 tsp dried thyme)","1/4 cup plain flour (all-purpose flour)","3/4 cup Guinness beer (Note 3)","1 1/2 cups beef stock / broth (, low sodium)","3/4 cup water","1 tbsp tomato paste"],"purpose":"Pie filling:"},{"ingredients":["1 kg / 2 lb starchy potatoes (, peeled, cut into 2.5cm / 1\" cubes (Note 4))","30g / 2 tbsp unsalted butter (, cut into 1.5 cm / 1/2\" pieces)","1/3 cup milk (, hot)","1/8 tsp white pepper (sub black)"],"purpose":"Mashed potato topping:"},{"ingredients":["30g / 2 tbsp unsalted butter (, melted (or olive oil spray))","2 tbsp grated parmesan (, sandy store bought type works best or grate your own)","2 tsp finely chopped parsley for garnish (, optional)"],"purpose":"Topping:"}]', '[{"description":"Brown mushrooms, remove, sear chicken (aggressively!) in same pan, cut into large pieces. Sauté bacon, onion and garlic, deglaze with Guinness, make roux, add stock, simmer with mushrooms to thicken (~10 min). Add chicken towards end. Pour into a baking dish, pipe on mashed potato, finish with butter and parmesan, bake 30 min.","images":[],"step":1},{"title":"Garlic butter mushrooms","description":"Melt 1/4 of the butter in a large 30cm/12\" non stick pan over high heat. Add mushrooms, toss for 3 - 4 minutes until you get some browning on the surface. Add another 1/4 of the butter, melt, toss to coat. Add 1/4 tsp each salt and pepper and half the garlic, toss 30 seconds until garlic is golden - mushrooms will still be hard inside, they finish cooking later. Remove into bowl (make sure you scrape out all garlic bits).","duration":3.5,"images":[],"step":2},{"title":"Sear chicken","description":"Sprinkle the chicken with 1/2 tsp salt and 1/4 tsp pepper. In the same pan, melt another 1/4 of the butter until hot and foamy. Sear chicken 2 minutes on each side until nicely golden but inside is still raw (if they don''t fit in a single layer, do in batches). Remove onto plate, once cool enough to handle cut into 2.5cm (1\") pieces.","images":[],"step":3},{"title":"Bacon and onion","description":"In the same pan, add bacon and stir for 15 seconds, then add the onion (there should be enough fat from the chicken). Cook for 2 minutes until the onion edges are golden and starting to soften. Add remaining garlic and stir 20 seconds.","duration":0.25,"images":[],"step":4},{"title":"Deglaze with Guinness","description":"Add Guinness and let it simmer rapidly, scraping the base of the pan to loosen any golden bits into the liquid (“fond” = free flavour!), until the Guinness is reduced down by 75%.","images":[],"step":5},{"title":"Sauce","description":"Lower heat to medium and add remaining butter. Once melted, sprinkle flour all across the surface and stir for 1 minute - it will look pasty. While stirring, pour in half the stock. Keep stirring until the flour paste dissolves into the stock, for lump-free sauce (yay!). Then add remaining stock, water, tomato paste, 1/4 tsp salt and 1/2 tsp pepper, stir well.","duration":1,"images":[],"step":6},{"title":"Simmer","description":"Add the mushrooms plus all mushroom juices accumulated in the bowl into the pan. Simmer for 10 minutes or until the liquid reduces down into a fairly thick gravy and the mushrooms become soft. (Meanwhile, start the mash)","duration":10,"images":[],"step":7},{"title":"Thicken sauce","description":"Add the chicken (plus all juices) and simmer for another 2 to 3 minutes until the gravy is quite thick and you can draw a path on the base of the pan. (Sauce thickness now = sauce thickness once baked). Taste - add more salt if needed (I don’t).","images":[],"step":8},{"title":"Assemble","description":"Pour into a 1.5 - 2 L (6 - 8 cup) baking pan and smooth the surface. (Note 5 for other pan sizes)","images":[],"step":9},{"description":"Preheat oven to 200°C / 390°F (180°C fan-forced).","images":[],"step":10},{"title":"Duchess potato topping","description":"Pipe mounds of mashed potato swirls on the surface. My swirls have a 4.5cm base (1.6\"), about 4cm tall (1.4\"), then I fill gaps with small swirls/blobs. I use all the mash! Drizzle with melted butter, sprinkle with parmesan. (Note 6 for no piping bag)","images":[],"step":11},{"description":"Bake for 30 minutes, rotating the pan at the 20 minute mark.","duration":30,"images":[],"step":12},{"title":"Serve","description":"Rest for 10 minutes, sprinkle with parsley if using. Attack!","duration":10,"images":[],"step":13},{"title":"Make mash","description":"Put the potatoes into a large pot of cold tap water. Bring to a boil over high heat then cook for 15 minutes until soft. Drain, pass through a potato ricer (smoother) or mash well with a potato masher in the now empty pot. Add butter, milk, 1/2 tsp salt and 1/8 tsp white pepper, stir through - it should be creamy but not loose (so it holds its form when piped).","duration":15,"images":[],"step":14},{"title":"Piping bag","description":"Transfer mash into a piping bag fitted with a star tip. (Note 6 for no piping bag)","images":[],"step":15}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-recipes","mains","quiches-tart-and-pie-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_15961522cbb1', 'en', 'US', 'Chicken Cacciatore', 'Recipe video above. I love this chicken stew, made with simple ingredients that''s so cosy and comforting. Also known as Hunter''s Stew, this is made with a tomato sauce that''s rich with red wine, herbs, and Kalamata olives. While there are various regional variations, capsicum (bell peppers) and mushrooms are typical vegetable inclusions though I''ve also seen varieties using fennel which is so distinctly Italian too (finely slice and sauté). Serve over mash or polenta for the perfect cosy evening meal.', 'https://www.recipetineats.com/tachyon/2024/06/Chicken-Cacciatore-50813.jpg', 15, 55, 70, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_pinot_noir", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_whole_kalamata_olives", "quantity": {"value": 16.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 bone in chicken thighs large (1 kg / 2 lb)","4 chicken drumsticks","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1 tbsp olive oil"],"purpose":"Chicken (Note 1):"},{"ingredients":["1 onion (, halved, finely sliced)","2 rosemary sprigs ((about 15 cm/6\" long), or 1 tsp dried rosemary)","2 bay leaves (, preferably fresh else dried)","3 garlic cloves (, finely minced)","3 anchovy fillets (or 1 tsp anchovy paste), optional (Note 2)","250g / 8 oz mushrooms (, sliced)","2 red capsicum (, sliced 8 mm thick (medium, not giant))","1/3 cup tomato paste","3/4 cup pinot noir (or other dry red wine (Note 3))","2 cups chicken stock/broth (, low sodium)","400g/14 oz canned crushed tomato","16 whole kalamata olives (, pitted, drained)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper","1 tsp dried oregano"],"purpose":"Cacciatore:"},{"ingredients":["Mashed potato ( or polenta)","Finely chopped parsley (, for sprinkling (optional))"],"purpose":"Serving"}]', '[{"title":"Season","description":"Spread the chicken out on a tray. Sprinkle both sides with the salt and pepper.","images":[],"step":1},{"title":"Brown skin","description":"Heat the oil over high heat in a large, deep, heavy based pan, preferably one with a lid (Note 4). Place the chicken thighs in the pan, skin side down, and cook until the skin is golden brown, around 6 minutes. Turn and cook the flesh side for just 1 minute, then remove the chicken onto the same tray. Then add the drumsticks and brown each side as best you can, about 1 1/2 minutes on each side (the shape makes it awkward). Remove onto the tray.","images":[],"step":2},{"title":"Onion","description":"Pour off and discard all but about 2 tablespoons of fat. Turn the heat down to medium and let the pan cool slightly. Add the onion, rosemary leaves, bay leaves and dried oregano. Cook for 3 minutes until the onion is starting to soften.","duration":3,"images":[],"step":3},{"title":"Garlic and anchovies","description":"Clear a space in the middle of the pan. Add the anchovies and garlic, cooking, mashing up the anchovies, until the garlic is light golden, then stir it into the onion.","images":[],"step":4},{"title":"Vegetables & tomato paste","description":"Turn the heat back up to high. Add the mushroom and capsicum. Stir until softened - about 5 minutes (the mushrooms will go watery then the water will evaporate). Add the tomato paste and cook for 2 minutes to cook out the sour flavour - do not shortcut this.","duration":2,"images":[],"step":5},{"title":"Sauce","description":"Add the wine. Stir, bring to simmer then allow to reduce by around 75%. Add the stock, canned tomato, salt and pepper. Stir, bring to a simmer.","images":[],"step":6},{"title":"Simmer","description":"Then carefully place the chicken into the sauce (skin side up) and pour any juices on the tray in as well. When the liquid returns to a simmer, cover, reduce the heat to medium then simmer energetically for 20 minutes. Remove lid, add olives, simmer for a further 10 minutes (no lid). This will reduce and thicken the sauce.","duration":20,"images":[],"step":7},{"title":"Serve","description":"Serve the chicken with plenty of sauce over mashed potato or polenta, sprinkled with parsley if desired.","images":[],"step":8}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-drumstick-recipes","chicken-recipes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d3a5c00a721', 'en', 'US', 'Chicken pasta bake', 'Recipe video above. Everything a chicken pasta bake should be - big, juicy, bubbly, cosy, with loads of extra tasty sauce, sizzling seasoned chicken, bacon and plenty of cheese. Nice change from the usual creamy pasta bakes!This is a complete meal with starch, protein and veg so you won''t need a side salad for this. Love the juicy chunks of tomato!', 'https://www.recipetineats.com/tachyon/2023/05/Chicken-pasta-bake_7.jpg', 15, 45, 60, 6, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_rigatoni", "quantity": {"value": 300.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["500g / 1 lb chicken thighs (, cut into small bite size pieces (Note 1))","1/2 tsp cooking/kosher salt","1/4 tsp black pepper","1/2 tsp garlic powder","2 tsp Italian herb mix (, any store bought type)"],"purpose":"Seasoned Chicken"},{"ingredients":["300g/10oz rigatoni (or penne, elbow macaroni, shells or similar)","2 tsp salt (, for cooking pasta)","5 slices streaky bacon","1/2 onion (, finely chopped)","2 garlic cloves (, minced)","1 1/2 tsp dried oregano","1/2 tsp chilli flakes / red pepper flakes","1/2 cup chardonnay or other dry white wine (Note 2)","2 tbsp tomato paste","700g / 24oz tomato passata (Note 3)","1/2 cup water","1 tsp cooking/kosher salt","1/2 tsp black pepper","3 tomatoes (, cut into 8 wedges then halved)","2 big handfuls baby spinach (or bite size kale)","2 cups mozzarella, (shredded)","1/2 cup (tightly packed) parmesan, (finely shredded)"],"purpose":"Pasta bake"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"description":"Cook pasta per packet directions, using boiling water seasoned with the 2 teaspoons of salt. Drain, rinse briefly under tap water, then set aside to cool while making the sauce.","images":[],"step":2},{"title":"Season chicken","description":"Toss together Seasoned Chicken ingredients in a bowl.","images":[],"step":3},{"title":"Crisp bacon","description":"Put bacon in an unheated very large non-stick pan (Note 2). Turn stove on medium high. The fat will melt so the bacon cooks in its own fat. Cook until light golden, remove onto paper towels, leaving fat in the pan. Once cool, cut into 1cm / 1/3\" pieces.","images":[],"step":4},{"title":"Sizzle chicken","description":"Top up bacon fat with olive oil if you don’t have at least 1 tbsp. Increase heat to high. Cook chicken for 3 minutes until light golden on the outside but still raw inside. Remove into a bowl with a slotted spoon.","duration":3,"images":[],"step":5},{"title":"Sauce","description":"In the same pan, cook garlic and onion for 1 minute, then add chilli flakes and oregano. Cook for 2 minutes until onion is translucent. Add wine and rapidly simmer for 1 to 2 minutes until mostly evaporated. Add tomato paste and cook for 1 minute to concentrate and improve flavour. Add passata, then use the water to rinse out the bottle. Add salt, pepper, chicken (including all juices on the plate). Mix, then simmer for 5 minutes on medium.","duration":1,"images":[],"step":6},{"title":"Toss","description":"Add baby spinach, tomato, pasta and bacon. Toss well.","images":[],"step":7},{"title":"Assemble","description":"Transfer to 23 x 33cm/9 x 13\" pan. Top with mozzarella then parmesan. Bake 25 minutes until melted with some golden spots.","images":[],"step":8},{"title":"Serve","description":"Stand for 5 minutes then serve!","duration":5,"images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-recipes","mains","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_21c841bde5ba', 'en', 'US', 'Spinach Ricotta Stuffed Shells (Conchiglioni)', 'Recipe VIDEO above. There''s no need to mess around stuffing hot floppy shells. Just stuff uncooked jumbo pasta shells and bake in loads of sauce! Bonus: The shells absorb the flavour of the sauce, and there''s plenty of tasty sauce for serving. Because nobody likes dry pasta shells!', 'https://www.recipetineats.com/tachyon/2023/03/Spinach-ricotta-stuffed-shells_4.jpg', 25, 105, 60, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.033, "unit": "jar of 50g"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["2 tbsp olive oil","2 eschallots/shallots or 1 small onion (, finely chopped (Note 1))","4 garlic cloves (, finely minced)","1 bay leaf (, fresh (sub dried))","1/2 tsp each dried thyme and oregano","1/3 cup tomato paste","700g / 25 oz tomato passata (US: tomato sauce) (Note 2)","1/3 cup Chardonnay or other dry white wine (sub more stock)","4 cups vegetable stock/broth (, low sodium)","3/4 tsp salt","1 1/2 tsp white sugar","1/3 tsp black pepper"],"purpose":"Sauce (you need LOTS!):"},{"ingredients":["250g / 8 oz frozen chopped spinach (, thawed (Note 3))","500g / 1 lb ricotta (, full fat please (Note 4))","1/2 cup parmesan (, finely shredded)","1 cup shredded cheese (Mozzarella, Colby, Cheddar, Tasty, Gruyere, Swiss, anything!)","1 egg","1 large garlic clove (, minced)","Grated fresh nutmeg (just a sprinkling) ( or 1/8 tsp nutmeg powder (optional))","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Filling:"},{"ingredients":["250g / 8 oz jumbo pasta shells (conchiglioni) (Note 3)","1 1/2 cups shredded mozzarella","1/2 cup parmesan (, shredded)","Fresh basil and parmesan (, for garnish (optional))"],"purpose":"Stuffed shells"}]', '[{"title":"Sauté","description":"Heat oil in a small pot over medium high heat. Add garlic, onion, bay leaf, thyme and oregano. Cook for 3 - 4 minutes until the onion is translucent. Add tomato paste and cook for 1 minute.","duration":3.5,"images":[],"step":1},{"title":"Reduce wine","description":"Add wine, increase heat to high and let it simmer rapidly until mostly evaporated (about 2 minutes).","images":[],"step":2},{"title":"Simmer","description":"Add passata, stock, sugar, salt and pepper. Stir then simmer on low *(uncovered) for 20 minutes. Use while hot.","duration":20,"images":[],"step":3},{"title":"Squeeze spinach","description":"Grab handfuls of spinach and squeeze out excess water.","images":[],"step":4},{"title":"Mix filling","description":"Place spinach in a bowl with remaining Filling ingredients. Mix well.","images":[],"step":5},{"description":"Assemble & Bake:","images":[],"step":6},{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":7},{"title":"Stuff","description":"Stuff UNCOOKED shells with spinach ricotta filling. Stuff them full!","images":[],"step":8},{"title":"Assemble","description":"Pour the hot tomato sauce in a 23 x 33 cm / 9 x 13\" baking dish. Gently place the stuffed shells in - most will be submerged, some may poke above surface.","images":[],"step":9},{"title":"Bake","description":"Cover with a baking tray (or foil) then bake for 70 minutes.","duration":70,"images":[],"step":10},{"title":"Cheese it! Check the shells","description":"they should be al dente! (If not, return to oven, covered). Sprinkle with mozzarella then parmesan. Bake 15 minutes until melted.","images":[],"step":11},{"description":"Serve, garnished with extra parmesan and basil if desired!","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian","Western"],"categories":["casseroles-and-cosy-bakes","cosy-desserts","italian-recipes","pasta-bakes","pasta-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c0bed5d30664', 'en', 'US', 'Chorizo chickpea stew (fast)', 'Recipe video above. This is a great, hearty, full flavoured Spanish-inspired stew that''s quick to make. Chorizo is the shortcut here, adds a ton of flavour into the sauce!Serve this as a chunky soup with crusty bread for mopping, flatbreads for dunking, or like stew over a bed of couscous, small pasta (like orzo/risoni, orecchiette), mashed potato or cauliflower puree. For an extra hit of protein, top with a fried egg. YUM!Serves 2 hearty appetites, or 3 normal appetites.', 'https://www.recipetineats.com/tachyon/2023/01/Chorizo-chickpea-stew_0.jpg', 7, 20, 27, 2, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_chorizo", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","250g / 8 oz chorizo (2 pieces) (, cut into 8mm / 1/3\" slices (Note 1))","2 garlic cloves (, minced)","1/2 tsp dried thyme","1/2 tsp smoked paprika (sub normal paprika)","1 bay leaf (, preferably fresh, otherwise dried)","400g / 14oz can crushed tomato","400g/14 oz can chickpeas (, drained (or other beans of choice))","1 cup chicken stock/broth (, low sodium)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"]}]', '[{"title":"Sauté chorizo","description":"Heat olive oil in a large saucepan or small pot over medium high heat. Add chorizo and cook for 3 minutes or until golden.","duration":3,"images":[],"step":1},{"title":"Sauté aromatics","description":"Add garlic, thyme, paprika and bay leaf, then stir for 1 minute.","duration":1,"images":[],"step":2},{"title":"Add everything else","description":"Add tomato, chickpeas, chicken stock, salt and pepper. Stir, bring to a simmer then lower the heat down to medium low so it is simmering very gently.","images":[],"step":3},{"description":"Cook for 15 minutes (no lid), stirring regularly to ensure the base does not catch, until the sauce has reduced and thickened.","duration":15,"images":[],"step":4},{"title":"Serve","description":"Discard bay leaf and serve. I love this with hot crusty bread (slathered with butter!).","images":[],"step":5}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Spanish","Spanish Style","Western"],"categories":["casseroles-and-cosy-bakes","dinner-tonight","quick-and-easy","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_99df5f43dfdc', 'en', 'US', 'Chicken Tagine', 'Recipe video above. Browned chicken braised in a spiced sauce, the secret to a great Moroccan Chicken Tagine is a well-balanced spice blend! Best made with bone-in chicken thighs, which stay juicy for the required sauce simmering time. Drumsticks work well too. Some versions are made with olives, others use dried fruit, and some even use both. I''ve opted for fruit because it''s one of the few dishes I love fruit with meat! See note 7 for the olive option (it''s delish too). Note: Crushed tomato isn''t typically used in traditional tagines but I love how it thickens the sauce so it clings to the couscous better. Without, the sauce is watery.', 'https://www.recipetineats.com/tachyon/2022/05/Chicken-tagine_5.jpg', 15, 40, 55, 6, '[{"id": "ing_apricots", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_powder", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_couscous_plain_or_with_fruit_and_or_nuts", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_almonds", "quantity": {"value": 0.2, "unit": "pack of 250g"}}]', '[{"ingredients":["1 cup dried apricot, halved (Note 1)","6 x 220g / 7 oz chicken thighs (, bone-in skin-on (Note 2))","3/4 tsp salt (cooking/kosher salt)","2 tbsp olive oil","1 onion ((brown/yellow), cut into 0.3 cm/ 1/8\" slices)","2 garlic cloves (, finely minced)","1 cinnamon stick (sub 1/2 tsp powder)","400 g / 14 oz crushed tomato (1 can)","400g / 14 oz canned chickpeas (, drained (Note 10))","1 tbsp preserved lemon skin (, finely minced (Note 3))","2 1/2 cups chicken stock, low-sodium ( (or homemade))"]},{"ingredients":["1 tsp cooking salt","3/4 tsp ground cumin","3/4 tsp ground ginger","3/4 tsp black pepper","1/2 tsp allspice powder","1/4 tsp cinnamon powder","1/4 tsp coriander powder","1/8 tsp clove powder"],"purpose":"Ras el hanout spice blend (Note 4):"},{"ingredients":["Couscous - plain or with fruit and/or nuts (recipe here)","2 tbsp fresh coriander (, roughly chopped)"],"purpose":"For serving:"},{"ingredients":["1 cup kalamata olives (instead of apricots) (Note 7)","1/3 cup slivered almonds (, lightly toasted, for garnish (Note 8))"],"purpose":"Alternative add in options"}]', '[{"title":"Plump apricots","description":"Soak the dried apricots in a bowl of boiling water for 30 minutes, then drain (this plumps them up).","duration":30,"images":[],"step":1},{"title":"Season chicken","description":"Sprinkle both sides of the chicken with the salt.","images":[],"step":2},{"title":"Brown chicken","description":"Heat oil the oil in a large, deep skillet or pot (Note 5) over high heat. Place chicken in the skillet skin side down and cook for 8 to 10 minutes until deep golden. Turn and cook the flesh side for 1 minute then remove to a plate.","duration":9,"images":[],"step":3},{"title":"Sauté aromatics & spices","description":"Discard all but 2 tablespoons of fat in the skillet. Reduce heat to medium. Add onions and cook for 3 minutes. Add garlic and cook for 1 minute. Add the Ras el hanout and stir for 30 seconds.","duration":3,"images":[],"step":4},{"title":"Tagine sauce","description":"Add the cinnamon stick, tomato, chickpeas, plumped apricots, stock and preserved lemon, then stir. Place the chicken on top, skin side up.","images":[],"step":5},{"title":"Simmer covered 5 minutes","description":"Bring the liquid to a simmer then cover with a lid (Note 6). Cook for 5 minutes, adjusting the heat as needed so the liquid is simmering (but not too rapidly else base may catch).","duration":5,"images":[],"step":6},{"title":"Simmer uncovered 20 minutes","description":"Remove lid then cook for a further 20 minutes or until the internal temperature of the chicken is at least 70°C/158°F (Note 6).","images":[],"step":7},{"title":"Serve","description":"Remove from stove and rest for 5 minutes. Serve over couscous (Note 9), sprinkled with fresh coriander.","duration":5,"images":[],"step":8}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Moroccan"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-recipes","cuisines","mains","middle-eastern-recipes","moroccan","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cf5a8dcf7b6a', 'en', 'US', 'Eggplant Parmigiana (Parmigiana di Melanzane)', 'Recipe video above. There''s a little labour involved in this. But you''ll be rewarded with one of the all-time greatest vegetarian comfort foods known to mankind!Assemble ahead, then pop in the oven to bake when you''re ready!', 'https://www.recipetineats.com/tachyon/2021/05/Eggplant-Parmigiana_1.jpg', 40, 60, 100, 8, '[{"id": "ing_egg", "quantity": {"value": 1.8, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.833, "unit": "pack of 200g"}}, {"id": "ing_basil", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1.8kg / 4 lbs large eggplants (aubergines) - about 5 (, sliced lengthways 8mm (1/3\")-thick (skin on, Note 1))","1/4 cup olive oil (for brushing)"],"purpose":"Baked Eggplant Slices:"},{"ingredients":["1 2/3 cups parmesan (, finely grated)","2 cups basil leaves ((loosely packed), stalks reserved)","1 1/2 cups mozzarella (, shredded (for topping) (Note 2))"],"purpose":"Layers:"},{"ingredients":["2 tbsp extra virgin olive oil","1 onion (, finely diced)","5 garlic cloves (, finely minced)","600ml / 20oz tomato passata (Note 3)","400g/ 14oz canned tomatoes (, crushed or finely chopped (Note 4))","1 1/2 tsp white sugar","1 1/2 tbsp fresh oregano (, finely chopped (or 1/2 tsp dried oregano, or 1 sprig fresh basil))","1 cup water","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Sugo (tomato sauce):"}]', '[{"description":"Baking eggplant:","images":[],"step":1},{"description":"Preheat oven to 220°C / 430°F (200°C fan).","images":[],"step":2},{"title":"Line three trays","description":"Line three large trays with baking / parchment paper.","images":[],"step":3},{"title":"Brush eggplant with oil","description":"Brush eggplant slices on each side with oil.","images":[],"step":4},{"title":"Bake 35 minutes","description":"Arrange eggplant in a single layer on the trays and bake for about 35 - 45 mins or until browning and tender, turning the eggplant halfway. I put the trays on the top shelf, in the middle, then I put one tray on the floor of the oven. As each tray finishes, I remove the tray and move the others up.","images":[],"step":5},{"title":"Cool","description":"Remove from oven, leave on trays to cool.","images":[],"step":6},{"description":"Tomato sauce (sugo):","images":[],"step":7},{"title":"Sauté onions and garlic","description":"Heat olive oil in a large skillet over medium-high heat. Sauté onions and garlic for 3 minutes until softened and just about to colour on the edges.","duration":3,"images":[],"step":8},{"title":"Add remaining ingredients","description":"Pour in the passata , canned tomatoes, water, oregano and sugar. Stir and bring to a simmer.","images":[],"step":9},{"title":"Simmer 30 minutes: Simmer uncovered for about 30","description":"40 minutes, stirring occasionally, until thickened, adding the basil stalks halfway through cooking (so they don’t lose their flavour).","images":[],"step":10},{"description":"The final consistency should be slightly thicker than a pasta sauce so it’s spreadable and not leaching liquid, but not too pasty either. Add extra water a little at a time if required during cooking if it gets too thick. Remove the basil stalks and discard.","images":[],"step":11},{"title":"Season","description":"Stir in salt and pepper. (Remember, we get salt from the parmesan too, so no need to go overboard here)","images":[],"step":12},{"description":"Assembling and baking:","images":[],"step":13},{"description":"Reduce oven to 180°C / 350°F (160°C fan).","images":[],"step":14},{"description":"Smear a little tomato sauce in the bottom of baking dish, 23 x 33cm / 9 x 13\" (or thereabouts).","images":[],"step":15},{"title":"Layer 1","description":"Lay one third of the eggplant so it covers the base (some overlap is OK when layering eggplant). Spread 1/3 of the remaining sugo over eggplant. Drizzle with a little olive oil. Sprinkle with 1/3 of the parmesan, and 1/3 of basil leaves.","images":[],"step":16},{"title":"Layer 2","description":"Repeat another 1/3 each of eggplant, tomato sauce, olive oil, basil and parmesan.","images":[],"step":17},{"title":"Layer 3 (top layer)","description":"Repeat again with remaining eggplant, tomato sauce and some olive oil. Do not put basil on top layer (we will garnish after baking). Scatter with remaining parmesan, then all the mozzarella.","images":[],"step":18},{"description":"Bake for 25 mins until bubbling and golden.","duration":25,"images":[],"step":19},{"title":"Rest","description":"Let it rest for 5 to 10 minutes (easier to slice neatly). Scatter over remaining fresh basil leaves. Cut like lasagna and serve! (Optional: sprinkle with extra parmesan).","duration":7.5,"images":[],"step":20}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian"],"categories":["casseroles-and-cosy-bakes","dietary","gluten-free-recipes","italian-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6399a0413b12', 'en', 'US', 'Pastitsio (Greek Pasta Bake)', 'Recipe video above. Greece''s answer to Italian Lasagna! This traditional Greek dish is made with layers of pasta topped with a rich meat sauce perfumed with a hint of cinnamon and clove, topped with a thick layer of cheese sauce.For the neat layers pictured, arrange the pasta so they''re all going in one direction, and rest the baked Pastitsio for 15 minutes before slicing. Excellent for making ahead (keeps for 4 to 5 days in the fridge) and freezes very well!', 'https://www.recipetineats.com/tachyon/2021/02/Pastitsio-_4.jpg', 15, 120, 135, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.25, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_round_clove", "quantity": {"value": 1000.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_cheese", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 120.0, "unit": "block of 200g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}]', '[{"ingredients":["2 tbsp olive oil","3 garlic cloves (, finely minced)","2 red onions (, finely chopped (sub yellow or brown onions))","1 kg / 2 lb beef mince (ground beef)","3/4 cup red wine (, dry (Note 1))","800g / 28 oz canned crushed tomato","2 beef bouillon cubes (, crumbled (stock cubes))","2 tbsp tomato paste","1 tsp white sugar","1 bay leaf","1/2 tsp cinnamon powder","1 cinnamon stick (or extra 1/2 tsp cinnamon powder)","1/4 tsp ground cloves","3/4 tsp salt","1 tsp black pepper"],"purpose":"Meat Sauce:"},{"ingredients":["100g / 7 tbsp butter (, unsalted)","3/4 cup flour (, plain/all purpose)","1 litre / 4 cups milk (, whole/full fat best but low fat ok)","1/8 tsp nutmeg (, preferably freshly grated)","1/2 tsp salt","100g / 3 oz Kefalotyri Greek cheese (sub Parmesan or Romano) (, finely shredded (Note 2))","2 egg yolks (egg whites are used in the pasta)"],"purpose":"Greek Bechamel:"},{"ingredients":["400g / 14 oz Pastitsio No. 2 pasta / Greek bucatini (sub small ziti, penne or normal bucatini, Note 3)","120g / 4 oz feta (, crumbled)","2 egg whites (yolks used in Béchamel)"],"purpose":"Pasta:"},{"ingredients":["75g / 3 oz Kefalotyri Greek cheese (sub parmesan or Romano) (, finely grated (Note 2))"],"purpose":"Topping:"}]', '[{"description":"Heat in a large pot over high heat. Add garlic and onion, cook for 2 - 3 minutes until onion is softened. Add beef and cook, breaking it up as you go, until it changes from red to brown.","duration":2.5,"images":[],"step":1},{"description":"Add wine and and cook until the wine has mostly evaporated - about 3 minutes.","images":[],"step":2},{"description":"Add remaining Meat Sauce ingredients. Stir well, bring to simmer, then reduce heat to medium / medium low so it''s simmering gently. Cook for 45 min to 1 hour until liquid is mostly gone, stirring every now and then. It should be a thick mixture with little liquid, not saucy like Spaghetti Bolognese (Note 4).","duration":45,"images":[],"step":3},{"description":"Remove from stove and cool. Preferably to room temperature, otherwise for at least 30 minutes before assembling (lid off).","images":[],"step":4},{"description":"Greek Béchamel (Note 5):","images":[],"step":5},{"description":"Melt butter in a large saucepan over medium heat. Add flour and stir for 1 minute.","duration":1,"images":[],"step":6},{"description":"While stirring, slowly pour half the milk in. It should turn into a wet paste. Then again, while stirring, pour in remaining milk - the paste should easily dissolve so it''s lump-free. If not, just whisk vigorously.","images":[],"step":7},{"description":"Cook, stirring so the base doesn''t catch, for 5 minutes or until thick enough so it coats the back of a wooden spoon thickly and you can draw a path across it with your finger.","duration":5,"images":[],"step":8},{"description":"Remove from stove. Stir in nutmeg, cheese and salt.","images":[],"step":9},{"description":"Leave to cool for 5 minutes. Then whisk in egg yolks quickly. Place lid on and set aside. If sauce cools and gets too thick to pour, just reheat on a low stove until pourable.","duration":5,"images":[],"step":10},{"description":"Pasta (Note 6):","images":[],"step":11},{"description":"When you''re ready to assemble, cook the pasta per packet instructions, minus 1 minute.","images":[],"step":12},{"description":"Drain, then return to the pot. Leave to cool for 3 minutes, then stir through egg whites. Gently stir through crumbled feta.","duration":3,"images":[],"step":13},{"description":"Assemble and bake:","images":[],"step":14},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":15},{"description":"Place pasta in a baking dish (33 x 22 x 7 cm / 9 x 13 x 2.75\"), arranging them so they are all going in the same direction as best you can (for visual effect when sliced). Make the surface as level as you can.","images":[],"step":16},{"description":"Top with Meat Sauce, then smooth the surface.","images":[],"step":17},{"description":"Pour over Béchamel Sauce, then sprinkle over the cheese.","images":[],"step":18},{"description":"Bake 30 min or until crust turns golden.","images":[],"step":19},{"description":"Cool for at least 10 minutes so you can cut neat slices with the layers neatly visible. Serve!","images":[],"step":20}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["casseroles-and-cosy-bakes","greek-recipes","mediterranean-recipes","pasta-bakes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a839b8dac309', 'en', 'US', 'Chicken Tetrazzini (creamy chicken mushroom pasta bake)', 'Recipe video above. A big, creamy pasta bake with juicy chicken and mushrooms. Cheesy, hot and completely delicioius! Rumoured to be named after an Italian opera star Luisa Tetrazzini when an American Chef created this dish for her. So it''s not authentic Italian - but it doesn''t make this any less delicious!!', 'https://www.recipetineats.com/tachyon/2020/08/Chicken-Tetrazzini_0.jpg', 15, 60, 75, 8, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}]', '[{"ingredients":["500g / 1lb spaghetti or other long pasta, cooked per packet (penne, macaroni, ziti ok too) (Note 1)"]},{"ingredients":["2 tbsp (30g) butter","500g / 1lb chicken thighs (, skinless boneless (Note 2))"],"purpose":"Chicken"},{"ingredients":["4 tbsp (60g) butter (, unsalted)","500g / 1lb mushrooms (, sliced 1/2 cm / 1/5\" thick)","2 garlic cloves (, minced)","1 onion (, finely chopped)","4 tbsp flour","2 cups milk (, any fat, any type)","1 cup cream (, heavy / thickened (sub more milk))","2 cups chicken stock/broth (, low sodium (or water + 2 stock cubes))","1/2 tsp black pepper","1 tsp salt","2 cups cheese (, shredded (cheddar, jack, colby - not mozz))"],"purpose":"Creamy Sauce"}]', '[{"description":"Melt 2 tbsp butter in a large pot over high heat. Add chicken, sprinkle with pinch of salt and pepper. Cook 1 1/2 minutes until golden.","images":[],"step":1},{"description":"Turn chicken, sprinkle with salt and pepper. Cook 1 minute until golden then remove onto plate - doesn''t need to be fully cooked (will cook more in oven).","images":[],"step":2},{"description":"Rest 5 minutes, then chop into small pieces, or shred.","images":[],"step":3},{"description":"Preheat oven to 160°C / 325°F.","images":[],"step":4},{"title":"Cook mushrooms","description":"Melt 4 tbsp butter over high heat in the same pot. Add mushrooms and cook for 4 minutes until starting to go floppy but not yet golden.","duration":4,"images":[],"step":5},{"title":"Add onion","description":"Add garlic and onion, cook for 3 minutes until mushrooms are golden. Add a pinch of salt and pepper halfway through.","duration":3,"images":[],"step":6},{"title":"Add flour & milk","description":"Turn heat down to medium. Add flour. Stir for 30 seconds. Add milk and stir for 10 seconds or until it thickens (see video at 52 sec).","duration":0.5,"images":[],"step":7},{"title":"Add cream and broth","description":"Add chicken stock, cream, 1 tsp salt and 1/2 tsp pepper. Stir, then let the mixture heat up, stirring every now and then so it doesn''t catch on the base, and cook until the sauce thickens enough so you can draw a path on the back of the spoon (video at 1.04). Do not make it very thick - it gets thicker in next steps.","images":[],"step":8},{"title":"Add cheese & pasta","description":"Turn stove off. Stir through half the cheese (will melt in oven), then add pasta and chicken. Toss to mix, taste and add more salt if needed.","images":[],"step":9},{"title":"Bake","description":"Pour into 23 x 33cm / 9 x 13\" pan, smooth surface. Top with remaining cheese. Bake 25 minutes until golden and bubbly. Serve immediately!","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","italian-recipes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2e596835d0b8', 'en', 'US', 'Baked Spinach and Ricotta Rotolo', 'Recipe video above. Rotolo is a lessor known Italian pasta dish where a filling is rolled up in pasta sheets then rolled like a roulade, poached, sliced then served. It is so tasty, but quite technical and time consuming to make. This is my version - a baked version which is made more like cannelloni. Much easier, just as tasty and best of all, you get crunchy brown bits you don''t get with the traditional rotolo!Want a meat filling? Use the filling from this Spinach & Beef Cannelloni - scale up by 50% (or use extra spinach), cool (will thicken) then roll!', 'https://www.recipetineats.com/tachyon/2014/07/Spinach-Ricotta-Rotolo-09.jpg', 30, 45, 75, 5, '[{"id": "ing_lasagne_sheets", "quantity": {"value": 8.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_spinach", "quantity": {"value": 500.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["8 - 10 fresh lasagne sheets (15 x 11 cm/6 x 4.5\") (Note 1)","1 cup mozarella cheese (, shredded)","1 tbsp olive oil (for drizzling later)"]},{"ingredients":["500g / 1 lb frozen spinach (pre chopped) (, thawed and excess water squeezed out (Note 2))","500 g / 1 lb ricotta cheese (NOT smooth, whipped or spreadable in tubs, Note 3)","1 cup mozzarella cheese (, shredded)","1 egg","1/2 cup parmesan cheese (, shredded)","1 garlic clove (, pressed using garlic crusher or finely grated)","1/8 tsp finely grated nutmeg (substitute nutmeg powder)","3/4 tsp salt","1/2 tsp Black pepper"],"purpose":"Filling"},{"ingredients":["2 tbsp olive oil","2 cloves garlic (, minced)","1/2 onion (, finely diced (brown, yellow, white))","3/4 tsp salt","1/2 tsp black pepper","700 g / 24 oz tomato passata (US: Tomato puree) (Note 5)","1 1/2 cups water","Handful basil leaves (optional)"],"purpose":"Tomato Sauce"}]', '[{"description":"Heat oil in a 25cm/10\" ovenproof skillet over medium high heat. (Note 6)","images":[],"step":1},{"description":"Add garlic and sauté for 10 seconds then add onion.","duration":0.16666666666666666,"images":[],"step":2},{"description":"Cook onion until translucent and starting to turn golden, then passata, water, chilli flakes (if using), salt and pepper.","images":[],"step":3},{"description":"Simmer for 5 minutes on medium low, then stir through basil. Should be quite thin - the lasagna sheets will absorb water while in the oven so sauce thickens alot in oven.","duration":5,"images":[],"step":4},{"description":"Scoop out 1 cup of the Tomato Sauce which will be used to drizzle over the dish at the end. Keep sauce warm.","images":[],"step":5},{"description":"Filling & Assembling:","images":[],"step":6},{"description":"Preheat oven to 180°C/350CF (all oven types)","images":[],"step":7},{"description":"Place Filling ingredients in a bowl. Mix well with wooden spoon.","images":[],"step":8},{"description":"As per the photo & video, lay out the lasagne sheet with the shorter end in front of you.","images":[],"step":9},{"description":"Place 1/3 cup (packed) of filling onto the lasagne sheet. Dab some water on the end furthest away from you (to seal the roll), then roll up starting from the end closest to you. Finish with the seal down.","images":[],"step":10},{"description":"Cut rolls into 3 (so each piece is 3.5cm/1.5\" wide). Place the rolls into the tomato sauce with the filling facing up.","images":[],"step":11},{"description":"Repeat with remaining lasagna sheets until all the Filling is used up.","images":[],"step":12},{"description":"Drizzle the reserved Tomato Sauce over (don''t cover completely, leave some exposed).","images":[],"step":13},{"description":"Cover loosely with foil, bake 30 minutes.","images":[],"step":14},{"description":"Remove from oven, remove foil. Drizzle with oil, top with mozzarella.","images":[],"step":15},{"description":"Bake 15 minutes or until the cheese is bubbly and golden and you''ve got some crunchy golden bits on the edges. Serve!","images":[],"step":16}]', '["egg","milk"]', '["gluten_free","high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["casseroles-and-cosy-bakes","italian-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_00a5320dffe7', 'en', 'US', 'Creamy Pasta Bake "formula" - make this with ANYTHING!', 'Recipe video above. This is a "formula" using a creamy white sauce to make a pasta bake using anything you''ve got. Add in literally any meat, raw or cooked, any vegetable (frozen, canned, dried, fresh, pickled). Canned tuna or salmon, bacon, ham, chorizo. You''re only limited by your imagination! (Eer - and what''s in your pantry 😂) If using raw meat and veg that needs to be cooked, cook them first then make the sauce in the same pot. If using add ins like canned salmon and corn that do not need pre cooking, just make the sauce and mix it up with the pasta, then bake until bubbly and golden! See above in post for combination suggestions.', 'https://www.recipetineats.com/tachyon/2020/03/Creamy-pasta-bake-make-with-anything-1.jpg', 15, 40, 55, 8, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.25, "unit": "L"}}, {"id": "ing_stock_bouillon_cube_or_powder", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}]', '[{"ingredients":["500g / 1lb pasta (any short or long except risoni/orzo) (Note 1)","1 tbsp salt (for water)"]},{"ingredients":["4 tbsp (60g) butter (, unsalted)","2 garlic cloves (, minced (optional, sub 1 tsp powder))","5 tbsp flour (, any (GF option Note 2))","5 cups (1.25 litres) milk (, any fat, any type)","2 tsp stock / bouillon cube or powder (, chicken or veg)","3/4 cup (75g) parmesan","1/2 tsp black pepper"],"purpose":"Creamy Sauce (Note 2 for subs)"},{"ingredients":["1 tsp EACH thyme and parsley (, or any other dried herbs)","1/2 tsp EACH mustard, garlic, onion powder"],"purpose":"Choose ONE flavouring (optional)"},{"ingredients":["8 cups Add Ins - raw or cooked meats, bacon, ham, diced vegetabes (frozen, canned, fresh), canned or fresh fish (Note 3)"],"purpose":"Add Ins"},{"ingredients":["1 tbsp olive oil","Salt and pepper"],"purpose":"For Cooking RAW Add Ins (like raw chicken, mushrooms, zucchini)"},{"ingredients":["2 cups (200g) cheese (, shredded (Note 4))"],"purpose":"Cheesy Topping"}]', '[{"description":"Preheat oven to 180°C/350°F.","images":[],"step":1},{"title":"Pasta","description":"Boil water with 1 tbsp salt. Add pasta, bring back up to boil then cook per packet directions MINUS 2 minutes. Should be just cooked, still slightly firm in middle. Drain, return to pot.","images":[],"step":2},{"description":"Cooking RAW Meat & Vegetables","images":[],"step":3},{"description":"Heat half butter & 1 tbsp oil in a large pot over high heat. Stir in garlic for 10 seconds, then cook your raw meat and vegetables with a sprinkle of salt and pepper. Meat must be fully cooked - will not cook further in oven.","duration":0.16666666666666666,"images":[],"step":4},{"description":"Add remaining butter, melt. Mix in flour, then follow Creamy Sauce step 2 onwards.","images":[],"step":5},{"description":"Start here if you have NO COOK Add Ins (like canned tuna): Melt butter in large saucepan over medium heat. Add garlic and stir for 10 seconds, then stir in flour.","duration":0.16666666666666666,"images":[],"step":6},{"description":"While mixing, gradually pour in about 1/3 of the milk. Once the flour-butter mixture is incorporated into the milk, pour in remaining milk and mix.","images":[],"step":7},{"description":"Add remaining milk, stock powder, parmesan, pepper and herbs (if using) and mix. When the milk starts to heat up, mix constantly to make sure the white sauce doesn’t catch on the base.","images":[],"step":8},{"title":"After 4","description":"5 minutes, the sauce should be thick enough that you can draw a path across the back of a spoon (see video).","images":[],"step":9},{"description":"Assemble & Bake","images":[],"step":10},{"description":"Return cooked pasta into pot. Mix with sauce and no-cook Add Ins.","images":[],"step":11},{"description":"Spread in large casserole dish, top with cheese and bake 25 minutes until golden and bubbly. Serve!","images":[],"step":12}]', '["fish","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","coronavirus-food","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d80d8f8b199f', 'en', 'US', 'Emergency Chicken Rice Casserole', 'Recipe video above. Dump-and-bake creamy chicken rice casserole made FROM SCRATCH! Perfectly cooked rice, creamy cheesy sauce, juicy seasoned chicken. Unusually high liquid-to-rice ratio because 1) baked uncovered (brown chicken); and 2) creamy rice (rather than stodgy!). See Note 7 re: SCALING recipe!', 'https://www.recipetineats.com/tachyon/2019/08/Ultra-Lazy-Chicken-Rice-Casserole_6.jpg', 10, 45, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_broccoli", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}]', '[{"ingredients":["500g (1 lb) chicken thighs or tenders (tenderloin) (, cut into 1.5cm / 2/3\" pieces (Note 1))","1/2 tsp dried thyme","1 tsp garlic powder","1/2 tsp pepper","1/2 tsp vegetable or chicken stock powder (granulated bouillon) (Note 2)","1 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["2 1/2 cups (625 ml) chicken broth/stock (, low sodium)","2 1/2 cups (625 ml) milk (, any fat %)","1 1/2 cups long grain white rice (, uncooked (Note 3))","1/4 cup (35g) flour (, plain / all purpose)","1 tsp vegetable or chicken stock powder (granulated bouillon) (Note 2)","2 cloves garlic (, minced)","2 tbsp (30g) unsalted butter","2 broccoli heads (large!), cut into florets (Note 4)","2 cups (200g) shredded cheese"],"purpose":"Rice:"},{"ingredients":["2 green onions (, finely sliced)"],"purpose":"Garnish:"}]', '[{"description":"Preheat oven to 190°C/375°F (180°C/350°F fan/convection).","images":[],"step":1},{"description":"Mix Chicken Ingredients.","images":[],"step":2},{"description":"Heat chicken broth and milk until hot using any method (stove, microwave). Can combine together in saucepan. (Note 5)","images":[],"step":3},{"description":"Spread rice in 23 x 33cm / 9 x 13\" ceramic or glass baking dish. (Note 6)","images":[],"step":4},{"description":"Sprinkle with flour, stock powder and garlic.","images":[],"step":5},{"description":"Add the hot chicken broth, stir until flour dissolved (some small lumps ok).","images":[],"step":6},{"description":"Add milk, swish rice to spread out evenly.","images":[],"step":7},{"description":"Spread broccoli on top, then chicken, then plonk butter on (anywhere).","images":[],"step":8},{"description":"Bake uncovered for 40 minutes. (Might get some browned skin on surface, that''s ok)","duration":40,"images":[],"step":9},{"title":"CHECK rice before stirring","description":"should be JUST cooked (Note 7).","images":[],"step":10},{"description":"Add half the cheese, stir through, being sure to get rice in the corners and edges of pan. Should be creamy and quite loose (see video).","images":[],"step":11},{"description":"Top with cheese, return to oven for 5 minutes until just melted.","duration":5,"images":[],"step":12},{"description":"Sprinkle with green onion, if using, then serve!","images":[],"step":13}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","chicken-recipes","dinner-tonight","emergency-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a5140d9f013b', 'en', 'US', 'Vegetable Lasagna', 'Recipe VIDEO above. Layered with roasted vegetables, spinach and ricotta, a homemade sauce and as much cheese as you see fit, this big batch vegetarian lasagna reheats brilliantly. Epic meat-free food for carnivores!', 'https://www.recipetineats.com/tachyon/2019/02/Vegetable-Lasagna_10.jpg', 25, 50, 75, 8, '[{"id": "ing_pumpkin", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_rated_nutmeg_optional", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.825, "unit": "jar of 50g"}}, {"id": "ing_lasagne_sheets", "quantity": {"value": 375.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 2.4, "unit": "pack of 125g"}}]', '[{"ingredients":["500 g / 1 lb pumpkin (, 2cm / 4/5\" cubes)","2 large zucchinis (, cut into 2cm / 4/5\" chunks)","2 onions (any type) (, cut into wedges)","2 tbsp olive oil","1 garlic clove (, minced)","Salt and pepper"],"purpose":"Roasted Vegetables (Note 1):"},{"ingredients":["250 g / 8 oz frozen chopped spinach (, thawed)","500 g / 1 lb ricotta (Note 2)","1/2 cup / 50 g grated parmesan (or 3/4 cup shredded cheese)","1 egg","1 garlic clove (, minced)","1/8 tsp grated nutmeg, optional (fresh or powder)","1/2 tsp each Salt and pepper"],"purpose":"Spinach Ricotta:"},{"ingredients":["1 tbsp olive oil","1 garlic clove","1 small onion (, finely chopped (any, I use brown))","700 g / 24 oz tomato passata (Note 3)","400 g / 14 oz crushed tomato","1/2 cup / 125 ml water","3/4 tsp each dried thyme and oregano (or basil, parsley)","1/2 tsp dried chilli flakes (can omit / adjust to taste)","Salt and pepper"],"purpose":"Sauce:"},{"ingredients":["330g / 11 oz jar roasted red pepper strips, drained (Note 4)","375 g / 13 oz fresh lasagne sheets (Note 5)","300 g / 3 cups shredded mozzarella (or MORE!)"],"purpose":"Lasagna:"}]', '[{"description":"Roasted Vegetables:","images":[],"step":1},{"description":"Preheat oven to 200C/390F.","images":[],"step":2},{"description":"Place vegetables on the tray, drizzle with oil, sprinkle with garlic, salt and pepper. Toss.","images":[],"step":3},{"description":"Roast for 25 minutes, turning at 15 minutes, until tender and browned.","duration":25,"images":[],"step":4},{"description":"Remove from oven, loosen from tray with spatula while warm (can stick when cools).","images":[],"step":5},{"description":"Heat oil in a skillet over medium high heat. Add garlic and onion, cook for 3 minutes until golden.","duration":3,"images":[],"step":6},{"description":"Add passata, crushed tomato, water, dried herbs, chilli, salt and pepper. Stir. Simmer on medium low heat for 20 minutes. Adjust salt at the end. *Add a teeny touch of sugar if it''s a bit sour, depends on quality of tomatoes used.*","duration":20,"images":[],"step":7},{"description":"Remove from stove and let cool for 5 minutes before using.","duration":5,"images":[],"step":8},{"description":"Ricotta Mixture:","images":[],"step":9},{"description":"Place ingredients in a bowl and mix until combined.","images":[],"step":10},{"description":"Preheat oven to 160C/320F.","images":[],"step":11},{"description":"Spread a ladle of tomato sauce on the base of a large baking dish (Note 5).","images":[],"step":12},{"description":"Cover with lasagna sheets, tearing as required to fit.","images":[],"step":13},{"description":"Top with roasted vegetables, scatter over red peppers. Spoon over 2 1/2 cups of Sauce, then sprinkle with half the cheese.","images":[],"step":14},{"description":"Cover with lasagna sheets. Spread over Ricotta mixture.","images":[],"step":15},{"description":"Cover with lasagna sheets. Pour over remaining sauce and sprinkle with remaining cheese.","images":[],"step":16},{"title":"Bake for 25","description":"30 minutes or until the cheese is golden. If using dried lasagna sheets, stick a knife in the middle to ensure it''s cooked - if it needs longer, cover and stick it back in the oven.","duration":27.5,"images":[],"step":17},{"description":"Rest for 5 minutes before cutting and serving. Store leftovers per notes - brilliant reheated!","duration":5,"images":[],"step":18}]', '["egg","milk"]', '["gluten_free","high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","pasta-bakes","pumpkin","sunday-supper","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_27b2c3b8bbe3', 'en', 'US', 'Spinach Ricotta Cannelloni', 'Recipe VIDEO above. Juicy, perfectly seasoned spinach and ricotta filling inside cannelloni pasta tubes, topped with a simple, tasty tomato sauce and melted cheese. Great for freezing!First published in September 2017, this reader favourite recipe is included by popular demand in my debut cookbook Dinner. I took the opportunity to make it even better by increasing the volume and thinning the thickness of the sauce so there''s plenty of liquid to cook the cannelloni but it''s still saucy when you serve it up. It was great before, it''s AMAZING now!', 'https://www.recipetineats.com/tachyon/2017/09/Spinach-Ricotta-Cannelloni-1-copy-1.jpg', 25, 35, 60, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.033, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cannelloni_tubes", "quantity": {"value": 18.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, finely chopped)","4 garlic clove (, minced)","1 bay leaf (, fresh (sub dried))","1/2 tsp each dried thyme and oregano","1/3 cup tomato paste","800 g / 28 oz canned crushed tomato","4 cups vegetable or chicken stock/broth (, low sodium)","1/3 cup Chardonnay or other dry white wine (sub more stock)","3/4 tsp salt","1 1/2 tsp sugar","1/3 tsp black pepper","2/3 cup basil leaves (, roughly torn (recommended but not critical))"],"purpose":"Sauce (you need LOTS!):"},{"ingredients":["250 g / 8 oz frozen chopped spinach (, thawed (Note 1))","500 g / 1 lb ricotta (, full fat please (Note 2))","1/3 cup parmesan (, finely shredded)","1 cup shredded cheese (Mozzarella, Colby, Cheddar, Tasty, Gruyere, Swiss)","1 egg","1 large garlic clove (, minced)","Grated fresh nutmeg (just a sprinkling) ( or 1/8 tsp nutmeg powder (optional))","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Filling:"},{"ingredients":["18 - 22 dried cannelloni tubes (250g pack) (or 14 manicotti tubes (8.8 oz) (Note 3))","1/3 cup parmesan (, finely shredded)","1 1/4 cups shredded Mozzarella","More basil and parmesan (, for garnish (optional))"],"purpose":"Cannelloni"}]', '[{"title":"Sauté","description":"Heat oil in a small pot over medium high heat. Add garlic, onion, bay leaf, thyme and oregano. Cook for 3 - 4 minutes until the onion is translucent. Add tomato paste and cook for 1 minute.","duration":3.5,"images":[],"step":1},{"title":"Reduce wine","description":"Add wine, increase heat to high and let it simmer rapidly until mostly evaporated (about 2 minutes).","images":[],"step":2},{"title":"Simmer","description":"Add tomatoes, stock, sugar, salt and pepper. Stir then simmer on medium low for 20 minutes.","duration":20,"images":[],"step":3},{"title":"Blitz","description":"Remove bay leaf then blitz with a stick blender until smooth. Simmer for 1 more minute then remove from the stove","images":[],"step":4},{"title":"Basil","description":"Stir in basil then cover to keep warm until required.","images":[],"step":5},{"title":"Squeeze spinach","description":"Place spinach in a colander and press out most of the liquid (don''t need to thoroughly squeeze dry).","images":[],"step":6},{"title":"Mix filling","description":"Place Spinach in bowl with remaining Filling ingredients. Mix, taste, adjust salt and pepper to taste (different cheeses have different saltiness).","images":[],"step":7},{"description":"Assemble & Bake:","images":[],"step":8},{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":9},{"title":"Pan","description":"Choose a baking pan which will comfortably fit about 20 cannelloni - mine is 21 x 26 cm / 8.5 x 10.5\".","images":[],"step":10},{"title":"Smear","description":"Spread 1 cup of Sauce on the base (stops cannelloni from sliding around).","images":[],"step":11},{"title":"Fill tubes","description":"Transfer Filling to a piping bag with a large nozzle (that fits in the tubes), or use a strong ziplock bag. Or do this step using a knife (it''s a bit tedious though!). Pipe the filling into the tubes.","images":[],"step":12},{"title":"Assemble","description":"Place cannelloni in baking dish. Pour over remaining Sauce, covering all the tubes.","images":[],"step":13},{"title":"Bake covered (but naked)","description":"Cover with foil, then bake for 30 minutes.","duration":30,"images":[],"step":14},{"description":"Cheese it! Remove foil, scatter over parmesan then mozzarella. Return to oven for 15 minutes until cheese is melted.","duration":15,"images":[],"step":15},{"description":"Serve, garnished with extra parmesan and basil if desired.","images":[],"step":16}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Western"],"categories":["casseroles-and-cosy-bakes","dinner-tonight","italian-recipes","main-dishes","pasta-bakes","pasta-recipes","sunday-supper","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_925a38cdaefc', 'en', 'US', 'Creamy Seafood Pasta Bake', 'Pasta baked with mixed seafood in a creamy white béchamel sauce. It''s like a gratin made with pasta - which is why I describe this as French-ish! The key to getting gorgeous flavour in the sauce is searing the seafood in the skillet first, then making the sauce in the same skillet to soak up all those seafood flavours!', 'https://www.recipetineats.com/tachyon/2016/06/Seafood-Gratin-Pasta_10.jpg', 5, 30, 35, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.397, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_mixed_seafood", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_eek", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_panko", "quantity": {"value": 112.5, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["7 oz / 200 g macaroni or other pasta of choice","1 1/2 tbsp olive oil (, separated)","1 lb / 500 g mixed raw seafood (Marinara seafood mix) (Note 1)","2 leeks (, white and pale green part only finely sliced)","2 garlic cloves (, minced)"]},{"ingredients":["3 tbsp butter","3 tbsp flour","2 1/2 cups milk","1 chicken bouillon cube ((or 1 1/2 tsp chicken stock powder) OR 1/2 cup grated parmesan cheese)"],"purpose":"White Sauce"},{"ingredients":["3/4 cup panko","1/4 cup grated parmesan cheese (high recommended)","Finely chopped fresh parsley (optional)"],"purpose":"Topping"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cook pasta according to packet directions. Drain and pour into baking dish.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a skillet over very high heat. Add seafood and sear for 30 seconds, turn then sear the other side for 30 seconds (should still be raw inside). Remove into baking dish.","duration":0.5,"images":[],"step":3},{"description":"Return pan to stove, add remaining 1/2 tbsp oil and turn down to medium. Cook leeks and garlic for 3 minutes or until soft. Add to baking dish.","duration":3,"images":[],"step":4},{"description":"Mix pasta, seafood and leeks together in the baking dish.","images":[],"step":5},{"description":"Melt butter in the skillet. Add flour and mix into the butter. Cook for 1 minute,","duration":1,"images":[],"step":6},{"title":"Add 1 cup of milk and use a whisk to combine","description":"it will thicken quickly. Add remaining milk and bouillon cube (crumbled) and whisk to combine. Cook, whisking occasionally at first then constantly as it thickens, for around 5 minutes or until the sauce is thick enough to coat the back of a wooden spoon (see photo in post). Season with salt and pepper.","images":[],"step":7},{"description":"Pour into the baking dish. Top with panko and parmesan.","images":[],"step":8},{"title":"Bake for 20","description":"25 minutes, or until the top is golden.","duration":22.5,"images":[],"step":9},{"description":"Rest for 5 minutes before serving, garnished with fresh parsley if desired.","duration":5,"images":[],"step":10},{"description":"I served this with garlic spinach (Note 2).","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French-ish"],"categories":["casseroles-and-cosy-bakes","dinner-tonight","easter-mains-fish-seafood","main-dishes","pasta-bakes","prawns-shrimp","seafood-recipes","sunday-supper","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b649b6d9511', 'en', 'US', 'One Pot Chicken Enchilada Rice Casserole', 'Everything you know and love about the flavour of Chicken Enchiladas.....but in the form of a rice casserole! And all made in ONE POT on the stove! I like the flow of this recipe because you don''t need to measure everything out in advance. After cooking the bell pepper (capsicum) add the passata and chicken broth, then while that comes to a simmer you can gather all the spices. Saves time! This recipe makes a LOT. Because it is carb heavy, I think it is enough to feed 6.', 'https://www.recipetineats.com/tachyon/2015/10/Mexican-Chicken-Enchilada-Rice-Casserole_600px.jpg', 15, 25, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.562, "unit": "can of 400g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","400g (13oz) chicken breast, about 1/3\"/1cm thick, sliced horizontally into thin steaks (Note 1)","1 small onion, diced","3 cloves garlic, crushed","1 red bell pepper/capsicum, diced","680g (24oz) tomato passata or crushed canned tomatoes* (Note 2)","3 cups chicken broth or water (750ml)","1 1/2 cups frozen corn (250g)","1/2 tsp cayenne pepper* (spicy - adjust to taste)","1 tbsp dried oregano*","2 tsp cumin*","1 1/2 tsp coriander*","2 tsp onion powder*","1 tbsp brown sugar*","Salt and pepper","1 1/2 cups (270g) white rice (short, medium or long grain (, uncooked (Note 4))","1 - 1 1/2 cups grated cheese (about 125 - 150 g)"]},{"ingredients":["Chopped cilantro/coriander (optional)"],"purpose":"To Serve"}]', '[{"description":"Heat olive oil over medium high heat in large skillet.","images":[],"step":1},{"description":"Add chicken and cook each side for 2 minutes or until cooked, then remove onto a plate.","duration":2,"images":[],"step":2},{"description":"Add extra oil if the skillet is looking dry. Add onion and garlic, cook for 1 1/2 minutes until starting to soften.","images":[],"step":3},{"description":"Add bell peppers and cook for a further 2 minutes.","images":[],"step":4},{"description":"Add remaining ingredients except rice and cheese. Bring to simmer, then add rice.","images":[],"step":5},{"description":"Stir, cover with a lid and turn down heat to medium low. Cover and cook until rice is cooked but not mushy and most of the liquid is absorbed - about 15 to 18 minutes. (Note 3). Do not stir while it cooks.","images":[],"step":6},{"description":"Meanwhile, shred or roughly chop chicken.","images":[],"step":7},{"description":"When rice is cooked, quickly stir chicken through, sprinkle with cheese then pop under broil / grill until golden and bubbly.","images":[],"step":8},{"description":"Serve, garnished with fresh cilantro/coriander if desired.","images":[],"step":9}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","most-popular","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f16048e380e6', 'en', 'US', 'One Pot Creamy Tomato Chicken Pasta Bake (no cream)', 'A pasta bake, cooked entirely in one pot! The sauce is creamy and tomatoey but is made without a drop of cream, making this a great midweek meal.', 'https://www.recipetineats.com/tachyon/2015/04/One-Pot-Creamy-Tomato-Pasta-Bake_action_680px1.jpg', 5, 30, 35, 6, '[{"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.9, "unit": "pack of 500g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.6, "unit": "pack of 125g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["4 tbsp unsalted butter","1 small onion (, diced)","2 garlic cloves (, minced)","6 tbsp / 1/2 cup plain flour","2 cups milk (500ml)","2 cups tomato passata (500ml) (Note 1)","1 cup water (or chicken or vegetable broth) (250ml)","2 tsp salt","Black pepper","3 cups dried ziti / penne pasta (uncooked)","2 cups shredded cooked chicken","1 cup shredded cheddar cheese","3/4 cup shredded mozzarella cheese","Pepper"]},{"ingredients":["Fresh basil leaves","Freshly grated parmesan"],"purpose":"Garnish (optional)"}]', '[{"description":"Preheat oven to 350F/180C.","images":[],"step":1},{"description":"Melt butter in a deep fry pan or skillet (Note 2) over medium heat. Add the onion and garlic and sauté for 5 minutes until translucent. Add the flour and stir to combine, then cook for 2 minutes.","duration":5,"images":[],"step":2},{"description":"Add the milk and whisk for 1 minute, in small circles around the fry pan, until it starts to thicken. Then add the tomato passata, water, salt and pepper. Increase the heat to medium high and cook for around 5 minutes or until thick enough to coat the back of a metal spoon (see photo below). Whisk occasionally for the first 3 minutes, then whisk constantly for the last 2 minutes.","duration":1,"images":[],"step":3},{"description":"Do a taste test and add 1 to 2 tsp of sugar if it is a bit sour (depends on quality of passata you use).","images":[],"step":4},{"description":"Add the ziti/penne, chicken and cheddar cheese and mix through. Leave it to cook for around 1 minute on the stove, then take it off the stove.","images":[],"step":5},{"description":"Scatter with mozzarella cheese. Cover with a lid or foil (Note 3) and bake for 10 minutes. Remove the lid/foil and bake for a further 5 minutes. Rest for 5 minutes before serving, garnished with fresh basil leaves and grated parmesan, if desired.","duration":10,"images":[],"step":6}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_99a6e56f28ad', 'en', 'US', 'Chinese eggplant and minced pork - Sichuan Fish Fragrant Eggplant', 'Recipe video above. Tried making this iconic Sichuan dish before and been underwhelmed? This one’s the real deal! Called Yu Xiang Qie Zi, this is straight from our RTM Chef Hannah, born and raised in the Sichuan province of China, a family of chefs at that! Even her chef father gave this recipe his rare stamp of approval.🙌🏻For full authenticity, grab broad bean sauce and pickled chilli from an Asian store. That said, our supermarket-sub version is so good, we’d have happily shared it - if we hadn’t already tasted the OG!Traditionally, the eggplant is deep fried (and yes, that’s why it’s so melt-in-your-mouth good). But see Note 1 for a fantastic no-fry pan-steamed option! Spiciness - Low mild. There''s not that much chilli in it!', 'https://www.recipetineats.com/tachyon/2025/05/Chinese-eggplant-with-minced-pork_7.jpg', 10, 20, 30, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_broad_bean_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.01, "unit": "jar of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.018, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 cup vegetable oil (, or canola, sunflower oil (Note 1 for no-fry version))","1 large eggplant or 2 medium/small (450 to 500g), cut into 7 x 1.5cm batons (2.7 x 0.6\"), skin on (Note 2)","100g / 3.5 oz pork mince / ground pork (Note 3)","1 tbsp ginger (, finely minced)","1 1/2 tbsp garlic (, finely minced)","1 green onion (, finely sliced, white & pale green part (for cooking) separated from the green part (garnish))","1 tsp pickled red chilli (, or any pickled spicy peppers (Note 4))","1 tbsp broad bean sauce (, we use Pixian doubanjiang, the spicy Sichuan version(Note 5))"]},{"ingredients":["1 1/2 tsp cornflour / cornstarch","1 tbsp light soy sauce (Note 7)","1/2 tsp dark soy sauce (Note 7)","1 1/2 tbsp sugar","1 tsp honey","3 1/2 tsp black vinegar (Note 8)","1/2 cup water"],"purpose":"Sauce:"},{"ingredients":["White rice"],"purpose":"Serving:"}]', '[{"title":"ABBREVIATED","description":"Mix sauce. Fry eggplant until soft. Keep 2T oil. Cook pork 2 min, then garlic, ginger and white part green onion for 30 sec. Cook chilli + broad bean sauce 1 min. Add eggplant and sauce in 2 batches, once thickened, serve!","duration":0.5,"images":[],"step":1},{"title":"Sauce","description":"Mix the cornflour and light soy in a jug until lump free. Add the remaining Sauce ingredients and mix to combine. Set aside.","images":[],"step":2},{"title":"Fry eggplant","description":"Heat oil in a wok on high heat until hot - 180°C/350°F. Add half of the eggplant and fry for around 4 minutes, stirring and turning gently a few times, until soft all the way through and a bit browned on the surface. Remove with a slotted spoon onto a paper towel lined tray. Repeat with remaining eggplant.","images":[],"step":3},{"title":"Remove oil","description":"Carefully remove the leftover oil from the wok except 2 tablespoons, for cooking.","images":[],"step":4},{"title":"Stir fry","description":"Cool the wok slightly then return to high heat. Add the pork and cook for 1 - 2 minutes, breaking it up as you go, until you no longer see pink. Add garlic, ginger, white part of the green onion. Stir fry for 30 seconds. Add pickled red chilli and broad bean sauce. Cook for 1 minute.","duration":1.5,"images":[],"step":5},{"title":"Add sauce","description":"Give the Sauce a quick mix (to dissolve settled cornflour). Add eggplant, then add half the Sauce into the wok, toss gently until the sauce starts thickening - about 30 to 45 seconds. Add remaining Sauce, toss gently for 45 seconds until it thickens (goal: between maple syrup and honey).","duration":0.75,"images":[],"step":6},{"title":"Serve","description":"Turn off heat. Pour into a serving bowl, sprinkle with green onion. Serve with rice!","images":[],"step":7},{"description":"Healthier pan-steamed eggplant option:","images":[],"step":8},{"title":"Brown eggplant","description":"Heat 2 tbsp oil in a large non-stick pan (with lid) over medium high heat. Pan fry eggplant for 1 1/2 minutes on each side until lightly browned.","images":[],"step":9},{"title":"Steam","description":"Carefully add 1/3 cup water around the eggplant (it will steam, so be careful). Immediately cover with a lid to trap the steam. Steam for 2 minutes or until the water has evaporated and the eggplant is soft all the way through (if needed, add more water and keep steaming).","duration":2,"images":[],"step":10},{"title":"Proceed","description":"Transfer eggplant to a plate. Proceed with recipe using the large non stick pan rather than wok.","images":[],"step":11}]', '["gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese","Sichuan"],"categories":["chef-hannahs-recipes","chinese-recipes","iconic-dishes","mains","pork","pork-recipes","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6be9bb6dd6de', 'en', 'US', 'Tuscan Chicken Stew', 'Recipe video above. This is a 30 minute creamy white stew filled with seared Italian-seasoned chicken, sun dried tomatoes, burst-in-your-mouth cherry tomatoes, meaty white beans and swirls of spinach in a garlicky parmesan sauce. It''s not authentic Italian but I think it channels Tuscan vibes with the bright colours of Italy, in a bowl!', 'https://www.recipetineats.com/tachyon/2026/06/Tuscan-chicken-stew-5.jpg', 13, 22, 35, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 100.0, "unit": "bag of 250g"}}]', '[{"ingredients":["600g / 1.2 lb chicken thighs (, boneless skinless (or breast), cut into large bite size pieces 3 - 4 cm / 1.2 - 1.4\" (Note 1))"]},{"ingredients":["1 1/2 tsp Italian herb mix (store bought mix, or see Note 2)","1/2 tsp garlic powder","1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/4 tsp black pepper"],"purpose":"Chicken seasoning:"},{"ingredients":["1 1/2 tbsp olive oil","1 onion (, halved and sliced into 1cm / 0.4\" wedges)","3 garlic cloves (, finely minced)","1/2 cup (100 g) sun dried tomatoes (, cut into 0.5cm / 0.2\" slices (Note 3))","200g (1 1/4 cups) cherry or grape tomatoes (1 punnet)","2 x 400g/14oz cans butter beans (large lima beans), drained - or cannellini, Great Northern or other white beans (Note 4)","1/3 cup Chardonnay or other dry white wine (, substitute chicken stock/broth (Note 5))","1/3 cup plain flour / all-purpose flour (Note 6 for gluten-free)","3 cups chicken stock / broth (, low sodium)","3/4 cup thickened cream / heavy cream (, or any full fat cream ~35% fat)","1/2 cup parmesan (, finely grated or store bought sandy-type - substitute with cheddar, tasty or other sharp cheese)","100g / 3.5oz baby spinach (, or a few big handfuls torn kale)"],"purpose":"Stew:"}]', '[{"description":"Season chicken, sear. Sauté onion and garlic. Deglaze with wine, stir in flour, then stock. Add beans and sun dried tomato, simmer 7 minutes. Add cream, parmesan and cherry tomatoes, simmer 8 minutes. Stir in spinach, serve!","images":[],"step":1},{"title":"Season and sear chicken","description":"Sprinkle chicken with the seasoning and toss to coat. Heat the oil on high in a 30 cm / 12\" non stick pan until very hot. (Note 7 re: cooking vessel) Add the chicken, spread it out, then leave it for 30 seconds or so until golden. Then start stirring, leaving it for 20 seconds every now and then to get colour on the pieces, until most of the pieces are light golden.","duration":0.5,"images":[],"step":2},{"title":"Sauté onion","description":"Lower heat to medium high. Add onion and garlic then cook for around 2 minutes until the onion is wilted.","images":[],"step":3},{"title":"Deglaze and add flour","description":"Turn the heat back up to high. Add the wine and let it simmer for 1 - 2 minutes until reduced by half. Add flour and stir until it is mixed in.","duration":1.5,"images":[],"step":4},{"title":"Make sauce","description":"Slow pour in a third of the stock, mixing as you go. The flour will make the liquid turn into a thick sauce quite quickly. Then add the rest of the stock, beans and sun dried tomato, and stir well.","images":[],"step":5},{"title":"First simmer 7 minutes","description":"Bring to a simmer. Lower heat to medium or medium high so it''s simmering, not too rapidly. Simmer 7 minutes, stirring every now and then.","images":[],"step":6},{"title":"Second simmer 8 minutes","description":"Add cherry tomatoes, cream and parmesan. Mix and simmer for 8 minutes. The sauce should be reduced and thicken into a gravy consistency.","duration":8,"images":[],"step":7},{"title":"Wilt spinach","description":"Stir spinach in to make it wile (~ 30 seconds). Ladle into bowls, garnish with extra parmesan and chilli flakes if desired. Serve with warm crusty bread for dunking!","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["chicken","chicken-recipes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_894df79de4d0', 'en', 'US', 'Coconut Chicken Curry - quick and easy', 'Recipe video above. This Coconut Chicken Curry proves you don’t need a long list of spices or a jar of curry paste to make a truly Indian-tasting curry - just 3 simple spices and very little effort. Tastes like a coconut-y Rogan Josh! I love that it''s made from scratch rather than using a jar of paste. I''ve used chickpeas to fill this out and add a nice nutty crunch just by opening a can, but you could use diced potatoes instead. Stirring in a handful of spinach at the end wouldn''t go astray either.Bonus - It makes a good amount so there''s enough for lunch tomorrow.Spice level - None. Feel free to add some with cayenne pepper or using a HOT curry powder!', 'https://www.recipetineats.com/tachyon/2026/04/Coconut-chicken-curry-quick-easy_7.jpg', 15, 20, 35, 5, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.75, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_naan", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["2 tbsp unrefined coconut oil (virgin), ie coconut flavoured, or butter, ghee, or any cooking oil you want (Note 1)","500 g/1lb boneless chicken thighs (, cut into ~2cm / 0.8\" pieces (Note 2))","1 large onion (, diced)","1 1/2 tbsp garlic (, finely grated using a microplane (~6 large cloves))","1 1/2 tbsp ginger (, finely grated using a microplane)","2 1/2 tbsp curry powder (, mild - just regular ones like Clives, Keens (feel free to use HOT for spicy!))","1 tsp cumin powder","1 tsp turmeric powder","1/4 cup tomato paste","1 1/2 cups chicken stock/broth (, low sodium)","400g / 14oz coconut cream (substitute coconut milk), full fat (Note 3)","400g / 14oz can chickpeas (, drained)","1 1/4 tsp cooking salt / kosher salt (halve for table salt, double for flakes)"]},{"ingredients":["Plain yogurt (, slightly thinned with water to make it drizzle-able)","Coriander leaves (cilantro) (, roughly chopped, recommended)","Basmati rice ((you''ll need to cook 3 cups rice grains to make enough) or other rice of choice)","Naan (, optional)"],"purpose":"Serving:"}]', '[{"description":"Melt oil, sauté onion, then garlic and ginger. Toast spices, then tomato paste, coat chicken. Reduce chicken stock by half (5 min), then add coconut, chickpeas and salt. Simmer rapidly 8 min, stand 5 min then serve over rice.","images":[],"step":1},{"title":"Sauté","description":"Melt the coconut oil in a large pot over medium high heat (or a large deep skillet). Add the onion and cook for 2 minutes, until translucent. Add the garlic and ginger, stir constantly for 30 seconds (scrape base if it starts to stick).","duration":2,"images":[],"step":2},{"title":"Toast spices","description":"Add the curry powder, turmeric and cumin. Stir for 15 seconds, taking care to make sure it doesn''t stick and burn on base (if it does, add splash of water).","duration":0.25,"images":[],"step":3},{"title":"Coat chicken","description":"Add tomato paste and stir to coat all the onion, then add the chicken and stir to coat.","images":[],"step":4},{"title":"Reduce chicken stock 5 minutes","description":"Add the chicken stock, stir well, then once it starts bubbling, simmer rapidly for 5 minutes to reduce the liquid, stirring once in a while (adjust heat as needed, we want rapid bubbles - this is a speedy recipe remember!).","duration":5,"images":[],"step":5},{"title":"Simmer 8 minutes","description":"Add the coconut cream, chickpeas and salt. Stir well, bring back up to a simmer then simmer rapidly for 8 minutes, stirring every now and then. The sauce should be creamy but a little thinner than you''d expect.","duration":8,"images":[],"step":6},{"title":"Serve","description":"Remove the pot from the stove and leave to cool for 5 minutes, during which time the sauce will thicken a bit more. Serve over basmati rice with a drizzle of yogurt and sprinkle of fresh coriander. I wouldn''t say not to a warm naan or flatbread either. :)","duration":5,"images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian","Western"],"categories":["chicken-recipes","curry-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_28036739f338', 'en', 'US', 'JB''s Chicken au Poivre (Creamy Peppercorn Sauce)', 'Recipe above video. Inspired by Steak with Creamy Peppercorn Sauce (Steak au Poivre), one of my all-time favourites. This recipe has the same creamy pepper sauce with brandy and cream, just swapped for golden chicken. “Chicken au Poivre” is a perfect quick mid-week dinner with a French accent!', 'https://www.recipetineats.com/tachyon/2026/02/Chicken-Au-Poivre_4-copy.jpg', 8, 20, 28, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_brandy", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 large chicken breasts (, skinless & boneless (250–300g / 8–10oz each) (Note 1))","3/4 tsp cooking salt / kosher salt","2 tbsp vegetable oil (, or any other neutral flavoured oil)"]},{"ingredients":["2 tsp whole black peppercorns (, coarsely crushed (Note 2))","1/3 cup brandy or cognac (, or masala (Note 3))","1 1/2 cups beef stock / broth (, low sodium (Note 4))","3/4 cup thickened / heavy cream (, or any other full fat cream)"],"purpose":"SAUCE AU POIVRE"}]', '[{"description":"Season chicken with salt. Sear in oil until golden. Remove. Deglaze with cognac. Add beef stock, simmer for 4 minutes . Pour cream, add pepper and simmer for 5 minutes. Return chicken, cook for 3 minutes while basting. Serve immediately.","duration":4,"images":[],"step":1},{"title":"Prepare the chicken","description":"Cut each chicken breast in half horizontally to make 4 thin steaks and sprinkle both sides with salt (If you’re wondering why I don’t season the chicken with pepper it’s because once combined with the sauce, it would make the dish too peppery.)","images":[],"step":2},{"title":"Sear the chicken","description":"Heat oil in a large pan (28cm / 11\") over high heat. Add chicken and cook 2–3 minutes per side until golden. Remove to a plate and rest (don’t cover). If you think your chicken is still a little bit under after resting, don’t worry it will finish cooking later in the sauce.","images":[],"step":3},{"title":"Deglaze with brandy","description":"TURN THE STOVE OFF to avoid the brandy catching fire (unless you want to flambé). Then carefully pour the brandy in. Be careful, it will sizzle hard, that’s normal. Let it bubble for 20-30 seconds to let alcohol burn off, reduce by about 2/3 (turn the stove on if needed). Scrape the fond at the base of the pan well to release all that flavour. (Note 5 & 6)","duration":0.4166666666666667,"images":[],"step":4},{"title":"Beef stock","description":"Turn the heat back on high. Add beef stock. Simmer rapidly for 4 minutes, until reduced by half.","duration":4,"images":[],"step":5},{"title":"Cream","description":"Stir in cream and crushed pepper. Lower the heat to medium high. Simmer for 3-4 minutes, to reduce the sauce until it thickens enough to lightly coat the back of a spoon. Stir and scrape the sides of the pan as it reduces. Keep in mind that some stoves run stronger than others. If the heat is gentler, the sauce may take a little longer to reduce, so just allow a bit of extra time.","duration":3.5,"images":[],"step":6},{"title":"Simmer","description":"Turn heat down to medium. Return chicken and resting juices to the pan. Cook 2–3 minutes, spooning the sauce over the chicken, until it is warmed through and the sauce darkens in colour and thickens a little more. When you drag a spoon through the pan, the sauce should slowly flow back together. If it thickens too much, add a splash of cream or water to loosen.","images":[],"step":7},{"title":"Serve","description":"This dish is best served straight away. If it sits, the sauce can become too thick and the chicken be overcooked.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","jbs-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_60c11623ffdd', 'en', 'US', 'Kalimera''s Famous Greek Chicken Gyros', 'Recipe video above. This Chicken Gyros recipe was given to me by Thomas Deliopoulos, the owner of Kalimera Souvlaki Art which is a wildly popular gyros bar in Melbourne. It''s ridiculously, unbelievably, eye-rollingly good that has top chefs like Australia''s Ben Shrewry and New York Times food critic Sam Sifton raving!Thomas’s secret is a touch of curry powder in the marinade. Yes, really!At Kalimera, the chicken is cooked on a vertical spit layered with fat, but even on the BBQ or stove, it’s ridiculously good. I''ve made it for many people now, and everyone is nuts for it!', 'https://www.recipetineats.com/tachyon/2025/10/Kalimera-Greek-Chicken-Gyros_8.jpg', 20, 10, 1470, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_thick_cut_chips", "quantity": {"value": 400.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.113, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}]', '[{"ingredients":["1.25 kg / 2.5 lb chicken thighs, skinless boneless"]},{"ingredients":["1 tbsp sweet paprika (ie regular paprika, not smoked not spicy)","1 tbsp mustard powder (substitute with Dijon mustard)","1 tbsp dried oregano (Greek, if you''ve got it)","1/2 tbsp curry powder (, mild not spicy *secret ingredient!* (Note 2))","1 1/2 tsp cooking salt / kosher salt (halve if using table salt, +50% if using flakes)","1/2 tsp black pepper","1/3 cup extra virgin olive oil"],"purpose":"Kalimera''s chicken gyros marinade"},{"ingredients":["400g / 14oz thick-cut chips (, frozen - optional (Note 3))","Pinch table salt (, for the chips (or chicken salt))"],"purpose":"Hot chips"},{"ingredients":["1 cup plain yoghurt (, preferably Greek or Greek-style)","3 tbsp whole-egg mayonnaise (, substitute regular mayonnaise)","3 tbsp extra virgin olive oil","2 tbsp yellow American mustard ((yes, really!) - substitute with Dijon mustard, not hot English mustard, too spicy)","2 tsp garlic powder","2 tsp sweet paprika","1/2 tsp cooking salt / kosher salt"],"purpose":"Kalimera gyros sauce:"},{"ingredients":["2 tomatoes (, halved and sliced)","3 cups cos lettuce (romaine) (, finely sliced (5mm / 0.2\"))","1/2 small red onion (, diced (5mm / 0.2\" squares))","5 x 20cm / 8\" pita breads, (the slightly bready kind if you can (Note 5))"],"purpose":"To serve"}]', '[{"description":"Marinate chicken overnight (minimum 3 hours). Mix sauce, make chips. Cook chicken, rest 3 minutes, assemble gyros as follows: Sauce, chicken, lettuce, tomato, onion, chips, sauce. Fold, devour!","images":[],"step":1},{"title":"Marinate chicken","description":"Mix the marinade ingredients in a large bowl. Add the chicken and mix well to coat. Marinate in the fridge for 24 hours (absolute minimum 3 hours!)","images":[],"step":2},{"description":"Before cooking:","images":[],"step":3},{"title":"Sauce first","description":"Mix the ingredients in a bowl and set aside for at least 20 minutes to let the flavours meld.","images":[],"step":4},{"title":"Chips next","description":"If using hot chips, make them before cooking the chicken using whatever method suits - baked, fry, air fry. (I bake for convenience and fry to impress.) Season with salt to taste (sorry, you''re going to have to eat one!) Keep them warm in a 100°C/200°F oven while you cook the chicken.","images":[],"step":5},{"description":"Cooking the chicken gyros","images":[],"step":6},{"title":"BBQ option (recommended!)","description":"Preheat the BBQ on medium high (the grill side preferred, flat iron also works). No need to oil the grills. Cook the chicken for 3 - 4 minutes on each side until deep golden with slightly charred edges.","duration":3.5,"images":[],"step":7},{"title":"Stove cook","description":"Heat a large non stick pan over medium high heat (no oil required). Cook the chicken in batches for 3 - 4 minutes on each side until deep golden and cooked through (internal temperature 72°C/162°F). Give the pan a quick wipe with paper towels between batches, to remove excess black bits.","duration":3.5,"images":[],"step":8},{"title":"Remove & rest","description":"Remove chicken onto a tray. Loosely cover with foil and rest for 3 minutes, then slice into 1 cm / 0.4\" pieces.","duration":3,"images":[],"step":9},{"description":"Heat the pita bread until warm and pliable. Honestly, microwave is so easy (stack on plate, 45 sec - 1 1/2 minutes on high). For stove, brush each side with water then heat in lightly oiled non-stick pan for 1 minute on each side (medium high), don''t let it go crispy else it will crack when folded.","duration":1,"images":[],"step":10},{"title":"Wrapping","description":"Spread 3 tablespoons of the sauce down the middle. Pile the chicken onto the sauce, add lettuce and tomato on one side. Sprinkle with red onion, pile chips on top, drizzle with more sauce. Fold to enclose, wrap in foil to keep everything in place.","images":[],"step":11},{"description":"Serve gyros with extra sauce for dunking!","images":[],"step":12}]', '["egg","milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["chicken-recipes","greek-recipes","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4827ac1b72ac', 'en', 'US', 'JB''s Chicken Chasseur', 'Recipe video above. Chicken Chasseur (chasseur is French for “hunter”) is a classic French dish made with pieces of chicken cooked in a rich mushroom and tomato sauce with a gentle touch of brandy, finished with fresh tarragon. It’s rustic and cosy, and it was the first recipe I learned to master at cooking school back in France. - JB', 'https://www.recipetineats.com/tachyon/2025/10/Chicken-Chasseur-JB_7.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_brandy", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_tarragon", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["4 chicken thighs, bone-in, skin on (~250g/8oz each) (Note 1)","4 chicken drumsticks (Note 1)","3/4 tsp cooking salt / kosher salt","1/2 tsp black pepper","3 tbsp plain flour (all-purpose flour)","2 tbsp vegetable oil (or any other neutral flavoured oil)","30g / 2 tbsp unsalted butter"]},{"ingredients":["400g / 14oz white mushrooms (, sliced 6mm/0.2”)","2 onions (, brown or yellow, halved then sliced 6mm/0.2” thick)","3 garlic cloves (, finely minced)","1/4 cup brandy (Note 2)","1/2 cup chardonnay or other dry white wine (Note 3)","3 tbsp tomato paste","2 1/2 cups beef stock (, low-sodium (note 4))","3/4 tsp cooking salt/kosher salt","1/4 tsp black pepper","30g / 2 tbsp unsalted butter (, COLD and cubed (KEEP REFRIGERATED until required) )","1 tbsp fresh tarragon (, finely chopped (Note 5))"],"purpose":"Sauce Chasseur"},{"ingredients":["Creamy mashed potato (or rice or small pasta)"],"purpose":"For serving"}]', '[{"description":"Abbreviated Recipe","images":[],"step":1},{"description":"Season and flour the chicken, then brown in oil and butter. Remove. Sauté mushrooms and onion, add garlic briefly, then pour in brandy and wine to reduce. Stir in tomato paste for 1 minute, then stock, salt, and pepper. Return chicken, simmer covered 10 minutes then uncovered for 20 minutes until tender. Finish with cold butter and fresh tarragon.","duration":1,"images":[],"step":2},{"title":"Season the chicken","description":"Pat the chicken dry thoroughly with paper towels. This removes surface moisture, allowing the skin to brown properly and avoiding splatter. Season with salt and pepper on all sides. Coat in flour, shaking off excess. This helps develop a golden crust and also thickens the sauce later.","images":[],"step":3},{"title":"Brown the Chicken","description":"Heat vegetable oil in a large (30cm/12\") skillet (with lid) over medium-high heat. Add butter, once melted and foaming, place thighs skin-side down. Sear for 5 minutes until golden and crispy. Flip and cook the other side for 1 minute. Transfer to a plate. Add the drumsticks and brown them on 3 sides, about 2 minutes per side. Don’t rush this step – browning adds depth of flavour. Transfer drumsticks to the plate with the thighs. ⚠️ Be mindful when searing skin-on chicken pieces, the skin can pop and hot oil may splash.","duration":5,"images":[],"step":4},{"title":"Onion, mushrooms and garlic","description":"In the same pan, increase the heat to high and add the mushrooms and onions. Cook for 5 minutes, stirring occasionally, until the mushrooms start to wilt. Add the garlic and cook for 30 seconds until fragrant.","duration":5,"images":[],"step":5},{"title":"Brandy and wine","description":"Pour in the brandy. Carefully flambé (ignite) if desired - let it burn until the flame dies out by itself (~10 seconds). Flambéing intensifies the aroma - and puts on a show! Or simply let it bubble for 20–30 seconds until the alcohol burns off. Add the white wine. Let it simmer rapidly to reduce by half. Use a wooden spoon to scrape up the fond (the browned bits stuck to the bottom), which is a crucial ingredient to the creation of our sauce. It will make it rich and complex.","duration":0.4166666666666667,"images":[],"step":6},{"title":"Tomato and stock","description":"Stir in the tomato paste, cook for 1 minute. Then add the stock, salt, and pepper.","duration":1,"images":[],"step":7},{"description":"Cooking","images":[],"step":8},{"title":"Simmer","description":"Return the chicken to the pan skin-side up, nestling them into the stock. Bring the sauce to a simmer, then reduce the heat to medium (bubbling constantly but not rapidly). Cover with a lid and simmer for 10 minutes. Then remove the lid and simmer uncovered for a further 20 minutes. This allows the sauce to reduce and concentrate while the chicken finishes cooking.","duration":10,"images":[],"step":9},{"title":"Reduce sauce slightly","description":"Transfer the cooked chicken to a plate. Turn the heat to medium-high, and simmer the sauce for 3 minutes to reduce slightly.","duration":3,"images":[],"step":10},{"title":"Finish the sauce","description":"Turn off the heat. Scatter half of the COLD butter cubes in then stir until melted. Scatter the rest of the butter cubes in then stir again until melted. This is a classic emulsification technique that gives the sauce a silky, glossy finish (monter au beurre) as well as thickening it slightly. (Note 6)","images":[],"step":11},{"title":"Serve","description":"Bring the sauce to a gentle simmer again. Return the chicken to the sauce and sprinkle over the fresh tarragon. Take it to the table and serve out of the pan with creamy mashed potato.","images":[],"step":12}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","jbs-recipes","mains","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d838ea82fee0', 'en', 'US', 'Nando''s Portuguese chicken and rice - one pot recipe', 'Recipe video above. My friend calls this Portuguese biryani. I know there''s 1 billion Indians crying right now, but it describes this perfectly! A Nando''s* inspired recipe with Peri Peri rub sprinkled on chicken then cooked in the same pot with a Nando''s copycat spicy rice. Essentially a one pot version of Nando''s paella! It''s seriously good, the rice alone puts Nando''s to shame. Don''t skip the Peri-naise. :-)* Portuguese chicken restaurant chain, bit of a cult following. Do you have it where you are?UPDATE: A few readers left feedback saying they thought it was bland, if you use chicken stock/broth, the spices and the amount of salt specified in the ingredients, this just isn''t possible! :) Please make sure you''re using the right amount of salt!', 'https://www.recipetineats.com/tachyon/2025/09/Portuguese-chicken-and-rice-one-pot_9.jpg', 15, 25, 40, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_cayenne", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.562, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_perinaise_pink_sauce_or_any_of_the_other_sauce_suggestions_listed_in_post", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["500g/1 lb chicken thighs (, boneless, skinless, cut into bite size pieces (Note 1))"]},{"ingredients":["2 tsp paprika (regular/sweet, not spicy)","1 tsp garlic powder (substitute large garlic clove, minced)","1 tsp dried oregano","1/4 tsp coriander","1/4 tsp cayenne (can omit for zero spicy)","1 tbsp brown sugar","1 tsp cooking salt / kosher salt (+50% for flakes, halve for table salt)","1 tbsp extra virgin olive oil","1/2 tbsp lemon juice (substitute apple cider vinegar)"],"purpose":"Portuguese chicken seasoning:"},{"ingredients":["2 tbsp extra virgin olive oil","2 garlic cloves (, finely minced)","1 small onion (, diced)","1 red capsicum ((bell pepper), deseeded, chopped into 1cm/0.4\" squares)","1 1/2 cups basmati rice (or long grain rice or medium grain rice) (Note 2)","1/4 tsp chilli flakes / red pepper flakes (omit for not spicy)","2 tsp turmeric powder","2 1/4 cups chicken stock/broth (, low sodium)","1 cup frozen peas (still frozen)","1/2 tsp cooking salt / kosher salt (+50% for flakes, halve for table salt)"],"purpose":"Nando’s copycat spicy rice (or not):"},{"ingredients":["Perinaise ((I use the quick dry spices version), Pink Sauce (Note 4) or any of the other sauce suggestions listed in post)","Green onion (, finely sliced)"],"purpose":"Garnishes:"}]', '[{"description":"Toss chicken with seasoning, sear, remove. Sauté onion and garlic, then capsicum, stir in rice, add everything else + chicken. Steam 15 minutes covered, rest 10 minutes. Serve!","images":[],"step":1},{"title":"Season chicken","description":"Mix the Portuguese Chicken Seasoning ingredients in a bowl. Add chicken and toss to coat. Set aside while you prepare the rest of the ingredients, or overnight if you want (though not necessary).","images":[],"step":2},{"title":"Sear","description":"Heat the 2 tablespoons of oil in a large heavy based pot over high heat. Add the chicken and cook until the outside is sealed and gets a bit of colour (it won''t go golden). Remove with a slotted spoon into a bowl, leaving oil behind in the pot.","images":[],"step":3},{"title":"Sauté","description":"Add garlic and onion into the pot, cook for 1 minute. Add capsicum and cook for 1 1/2 minutes or until onion is translucent.","duration":1,"images":[],"step":4},{"title":"All in","description":"Add rice and stir to coat in the tasty oil. Add remaining rice ingredients, then scatter the chicken evenly across the surface. Also add any juices accumulated in the bowl. Stir, bring to a simmer, then put the lid on and lower heat to medium low so it''s simmering gently. (Note 3)","images":[],"step":5},{"title":"Cook 15 minutes","description":"Cook for 15 minutes, no peeking, no stirring! Liquid should be absorbed - tilt pot and lift lid for quick peek.","duration":15,"images":[],"step":6},{"title":"Rest 10 minutes","description":"Remove pot from the stove and leave to rest for 10 minutes with the lid still on.","duration":10,"images":[],"step":7},{"title":"Fluff & serve","description":"Remove lid, gently toss the rice. Spoon into bowls, drizzle over Peri-naise, sprinkle with green onions and serve!","images":[],"step":8}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Portuguese inspired"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","mains","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f375a37487ed', 'en', 'US', 'My go-to Chicken Breast recipe', 'Recipe video above. Ready in 12 minutes, this is my current go-to chicken breast recipe. AKA Pan-Seared Country Seasoned Chicken Breast with Butter Sauce, it''s fast, simple, not-boring and you can make it anytime with pantry staples!Simple country-inspired seasoning tossed with the tiniest amount of flour so the chicken gets a lovely crust on it, served with a butter sauce made in the same pan so it gets flavour from the residual seasoning.Mix and match magic: Skip the sauce and just serve the seasoned chicken, or skip the spices and let the butter sauce shine with a simple salt-and-pepper seared chicken.', 'https://www.recipetineats.com/tachyon/2025/07/Anytime-Chicken-Breast-in-white-wine-sauce_5.jpg', 5, 7, 12, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 20.0, "unit": "block of 250g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 20.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (250 - 300g/8 - 10 oz each), each cut in half horizontally to form 4 steaks, no need to pound (Note 1)","20g/ 1 1/2 tbsp unsalted butter (or 1 1/2 tbsp olive oil)"]},{"ingredients":["1 tsp paprika (, regular/sweet (or smoky))","1/2 tsp onion powder (or more garlic)","1/2 tsp garlic powder (or more onion)","1/4 tsp cumin (sub coriander, thyme leaves crushed between fingers, or omit)","3/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/8 tsp black pepper","1 1/2 tbsp flour (, plain/all-purpose, GF (Note 2))"],"purpose":"Savoury Seasoned Crust:"},{"ingredients":["1/3 cup dry white wine ( or chicken stock (low sodium), sub water (Note 3))","30g/ 2 tbsp unsalted butter","1 tbsp roughly chopped parsley (, optional but recommended)"],"purpose":"Butter sauce:"}]', '[{"description":"Dust chicken with Seasoning, pan fry in the butter, remove. Deglaze with wine, melt in butter, serve sauce on chicken.","images":[],"step":1},{"title":"Season","description":"Mix the Seasoning ingredients in a bowl. Sprinkle on each side of the chicken, spreading with fingertips to coat evenly, then shake off excess.","images":[],"step":2},{"title":"Sear","description":"Melt the butter in a large non-stick pan over high heat. Cook chicken for 2 1/2 minutes on each side until deep golden, or until the internal temperature reaches 67C/153F. Remove onto a plate.","images":[],"step":3},{"title":"Pan sauce","description":"Lower then heat to medium high. Add the wine and simmer rapidly for 1 - 1 1/2 minutes, scraping the pan with a rubber spatula to loosen the golden bits into the sauce, until it''s reduced by half. Add the butter and let it melt, mixing well to combine. (Note 4 on sauce amount)","images":[],"step":4},{"title":"Serve","description":"Serve chicken with sauce and sprinkled with parsley. Enjoy!","images":[],"step":5}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3c418264c155', 'en', 'US', 'Whipped ricotta one pot chicken pasta', 'Recipe video above. Meet your new favourite one-pot recipe! I''m sharing this as a guest-worthy dish based on a simple mid-week recipe. It''s quite amazing how just a little dollop of creamy ricotta can transform a regular bowl of pasta into something you''d expect to get at a rustic trattoria! Love how it melts into a flood of creamy goodness on your hot bowl of pasta - thicker than cream, and much lower fat.', 'https://www.recipetineats.com/tachyon/2025/04/One-pot-whipped-ricotta-chicken-pasta-with-sun-dried-tomatoes_6a.jpg', 10, 20, 30, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 220.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_ricotta", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["500g/1 lb chicken thigh fillets (, cut into small bite size pieces (or breast or tenderloin))","1/2 tsp cooking salt/kosher salt","1/4 tsp black pepper"],"purpose":"Chicken:"},{"ingredients":["220g/ 7 oz jar sun-dried tomato stripes in oil (, drained (RESERVE OIL) (Note 1))","3 tbsp oil (from the sun dried tomato jar)","1 small onion (, finely diced)","2 garlic cloves (, finely minced)","1 tbsp tomato paste (ok if you don''t have)","1/4 cup dry white wine (, optional (Note 2))","400g/14 oz canned crushed tomato","350g / 12oz fusilli pasta (spirals) (, penne, ziti, macaroni, small shells or similar, uncooked)","1 litre / 4 cups chicken stock/broth (, low sodium (sub water plus 1/2 tsp salt))","1/4 tsp cooking salt/kosher salt","1/4 tsp black pepper","1 cup basil leaves (, roughly chopped (can survive without), plus extra for garnish)"],"purpose":"Pasta:"},{"ingredients":["1/2 cup ricotta ((Paesanella is my preferred brand), full fat)","4 tbsp milk (, preferably full fat)","1/4 cup (packed) finely grated parmesan (, sub pinch of salt)"],"purpose":"Whipped ricotta:"}]', '[{"title":"Whipped ricotta","description":"Put the ingredients in a bowl. Whisk vigorously for 10 to 15 seconds until it becomes the texture of softly whipped cream. Add milk to loosen, if needed.","duration":0.20833333333333334,"images":[],"step":1},{"title":"Seal chicken","description":"Heat sun dried tomato oil in a large heavy based pot over high heat. Add the chicken. sprinkle with salt and pepper. Cook for 3 minutes until the outside is sealed but the inside is still raw. Remove with slotted spoon into a bowl.","duration":3,"images":[],"step":2},{"title":"Sauté","description":"In the same pot, add the onion and garlic. Cook for 3 minutes until the onion is translucent. Add the tomato paste and oil drained sun dried tomatoes (reserve any remaining oil for another use). Cook for 1 minute.","duration":3,"images":[],"step":3},{"title":"Deglaze","description":"Add white wine and let it simmer rapidly for 1 - 2 minutes, stirring regularly, until mostly evaporated.","duration":1.5,"images":[],"step":4},{"title":"Cooking liquid","description":"Add pasta and cooked chicken along with any juices accumulated in the bowl. Stir to coat in all the tasty flavours. Add the stock, canned tomato, salt and pepper.","images":[],"step":5},{"title":"Cook 15 minutes","description":"Give it a good stir, let it come to a boil then lower the heat to medium high so it''s simmering rapidly but not boiling like crazy. Cook for 15 minutes (no lid), stirring every 2 minutes or so at first then more regularly towards the end, so the base doesn''t catch. Lower the heat a touch towards the end, if needed.","duration":15,"images":[],"step":6},{"title":"How to tell it''s done","description":"Most of the liquid should be absorbed and the pasta should be just cooked (al dente), though still a little soupy (that''s good, it gets absorbed quickly while serving). Stir in the basil.","images":[],"step":7},{"title":"Serve","description":"Transfer into a serving bowl or divide between bowls. Dollop the whipped ricotta on top then randomly smear (or let everyone do that themselves), it will get all melty. Dig in!","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-recipes","dinner-tonight","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_81e9be2d7579', 'en', 'US', 'Lebanese Lemon Garlic Chicken - Al Aseel copycat', 'Recipe video above. A copycat of a signature dish at Al Aseel, a popular Lebanese restaurant in Sydney! Chicken is marinated in a bold lemon-garlic yogurt mix, then smothered in a garlicky lemon yogurt sauce. Warm yogurt may sound unusual, but one bite will win you over! Serve with pita bread and Fattoush.PS. Please measure the garlic - too much is harsh, too little is sad.PPS. The salt might seem a lot, but please trust, it''s not salty!', 'https://www.recipetineats.com/tachyon/2025/04/Lebanese-lemon-garlic-chicken-Al-Aseel_2.jpg', 15, 10, 25, 3, '[{"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.12, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_extra_virgin_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["500g/ 1lb chicken tenderloin (or breast), cut into 4cm / 1.5\" squares, large vein cut out (Note 1)"]},{"ingredients":["4 tbsp Greek or plain yogurt","3 tbsp lemon juice","1 tbsp garlic (, finely grated or crushed using garlic press (~4 big cloves))","1 tbsp olive oil","1 tsp cooking salt / kosher salt (1/2 tsp table salt, 1 1/4 tsp flakes)"],"purpose":"Lemon garlic marinade:"},{"ingredients":["1 cup Greek or plain yogurt (, full fat essential here!)","3/4 tsp garlic (, finely grated or crushed using garlic press (~1 clove))","2 tbsp extra virgin olive oil","1 tbsp lemon juice","1 tbsp tahini (hulled), or extra 1 tbsp olive oil (Note 3)","1 tbsp+ water","1 tsp cooking salt / kosher salt (1/2 tsp table salt, 1 1/4 tsp flakes)"],"purpose":"Lemon garlic yogurt sauce:"},{"ingredients":["2 tbsp olive oil (, for cooking)","1 tsp parsley (, roughly chopped (or equal amounts mint and parsley))","Lemon wedges and extra virgin olive oil (, for garnish)","Lebanese bread (for sauce mopping (recommended))"],"purpose":"Cooking & serving:"}]', '[{"title":"Marinade chicken 12","description":"24 hrs. Cook in 2 batches. Whisk sauce, rest 1 hr, warm just before serving. Smother chicken, serve!","images":[],"step":1},{"title":"Marinade","description":"Mix the marinade ingredients in a bowl. Add the chicken, toss to coat then refrigerate to marinate for 12 - 24 hours (Note 2).","images":[],"step":2},{"title":"Sauce","description":"Put the sauce ingredients in a microwaveable bowl and whisk to combine. Set aside for 1 hour + to let the garlic flavour meld. (Note 4)","images":[],"step":3},{"title":"Cook chicken","description":"Drain off excess marinade from the chicken. Heat 1 tbsp oil in a large non stick pan over high heat. Place half the chicken in and cook for 1 1/2 - 2 minutes on each side until golden. Remove onto a plate.","images":[],"step":4},{"title":"Repeat","description":"Scrape out / roughly wipe loose black bits out of the pan. Reheat remaining oil and cook remaining chicken. Rest for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Warm sauce","description":"While the chicken is resting, microwave for 40 seconds to warm (but not hot) then give it a good whisk. Taste and add more lemon for tangier, or more water to loosen (some yogurts are thicker than others).","duration":0.6666666666666666,"images":[],"step":6},{"title":"Serving","description":"Spread half the sauce in a shallow bowl. Use a spatula to transfer the chicken onto the yogurt. Spoon over remaining sauce, finish with a swish of olive oil and sprinkle of parsley. Serve!","images":[],"step":7}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["lebanese"],"categories":["chicken-breast-recipes","chicken-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_371c245bc354', 'en', 'US', 'Chicken and Leek Pie', 'Recipe video above. Tender bites of chicken and slippery pieces of sweet leek smothered in a creamy white-wine thyme infused sauce, bubbling under a golden puff pastry crust. Chicken and Leek Pie is comfort food we dream about!I cut my leeks in a specific way. I like larger pieces rather than thinly sliced rings which get too soggy-stringy for my taste. Also, if you don''t like / can''t get puff pastry, cover this pie in mash (like Cottage Pie!) or use a homemade shortcrust pastry.Make one big pie like I''ve done, or ramekins (makes 4 large, 5 regular). For a pie with a base, replace the filling in my Family Meat Pie (there will be leftover filling) or individual meat pies. See the FAQ above for the gluten-free option.', 'https://www.recipetineats.com/tachyon/2024/09/Chicken-and-Leek-Pie_9.jpg', 25, 60, 145, 5, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bacon", "quantity": {"value": 0.4, "unit": "pack of 200g"}}, {"id": "ing_eek", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}]', '[{"ingredients":["50g/ 3 1/2 tbsp unsalted butter (, divided)","750g/ 1.5lb chicken thighs (, skinless, boneless, cut into 1.8 cm / 3/4\" bite size pieces (Note 1))","1/4 tsp each black pepper and cooking salt (kosher salt)"]},{"ingredients":["80g / 3 oz streaky bacon (, chopped into 1cm / 0.4\" squares (Note 2))","2 leeks (Note 3)","2 celery stems (, sliced 4 mm / 0.2\" thick (cut thick end in half lengthways first))","2 garlic cloves (, finely minced)","1/3 cup chardonnay (or other dry white wine (Note 4))","1/4 cup flour (plain / all-purpose)","1 tbsp dijon mustard (Note 5)","2 thyme sprigs (or 1/2 tsp dried thyme)","2 bay leaves (preferably fresh, else dried)","1 cup chicken stock / broth (, low sodium)","1 cup thickened / heavy cream (or any full-fat cream, or sub milk for lower fat)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Pie filling:"},{"ingredients":["2 x 20cm / 8\" frozen butter puff pastry sheets (, or single sheet large enough to cover baking dish, 360g / 12 oz (Note 6))","1 egg (, yolk and whites separated, lightly whisked)"],"purpose":"Pie:"}]', '[{"description":"Sear surface of chicken in half butter, remove. Cook bacon 1 minute, then leek, celery and garlic 5 minutes. Deglaze with wine, melt remaining butter, then cook flour 1 minute. Add stock, then remaining Filling ingredients. Add chicken, thicken sauce (~5 minutes).","images":[],"step":1},{"description":"Cool filling 1 hour, assemble pie with double layer puff on rim, brush lid with yolk, bake 45 minutes 200°C/375°F (180°C fan).","images":[],"step":2},{"description":"Cut leek (step photos above helpful):","images":[],"step":3},{"description":"Trim the reedy dark green ends and root off, then cut in half. Cut each piece in half lengthways. Remove the outer 5 to 6 layers (keep them together), lay them flat, cut in half lengthways then into 1.8cm / 3/4\" squares. Cut the inner core into 2cm / 0.8\" pieces.","images":[],"step":4},{"title":"Chicken","description":"Melt half the butter in a large pan over high heat. Add the chicken, salt and pepper. Cook until the surface changes from pink to white (inside still raw), then remove into a bowl using a slotted spoon. Leave residual butter and chicken juices in the pan.","images":[],"step":5},{"title":"Sauté","description":"In the same pan, cook the bacon for 1 minute. Add the leek, celery and garlic. Cook for 5 minutes until the celery is softened. Don''t let the leek brown - lower the heat if needed.","duration":1,"images":[],"step":6},{"title":"Deglaze","description":"Add the wine and simmer rapidly on high heat, stirring, until it is mostly evaporated.","images":[],"step":7},{"title":"Roux","description":"Lower the heat to medium. Add the remaining butter. Once it melts, sprinkle the flour across the surface (don''t dump in one place) and stir for 1 minute.","duration":1,"images":[],"step":8},{"title":"Creamy sauce","description":"While stirring, slowly pour the stock in. The mixture will thicken into a thick sauce once combined. Then add the mustard, cream, thyme, bay leaves, salt and pepper. Stir to combine, then add the chicken including all the juices accumulated in the bowl.","images":[],"step":9},{"title":"Simmer","description":"Increase the heat, stir to combine. Once it comes to a simmer, reduce the heat to medium high. Simmer for 5 minutes, stirring regularly, or until the sauce is a thick creamy consistency you want in the finished pie (ie sauce thickness now = thickness in the baked pie, see Note 7).","duration":5,"images":[],"step":10},{"title":"Cool","description":"Remove the pan from the stove and cool for 1 hour. (You can also store in fridge for 3 - 4 days).","images":[],"step":11},{"description":"Assembling and baking:","images":[],"step":12},{"description":"Preheat the oven to 200°C/375°F (180°C fan-forced). Use a 1.5 litre / 1.5 quart baking pan (Note 9) or 4 to 5 x ~350ml / 12 oz ramekins.","images":[],"step":13},{"title":"Connect puff pastry sheets (if needed)","description":"Semi-thaw the puff pastry (Note 6). Brush the edge of one sheet with egg white, then overlap 0.5cm / 0.2\" with the other sheet to connect them. Use the back of a spoon to \"smear\" the pastry to hide the seam and firmly connect.","images":[],"step":14},{"description":"Cut out the pie lid (I use the dish as a cutting guide).","images":[],"step":15},{"title":"Optional strips for extra puffy edges (Note 8)","description":"Cut strips using the residual pastry to line the rim of the dish (if your dish has a thick rim, like mine) and place on the rim of the dish.","images":[],"step":16},{"description":"Fill the pie dish with the cooled filling and smooth the surface. Brush the pastry strips on the rim with egg white (if not using strips, don''t do this step) then cover with the puff pastry lid.","images":[],"step":17},{"description":"Brush the lid with egg yolk. Cut a small X in the middle.","images":[],"step":18},{"description":"Bake 45 minutes or until the surface is a deep golden brown. Rest 5 minutes then serve!","images":[],"step":19}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-recipes","mains","quiches-tart-and-pie-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_98c0c9ef9775', 'en', 'US', 'One pot chicken risoni with crispy salami (orzo)', 'Recipe video above. Risoni - also known as orzo - in a creamy tomato parmesan sauce with juicy slices of seasoned chicken and lots of awesome crispy bits of golden salami! The better bacon - bolder flavour, and it doesn''t spit when you''re cooking it. :) The addition of chickpeas adds a soft nutty crunch and another layer of texture to this one-pan wonder that''s a cosy bowl of deliciousness! Total crowd pleaser.', 'https://www.recipetineats.com/tachyon/2024/01/One-pan-chicken-creamy-tomato-risoni-with-crispy-salami-2.jpg', 15, 0, 15, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_salami_stick", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_sage", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.375, "unit": "pack of 500g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 150.0, "unit": "bag of 250g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["1/2 tbsp olive oil","100g/ 3 oz salami stick (, cut into 3mm / 1/8\" thick rounds then chopped into small batons (Note 1))","2 x 250g / 8 oz chicken breasts ( (large), each cut in half horizontally to form 4 thin steaks (Note 2))"]},{"ingredients":["1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/2 tsp garlic powder","3/4 tsp paprika","1/4 tsp sage powder (optional)"],"purpose":"Chicken spice mix:"},{"ingredients":["2 garlic cloves (, finely minced)","1/2 onion (, finely chopped)","1/4 cup chardonnay or other dry white wine (, optional (Note 3))","1/4 cup tomato paste","1 1/4 cups risoni/orzo (, uncooked (Note 4))","400g / 14 oz canned chickpeas (, drained (or other beans))","3 cups chicken stock (, low sodium (or veg stock))","1/2 tsp cooking / kosher salt","1/4 tsp black pepper","3/4 cup thickened / heavy cream (low-fat ok)","1/3 cup parmesan (, finely grated (I use store bought sandy type))","150g/ 5 oz baby spinach (or 4 cups kale pieces)","1/3 cup sun dried tomato (, chopped (optional) (Note 5))"],"purpose":"Creamy tomato parmesan risoni (orzo):"},{"ingredients":["2 tbsp roughly chopped basil (optional) (Note 5)"],"purpose":"Optional garnish"}]', '[{"title":"Spice Mix","description":"Mix the ingredients in a small bowl then sprinkle both sides of the chicken.","images":[],"step":1},{"title":"Crispy salami","description":"Heat the oil in a large non-stick pan over medium high heat. Cook the salami for 2 minutes, stirring constantly, until crispy and golden. Remove into a paper towel lined bowl using a slotted spoon, leaving the tasty salami fat in the pan.","duration":2,"images":[],"step":2},{"title":"Cook chicken","description":"In the same pan, cook the chicken for 3 minutes on each side until dark golden and just cooked through (internal temperature 67°C/153°F). Remove onto a plate and cover loosely with foil to keep warm.","duration":3,"images":[],"step":3},{"title":"Sauté","description":"Still on medium high, cook the garlic and onion for 1 1/2 minutes until the onion is translucent. Add the wine and let it simmer rapidly for a couple of minutes until mostly evaporated, stirring to dissolve the fond (gold bits) on the base of the pan into the wine.","images":[],"step":4},{"title":"Risoni (orzo)","description":"Add the tomato paste and stir for 1 minute to cook out the sour raw flavour. Add the risoni and stir to coat in the tomato paste. Add the chickpeas, chicken stock, salt, pepper.","duration":1,"images":[],"step":5},{"title":"Simmer","description":"Bring to a simmer, then cook for 8 minutes, stirring every minute or so, until the risoni is just about cooked. Lower the heat to medium as it gets thicker so the base doesn''t catch.","duration":8,"images":[],"step":6},{"title":"Cream & spinach","description":"Add the cream, parmesan, spinach and sun dried tomatoes (if using). Stir until the spinach is wilted then remove from the heat. The risoni should be oozy and tender. (Still firm? Note 6)","images":[],"step":7},{"title":"Finish","description":"Cut the chicken into thick slices. (Bit cool? Note 7) Spoon risoni into bowls. Top with the chicken, sprinkle with lots of crispy salami, parmesan and basil (if using). Dig in!","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a2fe549aa309', 'en', 'US', 'One-pan Baked Butter Chicken', 'Recipe video above. The miraculous, easy way to make butter chicken in the oven! Just put everything in a pan and pop it in the oven. That sauce is to-die for! Just like the real-thing, with a fraction of the effort.This doesn''t even need to be marinated because the flesh gets infused with flavour as it bakes. Not spicy at all, so this one for everyone!', 'https://www.recipetineats.com/tachyon/2023/11/One-pan-baked-butter-chicken_9.jpg', 10, 45, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_garam_masala", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_naan", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1.2 kg/ 2.4lb (6 pieces) bone-in chicken thighs (, skin removed (Note 1))"]},{"ingredients":["1/2 cup plain yoghurt (, full fat)","1 tbsp lemon juice","1 tbsp ginger (, finely grated)","2 cloves garlic (, finely grated or crushed)","1 tsp turmeric powder","2 tsp garam masala (Note 2)","1/2 tsp chilli powder ((pure, not US blend) or cayenne pepper powder)","1 tsp ground cumin","1/2 tsp cooking salt / kosher salt"],"purpose":"Butter chicken marinade:"},{"ingredients":["2 tbsp/ 30g melted ghee or butter (Note 3)","1 cup tomato passata (US: tomato puree) (Note 4)","3/4 cup heavy / thickened cream (or regular cream, or coconut milk)","1 1/2 tsp white sugar","3/4 tsp cooking salt / kosher salt"],"purpose":"Butter chicken curry sauce:"},{"ingredients":["1/2 cup coriander leaves (cilantro) (, for garnish (optional))","Basmati rice (or other plain rice)","Naan (easy - no kneading required!)"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 200°C / 400°F (180°C fan-forced).","images":[],"step":1},{"title":"Coat chicken","description":"Mix the marinade ingredients in a bowl, then add the chicken and toss to coat.","images":[],"step":2},{"title":"Optional marinade","description":"overnight. (Note 5)","images":[],"step":3},{"title":"Assemble","description":"Mix Sauce ingredients in a 23 x 33cm / 9 x 13\" baking dish. Place chicken in, smooth side up. Scrape residual marinade out of bowl and dab onto chicken surface.","images":[],"step":4},{"description":"Bake 45 minutes, basting with sauce at the 30 minute and 40 minute mark. The sauce will change from pink to orangey-red (Note 6 for sauce thickening).","images":[],"step":5},{"title":"Serve","description":"Rest for 5 minutes. Then serve over basmati rice, garnished with coriander if desired! Naan for mopping would make everyone extra happy. :)","duration":5,"images":[],"step":6}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["chicken","chicken-recipes","indian-recipes","mains","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0feced2927c4', 'en', 'US', 'African coconut chicken curry - Kuku Paka', 'Recipe video above. Are you ready to discover the world''s easiest curry?? As in, a real one, made from scratch. Introducing - Kuku Paka! This chicken curry in a tomato coconut spiced sauce tastes like an Indian curry. Except it''s African, and you can get everything you need from your regular grocery store. For a strictly traditional version, sear the chicken over charcoal for chargrilled flavour before adding into the sauce. To make this Monday-night-friendly, I''ve just pan-seared. Serves 4 hearty appetites or 5 to 6 regular servings.', 'https://www.recipetineats.com/tachyon/2023/10/African-coconut-chicken-curry_3.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["4 chicken thigh fillets (, skin-on and bone-in (~250g/8oz each) (Note 2))","4 chicken drumsticks (~150g / 5oz each) (Note 2)","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Seasoned chicken:"},{"ingredients":["2 tbsp coconut oil (or vegetable, canola or other plain oil) (Note 1)","1 onion (, finely diced)","3 garlic cloves (, finely minced)","2 tsp ginger (, finely minced)","1 tbsp coriander powder","1/2 tbsp cumin powder","1/2 tbsp turmeric powder","1 tsp pure chilli powder or cayenne pepper (, reduce or omit to taste (Note 3))","400g / 14 oz coconut milk (, full-fat (Note 4))","400g / 14 oz crushed canned tomato","1 1/4 tsp cooking / kosher salt","2 tbsp lemon juice (sub apple cider vinegar)","1/2 cup (lightly packed) coriander/cilantro leaves (sub parsley or baby spinach, or omit)"],"purpose":"The curry:"},{"ingredients":["Basmati rice"],"purpose":"Serving:"}]', '[{"title":"Season chicken","description":"Pat chicken dry using paper towels then sprinkle with the salt and pepper.","images":[],"step":1},{"title":"Brown chicken","description":"Heat oil in a large heavy based pot over high heat. Add the thighs, skin-side down, and cook for 4-5 minutes until golden brown. Turn and cook the other side for 1 minute. Transfer to a plate (it will still be raw inside). Then brown the drumsticks as best you can. I do 3 sides, 2 minutes each side. Transfer to the plate.","duration":4.5,"images":[],"step":2},{"title":"Sauté aromatics","description":"Turn heat down to medium high. Add the onion and cook for 1 minute until softened. Add garlic and ginger, cook for 30 seconds. Add the coriander, cumin, turmeric and chilli. Stir for 30 seconds.","duration":1,"images":[],"step":3},{"title":"Sauce","description":"Add coconut milk, tomato and salt. Stir, then return chicken into the pot (including juices on the plate). Submerge chicken as best you can.","images":[],"step":4},{"title":"Simmer 30 min","description":"Once the sauce comes to a simmer, reduce the heat so it’s bubbling gently. Cover and cook for 10 minutes. Remove the lid and simmer for a further 20 minutes, stirring occasionally to ensure the base doesn''t catch.","duration":10,"images":[],"step":5},{"title":"Finish & serve","description":"Stir in lemon and half of the coriander. Lade into bowls and serve garnished with the rest of the coriander!","images":[],"step":6}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["african"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","curry-recipes","mains","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0035a9fc479f', 'en', 'US', 'Chicken Francese', 'Recipe video above. Lightly battered pan-fried chicken breast with an elegant white wine lemon sauce. It''s like Chicken Piccata, but a thicker sauce, more of it, no capers, with subtle lemon flavour. It''s got a terrific crust that soaks up the sauce! Lovely restaurant dish that''s simple to make at home.Doesn''t taste winey because the alcohol is cooked out, leaving behind magical flavour only wine can bring to sauces.', 'https://www.recipetineats.com/tachyon/2023/10/Chicken-Francese_4.jpg', 10, 15, 25, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (, skinless boneless (250-300g / 8-10oz each))","1/4 cup flour (, plain / all-purpose)","1 tsp cooking salt / kosher salt","1 tsp black pepper","2 large eggs","1 tbsp milk ( (any fat %))"],"purpose":"Chicken & coating:"},{"ingredients":["3 tbsp extra virgin olive oil","1 lemon (, thinly sliced 0.3cm / 1/8\")","50g / 3 tbsp unsalted butter","2 tbsp flour (, plain / all-purpose)","2 cups chicken stock/broth (, low sodium)","1/3 cup Chardonnay or other dry white wine (Note 1)","1/2 tsp cooking salt / kosher salt (no pepper!)","1 tbsp finely chopped parsley (, for garnish (optional))"],"purpose":"Cooking & sauce:"}]', '[{"description":"Cut each breast in half horizontally to form 4 thin steaks in total.","images":[],"step":1},{"description":"Whisk eggs and milk in a small bowl. Set aside.","images":[],"step":2},{"title":"Flour coating","description":"Mix flour, salt and pepper on a plate (I use my fingertips). Coat the chicken in the flour, shaking off excess, then set aside on a plate.","images":[],"step":3},{"description":"Heat the oil in a large nonstick pan over medium-high heat.","images":[],"step":4},{"title":"Cook chicken","description":"Dip the chicken in the egg, allow excess to drip off, then put into the pan. Cook for 3 minutes until golden. Flip, lower heat to medium, then cook for 4 minutes until the chicken is golden (internal temp 68°C/155°F). Remove onto a plate.","duration":3,"images":[],"step":5},{"title":"Lemon","description":"Add the lemon slices to the pan. Cook for a minute or until the lemons go soft / brown, then turn and cook the other side for 30 seconds. Remove onto a plate. (Note 2)","duration":0.5,"images":[],"step":6},{"description":"Wipe the pan clean using paper towels.","images":[],"step":7},{"title":"White wine sauce","description":"Still on medium heat, melt the butter in the pan. Add flour and stir for 1 minute using a wooden spoon. While stirring, slowly pour in half the stock. Once the flour is dissolved into the liquid, stir in remaining stock, then the wine and salt. (See Note 3 for lumps tip)","duration":1,"images":[],"step":8},{"title":"Thicken sauce","description":"Turn the heat up slightly then simmer for 3 - 4 minutes or until the sauce thickens into a syrupy consistency.","duration":3.5,"images":[],"step":9},{"description":"Sauce it! Return the chicken and lemon slices to the pan, then spoon the sauce all over the chicken. Sprinkle with parsley then serve the chicken with the sauce (use it ALL!).","images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b4a9348ac3d5', 'en', 'US', 'Golden coconut chicken curry', 'Recipe video above. This Golden Coconut Chicken Curry blows me away every time I make it - and I''ve been making it a lot lately! Such a beautiful spice blend, Thai vibes with a whisper of Indian, like a less shrimpy version of Thai Yellow Curry with a hint of Massaman. Don''t skip the star anise and cinnamon stick, and really try to use fresh turmeric rather than dried, for max flavour and yellow colour. All credit to JB for this one, his invention. :)*UPDATE: If you skip fresh turmeric and sub other spices and you''re using rather old spices (which lose flavour), the recipe won''t be as good as the rave reviews below and will make me sad*', 'https://www.recipetineats.com/tachyon/2023/09/Chicken-broccoli-coconut-curry_3.jpg', 10, 20, 30, 4, '[{"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_star_anise", "quantity": {"value": 3.0, "unit": "jar"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_aram_masala", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_fennel", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["3 tbsp coconut oil (, vegetable or canola oil (Note 1))","3 star anise","1 cinnamon stick","1 onion (, finely diced)","500g / 1lb chicken thigh fillets (, cut into small 1cm / 1/3\" slices (Note 2 options!))","1 tsp garlic (, finely grated)","1 tsp ginger (, finely grated)","3 tsp turmeric (, finely grated (sub 1 1/2 tsp powder, Note 3))","2 cups chicken stock/broth (, low sodium)","400g / 14 oz coconut cream (, unsweetened (sub coconut milk, Note 4))","1 large head broccoli (, florets cut small (can use stem too - peel & dice), or other veg (4 heaped cups))","1 cup coriander/cilantro leaves (, lightly packed, plus extra for garnish (I''d still make without this))"]},{"ingredients":["1 1/2 tsp cooking/kosher salt","1 1/2 tsp garam masala (Note 5)","1 1/2 tsp coriander powder","1/2 tsp cumin powder","1/2 tsp fennel powder (sub more garam masala)"],"purpose":"Spice mix:"},{"ingredients":["Crispy fried shallots (, store bought, for garnish (Note 6))","1 large head broccoli (, florets cut small (can use stem too - peel & dice), or other veg (4 heaped cups))"],"purpose":"Serving"}]', '[{"title":"Spice mix","description":"Mix the spices in a small bowl.","images":[],"step":1},{"title":"Toast","description":"Heat the oil in a large heavy based pot over medium high heat. Toast the star anise and cinnamon for 2 minutes.","duration":2,"images":[],"step":2},{"description":"Add onion, cook for 2 minutes.","duration":2,"images":[],"step":3},{"description":"Add chicken, cook for 3 minutes or it''s no longer pink on the outside (still raw inside).","duration":3,"images":[],"step":4},{"title":"Add aromatics","description":"Add garlic, ginger and turmeric. Cook for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add spice mix and stir for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Simmer 12 minutes","description":"Add stock and coconut cream. Stir and bring to an energetic simmer. Cook for 12 minutes (no need to stir) so the sauce thickens slightly.","duration":12,"images":[],"step":7},{"description":"Add broccoli florets. Bring back to a simmer and cook for 3 minutes or until softened.","duration":3,"images":[],"step":8},{"title":"Serve","description":"Cool for 5 minutes, this will allow the sauce to thicken slightly. Then stir in coriander and serve with rice (basmati or jasmine especially nice). Garnish with extra coriander and crispy fried shallots.","duration":5,"images":[],"step":9}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Indian"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","cuisines","curry-recipes","mains","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_391d4f388a0f', 'en', 'US', 'Herb & Garlic Butter Chicken Marylands (chicken leg quarters)', 'Recipe video above. Chicken marylands - such an under utilised cut of chicken! Cheap, juicy, flavourful, hard to stuff up. I tell people it''s like roast chicken: without the mess of carving up a whole chicken. Slather in herb & garlic butter then bake until golden. Don''t waste a drop of the pan juices - it''s liquid gold!Serve with potato gratin or creamy mash with garlic sautéed green beans for the perfect meal!', 'https://www.recipetineats.com/tachyon/2023/06/Herb-Garlic-Chicken-Marylands_8.jpg', 10, 50, 60, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["4 pieces (~1.5 kg/3 lb) chicken marylands (US: leg quarters) ( or 8 bone-in, skin-on thighs (Note 1))","1/2 tsp cooking/kosher salt","1/3 cup chardonnay or other dry white wine (sub low-sodium chicken stock/broth)"]},{"ingredients":["100g/7 tbsp unsalted butter (, softened)","4 garlic cloves (, minced using a garlic press (Note 2))","2 tsp fresh rosemary leaves (, finely chopped (Note 3 for dried))","2 tsp thyme leaves (, finely chopped (Note 3 for dried))","3/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Herb & garlic butter:"}]', '[{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":1},{"description":"Mix Herb & Garlic Butter ingredients until combined.","images":[],"step":2},{"title":"Butter chicken","description":"Use an upside down tablespoon to loosen the chicken skin from the flesh on the thigh and most of the leg (Note 4). Smear 80% of the butter under the skin, just a small amount (~5%) on the underside (flesh side) then the remainder on top of the skin. (The flesh side gets lots of flavour from the pan juices).","images":[],"step":3},{"description":"Put chicken in roasting pan, skin side up. Sprinkle skin with the 1/2 tsp salt. Pour wine around chicken.","images":[],"step":4},{"title":"Roast 50 minutes","description":"Roast 10 minutes to get the skin going. Then reduce the heat to 200°C /400°F (180°C fan) and roast for a further 40 minutes, basting every 10 minutes from the 20 minute mark onwards.","images":[],"step":5},{"title":"Rest & serve","description":"Remove from oven. Rest 10 minutes then serve with the garlic-herb-butter pan juices as the sauce!","images":[],"step":6}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_179548403868', 'en', 'US', 'Chicken Marsala', 'Recipe video above. A beloved Italian-American classic comprised of a crispy golden chicken cutlet smothered in a rich Marsala wine flavoured mushroom sauce. A restaurant favourite that''s easy to make at home, one bite and you''ll be hooked for life like I was!The key flavour here is Marsala wine so if you can''t consume alcohol or don''t have it, make Chicken in Creamy Mushroom Sauce instead! Also, this dish uses more alcohol than my usual "just a splash of wine" so it''s not recommended for kids. :)', 'https://www.recipetineats.com/tachyon/2023/06/Chicken-Marsala_0b.jpg', 10, 15, 25, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (300g/10oz each), cut in half horizontally (or 4 thighs, Note 1)","1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper","1/4 cup flour (, plain/all-purpose)"],"purpose":"Golden crusted chicken:"},{"ingredients":["2 tbsp extra virgin olive oil","2 tbsp / 30g unsalted butter","2 eschalots (US: shallots), peeled and cut into 1cm / 1/3\" squares (Note 2)","1 garlic (, finely minced)","2 cups white mushrooms (, sliced 0.5cm / 1/5\" thick)","1 cup dry marsala wine (Note 3)","1/2 cup chicken stock/broth (, low sodium)","1/2 cup thickened / heavy cream ( (Note 4))","1/4 tsp cooking salt / kosher salt","1/8 tsp black pepper","1 tbsp finely chopped parsley (, for garnish (optional))"],"purpose":"Marsala sauce:"}]', '[{"description":"Chicken escalopes:","images":[],"step":1},{"title":"Pound","description":"Cut each breast in half to form 2 thin steaks. Cover with a freezer bag or Go-Between (Note 5) and pound to 1 cm / 0.4″ thickness using a meat mallet or rolling pin. This tenderises and ensures even cooking of the chicken.","images":[],"step":2},{"title":"Dust","description":"Sprinkle the surface with half the salt, pepper then flour. Lightly rub flour across surface, turn and repeat with remaining salt, pepper and flour. Shake excess flour off each piece just before cooking.","images":[],"step":3},{"title":"Cook","description":"Put half the butter and oil in a large non-stick pan over medium high heat. Once the butter is melted and foamy, place chicken in, then cook for 3 to 4 minutes until it''s gorgeously golden and crispy. Turn and cook the other side for 2 minutes. Remove onto a plate.","duration":3.5,"images":[],"step":4},{"description":"Creamy marsala sauce:","images":[],"step":5},{"title":"Sauté aromatics","description":"In the same pan, add remaining butter and oil. Once butter is melted, add eschalots and garlic. Cook for 1 minute.","duration":1,"images":[],"step":6},{"title":"Cook mushrooms","description":"Add mushrooms. Cook for 3 minutes, stirring regularly.","duration":3,"images":[],"step":7},{"title":"Reduce marsala","description":"Add marsala, turn up heat to high and boil for 3 minutes or until reduced by half.","duration":3,"images":[],"step":8},{"title":"Thicken sauce","description":"Add chicken stock, cream, salt and pepper. Stir, then lower heat so it''s simmering (not boiling rapidly) and simmer for 3 to 5 minutes until the sauce thickens to a cream consistency (not too thick, will thicken more).","duration":4,"images":[],"step":9},{"title":"Rewarm chicken","description":"Nestle chicken into sauce and leave for 30 seconds to reheat.","duration":0.5,"images":[],"step":10},{"description":"Serve! Take off the stove. Sprinkle with parsley, serve over starchy vehicle of choice (I chose mash. Rice, small pasta, polenta or bread for plate mopping also work well!).","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Italian-American"],"categories":["chicken-breast-recipes","chicken-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8d75575a9ea4', 'en', 'US', 'Crunchy crumbed chicken drumsticks', 'Recipe video above. Super crunchy baked drumsticks that are generously seasoned with an addictive zingy kick from black pepper and cayenne. It''s not blow-your-head off but it has a very warm buzz! Just omit the cayenne and reduce the pepper to make it kid friendly. It''s so seasoned you don''t need a sauce for dunking but if you want something quick but great, use my honey mustard or pink sauce - both recipes in the notes.', 'https://www.recipetineats.com/tachyon/2023/05/Crunchy-crumbed-chicken-drumsticks_8.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}]', '[{"ingredients":["8 chicken drumsticks","1/2 cup flour (, plain/all purpose)","3 large eggs (, beaten)","1 cup panko breadcrumbs (Note 1)","Canola oil spray (or other oil)"]},{"ingredients":["1 tbsp dried oregano","1 tbsp dried basil","1 tsp garlic powder","1 1/2 tsp smoked paprika","1 1/2 tsp cayenne pepper or pure chilli powder (- Note 2 (omit for kid-friendly))","1 1/2 tsp cooking salt","2 tsp black pepper (reduce to 1/2 tsp for kid-friendly)"],"purpose":"Seasoning:"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan). Place a rack on a foil lined tray. Spray rack with oil.","images":[],"step":1},{"title":"Crumbing bowls","description":"Place the flour, whisked eggs and panko in 3 separate medium bowls (bear in mind shape to fit the drumsticks!).","images":[],"step":2},{"description":"Mix Seasoning in a small bowl. Put 1 tablespoon into the flour and the rest in the panko, then mix.","images":[],"step":3},{"title":"Crumb","description":"Pat drumsticks dry with paper towels. Coat in flour (shake off excess), then egg (let excess drip off). Place in panko and rotate, pressing to adhere all over, including the handle. (Note 3 for mess-free hands technique!)","images":[],"step":4},{"title":"Spray","description":"Place drumstick on the rack. Repeat with remaining chicken. Spray very generously with oil.","images":[],"step":5},{"description":"Bake 25 minutes. Turn drumsticks, spray again with oil. Bake a further 20 minutes until golden brown and super crunchy!","images":[],"step":6},{"description":"Serve Eat and enjoy the CRUNCH!","images":[],"step":7}]', '["egg","gluten"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b20ecad7f571', 'en', 'US', 'Thai red curry pot roast chicken', 'Recipe video above. Such a spectacular way to cook a whole chicken! Cooked in a Thai red curry sauce with potatoes and beans, the pot-roasting method keeps the chicken ultra juicy. Plus, we can get away with store bought curry paste here because the chicken juices add a stack of money-can''t-buy flavour into the sauce.Easy enough for midweek, definitely impressive enough for company!', 'https://www.recipetineats.com/tachyon/2023/04/Thai-Red-Curry-Pot-Roast-Chicken_3a.jpg', 10, 75, 155, 5, '[{"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 115.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_green_beans", "quantity": {"value": 120.0, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 15.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.8 kg/ 3.6 lb whole chicken","1 tsp cooking/kosher salt","3 tbsp vegetable oil","115g/ 4 oz (1/2 cup) Thai red curry paste ( (Maesri recommended, Note 1))","2 large garlic cloves (, finely grated (Note 2))","2 tsp fresh ginger (, finely grated (Note 2))","2 tsp fresh lemongrass (, finely grated, white / pale green part only (Note 2))","1 cup chicken stock/broth (, low sodium)","400 ml/ 14 oz coconut cream (Note 3)","6 kaffir lime leaves (, crushed in hand (Note 4))","1 tbsp white sugar","2 tsp fish sauce","600g/ 1.2lb small potatoes (12 or so), (skin on (Note 5))","120g/ 4oz green beans (, trimmed and cut in half)","15 Thai basil leaves (, or more! (sub ordinary Italian basil, Note 6))"]},{"ingredients":["Jasmine rice","Red chilli (, finely sliced)","Coriander / cilantro leaves"],"purpose":"Serving + optional garnishes:"}]', '[{"title":"De-chill & salt chicken","description":"Take the chicken out of the fridge 1 hour prior. Pat dry then sprinkle with the salt.","images":[],"step":1},{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":2},{"title":"Sauté curry paste","description":"Use a large, oven-proof pot with a lid. Heat oil on medium high heat. Cook curry paste, garlic, ginger and lemongrass for 2 minutes. This step substantially improves the flavour of store bought curry paste.","duration":2,"images":[],"step":3},{"title":"Sauce","description":"Add chicken stock, stir, then simmer rapidly for 3 minutes to reduce by half. Stir in coconut cream, hand-crushed kaffir lime leaves, sugar and fish sauce.","duration":3,"images":[],"step":4},{"description":"Place chicken into the sauce. Spoon over sauce. Surround with potatoes.","images":[],"step":5},{"title":"Bake 1 hour","description":"Place the lid on and bake for 40 minutes. Remove lid spoon sauce over chicken (ie. baste). Turn the oven up to 220°C/425°F (200°C fan). Bake uncovered for 10 minutes, baste, bake another 10 minutes.","duration":40,"images":[],"step":6},{"title":"Beans, then bake 10 minutes","description":"Push beans into the sauce (wherever they fit!). Baste again then bake for a final 10 minutes (no lid).","images":[],"step":7},{"title":"Rest 10 minutes","description":"Remove chicken onto a plate (Note 7). Rest 10 minutes. Put lid on pot to keep sauce warm.","images":[],"step":8},{"title":"Serving","description":"Carve chicken, place on platter. Stir basil leaves into sauce. Pour/spoon sauce, potatoes and beans over chicken. Garnish with chilli and coriander, if desired. Serve with jasmine rice!","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai-ish"],"categories":["chicken-recipes","cuisines","one-pot-recipes","thai-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_89bf2e1811c6', 'en', 'US', 'Jalapeño popper stuffed chicken', 'Recipe video above. I love a stuffed chicken - and this is my (current) favourite. Think - Jalapeño popper, stuffed inside chicken. Warm, cheesy, spicy. Fabulous, easy way to make chicken breast a whole lot more exciting! Adore the jalapeño flavour in this.Spice level - not too spicy at all! The spiciness of fresh jalapeños gets dialled down a LOT when baked in the cream cheese. It will surprise you. Reader feedback - Sue says "My husband does not like spicy and said it was delicious. A definite “make again”." - 30 Mar 2023', 'https://www.recipetineats.com/tachyon/2023/03/Jalapeno-popper-stuffed-chicken_4.jpg', 15, 20, 35, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cream_cheese", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.4, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_jalape_os", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["2 x 220g/7oz chicken breast, (skinless, boneless)","1/4 tsp cooking/kosher salt","1/2 tsp smoked paprika (or ordinary paprika)","1 tbsp extra-virgin olive oil"]},{"ingredients":["60g/ 2 oz cream cheese","1/2 cup mozzarella cheese (, shredded (or other cheese))","1/4 cup parmesan (, finely shredded)","2 jalapeños (, deseeded and finely diced (Note 1))","1/2 tsp garlic powder","1/2 tsp black pepper","1/2 tsp cooking / kosher salt"],"purpose":"Jalapeño Popper Stuffing :"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"description":"Cut pockets into each chicken breast (Note 2), taking care not to cut all the way through. Cut on the side with the fold in the meat, to keep the smooth side intact.","images":[],"step":2},{"title":"Stuffing","description":"Microwave the cream cheese for 30 seconds to soften. Mix together with remaining jalapeño popper stuffing ingredients.","duration":0.5,"images":[],"step":3},{"title":"Stuff & seal","description":"Stuff inside the chicken pockets, stuffing it all the way in! Then seal each chicken with 2 or 3 toothpicks. If some stuffing is oozing out, that’s a bonus - it’s the best part when it crisps in the pan! Sprinkle both sides of the chicken with the paprika and salt.","images":[],"step":4},{"title":"Sear","description":"Heat the oil in an oven-proof skillet over medium-high heat. Place the breast smooth-side down, sear for 2 minutes until golden (it won''t colour more in the oven). Flip and sear the other side for another 2 minutes.","duration":2,"images":[],"step":5},{"title":"Bake 15 min","description":"Transfer the pan to the oven and bake for 15 minutes, or until the internal temperature of the chicken reaches 67°C/155°F.","duration":15,"images":[],"step":6},{"title":"Rest and serve","description":"Remove the chicken to a plate and rest for 5 minutes, then serve!","duration":5,"images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_48859ff3efa2', 'en', 'US', 'One Pot Chicken Risoni', 'Recipe video above. A great one-pot meal for midweek, tastes like risotto but so much easier to make! Lemon garlic chicken, surprising amount of hidden vegetables, oozy tomato risoni (orzo), loaded with Greek flavours! The list of ingredients is looks long, but there''s actually a lot of repeat ingredients. :)', 'https://www.recipetineats.com/tachyon/2016/01/One-Pot-Greek-Risoni_7.jpg', 15, 35, 50, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.9, "unit": "punnet of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g chicken thighs (, boneless skinless (or breast), cut into 2 cm / 1\" pieces)","2 garlic cloves (, finely minced)","1 tbsp dried oregano","1 tbsp olive oil","1/2 tbsp lemon juice","1 tsp lemon zest","1/2 tsp each salt and pepper"],"purpose":"Lemon Garlic Chicken"},{"ingredients":["2 tbsp olive oil","2 garlic cloves (, minced)","1 small onion (, finely chopped)","2 zucchini (medium, or 1 large) (, cut into 1cm / 1/3\" cubes (Note 1))","1 red bell pepper/capsicum (, cut into 1cm / 1/3\" cubes (Note 1))","1 tbsp dried oregano","2 1/2 cups chicken broth/stock (, low sodium)","14 oz / 400g canned crushed tomatoes","1 tbsp tomato paste","1 1/2 cups orzo/risoni (Note 2)","1 1/2 cups cherry tomatoes (1 Australian punnet)","1 tsp cooking salt (kosher salt)","1/2 tsp black pepper"],"purpose":"Orzo/Risoni"},{"ingredients":["2 tbsp lemon juice (, drizzling at end)","1/2 cup (100g) Greek feta cheese (, crumbled (not optional))","Fresh oregano leaves (optional)"],"purpose":"Garnish (semi-optional)"}]', '[{"title":"Marinade chicken","description":"Combine Marinated Chicken ingredients in a bowl and set aside for marinate for 20 minutes. (Skip if in hurry, can also do overnight)","duration":20,"images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":2},{"title":"Brown chicken (raw inside)","description":"Heat 1 tablespoon olive oil in a a large oven proof skillet or pot over high heat (Note 3). Cook chicken until lightly browned but still pink inside. Remove from skillet.","images":[],"step":3},{"title":"Sauté vegetables","description":"Add 1 tbsp olive oil, garlic and onion. Saute for 1 minute, then add zucchini and bell peppers/capsicum. Cook for 2 minutes.","duration":1,"images":[],"step":4},{"title":"Add everything else","description":"Add risoni, oregano, chicken broth, tomato, tomato paste, salt and pepper.","images":[],"step":5},{"description":"Scatter chicken and cherry tomatoes across the surface (don''t stir in).","images":[],"step":6},{"title":"Bake 15 minutes","description":"Once the liquid comes to a simmer, transfer to the oven (no lid) and bake for 15 minutes (or until risoni is just cooked, tender but still firm). There may be liquid on the surface still - that''s good!","duration":15,"images":[],"step":7},{"title":"Drizzle with lemon","description":"Remove from oven, drizzle with lemon juice. Garnish with feta and fresh oregano leaves, if desired, then serve.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek(ish)"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","greek-recipes","main-dishes","mediterranean-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7cf0a5b018f6', 'en', 'US', 'One Pot Mexican Chicken and Rice', 'Recipe video above. Chicken seared with Fajita flavours then baked with seasoned Mexican red rice. This is a flavour explosion in one pot! People love that it''s finished in the oven. No need to worry about a scorched base!Makes more rice than you''ll need because it is difficult to make less using this method of cooking. Nobody complains, cause it''s so good!', 'https://www.recipetineats.com/tachyon/2014/12/One-Pot-mexican-chicken-and-rice_3.jpg', 15, 50, 55, 5, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tsp garlic powder (or 2 garlic cloves, minced)","2 tsp paprika","2 tsp cumin powder","1 3/4 tsp salt","1/2 tsp cayenne pepper ((Note 1), optional)","Black pepper"],"purpose":"Mexican Spice Mix"},{"ingredients":["5 chicken thighs, bone-in, skin on ( (Notes 2 and 3))","2 tbsp olive oil","1 tbsp lime juice"],"purpose":"Chicken"},{"ingredients":["1 small onion (, peeled and diced (or 1/2 large))","1 garlic clove (, minced)","1 red capsicum ((bell pepper), diced or sliced)","1 cup long grain rice (, uncooked (Note 4))","1 cup chicken stock/broth (, low sodium (or vegetable stock))","3/4 cup tomato passata (US: tomato puree) (Note 5)","1 cup frozen corn kernels (or canned - drained)","1 can (400g/16oz) black beans (, drained and rinsed (sub red kidney beans))"],"purpose":"Rice"},{"ingredients":["1 lime (, plus extra to serve)","Coriander/cilantro","Sliced jalapeño peppers (optional)"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 180°C/350°F (160° fan).","images":[],"step":1},{"title":"Mexican spice mix","description":"Mix the ingredients in a small bowl.","images":[],"step":2},{"title":"Rub Chicken","description":"Place 1 1/2 tablespoons of the Mexican Spice Mix in a large bowl (reserve rest for rice) with 1 tablespoon olive oil and lime juice. Mix to form a paste then add the chicken and toss to coat the chicken.","images":[],"step":3},{"title":"Marinate (optional)","description":"Marinate chicken for 1 hour, or even overnight, if you have the time. Otherwise, it''s fine to proceed with the recipe!","images":[],"step":4},{"title":"Sear chicken","description":"Using a large deep skillet preferably with a lid (Note 6), heat the remaining 1 tbsp olive oil over medium high heat. Sear the skin side of the chicken for 4 minutes until light golden, then sear the flesh side for 1 1/2 minutes (will still be raw inside). Remove onto a plate.","duration":4,"images":[],"step":5},{"title":"Sauté aromatics","description":"If you''ve got a lot of burnt spices on the base, scrape off and discard some of it. Then in the same skillet, still over medium high heat, add the onion, garlic and capsicum (bell peppers). Sauté for 3 minutes until the onion softens.","duration":3,"images":[],"step":6},{"title":"Rice & liquid","description":"Add the rice and stir. Add chicken stock, tomato passata, corn, beans and remaining Mexican Spice Mix. Stir to combine.","images":[],"step":7},{"title":"Top with chicken","description":"Place chicken on top of the rice, skin side up. It will be partially submerged but most of the skin should be above the liquid.","images":[],"step":8},{"title":"Bake covered 25 min","description":"Bring to simmer, then cover skillet with a lid or foil and place in the oven for 25 minutes.","duration":25,"images":[],"step":9},{"title":"Bake uncovered 15 min","description":"Remove the lid/foil and bake for a further 15 minutes until only small puddles of liquid remain on the surface of the rice.","images":[],"step":10},{"title":"Rest 10 minutes","description":"Remove from the oven and allow to rest for 10 minutes (uncovered). Any remaining liquid will evaporate in this step.","duration":10,"images":[],"step":11},{"title":"Serve","description":"Squeeze the juice of 1 lime over the chicken and rice. Remove chicken or push to the side then fluff the rice. Serve, garnished with coriander/cilantro leaves, extra lime wedges and sliced jalapeños, if desired. Sour cream also goes well with this, or a dollop of guacamole or avocado sauce!","images":[],"step":12}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","most-popular","one-pot-recipes","quick-and-easy","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bc52387c7145', 'en', 'US', 'Honey Soy Wings', 'Recipe video above. The easiest, no-fuss way to make sticky Honey Soy Wings in the oven. Don''t you hate it when you''re promised sticky wings but the sauce stays watery and never thickens?? Trick is to just pour off chicken juices partway through cooking. Easy!Serve with fried rice or Vermicelli Noodle Salad for a great quick midweek meal.', 'https://www.recipetineats.com/tachyon/2022/11/Honey-Soy-Wings_7.jpg', 5, 60, 65, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_honey", "quantity": {"value": 0.12, "unit": "jar of 500g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.09, "unit": "bottle of 500ml"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}]', '[{"ingredients":["1.25 kg / 2.5 lb chicken wings (wingettes/drumettes), or cut up whole wings (Note 1 for whole wings)","1 tsp white sesame seeds","1 green onion stem (, finely sliced)"]},{"ingredients":["4 tbsp honey","5 tbsp light soy sauce (Note 2)","1 tbsp dark soy sauce (Note 2)","3 tbsp apple cider vinegar (or other clear vinegar)","1 large garlic clove (, crushed using garlic press (or finely minced or grated))","1/2 tbsp canola oil"],"purpose":"Honey soy marinade:"}]', '[{"description":"Mix marinade in a bowl until honey is dissolved. Pour over the wings in a ziplock bag. (Note 3)","images":[],"step":1},{"description":"Marinade for 30 minutes. You can do overnight but it doesn''t noticeably improve flavour in the flesh.","duration":30,"images":[],"step":2},{"description":"Preheat oven to 200°C/400°F (180°C fan). Line a large tray with foil then paper.","images":[],"step":3},{"title":"Bake","description":"Spread wings out on the tray, skin side up. Reserve marinade. Bake 30 minutes.","images":[],"step":4},{"description":"Drain off juices on the tray and discard. (Key step to ensure sauce thickens).","images":[],"step":5},{"title":"Sauce","description":"Pour reserved marinade over wings. Toss to coat then spread the wings out, skin side up.","images":[],"step":6},{"title":"Bake & baste","description":"Turn oven down to 180°C/350°F (160°C fan). Bake wings for 30 minutes, basting with tray juices every 10 minutes (3 times). Rearrange wings as needed if cooking unevenly, you can even turn them upside down if they brown too quickly. Sauce should be syrupy by the end so you can glaze well. (Note 4 if sauce still watery).","duration":30,"images":[],"step":7},{"title":"Serve","description":"Transfer wings into a serving bowl. Pour over syrup on tray, sprinkle with sesame seeds and green onion. Serve!","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Asian-esque","Western"],"categories":["chicken-recipes","chicken-wings","finger-food","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2544a6f1bff9', 'en', 'US', 'Chicken in Creamy Mustard Sauce', 'Recipe video above. Here''s a really quick way to cook chicken thighs or breast in a simple yet elegant creamy mustard sauce. Mustard adds flavour as well as thickening the sauce while tarragon infuses the sauce with elegant aniseed notes, giving it a very restaurant-y flavour. But even if you don''t have fresh tarragon or don''t like it, this is absolutely still worth making. In fact, I''ve probably made it as often without tarragon as I have with!', 'https://www.recipetineats.com/tachyon/2022/11/Chicken-in-creamy-mustard-sauce_3.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["700g / 1.4 lb chicken thigh fillets (, skinless boneless (4 - 6 pieces, Note 1))","1 1/2 tbsp olive oil","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"]},{"ingredients":["1/2 cup thickened/heavy cream","1 tbsp Dijon mustard","1 tbsp whole grain mustard","1/4 tsp cooking/kosher salt","1/4 tsp black pepper","1-2 tbsp water (, as needed)"],"purpose":"Creamy mustard sauce:"},{"ingredients":["2 tsp fresh tarragon (, finely chopped (Note 2))","2 tsp parsley (, finely chopped)"],"purpose":"Optional herbs:"}]', '[{"description":"Season chicken with the salt and pepper.","images":[],"step":1},{"title":"Sear chicken thighs","description":"Heat oil in a large pan that is not non-stick over medium-high heat. (Note 3) Place chicken in pan smooth side-down and cook for 4 minutes or until deep golden. Turn and cook the other side for 3 minutes until cooked through (internal temperature 72°C/162°F, Note 4). Remove to a plate.","duration":4,"images":[],"step":2},{"title":"Breast","description":"If using breast (prepared per Note 1), sear on high for 2 minutes on each side, target temp 67°C/153°F.)","duration":2,"images":[],"step":3},{"title":"Clean pan","description":"Scrape any loose black bits out of the pan and discard.","images":[],"step":4},{"title":"Make sauce","description":"Return the pan to medium heat. Add cream and both mustards. Mix with a wooden spoon until mustard dissolves, scraping up any brown bits stuck to the pan. Once sauce is hot but not simmering, stir in salt, pepper and herbs (if using). If getting too thick loosen with a touch of water.","images":[],"step":5},{"title":"Serve","description":"Place chicken on serving plates. Spoon over sauce. Enjoy!","images":[],"step":6}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9c345eb01285', 'en', 'US', 'Chicken Rissoles', 'Recipe video above. The chicken version of the beloved Aussie beef rissoles! You''ll love the oozy little pockets of cheese.Makes 14 to 16 rissoles. Serves 4 to 5 as a meal, or one Dozer.', 'https://www.recipetineats.com/tachyon/2022/09/Chicken-Rissoles_4.jpg', 15, 20, 35, 16, '[{"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_ketchup", "quantity": {"value": 1.0, "unit": "bottle of 500g"}}]', '[{"ingredients":["500g / 1 lb chicken mince (ground chicken), excess liquid drained and discarded (Note 1)","1 carrot, medium (, grated on a shallow angle (Note 2))","1 zucchini, medium (, grated on a shallow angle (Note 2))","1 egg","1 1/2 cup Colby cheese, shredded (or cheddar, tasty, Monterey Jack - see Note 3)","3/4 cup panko breadcrumbs (Note 4)","1 tbsp finely chopped parsley (, optional)","1 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Rissoles:"},{"ingredients":["2 tbsp canola oil","Ketchup - for dipping"],"purpose":"Cooking & serving:"}]', '[{"description":"Pre-heat oven to 100°C/210°F (all oven types), to keep cooked rissoles warm. Place a rack over a tray.","images":[],"step":1},{"title":"Rissole mixture","description":"Mix all ingredients together in a bowl using a wooden spoon.","images":[],"step":2},{"title":"Form patties","description":"Wet your hands (stops the mixture sticking all over your hands). Measure out just shy of 1/4 cup and shape into a 6 cm wide x 1.5cm thick pattie (2.4\" x 0.6\" thick). See Note 1 if your mixture is too loose.","images":[],"step":3},{"title":"Cook","description":"Heat 1 tablespoon oil in a large non-stick pan over medium high heat. Cook 5 - 6 rissoles at the time, 3 to 4 minutes on each side, until beautifully golden (as pictured). (Note 5 for baking)","images":[],"step":4},{"title":"Keep warm","description":"Transfer to the rack on the tray and keep warm in the oven. Add more oil as needed and cook remaining rissoles.","images":[],"step":5},{"description":"Serve straight away with ketchup for dipping!","images":[],"step":6}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-mince-recipes","chicken-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_25cd81634cc8', 'en', 'US', 'Crispy Baked Chicken Drumsticks', 'Recipe video above. This is just a great, simple chicken drumsticks recipe you can get in the oven quickly. Tossed in a 3-ingredient, barbecue rub-like seasoning, they''re beautifully crispy thanks to a touch of baking powder, a tried and proven secret ingredient in my Truly Crispy Baked Chicken Wings recipe!', 'https://www.recipetineats.com/tachyon/2022/07/Crispy-Baked-Chicken-Drumsticks_5.jpg', 10, 45, 55, 5, '[{"id": "ing_chicken", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.625, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.068, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}]', '[{"ingredients":["12 chicken drumsticks (Note 1)","2 tbsp extra virgin olive oil","Oil spray"]},{"ingredients":["3 tsp garlic powder","3 tsp onion powder","5 tsp smoked paprika","2 tsp black pepper","1 1/2 tsp cooking/kosher salt","4 1/2 tbsp plain/all-purpose flour","3 tsp baking powder (makes them crispier, DO NOT confuse with baking soda / bi-carb) (Note 3)"],"purpose":"Seasoning (Note 2):"}]', '[{"title":"Preparation","description":"Preheat the oven to 200°C/390°F (180°C fan-forced). Line a tray with foil then place a rack on the tray (makes the underside of the drumsticks crispier, Note 4).","images":[],"step":1},{"title":"Seasoning","description":"Mix the Seasoning ingredients in a shallow bowl.","images":[],"step":2},{"title":"Coat in oil","description":"Toss the drumsticks in the olive oil. Stretch and pull the skin on each drumsticks to cover as much of the flesh as possible.","images":[],"step":3},{"title":"Coat in seasoning","description":"Coat a drumstick in the Seasoning then shake the excess off well. Place on the rack. Repeat with remaining drumsticks.","images":[],"step":4},{"title":"Spray with oil","description":"Spray the legs generously with oil.","images":[],"step":5},{"description":"Bake for 30 minutes, rotating the tray halfway through. Increase the oven to 220°C / 430°F (200°C fan) then bake for a further 15 minutes or until the skin is crispy. Enjoy!","duration":30,"images":[],"step":6}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7b601609467c', 'en', 'US', 'Chicken Fricassée (French creamy chicken stew)', 'Recipe video above. A recipe from our chef JB (yes, he''s French!), this traditional French dish is essentially a quick chicken stew with a creamy white mushroom sauce. It''s a bit like a white sauce version of the famous French Coq au Vin – but it''s much faster to make!This is a wonderful rustic family meal that''s quick enough for midweek, or to elevate to restaurant level by using homemade chicken stock.', 'https://www.recipetineats.com/tachyon/2021/09/Chicken-Fricasse_03-SQ.jpg', 20, 60, 80, 4, '[{"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.667, "unit": "carton of 250ml"}}]', '[{"ingredients":["4 chicken drumsticks (~150g/5oz each, Note 1)","4 chicken thighs (, skin-on and bone-in (~250g/8oz each, Note 1))","1 tsp salt (cooking / kosher salt)","1/2 tsp black pepper","4 tbsp / 60g unsalted butter"],"purpose":"Chicken"},{"ingredients":["300g / 10oz white mushrooms (, halved if small, or cut in 4 to 6 if large)","2 medium brown onions (, sliced 0.6cm (1/2in) wide)","2 garlic cloves (, finely minced)","1 bay leaf (, fresh (sub dried))","3 thyme sprigs (or 1/2 tsp dried thyme)","3 tbsp flour (, plain / all-purpose)","1/2 cup white wine (, preferably chardonnay (Note 2))","3 cups chicken stock (, low sodium (preferably homemade!))","1/4 tsp salt (cooking / kosher salt)","1/4 tsp black pepper","2 tbsp parsley (, chopped)","2/3 cup thickened/heavy cream"],"purpose":"Stew ingredients"}]', '[{"title":"Season chicken","description":"Pat chicken dry with paper towels then sprinkle with salt and pepper.","images":[],"step":1},{"title":"Brown thighs","description":"Melt butter over medium-high heat in a large skillet or heavy based pot with a lid. Add chicken thighs, skin side down, and cook for 4 to 5 minutes until golden brown. Turn and cook the other side for 1 minute then remove to a plate.","duration":4.5,"images":[],"step":2},{"title":"Brown drumsticks","description":"Then brown the drumsticks, as best you can. I do 3 sides, about 2 minutes each. Then remove from skillet.","images":[],"step":3},{"title":"Sauté mushrooms and onion","description":"Add mushrooms, onion, bay leave and thyme. Cook for 5 minutes until mushroom is lightly golden - they won''t go deep golden brown.","duration":5,"images":[],"step":4},{"title":"Garlic and flour","description":"Add garlic and stir for 30 seconds. Add flour and cook for 1 minute.","duration":0.5,"images":[],"step":5},{"title":"Wine and chicken stock","description":"Add wine, chicken stock, salt and pepper. Stir, scraping the base of the pot to dissolve the brown residue stuck to the pan (\"fond\") into the sauce.","images":[],"step":6},{"title":"Return chicken to sauce","description":"Return chicken back into the sauce with the skin side up.","images":[],"step":7},{"title":"Simmer covered 10 minutes","description":"Once it comes to a simmer, adjust heat so it''s bubbling constantly but not rapidly (see video) - medium-low on my stove. Cover with lid and simmer 10 minutes.","images":[],"step":8},{"title":"Uncover 20 minutes","description":"Remove lid and let it simmer for a further 20 minutes. Chicken will be cooked - internal temperature 75°C/167°F or slightly higher.","images":[],"step":9},{"title":"Creamy sauce","description":"Remove chicken to a plate. Add cream and stir. Once it comes up to a simmer, taste sauce (I know, big ask!), and add more salt if desired..","images":[],"step":10},{"description":"Serve! Return chicken into the sauce then remove from the stove. Sprinkle with parsley and serve! Traditionally served over mashed potato or rice. Also ideal with short pasta like penne, ziti or macaroni.","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","mains","quick-and-easy","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ffff10b2a364', 'en', 'US', 'Coq au Vin', 'Recipe video above. Coq au Vin – a true French classic from a true French chef, our very own JB! Chicken pieces are braised in a luscious, glossy red wine sauce with bacon, mushroom and onions that tastes utterly luxurious. Like Beef Bourguignon, the beauty of this dish lies in its simplicity: remarkably few ingredients and simple process with results fit for a king – or queen! For the best results, start this 2 days before serving: 12 - 24 hour marinade for the chicken (essential), then rest the finished stew overnight to let the flavours develop even further (recommended but not essential).', 'https://www.recipetineats.com/tachyon/2016/09/Coq-au-Vin_00.jpg', 15, 90, 105, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 16.0, "unit": "pack of 1kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.105, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["4 chicken thighs (, bone-in, skin on (~220g / 7 oz each) (Note 1))","4 chicken drumsticks (Note 1)","16 pearl onions or picking onions (Note 2)","1 bay leaf (, fresh (dry also ok))","3 thyme sprigs (sub 1 tsp dried thyme)","750 ml / 3 cups pinot noir red wine (, or other dry red wine (Note 3))"],"purpose":"Red Wine Chicken Marinade:"},{"ingredients":["3 - 4 tbsp vegetable oil (or canola oil)","3/4 tsp salt (cooking/kosher salt, or 1/2 tsp table salt)","1/2 tsp pepper"],"purpose":"Browning Chicken:"},{"ingredients":["400g / 14oz white mushrooms (, halved (quartered if large) (Note 4))","150g / 5oz bacon piece (, (speck) cut into 1 x 2.5cm / 0.4 x 1\" batons (Note 5))","60g / 4 tbsp unsalted butter","3 garlic cloves (, finely minced (with knife))","2 tbsp tomato paste","7 tbsp flour (, plain / all purpose)","750 ml / 3 cups beef stock","1/4 tsp salt (cooking/kosher salt, or 1/8 tsp table salt) (Note 7)","1/4 tsp black pepper"],"purpose":"Coq au Vin Stew:"},{"ingredients":["2 tbsp parsley (, chopped)","Mashed potato (or tagliatelle)"],"purpose":"Garnish and serving:"}]', '[{"description":"Marinate chicken:","images":[],"step":1},{"title":"Marinate chicken","description":"Place the Chicken Marinade ingredients in a large glass or ceramic bowl or dish. Marinate overnight in the fridge (minimum 12 hours, maximum 24 hours).","images":[],"step":2},{"description":"Strain wine into a bowl. Reserve herbs and wine. Separate the chicken and onion.","images":[],"step":3},{"title":"Dry chicken","description":"Spread chicken out on a try lined with paper towels, then pat dry with paper towels.","images":[],"step":4},{"title":"Reduce wine","description":"Pour red wine into a saucepan and bring to a boil over medium high heat. Simmer vigorously, skimming off any impurities that rise to the surface, until reduced by half. Set aside.","images":[],"step":5},{"description":"Brown chicken and vegetables:","images":[],"step":6},{"description":"Preheat oven to 180°C / 350°F (160°C fan).","images":[],"step":7},{"title":"Season chicken","description":"Sprinkle chicken with 3/4 tsp salt and 1/2 tsp black pepper.","images":[],"step":8},{"title":"Brown chicken","description":"Heat 3 tbsp oil in a large, heavy-based, oven-proof pot over medium-high heat. Add chicken thighs skin side down and cook for 2 - 3 minutes until nicely browned (it will be darker than usual because of the red wine). Flip thighs and cook the other side for another minute to kiss it with a little colour. Remove to a tray. Pull at skin of drumsticks to cover flesh as best as possible, then brown (I do 3 to 4 sides, ~5 minutes in total). Remove and set aside.","duration":2.5,"images":[],"step":9},{"title":"Fry bacon","description":"Remove any loose black burnt bits. Add a bit of extra oil if needed, then cook bacon for 3 minutes until golden. Add to tray with chicken.","duration":3,"images":[],"step":10},{"title":"Sauté mushrooms","description":"Add mushrooms and cook for 5 minutes, or until golden. Remove into a separate bowl.","duration":5,"images":[],"step":11},{"title":"Sauté onion","description":"Add a bit of extra oil if needed, then cook onions for 5 minutes or until there are nice golden patches.","duration":5,"images":[],"step":12},{"title":"Butter and flour","description":"Add butter into pot. Once melted, add garlic and cook for a further 1 minute. Add tomato paste and cook for 2 minutes. Add flour and cook for 2 minutes.","duration":2,"images":[],"step":13},{"title":"Add wine and stock","description":"While stirring, slowly pour in beef stock – this helps the flour dissolve lump-free into the stock. Then add the reduced wine and mix until flour mixture is dissolved and mostly lump-free. (Note 8)","images":[],"step":14},{"title":"Add everything back in","description":"Add chicken, bacon, mushroom, thyme, bay leaf, salt and pepper into the pot, then stir.","images":[],"step":15},{"title":"Oven 45 minutes","description":"Bring to a simmer, then cover and transfer to oven for 45 minutes. Chicken will be very tender - but not \"falling apart\". (Note 9)","duration":45,"images":[],"step":16},{"title":"Adjust salt","description":"Remove from oven, taste sauce and add salt if needed.","images":[],"step":17},{"title":"Leave overnight (recommended, Note 11)","description":"If time permits, leave the stew overnight before serving because as with all stews, it gets better with time! Reheat gently on a low stove in a covered pot, ensuring that chicken is fully heated through. Add water if needed to loosen sauce.","images":[],"step":18},{"description":"Serve over mashed potato or tagliatelle, sprinkled with fresh parsley! For the ultimate experience, mop the plate clean with homemade brioche (surprisingly straight forward to make). See in post for side salad and dessert options.","images":[],"step":19}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken-drumstick-recipes","chicken-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_248ab261c994', 'en', 'US', 'Mushroom Stuffed Chicken Breast', 'Recipe video above. These juicy chicken breasts are stuffed with garlicky mushrooms, spinach leaves and a blanket of oozing melted cheese. Simple to make with just a few ingredients, this is how to transform chicken breast from ho-hum into "ohhh yum!"After this one, try Sun Dried Tomato Stuffed Chicken!', 'https://www.recipetineats.com/tachyon/2021/07/Mushroom-Stuffed-Chicken-Breast_14.jpg', 15, 30, 45, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.64, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["2 x 220g / 7oz chicken breast (, skinless boneless (Note 1))","3/4 tsp salt","1/4 tsp pepper","30g / 2 tbsp unsalted butter","200g / 7 oz mushrooms (, sliced 3mm (1/8″) thick (~2 heaped cups))","2 garlic cloves (, finely minced)","1/2 tsp thyme leaves (Note 2)","2 cups baby spinach (Note 3)","80 g / 3oz mozzarella (, sliced (or other melting cheese))","1 tbsp olive oil"]}]', '[{"description":"Preheat oven to 200°C/390°F (180°F fan).","images":[],"step":1},{"description":"Cut pockets into each chicken breast, being sure not to cut all the way through (see photos in post). Cut on the side with the fold in the meat, to keep the smooth side intact.","images":[],"step":2},{"description":"Season the inside and outside of the chicken with half the salt and pepper.","images":[],"step":3},{"title":"Mushroom filling","description":"Melt butter in a heavy based oven proof skillet over high heat. Add mushrooms and cook for 3 minutes until they start to turn pretty golden. Then add garlic, thyme, remaining salt and pepper and continue cooking for a further 2 minutes until mushrooms are nice and golden.","duration":3,"images":[],"step":4},{"title":"Add spinach","description":"Add baby spinach and stir until wilted - about 30 seconds.","images":[],"step":5},{"description":"Stuff mushroom mixture into the pocket of each chicken, then top with cheese.","images":[],"step":6},{"title":"Seal with toothpicks as best you can","description":"it doesn’t need to be fully sealed like we do with Chicken Kiev. Just mostly sealed.","images":[],"step":7},{"title":"Sear chicken","description":"Give the pan a quick wipe with paper towels. Heat oil over medium high heat. Sear each side of the chicken breast for 1 1/2 minutes until golden.","images":[],"step":8},{"title":"Bake 15 minutes","description":"Transfer the skillet to the oven and bake for 15 minutes, or until the internal temperature of the chicken is 65°C/149°F (chicken flesh, not the mushroom filling).","duration":15,"images":[],"step":9},{"title":"Rest 5 minutes","description":"Remove from tray onto a plate, loosely cover with foil and rest for 5 minutes. Serve! Pictured in post with easy creamy Baked Lemon Herb Risotto and baby spinach with Balsamic Dressing.","duration":5,"images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b10b7260e13', 'en', 'US', 'Chicken Kiev', 'Recipe video above. The trick to ensuring the melted butter stays firmly sealed inside Chicken Kiev? Partially freezing the chicken. Stops the chicken from moving as you handle it for coating / cooking which ensures the chicken remains sealed and keeps the molten river of garlic butter inside!For a real Kiev experience, you do need to deep fry. BUT for the very best healthier baked option, see Note 6.', 'https://www.recipetineats.com/tachyon/2021/05/Chicken-Kiev_2-1.jpg', 30, 30, 60, 2, '[{"id": "ing_butter", "quantity": {"value": 6.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1000.0, "unit": "bottle"}}]', '[{"ingredients":["6 tbsp / 90g unsalted butter (, softened (or salted butter))","2 tsp parsley (, finely chopped)","2 garlic cloves (, very finely minced (2 tsp))","1/4 tsp salt (skip if using salted butter)"],"purpose":"Garlic Butter Stuffing:"},{"ingredients":["2 x 220 - 250g (7 - 8oz) chicken breast (, skinless and boneless (Note 1))","1/2 tsp salt","1/4 tsp pepper","1 egg (, lightly whisked)","1/4 cup flour","1 cup panko breadcrumbs (Note 2)","Oil for frying (, canola or vegetable oil (~4 cups / 1 litre))"],"purpose":"Chicken:"},{"ingredients":["Parsley (, finely chopped (garnish))"],"purpose":"Serving:"}]', '[{"title":"Garlic butter filling","description":"Place ingredients in a bowl and mix until combined.","images":[],"step":1},{"title":"Shape and chill butter","description":"Scrape butter on to a small sheet of baking / parchment paper and roughly shape into 10 x 6cm / 4 x 2.4\" rectangle. Refrigerate until firm, then cut in half lengthwise to form two batons.","images":[],"step":2},{"title":"Pound chicken","description":"Place chicken smooth side down between two freezer bags or paper (Note 3). Pound to an even 0.5 cm / 0.2\" thickness using a meat mallet (Note 4 for tips!)","images":[],"step":3},{"title":"Season","description":"Sprinkle each side of the chicken with salt and pepper.","images":[],"step":4},{"title":"Stuff and roll up chicken","description":"Place a baton of butter in the middle. Trim edges if needed, then add trimmings into the centre. Fold sides in over the butter, then roll the chicken up starting from the bottom, finishing with the seam side down.","images":[],"step":5},{"title":"Wrap and partially freeze","description":"Wrap the chicken log in cling wrap, twisting the ends tightly to create a firm log shape. Place in the freezer for 30 minutes until the surface is fairly firm to touch, but not frozen solid. (Note 5)","duration":30,"images":[],"step":6},{"title":"Crumb","description":"Place egg, flour and breadcrumbs in separate bowls. Coat chicken in flour, shaking off excess. Coat in egg, drip off excess. Then coat in breadcrumbs, pressing to adhere.","images":[],"step":7},{"title":"Partial freeze","description":"Place crumbed chicken in the freezer for 30 minutes until fairly firm to handle (but not frozen solid).","duration":30,"images":[],"step":8},{"description":"Preheat oven to 180°C / 350°F. Place a rack on a tray.","images":[],"step":9},{"title":"Fry","description":"Heat oil in a heavy based pot to 190°C / 375°F. Carefully place chicken in the oil and cook, turning once or twice, until golden (2 - 3 minutes). It will still be raw inside.","images":[],"step":10},{"title":"Bake","description":"Place chicken on a rack and bake for 15 minutes or until the internal temperature of the chicken is 65°C / 150°F. Pierce the top so you don''t cause butter leakage!","duration":15,"images":[],"step":11},{"description":"Rest for 2 minutes, then serve, sprinkled with a pinch of parsley if desired!","duration":2,"images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Russian"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","mains","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0992d206c899', 'en', 'US', 'Chicken Piccata (Lemon Chicken with Capers)', 'Recipe video above. If, like me, you find the sauce of other Chicken Piccata recipes too sour, and the chicken kind of bland, I think you''ll love this version! The lemon tang in the sauce is pleasant rather than lip-puckering, and the flavour of the chicken is boosted with a little parmesan in the flour coating.', 'https://www.recipetineats.com/tachyon/2021/05/Chicken-Piccata_0.jpg', 10, 0, 10, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.188, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.222, "unit": "bottle of 750ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_capers_in_brine", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["450g / 16oz chicken breast (2 large pieces), skinless boneless (Note 1)","4 tbsp flour (sub cornflour/cornstarch for GF)","2 1/2 tbsp parmesan (, finely grated (Note 2))","1/2 tsp salt","1/4 tsp pepper","2 1/2 tbsp olive oil","1 tbsp / 15g unsalted butter"]},{"ingredients":["2 tbsp / 30g unsalted butter (, cut into 1.5cm / 1/2\" cubes)","2/3 cup dry white wine (Note 3)","2 tbsp lemon juice (, fresh)","3 tbsp capers in brine (, drained (Note 4))","1 1/2 tsp parsley (, finely chopped, plus more for garnish)"],"purpose":"Lemon Sauce:"}]', '[{"description":"Crispy Parmesan Chicken:","images":[],"step":1},{"description":"Cut each breast into 3 pieces. Then place between 2 pieces of cling wrap or paper and pound to 1/2 cm / 0.2\" thickness.","images":[],"step":2},{"description":"Drizzle chicken with 1/2 tbsp olive oil and spread with your fingers on both sides.","images":[],"step":3},{"description":"Mix flour, parmesan, salt and pepper in a shallow dish. Coat chicken, pressing to adhere, then shaking off excess.","images":[],"step":4},{"description":"Heat olive oil in a large skillet over medium high heat. Then add butter and let it melt.","images":[],"step":5},{"title":"Place 3 pieces of chicken in the skillet. Cook 3","description":"4 minutes until golden, then turn and cook the other side for 1 minute. Remove onto plate, repeat with remaining chicken.","duration":1,"images":[],"step":6},{"description":"Chicken Piccata Sauce:","images":[],"step":7},{"description":"Pour out and discard excess fat in skillet, then give it a quick wipe with paper towels (no need to clean thoroughly).","images":[],"step":8},{"description":"Still on medium high heat, add wine. Let it simmer rapidly until it reduces by half - around 3 minutes.","images":[],"step":9},{"description":"Add lemon and simmer 1 minute.","images":[],"step":10},{"description":"Reduce heat to low. Add cubed butter and swirl pan to make it melt but not go foamy. Sauce should be glossy, translucent and slightly thickened.","images":[],"step":11},{"description":"Stir in capers and parsley. Serve chicken with Sauce, sprinkled with extra parsley if desired!","images":[],"step":12}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a24c6cbb0774', 'en', 'US', 'Sticky Glazed Christmas Chicken', 'Recipe video above. Everybody loves the glaze on a Christmas ham. So one year, I used it for chicken instead and people went mad over it! Easier and cheaper than ham, with a much higher ratio of glaze to meat, this is so good I''ve actually had people tell me they love this more than Christmas ham!!It''s ultra-sticky on the outside, and smells and tastes like Christmas. The meat is super tender – we''ve practically slow cooked the chicken!', 'https://www.recipetineats.com/tachyon/2020/12/Sticky-Glazed-Christmas-Chicken_1.jpg', 10, 60, 70, 6, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cinnamon", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_whole_star_anise", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_good_value_leafy_greens", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}]', '[{"ingredients":["1.2 kg / 2.4 lb chicken thighs, skin on, bone in ( (Note 1))","800g / 1.6 lb chicken drumsticks (, or more thighs (Note 1))"]},{"ingredients":["5 tsp orange zest (2 oranges)","1/2 cup orange juice (from the zested oranges)","1/4 cup cider vinegar (sub white wine, sherry or champagne vinegar)","1/2 cup brown sugar (, lightly packed)","2 tbsp Dijon mustard","1 tbsp olive oil","2 tsp ground cinnamon","1 1/2 tsp allspice","1 tsp ground ginger","2 whole star anise","2 tsp salt","1/2 tsp black pepper"],"purpose":"Marinade"},{"ingredients":["2 oranges (, cut into wedges or halved then sliced)","good value leafy greens (- like endive, watercress, for the bed)","orange zest curls (Note 3)"],"purpose":"Serving and garnishes"}]', '[{"description":"Marinate Chicken","images":[],"step":1},{"description":"Mix Marinade ingredients in a jug. Pour over chicken in a large ziplock bag (Note 2). Massage to coat, then marinate chicken for ideally 24 hours (bare minimum is 3 hrs, 12 hrs is ok).","images":[],"step":2},{"description":"Cook","images":[],"step":3},{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":4},{"description":"Line 2 trays with foil then parchment/baking paper (you''ll thank me later).","images":[],"step":5},{"description":"Distribute chicken on trays, then pour the marinade over. Roast 30 minutes.","images":[],"step":6},{"description":"Roast for a further 20 minutes, basting with pan juices 2 or 3 more times until the chicken is deep golden and sticky. At first, the juices will be watery but in the final 10 minutes or so, they will thicken and darken. Once this happens, baste more frequently and heavily. (Note 4)","images":[],"step":7},{"description":"When the top tray is almost ready, switch the tray positions (ie move bottom tray up and put the top tray undenerath) so they finish at the same time. GOAL: Deep golden and sticky chicken!","images":[],"step":8},{"description":"Before plating up, baste again with the sticky juices.","images":[],"step":9},{"title":"Serving suggestion","description":"Spread leafy greens on a platter, pile on sticky chicken. Decorate with orange slices or wedges.","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Christmas","Holiday","Western"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_498c3fdc6fa7', 'en', 'US', 'Leftover Turkey Pot Pie', 'Recipe video above. Leftover turkey is quite dry, given it''s a lean meat. So smothering it in a creamy sauce for a Turkey Pot Pie is the ideal way to repurpose perfectly good leftovers! This is like a cross between Chicken Pot Pie and Cheesy Garlic Bread. While the filling is delicious, that buttery garlicky cheesy topping steals the show. I just love how it gets soaked with the creamy white sauce!!Use whatever veggies you want. And of course, chicken is a straight up simple substitute for turkey if that''s what you have.', 'https://www.recipetineats.com/tachyon/2020/11/Leftover-Turkey-Pot-Pie_1.jpg', 15, 40, 55, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}]', '[{"ingredients":["1 tbsp olive oil","150g / 5 oz mushrooms (, sliced 1/2cm / 1/5\" thick)","50g / 4 tbsp butter","1 onion (, finely chopped (brown, white, yellow))","2 garlic cloves (, minced)","1 carrot (, peeled, chopped into 1cm/ 1/3\" pieces)","4 tbsp flour (plain/all purpose)","2 1/2 cups milk (any fat % fine)","4 cups (600g) cooked chopped turkey or chicken","1 1/2 cups frozen peas","1 tsp chicken or vegetable stock powder (or 1 cube. I use Vegeta powder)","1/4 tsp salt","1/2 tsp black pepper"]},{"ingredients":["50g / 4 tbsp salted butter","2 garlic cloves (, minced using garlic press)","5 packed cups bread chunks ~2.5cm/1\" cubes (Note 1)","2 tbsp parmesan cheese (, grated (optional))","1 cup mozzarella or other melting cheese, shredded or sliced (or enough slices to cover most of top)"],"purpose":"Garlic Bread Topping"}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types)","images":[],"step":1},{"title":"Topping","description":"Stir together melted butter and garlic. Place bread chunks in a bowl, drizzle over butter, toss. Set aside.","images":[],"step":2},{"title":"Brown mushrooms","description":"Heat oil in an oven-proof skillet over high heat. (Note 3) Add mushrooms and cook until browned - about 4 minutes. Remove.","images":[],"step":3},{"title":"Sauté garlic & onion","description":"Lower heat to medium high. Melt butter in same skillet. Add onion and garlic, cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add carrot then cook for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add flour, cook for 1 minute. You''ll have a pasty mix. Don''t worry if it looks dry (depends how sweaty your onions get).","duration":1,"images":[],"step":6},{"title":"Make roux","description":"While stirring, add half the milk and mix quickly to dissolve the paste into the liquid (this happens quite quickly). Add remaining liquid and stir. Add stock powder, salt and pepper, stir.","images":[],"step":7},{"title":"Thicken sauce: Cook for 2","description":"3 minutes, stirring regularly. It should start steaming and bubbling a bit, and the sauce will thicken. Thickness test: coat back of wooden spoon, you should be able to draw a line across it (see video, Note 3)","duration":2.5,"images":[],"step":8},{"description":"Add turkey, peas and mushrooms, and mix into sauce.","images":[],"step":9},{"description":"Top with bread, spread to cover surface. Grate over parmesan if using, top with melting cheese.","images":[],"step":10},{"title":"Bake: Bake for 12","description":"15 minutes or until the cheese gets some brown spots. Tent foil over so it doesn''t stick to the cheese, then bake for a further 10 minutes.","duration":13.5,"images":[],"step":11},{"title":"Serve","description":"Sprinkle with additional parmesan if desired, then serve!","images":[],"step":12}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","turkey-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1881ba70a6f1', 'en', 'US', 'Chicken with Creamy Mushroom Sauce', 'Recipe video above. The creamy mushroom sauce here is a cut above the usual basic recipes, thanks to the additions of wine, parmesan and chicken stock. It turns this quick chicken dinner into a meal that''s both worthy and elegant enough to serve to company!It''s an excellent sauce to serve with chicken breast, which is very lean and doesn''t actually have very much flavour. Also, the lightly-floured crust on the chicken makes it nice and crispy, giving the sauce something to cling on to. So don’t skip it!', 'https://www.recipetineats.com/tachyon/2020/10/Chicken-in-Creamy-Mushroom-Sauce_7.jpg', 5, 15, 20, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["2 chicken breasts, large (boneless skinless, ~600-700g / 1.2 - 1.4 lb total, Note 1)","1/2 tsp salt","black pepper","1/4 cup flour","15g / 1 tbsp unsalted butter"],"purpose":"CRISPY CHICKEN"},{"ingredients":["30g / 2 tbsp unsalted butter","300g / 10 oz mushrooms (, sliced (button or Swiss brown))","2 garlic cloves (, minced)","1/4 cup dry white wine (sub more chicken stock, Note 2)","1/2 cup chicken or vegetable stock (, low sodium)","1 cup thickened / heavy cream (, full fat (Note 3))","1/2 cup parmesan (, finely and freshly grated (Note 4))"],"purpose":"Mushroom Sauce"},{"ingredients":["2 tbsp chives (, finely sliced (optional) – sub parsley, green onions, or omit)"],"purpose":"For serving"}]', '[{"title":"Split breast","description":"Cut each breast in half horizontally to form 4 thin steaks in total.","images":[],"step":1},{"title":"Dust with flour","description":"Sprinkle each side with salt and pepper, then sprinkle with flour and use your fingers to spread it all over the surface.","images":[],"step":2},{"title":"Cook chicken","description":"Melt 15g butter in a large non-stick frying pan over medium high heat. Add chicken and cook each side for 2 1/2 minutes until golden brown and just cooked through. Remove from pan, cover and keep warm.","images":[],"step":3},{"title":"Cook mushrooms","description":"In the same frying pan, add remaining butter and increase heat to high. Add mushrooms and cook for 4 minutes, until starting to turn golden brown on the edges.","duration":4,"images":[],"step":4},{"title":"Add garlic later","description":"Then add garlic and a pinch of salt and pepper, and continue cooking for another minute until both garlic and mushrooms are golden.","images":[],"step":5},{"title":"Deglaze skillet: Add white wine","description":"it will bubble and be steamy! Cook for 30 seconds, scraping the bottom of the pan, until wine is mostly evaporated and the alcohol smell is gone.","duration":0.5,"images":[],"step":6},{"title":"Make creamy sauce","description":"Add chicken stock, cook vigorously for 1 minute so it mostly evaporates. Then add cream, lower heat to medium and simmer for 2 minutes until it reduces and thickens slightly.","duration":1,"images":[],"step":7},{"title":"Add parmesan","description":"Stir in parmesan, taste and add more salt and pepper if needed.","images":[],"step":8},{"title":"Finish chicken in sauce","description":"Return chicken to sauce for 30 seconds (to warm through slightly.) Garnish with chives and serve as-is in the pan, for people to help themselves (or transfer to serving platter, if you prefer). Alternatively, serve a portion of chicken onto each plate, spoon sauce over and garnish with more chives.","duration":0.5,"images":[],"step":9},{"title":"Sides: Ideal served with mashed potato or rice","description":"something to soak in that amazing sauce! See Note 5 for suggestions.","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","main-dishes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dd094ddfce27', 'en', 'US', 'Chicken Parmigiana', 'Recipe video above. Known as Chicken Parmesan in the US, the three key things that makes this the best Parmi you''ll ever have in your life are: layers upon layers on seasoning, dry brining for the most juicy chicken ever, and extra crispy chicken. Because I''ll never understand why you''d go to the trouble of making crispy crumbed chicken if the whole thing goes soggy when smothered in tomato sauce!Bonus baked option in Note 10. So golden and crunchy it will blow your mind!', 'https://www.recipetineats.com/tachyon/2020/09/Chicken-Parmigiana_7.jpg', 20, 40, 60, 6, '[{"id": "ing_chicken_breast", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 10.0, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.5, "unit": "L"}}]', '[{"ingredients":["3 chicken breasts (300g/10z each) (, halved horizontally to form 6 pieces (Note 2))","1 tsp salt (, cooking / kosher (or 3/4 tsp table salt, Note 3))","1/2 tsp black pepper","1/2 tsp Italian mixed herbs (Note 4)"],"purpose":"Brined Chicken Marinade (Note 1):"},{"ingredients":["1/3 cup flour (, plain/all purpose)"],"purpose":"Flour dusting:"},{"ingredients":["2 eggs","1 garlic clove (, minced using garlic press)","1/4 tsp each salt and pepper","1/4 tsp Italian mixed herbs (Note 4)"],"purpose":"Egg Dredge:"},{"ingredients":["1 1/2 cups panko breadcrumbs (sub normal, Note 5)","1/2 cup parmesan (, finely grated (store bought sand-like is best) (Note 6))","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Parmigiana Bread Crumbing:"},{"ingredients":["2 cups olive oil (or vegetable or canola)"],"purpose":"Frying:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1/4 cup onion or eschallots (, very finely chopped (Note 7))","1/4 tsp red pepper flakes ((chilli flakes), optional)","1/4 tsp Italian mixed herbs (Note 4)","1/4 cup white wine (, anything (optional, Note 10))","400g / 14 oz tomato passata (aka tomato puree) (Note 8)","1/2 cup chicken stock/broth (or water)","1/4 tsp each salt and pepper"],"purpose":"Parmigiana Pasta Sauce:"},{"ingredients":["10 basil leaves (, roughly chopped (sub pinch of dried - or omit))","2 cups mozzarella cheese (, shredded (or enough slices to cover))","3/4 cup parmesan (, finely grated (best to grate your own, Note 6))","1 tbsp extra virgin olive oil"],"purpose":"Layering:"},{"ingredients":["5 basil leaves (, roughly chopped)"],"purpose":"Garnish (optional)"}]', '[{"description":"Dry Brine Chicken:","images":[],"step":1},{"description":"Sprinkle both sides of chicken with salt, pepper and Italian herbs. Refrigerate for 30 minutes.","duration":30,"images":[],"step":2},{"description":"Parmigiana Tomato Sauce:","images":[],"step":3},{"description":"Heat oil in a saucepan over medium heat. Add garlic and onion, cook for 3 minutes until onion is translucent.","duration":3,"images":[],"step":4},{"description":"Add red pepper flakes and herbs, stir for 15 seconds. Add wine, turn up heat and let it simmer rapidly until mostly evaporated and winey smell is gone.","duration":0.25,"images":[],"step":5},{"description":"Add tomato, chicken stock, salt and pepper. Cover, then simmer 10 minutes on low until thickened. Cover and keep warm.","images":[],"step":6},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":7},{"title":"Crumbing set up","description":"Spread flour out in a shallow bowl. Whisk Egg Dredge in a separate shallow bowl. Mix Crumbing ingredients in a third shallow bowl or pan.","images":[],"step":8},{"title":"Dredge & crumb","description":"Press both sides of chicken into flour, then shake off excess. Coat in egg, letting excess drip off, then place in Crumbing, pressing to adhere.","images":[],"step":9},{"description":"Transfer to plate and repeat with remaining chicken.","images":[],"step":10},{"description":"Frying (Note 10 for baked option):","images":[],"step":11},{"description":"Line a tray with paper towels and place rack on tray.","images":[],"step":12},{"title":"Heat 1.5","description":"2cm / 2/3\" oil in a skillet over medium high heat to 180°C/350°F (Note 9).","images":[],"step":13},{"description":"Carefully place 2 or 3 pieces of chicken in. Cook 2 minutes until underside is golden, then carefully turn and cook the other side for 1 1/2 minutes.","images":[],"step":14},{"description":"Transfer to rack, then repeat with remaining chicken. (Note 12 - oil clean and reuse)","images":[],"step":15},{"description":"Assembling & baking:","images":[],"step":16},{"description":"Place chicken on a tray. Spoon 1/3 cup sauce over the chicken - cover around 80% of the chicken, leave the ends crispy.","images":[],"step":17},{"description":"Sprinkle sauce with basil, then mozzarella cheese (pile it on in mounds to use it all up), then sprinkle with parmesan. Drizzle oil over parmesan.","images":[],"step":18},{"description":"Bake 15 minutes until cheese is melted and there''s a few brown spots - no longer, otherwise chicken will overcook.","images":[],"step":19},{"description":"Remove from oven, sprinkle with extra basil if desired. Serve immediately (with leftover Tomato Sauce, if you''d like!)","images":[],"step":20}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","iconic-dishes","main-dishes","mains","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a2b5a3fc447', 'en', 'US', 'Gravy Baked Chicken (thighs & drumsticks) - 5 min prep!', 'Recipe video above. Crispy baked chicken thighs and drumsticks that magically makes its own gravy - all in one pan! Terrific last minute chicken dinner that takes minutes to prepare and is zero maintenance to cook. The flavour in the gravy is phenomenal because it''s flavoured with the chicken juices!', 'https://www.recipetineats.com/tachyon/2020/07/Gravy-Baked-Chicken.jpg', 5, 50, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}]', '[{"ingredients":["1.25 kg/ 3 lb bone in, skin on chicken thighs and/or drumsticks (all of one, or mix, Note 1)","2 tsp olive oil (or other oil)"]},{"ingredients":["1 tsp paprika powder","1 tsp dried thyme","1 tsp onion powder (or garlic powder)","1 tsp salt","1/2 tsp black pepper"],"purpose":"Chicken seasoning:"},{"ingredients":["4 tbsp flour (, plain/all purpose (Note 2 for GF))","1 1/2 cups beef stock/broth (yes, beef, not chicken! Note 3)","1/2 tsp black pepper"],"purpose":"Gravy:"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":1},{"title":"Seasoning","description":"mix in a small bowl.","images":[],"step":2},{"title":"Season chicken","description":"Place chicken in a 23 x 33cm / 9 x 13\" baking pan. Drizzle with oil then rub all over Sprinkle & rub in the Seasoning, using most on the skin side.","images":[],"step":3},{"description":"Arrange chicken skin side up in the pan.","images":[],"step":4},{"title":"Gravy mixture","description":"Whisk flour with about 1/2 cup of stock until lump free, then whisk in remaining stock and pepper (forgot in video!). Pour into the pan around the chicken.","images":[],"step":5},{"description":"Bake uncovered for 50 minutes, or until chicken is crispy and golden.","duration":50,"images":[],"step":6},{"title":"Whisk gravy","description":"Remove chicken onto a plate, then give the gravy a good whisk to make it smooth. Adjust Gravy thickness if required - Note 4. Taste and add salt and pepper, if needed.","images":[],"step":7},{"title":"Serve","description":"Pour gravy into a jug. Serve alongside chicken!","images":[],"step":8}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","emergency-recipes","main-dishes","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39f510179260', 'en', 'US', 'Chicken Salad - quick, easy, BIG!', 'Recipe video above. Here''s a speedy main course size salad that''s filled with all my favourite vegetables. I like this because it''s filled, colourful, interesting enough to serve to friends, but quick enough for a fast lunch, filling enough for dinner.', 'https://www.recipetineats.com/tachyon/2020/06/Quick-Chicken-Salad_6.jpg', 15, 0, 15, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 36.0, "unit": "head"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_mixed_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["3 cups store bought roast chicken (, shredded (Note 1))","12 cups cos / romaine lettuce (2 medium, 1 giant) (, chopped into bite size pieces (or other leafy greens))","1 cup corn kernels (can, drained - about 2/3 can)","1/2 red onion (, finely sliced)","300g/ 10oz cherry or grape tomatoes (or 2 normal tomatoes chopped)","2 cucumbers (, halved lengthwise then sliced 1cm / 1/3\" (or 1 long English/telegraph cucumber))","2 avocados (, cut into bite size chunks (or 1 giant one))","150g/ 5oz bacon (, cooked until crisp then chopped (optional))"]},{"ingredients":["2 1/2 tbsp cider vinegar (Note 2)","6 tbsp extra virgin olive oil","1 garlic clove (, minced using garlic press (~1 tsp))","1 tsp Dijon Mustard (or any smooth, non spicy mustard, optional)","2 tsp dried mixed herbs (Note 3 for subs)","1 tsp sugar (, optional (Note 4))","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Dressing:"}]', '[{"title":"Dressing","description":"Place ingredients in a jar, shake, set aside for at least 10 minutes to let flavours meld.","images":[],"step":1},{"title":"Salad","description":"Place all ingredients except bacon in a big bowl. Drizzle over most of the Dressing, then toss well.","images":[],"step":2},{"description":"Transfer to serving bowl, drizzle with remaining Dressing. Sprinkle with bacon. Serve immediately!","images":[],"step":3}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ce4b1beecdc2', 'en', 'US', 'Oven Baked BBQ Chicken - with quick homemade barbecue sauce', 'Recipe video above. This is how I make BBQ Chicken in the oven when I''m craving sticky chicken but don''t want to fire up the BBQ! Made with a quick homemade BBQ sauce, the chicken is braised in the sauce which is loaded with extra flavour from the juices of the chicken. Fabulous sticky glaze, juicy inside!', 'https://www.recipetineats.com/tachyon/2016/10/Baked-BBQ-Chicken-with-Barbecue-Sauce_2.jpg', 10, 50, 60, 5, '[{"id": "ing_ketchup", "quantity": {"value": 0.3, "unit": "bottle of 500g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 cup ketchup (or Australian/UK tomato sauce)","1/4 cup apple cider vinegar","2 tsp Worcestershire Sauce","4 tbsp brown sugar","2 tsp mustard powder","2 tsp onion powder","1/2 tsp salt","1/2 tsp fresh black pepper","1 cup water"],"purpose":"Sauce (Note 1)"},{"ingredients":["1.5 kg / 3 lb chicken thighs (bone in skin on), drumsticks or wings (Note 2)","Fresh parsley, chives or finely chopped green onions (, for garnish)"],"purpose":"Chicken"}]', '[{"description":"Preheat oven to 200°C/390°F.","images":[],"step":1},{"title":"Sauce","description":"Mix all Sauce ingredients in a ceramic/glass baking dish (Note 3), then mix in water.","images":[],"step":2},{"description":"Add chicken and turn to coat. Place chicken skin side down.","images":[],"step":3},{"description":"Bake for 20 minutes. Remove from oven, turn chicken, spoon over Sauce.","duration":20,"images":[],"step":4},{"description":"Bake for a further 30 minutes, then remove and spoon over Sauce.","images":[],"step":5},{"title":"Skim off fat (optional)","description":"Tilt pan and spoon or drain off excess fat.","images":[],"step":6},{"title":"Broil/grill","description":"Change to broiler/grill on high. Spoon sauce over chicken generously, then place under grill / broiler for 2 to 3 minutes to caramelise the chicken and the sauce to thicken more. Do not walk away - this can happen quickly!","duration":2.5,"images":[],"step":7},{"description":"Serve chicken, garnished with parsley or green onions, if using. Pictured in post with Mashed Potato and Green Bean Salad (minus feta).","images":[],"step":8},{"description":"Classic Side Dishes for BBQ Chicken","images":[],"step":9},{"description":"Cornbread, Coleslaw, Potato Salad (or try this no mayo Lemon Potato Salad), Southern Baked Beans, big leafy salad with classic Vinaigrette, steamed corn with butter, bread rolls, creamy mashed potato (or Creamy Cauliflower Mash for low carb emergency!), or Potato & Gravy.","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9df5f1a1dfd1', 'en', 'US', 'Oven Baked Chicken and Rice', 'Recipe VIDEO above. Made entirely in the oven (no stove!), the rice in this recipe is outrageously delicious! It''s buttery and garlicky, tender but not mushy. The secret tip is to briefly bake onion with garlic and butter before adding the rice, liquids and chicken - it adds a great flavour base!', 'https://www.recipetineats.com/tachyon/2018/06/Oven-Baked-Chicken-and-Rice_0.jpg', 10, 70, 80, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["5 bone in chicken thigh fillets, peel skin OFF (, (Note 1))","1 onion (, chopped (brown, white or yellow))","2 cloves garlic (large) (, minced)","2 tbsp (30g) butter (or olive oil)","1 1/2 cups (270g) uncooked white rice (Note 3)","1 1/2 cups (375 ml) chicken broth/stock (, hot (I microwave))","1 1/4 cups (315 ml) water (, hot (tap is fine))"]},{"ingredients":["1 tsp paprika powder","1 tsp dried thyme","1/2 tsp garlic powder","1/2 tsp onion powder","3/4 tsp salt","Black pepper"],"purpose":"Chicken Rub (Note 2):"},{"ingredients":["Oil spray","Fresh thyme leaves or finely chopped parsley"],"purpose":"Optional garnish:"}]', '[{"description":"Preheat oven to 180°C/350°F.","images":[],"step":1},{"description":"Scatter onion and garlic in a baking dish (about 10 x 15\" / 25 x 35 cm), then place butter in the centre. Bake for 15 minutes (check at 12 minutes, mix if some bits are browning too much).","duration":15,"images":[],"step":2},{"description":"Meanwhile, mix together Chicken Rub. Sprinkle on both sides of the chicken.","images":[],"step":3},{"description":"Remove baking dish from the oven. Add rice then mix.","images":[],"step":4},{"description":"Place chicken on rice. Then pour chicken broth and water around the chicken.","images":[],"step":5},{"description":"Cover with foil, then bake for 30 minutes. Remove foil, spray chicken with oil (optional, gives chicken nicer finish), then bake for a further 20 minutes until liquid is absorbed.","duration":30,"images":[],"step":6},{"description":"Stand for 5 minutes, then remove chicken and fluff up rice. Garnish with parsley or thyme if desired, serve and enjoy!","duration":5,"images":[],"step":7},{"description":"Dish is flavoured enough to serve without sauce, but if you want to take it over the top, make this quick Gravy in 4 minutes flat (pictured in video).","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dietary","emergency-recipes","gluten-free-recipes","mains","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6b970abcff5b', 'en', 'US', 'Chicken Enchiladas', 'Recipe video above. If you like your enchiladas plump, juicy, saucy and full of flavour, this is the recipe for you! Homemade from scratch, the foundation of this recipe is a double duty Enchilada Spice mix.', 'https://www.recipetineats.com/tachyon/2020/03/Chicken-Enchiladas_4.jpg', 20, 45, 65, 8, '[{"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_refried_beans", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 8.0, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["8 tortillas (, flour or corn (about 20cm/8\" wide, Note 1))"]},{"ingredients":["1 tsp EACH onion powder, garlic powder, salt","1 tbsp EACH dried cumin powder, paprika, dried oregano","1/4 tsp black pepper","3/4 tsp cayenne pepper (optional, adjust to taste)"],"purpose":"Enchilada Seasoning:"},{"ingredients":["2 tbsp olive oil","3 tbsp flour (, plain/all purpose)","2 cups (500ml) chicken stock/broth (, low sodium)","1.5 cups (375ml) tomato passata or US puree (Note 4 sub)"],"purpose":"Enchilada Sauce"},{"ingredients":["600g / 1.2lb chicken breast (, sliced in half horizontally (or boneless thigh) (Note 2))","2 tbsp olive oil (, separated)","1/2 onion (, chopped)","2 garlic cloves (, finely minced)","1 red capsicum/bell pepper (, diced)","400g / 14oz refried beans (Note 3)","400g/14oz canned corn (, drained (sub frozen 1 3/4 cups))","1/4 cup (65ml) water","1 cup (100g) cheese (shredded (Mexican cheese blend, Monterey Jack, cheddar))"],"purpose":"Chicken Filling:"},{"ingredients":["1.5 cups (150g) cheese (, shredded)","2 tbsp coriander/cilantro (, roughly chopped)"],"purpose":"Topping"}]', '[{"title":"Enchilada Seasoning","description":"Mix Enchilada Seasoning Spices. To be used for Filling and Sauce.","images":[],"step":1},{"description":"Enchilada Sauce","images":[],"step":2},{"title":"Make roux","description":"Heat oil in saucepan over medium heat. Add flour and stir 20 seconds.","images":[],"step":3},{"title":"Add other ingredients","description":"Add 2 tbsp Enchilada Seasoning, broth and tomato. Stir to combine.","images":[],"step":4},{"title":"Simmer to thicken","description":"Increase heat slightly to medium high. Cook for 4 minutes, whisking regularly, until the sauce thickens to the consistency of thick syrup (see video). Remove from stove.","duration":4,"images":[],"step":5},{"description":"Chicken Filling","images":[],"step":6},{"title":"Coat chicken","description":"Drizzle 1 tbsp oil over chicken, mix to coat. Sprinkle with Seasoning, toss to coat.","images":[],"step":7},{"title":"Cook chicken","description":"Heat remaining 1 tbsp oil in a large skillet over high heat. Add chicken, cook 2 minutes. Turn and cook 1.5 minutes. Remove, rest 2 minutes then chop.","images":[],"step":8},{"title":"Saute onion","description":"In the same skillet, add onion and garlic, cook 1 minute. Add capsicum, cook 2 minutes until onion is translucent.","images":[],"step":9},{"title":"Add everything else","description":"Add refried beans, diced chicken, corn and water. Stir and cook for 2 minutes until reduces slightly. Should be thick and juicy, not watery.","duration":2,"images":[],"step":10},{"description":"Assemble and bake:","images":[],"step":11},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":12},{"title":"Roll","description":"Lay tortilla on work surface. Spread 2/3 cup Filling on lower third, sprinkle with cheese then roll up, finishing with the seam side down (to hold it closed). Repeat to make 8.","images":[],"step":13},{"description":"Smear a scoop of Enchilada Sauce across base of 22 x 33cm /9 x 13\" pan. Place Enchiladas in, pour over remaining Sauce, sprinkle with cheese.","images":[],"step":14},{"title":"Bake 20","description":"25 minutes or until cheese is melted and golden. Serve immediately, sprinkled with coriander!","images":[],"step":15}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-recipes","enchiladas","main-dishes","mexican-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b186d4aa6e30', 'en', 'US', 'Mediterranean Chicken Dinner', 'Recipe video above. Infused with classic Mediterranean flavours of garlic, lemon, oregano and paprika, this is a terrific quick dinner idea. The sauce is the star of this and marinating is optional! I made this with drumsticks but you can make this with bone-in chicken thigh fillets too.', 'https://www.recipetineats.com/tachyon/2015/11/Lemon-Garlic-Chicken-Potato-Bake_7-copy.jpg', 10, 55, 55, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 5.0, "unit": "bag of 2kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}]', '[{"ingredients":["1kg / 2lb bone in, skin on chicken thighs and drumsticks (Note 1)","1/2 cup (125 ml) lemon juice","6 cloves garlic (, minced)","2 tsp Dijon mustard (Optional - Note 2)","2 tbsp honey or 1 tbsp sugar (or maple or other sweetener)","1 tbsp dried oregano","1.5 tsp paprika","1 tbsp olive oil","1/2 tsp EACH salt and pepper"],"purpose":"Marinade / Sauce"},{"ingredients":["5 smallish potatoes (7.5cm/3\" wide) (, quartered (Note 3))","2 red onions (, quartered)","1 cup (250ml) chicken broth/stock (, low sodium)","250g/8oz cherry tomatoes (whole)","1/2 tsp EACH salt and pepper","1 tbsp Olive oil (or oil spray)","Fresh oregano (, for garnish (optional))"],"purpose":"Bake"}]', '[{"description":"Mix Marinade ingredients in a bowl, then add chicken and toss to coat. If time permits, marinate for 24 hours, otherwise proceed to next step.","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"description":"Place potatoes and onion in baking pan, top with chicken. Pour over the chicken stock then marinade from the bowl.","images":[],"step":3},{"description":"Bake for 20 minutes, then remove from oven.","duration":20,"images":[],"step":4},{"description":"Scatter over cherry tomatoes, drizzle everything with 1 tbsp olive oil, sprinkle with salt and pepper. Bake for a further 30 - 35 minutes until chicken is golden and potatoes are cooked.","images":[],"step":5},{"description":"Remove from oven, garnish with fresh oregano if using and serve!","images":[],"step":6}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mediterranean-recipes","most-popular","one-pot-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_23566a2a247a', 'en', 'US', 'Fried Chicken - ultra craggy crispy crust!', 'Recipe video above. This is a fried chicken recipe that''s made using a technique that yields an incredible super crunchy, really craggy crust with loads of nubbly bits that get extra crunchy! Seasoned with a KFC copycat 11 Secret Herbs and Spices - but better than KFC, there''s no trace of soggy bits at all! Flesh is juicy all the way through thanks to a classic Southern buttermilk marinade (read in post why there''s no spices in the marinade!).Serve with French fries and potato with gravy for an epic homemade KFC experience at home.', 'https://www.recipetineats.com/tachyon/2020/01/Fried-Chicken_2.jpg', 15, 30, 45, 10, '[{"id": "ing_bone_in_skin_on_small_thighs_drumsticks_whole_wings_breast", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.281, "unit": "pack of 400g"}}, {"id": "ing_celery", "quantity": {"value": 0.075, "unit": "head"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.45, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_ginger", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.5, "unit": "L"}}]', '[{"ingredients":["1.8 kg/ 3.6lb bone in, skin on small thighs (< 200g/7oz), drumsticks, whole wings, breast (< 200g/7oz) (Note 1)"]},{"ingredients":["1 cup buttermilk (Note 2 for sub)","1 tbsp salt","1 egg"],"purpose":"Buttermilk marinade:"},{"ingredients":["2 1/4 cups flour (, plain / all purpose)","3/4 cup corn flour / cornstarch"],"purpose":"Fried Chicken Breading (Note 9):"},{"ingredients":["3 tsp salt","3/4 tsp celery salt","1.5 tbsp black pepper (Note 2)","1.5 tsp sweet paprika (ie. not hot or smoked)","1/2 tsp cayenne pepper (, optional)","1.5 tsp onion powder","3 tsp garlic powder","1 tsp mustard powder","3/4 tsp ginger powder","1.5 tsp dried thyme","1.5 tsp dried oregano"],"purpose":"KFC 11 Secret Herbs and Spices (Note 9):"},{"ingredients":["1.5 - 2 litres / quarts vegetable oil (or canola or peanut, Note 8 for re-use)"],"purpose":"To fry:"}]', '[{"description":"Buttermilk Marinade Chicken:","images":[],"step":1},{"description":"Mix Marinade in a bowl until salt dissolves.","images":[],"step":2},{"description":"Pour over chicken in ziplock bag, massage to coat chicken. Press out excess air, seal, refrigerate 12 to 24 hours, turning once or twice.","images":[],"step":3},{"description":"Pour chicken and marinade into large bowl.","images":[],"step":4},{"description":"Breading mixture:","images":[],"step":5},{"description":"Whisk together Breading and all KFC Secret Herbs & Spices.","images":[],"step":6},{"description":"Drizzle 4.5 tablespoons of Marinade into flour mixture. Use fingers to rub in so you get lots of pea sized lumpy bits all throughout (this creates extra super crunchy craggy bits).","images":[],"step":7},{"description":"Spread out in a shallow dish or pan (easier to work with).","images":[],"step":8},{"description":"Prepare to cook (work in specified order of steps):","images":[],"step":9},{"title":"Preheat oven to 80°C/175°F and place rack on tray","description":"to keep chicken warm. (Note 3)","images":[],"step":10},{"description":"Add oil to a wide, heavy based pot to a depth of 6 cm / 2.5 \" (my 26cm/10.5\" cast iron pot = 1.75L/quarts oil, Note 4)","images":[],"step":11},{"description":"Heat oil over medium to medium high heat to 180°C/350°F - maintain temp as best you can (Note 5).","images":[],"step":12},{"title":"Cooking order","description":"Start with thighs and drumsticks, wings next and cook breast last. (Note 6).","images":[],"step":13},{"description":"Squidge a piece of chicken in remaining marinade, place in flour.","images":[],"step":14},{"description":"Coat well, pressing very firmly to adhere. Transfer to plate.","images":[],"step":15},{"title":"Coat 2 or 3 more pieces","description":"just for one cooking batch, covering oil surface in single layer. (Note 7)","images":[],"step":16},{"title":"Carefully place chicken in oil","description":"it will bubble energetically but it will not spit.","images":[],"step":17},{"description":"Once chicken is in, oil temperature should drop to 150°C/300°C - adjust heat to target this.","images":[],"step":18},{"title":"DO NOT TOUCH chicken for 2 minutes","description":"to let the crust bond with the chicken skin. After this, you can move them around but oil should be deep enough that you do not need to flip (but you can if you want!).","duration":2,"images":[],"step":19},{"title":"Thighs and drumsticks","description":"cook for 8 minutes (wings for 5 minutes), or until deep golden brown and internal temperature at thickest part is 75°C / 167°F.","duration":8,"images":[],"step":20},{"title":"Breast","description":"fry for 6 minutes or until internal temperature at thickest part is 65°C / 150°F (time depends on size).","duration":6,"images":[],"step":21},{"description":"Place onto rack and keep warm in oven. Repeat with remaining chicken, coating each batch just prior to cooking.","images":[],"step":22},{"description":"Serve immediately!","images":[],"step":23},{"title":"Classic sides","description":"Coleslaw, KFC copycat potato and gravy, steamed or grilled corn, cornbread or soft rolls, fries, potato salad, Southern Baked Beans!","images":[],"step":24}]', '["egg","gluten","mustard","peanuts"]', '["high_protein","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Southern","Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","deep-fried-recipes","iconic-dishes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_96ca396a836b', 'en', 'US', 'Poached Chicken - Foolproof, perfect, AMAZINGLY juicy breast', 'Recipe video above. Forget every other method you''ve used. This recipe GUARANTEES the juiciest chicken breast you''ve ever made in your life. No special equipment, no fancy gadgets. It''s dead easy and foolproof. Use for anything that calls for cooked chicken. Slice it, dice it, shred it, pile onto sandwhiches. HIGH ALTITUDE locations - please see note 4', 'https://www.recipetineats.com/tachyon/2020/01/Poached-Chicken_8.jpg', 10, 25, 35, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["2 chicken breasts (, boneless skinless, 250g/8.5 oz each (Note 1))"]},{"ingredients":["1 lemon (, quartered)","1 bay leaf (, dried or fresh)","2 garlic cloves (, minced)"],"purpose":"Optional flavourings (Note 2)"}]', '[{"description":"Take chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Fill a saucepan with water so the chicken breast will be well submerged with at least 2\" / 5cm of water above it in a single layer (can be snug but do not stack).","images":[],"step":2},{"description":"Add Flavourings, if using (squeeze in lemon juice, add used lemon).","images":[],"step":3},{"description":"Bring water to boil.","images":[],"step":4},{"description":"Place chicken breast in water, place lid on, bring back up to the boil. IMMEDIATELY remove saucepan from stove and set aside for 20 minutes (it''s fine up to 45 min to 1 hr, won''t overcook).","duration":20,"images":[],"step":5},{"description":"Remove chicken from water. Slice and be amazed how perfectly juicy and tender the breast is!! Or chop/shred and use as desired.","images":[],"step":6},{"description":"If reserving for later use, cover loosely to cool then refrigerate whole - see Note 6.","images":[],"step":7}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","good-to-know","low-calorie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49cb8ba13215', 'en', 'US', 'Crispy Herb Baked Chicken with Gravy', 'Recipe video above. This is a fantastic, easy way to make "roast chicken" for loads of people without the fuss of man handling a whole chicken! Quick to prepare, no advance marinating or brining, the idea here is high temp cooking which really seals in the juices, creating crispy skin and meat that''s so juicy, it''s ideal for reheating to serve (which is what we did for a 40 guest Christmas lunch last weekend). Bonus mess-free way of making gravy with outrageously delicious flavour.', 'https://www.recipetineats.com/tachyon/2019/12/Herb-Baked-Chicken-and-Gravy_4-HERO.jpg', 5, 35, 40, 6, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_sage", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_marjoram", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.015, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tbsp vegetable oil (or canola or peanut oil, NOT butter or olive oil, Note 1)"]},{"ingredients":["1.8 kg / 3.6 lb whole chicken, butterflied / spatchcocked","1.8 kg / 3.6 lb large chicken thighs with bone in, skin on AND drumsticks (mix)"],"purpose":"Choose ONE chicken (Note 2):"},{"ingredients":["1 tsp dried oregano","1 tsp dried rosemary","1 tsp dried thyme","1 tsp dried sage (or 1/2 tsp ground sage)","3/4 tsp dried marjoram","1 tsp salt (coarse / kosher salt, OR 1 3/4 tsp sea salt flakes)","1/2 tsp black pepper"],"purpose":"Herb rub (Note 3):"},{"ingredients":["3 tbsp flour","1 1/2 cups (375ml) chicken stock/broth (, low sodium)","3/4 tsp dark soy sauce or gravy browner liquid","Salt and pepper to taste"],"purpose":"Gravy"}]', '[{"description":"Fridge dry skin (optional, for extra crispy skin):","images":[],"step":1},{"description":"Pat chicken skin dry with paper towels. Leave chicken in fridge overnight, uncovered, to dry skin out.","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"description":"Preheat oven to 240°C/ 465°F (220°C fan).","images":[],"step":4},{"description":"Line tray with foil then baking / parchment paper, place rack on tray (Note 4)","images":[],"step":5},{"description":"Mix Rub in a bowl.","images":[],"step":6},{"description":"Pat chicken skin dry with paper towel.","images":[],"step":7},{"description":"Drizzle with oil and rub all over, then sprinkle with Rub. Use hands to rub herbs all over the chicken, getting right into all the cracks and crevices. Place on rack.","images":[],"step":8},{"title":"Thigh + drumsticks","description":"Arrange thigh pieces skin side up, and for drumsticks the side with the most skin up.","images":[],"step":9},{"title":"Butterflied/spatchcocked","description":"Arrange breast side up with tail end of chicken pointed back towards back of oven, neck end closest to door.","images":[],"step":10},{"title":"Thighs + drumsticks","description":"roast for 35 minutes or until internal temperature is 75°C/165°F, or juices run clear when pierced in the middle.","duration":35,"images":[],"step":11},{"title":"Butterflied/spatchcocked","description":"roast for 45 minutes, or until internal temperature is: 66°C / 151°F for the breast AND 75°C/165°F when inserted into the joint between the leg and the thigh.","duration":45,"images":[],"step":12},{"title":"Extra browning","description":"if skin isn''t browned/crispy enough, flick grill/broiler on high for 1 - 3 minutes. CAREFUL - browns super quick!","duration":2,"images":[],"step":13},{"description":"Tent VERY loosely with foil (to preserve crispy skin) for 5 minutes.","duration":5,"images":[],"step":14},{"description":"Scrape every bit of juice, fat and all the brown stuff off the tray into a saucepan.","images":[],"step":15},{"description":"Turn stove onto medium. Once juices are bubbling, add flour and whisk to combine.","images":[],"step":16},{"description":"Slowly pour in broth, whisking as you go.","images":[],"step":17},{"description":"Add soy sauce or gravy browner and pepper.","images":[],"step":18},{"title":"Continue stirring for 3 to 5 minutes","description":"as it becomes steamy, gravy will thicken.","duration":4,"images":[],"step":19},{"description":"Once it becomes a syrupy consistency (see video), remove from stove. Adjust salt to taste right at end, then pour into jug.","images":[],"step":20},{"description":"Carve up the chicken as you would a roast chicken. Cut breast into 3 or 4 pieces. Cut thighs in half along the bone.","images":[],"step":21},{"description":"Pile it all up onto a plate, garnish with parsley or other fresh herbs. Serve with gravy!","images":[],"step":22}]', '["gluten","milk","peanuts","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2a4fa114cd7', 'en', 'US', 'Chicken Brine', 'Recipe video above. BRINING is the secret to the most succulent, tender roast chicken you will EVER have in your life! Adapted from a recipe by Thomas Keller, one of the great masters of the culinary world. The flesh is seasoned all the way through with a hint of the brine flavourings (herbs, lemon, garlic).', 'https://www.recipetineats.com/tachyon/2014/05/Chicken-Brine_3.jpg', 15, 60, 1515, 5, '[{"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.28, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}]', '[{"ingredients":["2 litres / 2 quarts water (, cold tap water)","1/3 cup kosher or cooking salt, NOT table salt (Note 1)","2 lemons (, quartered)","10 sprigs parsley (, fresh )","7 sprigs thyme","2 sprigs rosemary","5 bay leaves, fresh (or 3 dried)","1/4 cup honey","6 garlic cloves, (smashed (Note 3))","1 tbsp black peppercorns"],"purpose":"Brine"},{"ingredients":["1.5 - 2 kg / 3-4lb chicken (, whole)","3 tbsp / 40g butter (, melted)","Salt and pepper to season"],"purpose":"Roast Chicken"}]', '[{"description":"Pour about 1/3 of the water into a large pot (large enough for the brine and submerged chicken) with remaining Brine ingredients. Bring to boil boil 1 minute, stir to dissolve salt.","images":[],"step":1},{"description":"Remove from heat, pour in remaining water. Cool completely before using (I cool about 30 min then refrigerate 1 1/2 hours). DO NOT put chicken in before full cool, this is a health hazard (Note 4).","images":[],"step":2},{"description":"Flip chicken upside down (so legs and breast are on underside. Submerge chicken in brine, cover and refrigerate for 12 - 24 hours (Note 5). Don''t worry if underside of chicken doesn''t stay under water - the the breast side is, that is what matters.","images":[],"step":3},{"description":"Roasting Brined Chicken:","images":[],"step":4},{"description":"Remove chicken from brine and pat dry to remove excess moisture.","images":[],"step":5},{"description":"Tie legs with string (if desired), tuck wings under. Drizzle/brush with most of the butter all over, including underside (butter will firm up on contact).","images":[],"step":6},{"description":"Sprinkle with pepper and the TINIEST pinch of salt, place chicken on a rack in a heavy based roasting tray. Set aside for 20 minutes.","duration":20,"images":[],"step":7},{"description":"Preheat fan forced oven to 220°C/430°F.","images":[],"step":8},{"description":"Turn down the oven to 180°C/350°F, then roast chicken for 50 minutes to 1 hour (Note 7) or until the internal temperature at the joint between the leg and thigh is 75°C/165°F, or until juices run clear.","duration":50,"images":[],"step":9},{"description":"Check at 45 minutes, rotate the pan if not browning evenly, and brush top with remaining melted butter.","images":[],"step":10},{"description":"Remove chicken from the roasting tray, cover loosely with foil and rest for 10 to 15 minutes.","duration":12.5,"images":[],"step":11},{"description":"Chicken is so juicy, it needs little more than a tiny drizzle of the juices in the pan (go easy, it''s salty). Otherwise, make a gravy while the chicken is resting - see Note 8.","images":[],"step":12}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","good-to-know","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_88d0e49e9d93', 'en', 'US', 'Sicilian Chicken Spaghetti', 'Recipe video above. A quick tomato chicken spaghetti with olives, artichokes and a kick of spice if you so choose! Very little prep - nothing to chop except garlic!', 'https://www.recipetineats.com/tachyon/2019/09/Sicilian-Chicken-Pasta_9.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.64, "unit": "pack of 500g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_black_olives", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_artichokes_drained", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.009, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["320g / 11oz spaghetti (or other long pasta)","2 chicken breasts (, each halved horizontally to form 2 thin steaks)","2 tbsp olive oil","Salt and pepper","3 garlic cloves (, minced)","1/2 cup (125 ml) white wine (Note 1)","800g / 28oz can crushed tomato","1/2 cup (125 ml) water (about 1/3 empty tomato can)","1 cup (100g) sliced black olives (Note 2)","170g / 6 oz artichokes (marinated in can or jar), drained (Note 2)","1/2 - 1 tsp red pepper flakes (spiciness - adjust to taste!)","1/2 tsp salt and pepper (, each)","1 cup basil leaves (, optional (or sub baby spinach))"]},{"ingredients":["Parmesan cheese (, freshly grated)"],"purpose":"Serving"}]', '[{"description":"Cook pasta in a large pot of salted boiling water per packet directions, MINUS 1 minute. Drain. (Do this while sauce is simmering)","images":[],"step":1},{"title":"Cook chicken","description":"Sprinkle both sides of chicken with salt and pepper. Heat 1 tbsp oil in a large skillet over high heat. Sear chicken 1 1/2 minutes on each side until golden, then remove from skillet. Shred while sauce is simmering.","images":[],"step":2},{"description":"Add remaining 1 tbsp oil. Add garlic and sauté for 15 seconds.","duration":0.25,"images":[],"step":3},{"description":"Add wine and let it simmer rapidly for 1 minute, stirring to dissolve brown bits on bottom of skillet into the wine, until mostly evaporated.","duration":1,"images":[],"step":4},{"description":"Add tomato, water, olives, artichoke, red pepper flakes, salt and pepper. Stir, simmer on medium for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Stir shredded chicken into sauce.","images":[],"step":6},{"description":"Add pasta into sauce, still on the stove. Toss well for 1 minute or until sauce reduces more and is clinging to pasta strands, rather than pooled in the skillet.","duration":1,"images":[],"step":7},{"description":"Just before serving, toss through fresh basil.","images":[],"step":8},{"description":"Serve immediately with parmesan!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","italian-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c91eff732ca4', 'en', 'US', 'White Chicken Lasagna', 'Recipe video above. Tender shredded chicken and golden, garlicky mushrooms smothered in a cheesy Alfredo sauce, layered up with lasagna sheets. It''s a WHITE chicken lasagna - and it''s amazing!', 'https://www.recipetineats.com/tachyon/2019/08/White-Chicken-Lasagna_2.jpg', 15, 75, 90, 8, '[{"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_vegeta", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_sheets_lasagna", "quantity": {"value": 375.0, "unit": "pack"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}]', '[{"ingredients":["1 kg/ 2lb chicken breast ( or boneless skinless thigh)","4 cups (1L) milk (, any fat %)","2 cups (500ml) chicken broth (/ stock)","2 bay leaves (, dried)","3 sprigs thyme (or 1 tsp dried thyme)","2 tsp Vegeta (or chicken stock powder/granulated bouillon, Note 1)","1/2 tsp black pepper"],"purpose":"Chicken & semi-homemade stock:"},{"ingredients":["2 tbsp (30g) butter (, separated)","2 tbsp olive oil (, separated)","500g / 1lb mushrooms (, quartered)","2 garlic cloves (, minced)","1/2 tsp salt and pepper (, each)"],"purpose":"Mushrooms:"},{"ingredients":["50g / 4tbsp butter","2 garlic cloves (, minced)","3/4 cup (110g) flour (, plain / all purpose)","2 cups (200g) cheddar cheese (, shredded (Note 2))"],"purpose":"White sauce:"},{"ingredients":["375g (13 oz) lasagna sheets (, fresh (or 250g/8oz dried) (Note 3))","2 cups (200g) mozzarella cheese (, shredded)"],"purpose":"Lasagna:"}]', '[{"description":"Place milk, broth and stock powder in a large saucepan. Bring to a very gentle simmer over medium heat, add chicken, pepper, bay leaves and thyme.","images":[],"step":1},{"description":"Place lid on, simmer gently on medium low for 15 minutes (do not boil, can make milk split).","duration":15,"images":[],"step":2},{"description":"Remove chicken and shred. Cover pot and set poaching liquid aside.","images":[],"step":3},{"description":"Heat half the oil and butter in a very large, deep skillet over high heat (or use large pot). Add half the mushrooms with half the garlic, salt and pepper.","images":[],"step":4},{"description":"Cook for 5 minutes, stirring leisurely, until golden. Transfer to bowl and repeat with remaining mushrooms.","duration":5,"images":[],"step":5},{"description":"Lower heat down to medium.","images":[],"step":6},{"description":"Melt butter in skillet, then add garlic. Stir until golden.","images":[],"step":7},{"description":"Add flour. Stir constantly for 1 minute.","duration":1,"images":[],"step":8},{"description":"Gradually pour in 2 cups of reserved poaching liquid while stirring constantly, it should turn into a thick paste.","images":[],"step":9},{"description":"Mix in another cup of liquid, then add remaining liquid and stir well to dissolve. Use whisk if necessary to make lump free.","images":[],"step":10},{"description":"Stir constantly for 1 to 2 minutes until it thickens - you should be able to draw a path across a spoon (see video).","duration":1.5,"images":[],"step":11},{"description":"Remove from heat, stir in cheese until melted. Taste and add more salt & peppers, if needed.","images":[],"step":12},{"description":"REMOVE 2 1/2 cups (625ml) of sauce (save for topping). Then stir in chicken and mushrooms into remaining sauce.","images":[],"step":13},{"description":"Assemble & Bake:","images":[],"step":14},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":15},{"description":"Smear some sauce on the base of a 23 x 33 cm / 9 x 13\" baking dish. Cover base with lasagna sheets.","images":[],"step":16},{"description":"Top with half chicken mixture, then lasagna sheets, remaining chicken mixture then more lasagna sheets.","images":[],"step":17},{"description":"Pour over reserved White Sauce, sprinkle with mozzarella. Cover loosely with foil or use upside down baking tray (ensure it''s not touching cheese).","images":[],"step":18},{"description":"Bake for 25 minutes. Remove foil, bake further 10 minutes until golden and bubbly.","duration":25,"images":[],"step":19},{"description":"Stand 10 minutes, garnish with parsley if desired then cut to serve!","images":[],"step":20}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","iconic-dishes","main-dishes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0298973ad088', 'en', 'US', 'Chicken with Creamy Sun Dried Tomato Sauce', 'Recipe video above. Dinner on the table in 20 minutes! The sauce is ridiculously addictive - I''m tempted to double it!', 'https://www.recipetineats.com/tachyon/2015/07/Chicken-with-Creamy-Sun-Dried-Tomato-Sauce_2.jpg', 10, 10, 20, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["750g / 1.5lb chicken thighs OR chicken breast (, skinless and boneless)","1/2 tsp salt","Black pepper","1/2 cup sun dried tomatoes (, strips, drained of oil (Note 1))","2 tbsp oil from sun dried tomatoes jar (Note 1)","2 garlic cloves (, minced)","1/2 cup (125 ml) white wine (sub chicken broth)","3/4 cup (185 ml) chicken broth/stock (, low sodium)","3/4 cup (185 ml) thickened / heavy cream","1/3 cup (30g) parmesan, very finely shredded (Note 2)","2 tsp Dijon mustard (Note 3)","1 cup basil leaves (, packed (optional))"]}]', '[{"title":"Breast","description":"Cut chicken in half horiztonally to form 2 thin steaks.","images":[],"step":1},{"description":"Sprinkle chicken with salt and pepper. Heat oil from sun dried tomat jar in a large skillet over high heat.","images":[],"step":2},{"description":"Add the chicken and cook until golden brown on both sides - 6 minutes total for thigh or 4 minutes for breast. Remove onto a plate, keep warm.","images":[],"step":3},{"description":"Add the garlic and cook for 15 seconds until light golden.","duration":0.25,"images":[],"step":4},{"description":"Add wine. Bring to simmer and scrape the bottom of the skillet to mix all the brown bits into the wine.","images":[],"step":5},{"description":"Let the wine simmer for 1 minute or so until the smell of alcohol is gone which means it has evaporated.","duration":1,"images":[],"step":6},{"description":"Mix in mustard, then add the chicken broth, cream, parmesan and sun dried tomatoes.","images":[],"step":7},{"description":"Bring to simmer, then reduce heat to medium and simmer for 2 to 3 minutes until thickened. Stir regularly to dissolve parmesan cheese.","duration":2.5,"images":[],"step":8},{"description":"Taste sauce and add more salt and pepper if needed.","images":[],"step":9},{"description":"Stir through basil leaves, then return chicken into pan. Spoon sauce over and simmer 1 minute.","images":[],"step":10},{"description":"Serve immediately! Great served over mashed potato, Creamy Mashed Cauliflower or pasta. Or serve with bread on the side to mop up sauce!","images":[],"step":11}]', '["milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1383e8914ce8', 'en', 'US', 'Chicken Nachos', 'Recipe video above. Crispy chips loaded with juicy Mexican shredded chicken, plenty of melted cheese and toppings of choice. Your new favourite way with nachos! This chicken is a terrific all-purpose Mexican chicken, especially great in Tacos.', 'https://www.recipetineats.com/tachyon/2019/06/Chicken-Nachos_3.jpg', 15, 10, 25, 4, '[{"id": "ing_tortillas", "quantity": {"value": 31.25, "unit": "pack of 8"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_quick_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 3.0, "unit": "bunch"}}]', '[{"ingredients":["250g / 8 oz tortilla or plain corn chips (Note 1)","Shredded chicken for nachos (, recipe follows)","250g / 8 oz (2.5 cups) shredded cheddar or Monterey Jack cheese (Note 2)","Quick guacamole (, recipe follows)","Toppings: Sour cream, Coriander / cilantro leaves, Jalapeno (, sliced or chopped)"],"purpose":"Nachos"},{"ingredients":["700 g / 1.2 lb chicken thighs or breast (, skinless boneless (Note 3))","1.5 tbsp olive oil","2 tbsp tomato paste","2 tsp sugar","1 cup (250ml) chicken broth, separated (liquid stock)"],"purpose":"Chicken for Nachos"},{"ingredients":["3 tbsp lime juice (Note 4)","1 tbsp olive oil","2 garlic cloves (, minced)","2 tsp EACH garlic powder, onion powder, dried oregano","3 tsp EACH cumin powder, paprika","1/2 tsp cayenne pepper (optional)","1/2 tsp salt and pepper (, each)"],"purpose":"Homemade Nachos Meat Seasoning"},{"ingredients":["2 avocados (, medium)","3 tbsp coriander/cilantro (, roughly chopped)","2 tbsp lime juice (1 large)"],"purpose":"Quick Guacamole"}]', '[{"description":"Chicken for Nachos","images":[],"step":1},{"description":"Place Nachos Seasoning ingredients in a bowl. Add 2 tbsp of the chicken broth and mix to form a loose paste.","images":[],"step":2},{"description":"Add chicken, turn to coat in paste.","images":[],"step":3},{"description":"Heat oil in a large skillet over medium high heat. Cook chicken for 3 minutes on each side (reserve paste left in bowl). Remove chicken into a shallow dish.","duration":3,"images":[],"step":4},{"description":"Return skillet to stove. Add remaining chicken broth, tomato paste, sugar and scrape in any paste left in the bowl. Mix to dissolve, scraping base of pan, and bring to simmer.","images":[],"step":5},{"description":"Meanwhile, shred chicken with forks, or chop (don''t worry if raw inside).","images":[],"step":6},{"description":"Return chicken into sauce, toss and simmer for 3 minutes until sauce reduces down to a thick sauce. Adjust salt to taste. Keep warm.","duration":3,"images":[],"step":7},{"description":"Quick Guacamole:","images":[],"step":8},{"description":"Place ingredients in a bowl. Use potato masher to mash to desired consistency. Adjust salt and pepper to taste.","images":[],"step":9},{"description":"Preheat oven to 180C/350F.","images":[],"step":10},{"description":"Place half the corn chips slightly overlapping on a tray. Top with half the (warm) chicken and cheese.","images":[],"step":11},{"description":"Top with remaining chips and cheese. Bake 7 minutes or until cheese is melted and bubbly.","images":[],"step":12},{"description":"Garnish with coriander/cilantro and jalapeño. Serve immaterial with quick Guacamole and sour cream.","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","mexican-recipes","nachos-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2810a48f904f', 'en', 'US', 'Jambalaya Recipe (easy)', 'Recipe VIDEO above. Many people consider this to be the world''s best one pot rice meal.... you won''t hear any arguments from me!! Filled with big, punchy New Orleans flavours, a homemade Creole/Cajun spice delivers top notch flavour with consistency results for everyone, no matter where you live in this big wide world. This Jambalaya is started on the stove then finished in the oven - exactly the same outcome as cooking the whole thing on the stove (the traditional way), but far less risk of uneven cooked rice and mushy gluey rice from over stirring. And it''s just easier - entirely hands off time! :)', 'https://www.recipetineats.com/tachyon/2019/06/Jambalaya_0.jpg', 20, 50, 70, 5, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.9, "unit": "pack of 200g"}}, {"id": "ing_sausages", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 187.5, "unit": "pack"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["1 tbsp vegetable oil","180g (6oz) bacon (, preferably SMOKED, chopped)","200g (7oz) andouille or smoked sausage (, sliced 0.5cm / 1/5\" thick (Note 1))","300g (10oz) chicken thigh (, skinless boneless, cut into 2.5cm /1\" pieces)","12 prawns/shrimp (, raw, large, (peeled, with or without tails))","4 garlic cloves (, minced)","1 tbsp (15g) butter","1 onion (, large, cut into 1.5 cm / 0.5\" pieces)","2 celery ribs (, cut into 1.5 cm / 0.5\" pieces)","2 green capsicum / bell pepper (, medium, cut into 1.5 cm / 0.5\" pieces)","1.25 cups long grain rice (, uncooked (Note 2))","2.5 cups (625ml) low-sodium chicken broth / stock (Note 3)","200g (6.5oz) crushed canned tomato","2 tbsp tomato paste","1 cup green onions (, sliced, plus more for serving)"]},{"ingredients":["2 tsp chopped fresh thyme (or 1 tsp dried thyme)","4 tsp sweet paprika","1 tsp garlic powder","1 tsp onion powder","1/2 tsp cayenne powder (adjust spice to taste)","1/2 tsp black pepper","1/2 tsp salt"],"purpose":"Creole Seasoning Mix:"}]', '[{"description":"Preheat oven to 180C/350F (all types).","images":[],"step":1},{"description":"Heat oil in a very large skillet or dutch oven over medium high heat. (Note 4)","images":[],"step":2},{"description":"Add bacon, cook for 30 seconds (to start fat melting), then add sausages. Cook until sausages are golden - about 3 minutes - then remove into bowl.","duration":0.5,"images":[],"step":3},{"description":"Add chicken into the pan and cook until golden (doesn''t need to cook inside), then add to bowl with bacon.","images":[],"step":4},{"description":"Sear prawns in the pan for 1.5 minutes on each side, then transfer to a separate bowl (reserve until later).","images":[],"step":5},{"description":"Add butter, then garlic, onion, celery and capsicum. Cook for 3 to 4 minutes or until slightly softened.","duration":3.5,"images":[],"step":6},{"description":"Add rice, stir to coat grains in oil.","images":[],"step":7},{"description":"Add chicken broth, tomato paste, canned tomato, thyme and Seasoning Mix.","images":[],"step":8},{"description":"Stir well, then add chicken, sausages and bacon (including all liquid).","images":[],"step":9},{"description":"When you see bubbles across most of the surface, stir well once more. Ensure all rice is submerged, cover with lid, and transfer to oven. (See video)","images":[],"step":10},{"description":"Bake 20 minutes. Remove lid and check rice by eating a few grains (careful, very hot!) If the rice is just about done (Note 5 for the correct consistency), go to next step. If rice grains are still firm in the centre, continue to cook, checking rice every 5 mins - most ovens take about 30 mins total cooking (see Note 7).","images":[],"step":11},{"description":"Add prawns/shrimp and green onions, QUICKLY (but gently!) stir through, cover with lid, and return to oven for just 3 minutes (just to heat prawns).","images":[],"step":12},{"description":"Remove from oven (see video for finished consistency), stir gently to fluff, then serve, garnished with more green onions if desired.","images":[],"step":13}]', '["milk","shellfish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Cajun","Louisiana","New Orleans"],"categories":["chicken-recipes","iconic-dishes","one-pot-recipes","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9dbb9e5c6ab2', 'en', 'US', 'Chicken Pasta recipe of your dreams!', 'Recipe VIDEO above. The creamy chicken pasta recipe of your dreams! A creamy chicken Alfredo with sun dried tomato, spinach and bacon, you''ll love how the shredded chicken acts like a mop for the luxurious Alfredo sauce!', 'https://www.recipetineats.com/tachyon/2019/05/Chicken-Alfredo_8.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 70.0, "unit": "bag of 250g"}}, {"id": "ing_tomato", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["300g / 10 oz fettuccine (Note 1)","30g / 2 tbsp butter (, separated)","2 chicken breasts (, cut in half horizontally)","1/2 tsp each salt and pepper","2 garlic cloves (, minced)","1/2 cup (125ml) dry white wine (sub more chicken broth)","1/2 cup (125ml) chicken stock / broth (, low sodium)","1 1/4 cups (315ml) cream (, thickened / heavy (Note 2))","3/4 cup (75g) parmesan (, finely shredded (Note 3))","70g / 2.5oz baby spinach","100 g / 3oz sun dried tomato strips (Note 4)"]},{"ingredients":["120g / 4oz bacon (, cooked and crumbled)","More parmesan","Parsley (, for garnish (optional))"],"purpose":"Serving:"}]', '[{"description":"Cook pasta in a large pot of salted boiling water for time per packet minus 1 1/2 minutes.","images":[],"step":1},{"description":"Just before draining, scoop out a mugful of pasta cooking water. Then drain pasta.","images":[],"step":2},{"description":"Sprinkle both sides of chicken with salt and pepper.","images":[],"step":3},{"description":"Melt half the butter in a large skillet over hig heat.","images":[],"step":4},{"description":"Add chicken and cook for 2 minutes on each side until deep golden.","duration":2,"images":[],"step":5},{"description":"Remove chicken onto plate, rest for a few minutes then shred with 2 forks.","images":[],"step":6},{"description":"Turn down heat to medium high. In the same skillet, add remaining butter and garlic.","images":[],"step":7},{"description":"Cook garlic for 30 seconds until golden, then add wine.","duration":0.5,"images":[],"step":8},{"description":"Simmer rapidly, stirring to scrape the brown bits off the bottom of the pan. Once mostly evaporated, add chicken broth, cream, parmesan and sun dried tomato.","images":[],"step":9},{"title":"Simmer on medium for 3","description":"5 minutes, stirring leisurely, until it reduces and thickens.","duration":4,"images":[],"step":10},{"description":"Essential Tossing:","images":[],"step":11},{"description":"Add spinach, chicken and cooked pasta.","images":[],"step":12},{"title":"Toss for 1 1/2","description":"2 minutes on the stove, until sauce thickens and coats the pasta strands (see VIDEO). Use pasta cooking water if needed if it gets too thick.","images":[],"step":13},{"description":"Serve immediately with parmesan, crumbled bacon and parsley (if desired).","images":[],"step":14}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f1365b686cc7', 'en', 'US', 'Quick Chicken Tacos - WITH sauce!', 'Recipe video above. A 2-in-1 chicken taco filling: shredded chicken AND sauce made in the same pan using the same seasoning mix! Because it''s so juicy and packed with tons of flavour, the toppings can be kept simple and there''s not need to make an extra sauce. No marinating required.', 'https://www.recipetineats.com/tachyon/2019/03/Chicken-Tacos_3.jpg', 15, 10, 25, 12, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["700 g / 1.2 lb chicken thighs (, skinless boneless (or breast))","1.5 tbsp olive oil","2 tbsp tomato paste","2 tsp sugar","1 cup (250ml) chicken broth, separated (liquid stock)"]},{"ingredients":["3 tbsp lime juice (Note 1)","1 tbsp olive oil","2 garlic cloves (, minced)","2 tsp EACH garlic powder, onion powder, dried oregano","3 tsp EACH cumin powder, paprika","1/2 tsp cayenne pepper (adjust spiciness to taste, can skip)","1 tsp salt","1/2 tsp black pepper"],"purpose":"HOMEMADE TACO SEASONING:"},{"ingredients":["Taco shells or tortillas (, warmed per packet directions)","Diced tomato (, onion, avocado, coriander/cilantro leaves)","Shredded lettuce","Shredded cheese","Sour cream"],"purpose":"To serve:"}]', '[{"description":"Place Taco Seasoning ingredients in a bowl. Add 2 tbsp of the chicken broth and mix to form a loose paste.","images":[],"step":1},{"description":"Add chicken, turn to coat.","images":[],"step":2},{"description":"Heat oil in a large skillet over medium high heat. Cook chicken for 3 minutes on each side until lightly seared. (Reserve marinade dregs in bowl)","duration":3,"images":[],"step":3},{"description":"Remove chicken into a shallow dish.","images":[],"step":4},{"description":"Return skillet to stove, reduce to medium. Add remaining chicken broth, tomato paste, sugar and scrape in any marinade left in the bowl. Mix to dissolve, scraping base of pan, and bring to simmer","images":[],"step":5},{"description":"Meanwhile, shred chicken with forks, or chop (don''t worry if raw inside).","images":[],"step":6},{"description":"Return chicken into sauce, toss and simmer for 2 to 3 minutes until sauce reduces to a thin syrup consistency (add water if reduces too fast). Adjust salt to taste.","duration":2.5,"images":[],"step":7},{"description":"Transfer chicken and all sauce to serving bowl.","images":[],"step":8},{"description":"Warm taco shells or tortillas.","images":[],"step":9},{"description":"Stuff with chicken, making sure it''s soaked with the sauce.","images":[],"step":10},{"description":"Top with tomato, avocado, onion, coriander, lettuce and sour cream. Devour!","images":[],"step":11}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","mexican-recipes","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ae28d9c6e414', 'en', 'US', 'Easy Chicken Curry', 'Recipe video above. This is a Western style curry, and it''s the easiest chicken curry I know how to make with the least ingredients possible without sacrificing tastiness! Very mild, not spicy at all (assuming curry powder is mild).', 'https://www.recipetineats.com/tachyon/2019/03/Best-easy-Chicken-Curry_5.jpg', 8, 20, 28, 4, '[{"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.75, "unit": "jar of 50g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.675, "unit": "can of 400ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1.5 tbsp oil (vegetable, canola)","2 garlic cloves (, minced)","2 tsp ginger (, grated)","1/2 onion (, finely chopped)","500g / 1lb chicken thighs, sliced (Note 1)","2.5 tbsp curry powder (Note 2)","270 ml / 1.25 cups coconut milk (, full fat (9 oz) (Note 3))","1.5 cups (375 ml) chicken stock low sodium","1/2 tsp salt","3/4 cup frozen peas","1/4 cup coriander / cilantro leaves (, chopped)"]}]', '[{"description":"Heat oil in a skillet over medium high heat. Cook garlic, ginger and onion for 3 minutes until onion is translucent.","duration":3,"images":[],"step":1},{"description":"Add chicken and cook until it it changes from pink to white.","images":[],"step":2},{"description":"Add curry powder and cook for 2 minutes.","duration":2,"images":[],"step":3},{"description":"Add coconut milk and chicken stock. Stir, lower heat to medium and cook, simmering rapidly, for 10 minutes until sauce reduces and thickens.","duration":10,"images":[],"step":4},{"description":"Add peas and salt. Cook for a further 2 minutes, then taste to see if it needs more salt. Garnish with coriander.","images":[],"step":5},{"description":"Serve over rice, noodles or mashed potato!","images":[],"step":6}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-recipes","curry-recipes","dietary","dinner-tonight","gluten-free-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_434fc8348836', 'en', 'US', 'Oven Baked Chicken Breast', 'Recipe VIDEO above. My tips for a truly juicy, Oven Baked Chicken Breast: a touch of brown sugar in the seasoning which makes the chicken sweat while it bakes so it creates a semi "sauce", and cooking fast on a high temp! Go by the colour of the crust to know when it''s cooked through.', 'https://www.recipetineats.com/tachyon/2018/05/Oven-Baked-Chicken-Breast_-with-Garlic-Butter-Kale-Rice.jpg', 5, 18, 23, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 chicken breasts (, 150 - 180g / 5 - 6 oz each (Note 1))","2 tsp olive oil"]},{"ingredients":["1 1/2 tbsp brown sugar","1 tsp paprika","1 tsp dried oregano or thyme (, or other herb of choice)","1/4 tsp garlic powder","1/2 tsp each salt and pepper"],"purpose":"Seasoning:"},{"ingredients":["Finely chopped parsley"],"purpose":"Garnish, optional:"}]', '[{"description":"Preheat oven to 425°F/220°C (200°C fan).","images":[],"step":1},{"description":"Pound chicken to 1.5cm / 0.6\" at the thickest part - using a rolling pin, meat mallet or even your fist (key tip for even cooking + tender chicken).","images":[],"step":2},{"description":"Mix Seasoning.","images":[],"step":3},{"description":"Line tray with foil and baking / parchment paper. Place chicken upside down on tray. Drizzle chicken with about 1 tsp oil. Rub over with fingers. Sprinkle with Seasoning.","images":[],"step":4},{"description":"Flip chicken. Drizzle with 1 tsp oil, rub with fingers, sprinkle with Seasoning, covering as much of the surface area as you can.","images":[],"step":5},{"description":"Bake 18 minutes, or until surface is golden per photos and video, or internal temperature is 165°F/75°C using a meat thermometer.","images":[],"step":6},{"description":"Remove from oven and immediately transfer chicken to serving plates.","images":[],"step":7},{"title":"Wait 3","description":"5 minutes before serving, garnished with freshly chopped parsley if desired. Pictured with a side of Garlic Butter Rice with Kale.","images":[],"step":8}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","emergency-recipes","gluten-free-recipes","low-calorie-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ee33234a0baa', 'en', 'US', 'Chicken Stew', 'Recipe video above. Slow cooked chicken with ultra tender flesh and outrageous crispy skin smothered in a gravy-like sauce that''s lip smackingly delicious. Carrots, celery, onion and potato make this a filling meal so you won''t need a side - except perhaps some crusty bread to dunk in the sauce! Make this in a large oven proof pot, or see notes if you don''t have one.', 'https://www.recipetineats.com/tachyon/2018/05/Chicken-Stew_5.jpg', 10, 90, 100, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 3000.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 4.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_worscestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 tbsp olive oil","1.5 kg / 3lb bone in, skin on chicken thighs and drumsticks (6 to 8 pieces)","Salt and pepper","2 onions (, halved and cut into wedges)","2 garlic cloves (, minced)","3 large carrots (, cut thick end into 1.5cm / 3/5\" pieces, thin end 2.5cm/1\")","4 celery stalks (, cut into 2cm / 4/5\" chunks)","1/2 cup (125 ml) white wine (or water)","3 tbsp (35g) flour","3 cups (750 ml) chicken broth (, low low sodium)","2 tbsp tomato paste","2 tsp Worscestershire sauce","3 sprigs thyme (, or 1 tsp dried thyme (or other herb))","2 bay leaves (dried or fresh)","600 g / 1.2lb baby potatoes (, halved (quarter large ones))"]},{"ingredients":["Fresh thyme or parsley (chopped)","Warm crusty bread"],"purpose":"Serving (optional):"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat oil in a large pot over high heat. Brown chicken on both sides until light golden, sprinkling with salt and pepper. Remove from pot. (Do in 2 batches if pot not big enough).","images":[],"step":2},{"description":"If there''s too much oil in the pot, discard some. Add onion and garlic. Cook for 2 minutes until onion is translucent.","duration":2,"images":[],"step":3},{"description":"Add carrots and celery, cook for 1 minute.","duration":1,"images":[],"step":4},{"description":"Add wine. Stir, scraping the bottom of the pan to dissolve the brown bits into the liquid. Cook for 1 minute until liquid is mostly gone.","duration":1,"images":[],"step":5},{"description":"Sprinkle flour across surface, stir.","images":[],"step":6},{"description":"Add broth, tomato paste, Worcestershire sauce, thyme and bay leaves. Stir to dissolve tomato paste.","images":[],"step":7},{"description":"Place chicken on top, keeping the skin above the liquid level as much as you can.","images":[],"step":8},{"description":"Bring to simmer then cover. Bake for 45 minutes.","duration":45,"images":[],"step":9},{"description":"Remove from oven, remove lid. Add potatoes, pushing them into the liquid and rearranging chicken so they sit on top (for lovely crispy skin).","images":[],"step":10},{"description":"Return to oven without the lid for a further 40 minutes until the chicken skin is deep golden and super crispy, the potatoes are soft and the sauce is thickened.","images":[],"step":11},{"description":"Taste sauce and adjust salt and pepper to taste.","images":[],"step":12},{"description":"Serve with warm crusty bread on the side to dunk in the sauce - or go all the way with Garlic Bread! Optional: garnish with extra fresh thyme leaves or parsley.","images":[],"step":13}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cb93471958e8', 'en', 'US', 'Honey Mustard Baked Chicken Drumsticks', 'Recipe video above. A terrifically easy baked chicken drumsticks with a magical 4 ingredient Honey Mustard sauce. Plus, option to add crispy smashed potatoes for an effortless dinner on one tray!', 'https://www.recipetineats.com/tachyon/2018/04/Honey-Mustard-Baked-Chicken-Drumsticks-with-Crispy-Smashed-Potatoes_0.jpg', 11, 60, 71, 4, '[{"id": "ing_potato", "quantity": {"value": 4.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_broccoli", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["4 x 150g/5oz potatoes (Note 1)","2 tbsp / 30 g olive oil or melted butter"],"purpose":"Smashed Potatoes (optional):"},{"ingredients":["8 chicken legs (about 1 kg / 2 lb) (Note 2)","2 tsp olive oil"],"purpose":"Chicken:"},{"ingredients":["2 tbsp Dijon mustard (Note 3)","1 tbsp wholegrain mustard (or use more Dijon)","1/4 cup honey","1 garlic clove (, minced)","1 tsp cornflour/cornstarch (Note 4)","Pinch of salt and pepper"],"purpose":"Sauce:"},{"ingredients":["Fresh thyme leaves or chopped parsley","Steamed broccolini"],"purpose":"For serving (optional):"}]', '[{"description":"Smashed Potatoes option:","images":[],"step":1},{"description":"Microwave potatoes for 10 minutes on high or until cooked. (Note 5)","duration":10,"images":[],"step":2},{"description":"Place on one side of tray. Squish using potato masher (Note 6) to about 1.7cm / 2/3\" thickness. Drizzle with oil, sprinkle with salt and pepper.","images":[],"step":3},{"description":"If making smashed potatoes, fold up the edges of the foil the drumsticks are on","images":[],"step":4},{"description":"Sticky Baked Drumsticks:","images":[],"step":5},{"description":"Preheat oven to 180C/350F.","images":[],"step":6},{"description":"Mix Sauce ingredients together with a good pinch of salt and pepper.","images":[],"step":7},{"description":"Line tray with foil, then top with parchment paper.","images":[],"step":8},{"description":"Place drumsticks on paper. If making smashed potatoes, fold up the edges of the foil so the sauce won''t leak into the potatoes (doesn''t need to be high - even 1cm / 2/5\" is enough, video useful).","images":[],"step":9},{"description":"Spoon Sauce over drumsticks. Drizzle chicken with olive oil.","images":[],"step":10},{"description":"Bake for 30 minutes. Turn drumsticks (not potatoes), spoon juices over drumsticks.","duration":30,"images":[],"step":11},{"description":"Bake for a further 20 minutes, turn, spoon over juices. Bake for 10 - 15 minutes until sauce reduces and the drumsticks are golden and sticky.","duration":12.5,"images":[],"step":12},{"description":"Remove from oven. Squidge the drumsticks around in what should now be a syrupy sauce. (Note 7) Serve drumsticks with sauce, with crispy smashed potatoes and steamed broccolini on the side. Sprinkle with fresh thyme leaves if using.","images":[],"step":13}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-drumstick-recipes","chicken-recipes","dinner-tonight","main-dishes","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dc19ad410cb3', 'en', 'US', 'Sticky Baked Chicken Thighs', 'Recipe video above. This is what you make if you''ve got boneless skinless chicken thighs and haven''t planned anything for dinner. You''ve probably got everything required for the glaze - and if you don''t, there''s plenty of sub options. Savoury and sweet, the sauce is great drizzled over everything!', 'https://www.recipetineats.com/tachyon/2019/02/Sticky-Baked-Chicken-Thighs_5.jpg', 5, 25, 30, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.075, "unit": "bottle of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["700g / 1.4lb chicken thighs (, skinless boneless (5-7 pieces), Note 1)"]},{"ingredients":["1/4 cup ketchup","3 tbsp brown sugar (, lightly packed)","1.5 tbsp soy sauce (, all purpose or light (NOT dark))","1 tbsp apple cider vinegar","1 tbsp olive oil","2 tsp Worcestershire Sauce","2 clove garlics (, minced)"],"purpose":"Glaze (Note 2 for subs):"}]', '[{"description":"Preheat oven to 220°C/420°F (200°C fan).","images":[],"step":1},{"title":"Pan","description":"Use a pan large enough to fit the thighs lying flat (not bunched up/folded). Line pan with foil (you''ll thank me later), place thighs in pan.","images":[],"step":2},{"title":"Glaze 1","description":"Mix Glaze ingredients together. Spoon over about 2/3 of the Glaze on the surface of each (not underside), reserve rest.","images":[],"step":3},{"description":"Bake 15 minutes, remove pan.","images":[],"step":4},{"description":"Flick to grill/broiler on high, adjust shelf to be 20cm/8\" from heat source.","images":[],"step":5},{"title":"Glaze 2","description":"Spoon pan juices over chicken. Then spoon/dab remaining Glaze onto chicken.","images":[],"step":6},{"description":"Broil chicken for 8 to 10 minutes until surface is nicely caramelised.","duration":9,"images":[],"step":7},{"title":"Rest","description":"Remove and stand for a few minutes (uncovered) before serving with pan juices.","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dinner-tonight","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fe3ff2c848fd', 'en', 'US', 'Easy Chicken Cordon Bleu', 'Recipe video above. My midweek version of Chicken Cordon Bleu. All the flavour, all the crunch, much faster to make, and it''s better for you because it''s baked! Choose your method for crumbing the chicken - Super Easy or Quick Dredge (see photos for difference). Super Easy coats the top and sides of the chicken, but is faster than the Dredging Method. Served with a gorgeous traditional Dijon Cream Sauce!', 'https://www.recipetineats.com/tachyon/2015/10/Easy-Chicken-Cordon-Bleu-2.jpg', 15, 30, 45, 2, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_ham", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.113, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.113, "unit": "jar of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.225, "unit": "pack of 200g"}}]', '[{"ingredients":["Panko breadcrumbs - 1/2 cup for Super Easy or 1 cup for Quick Dredge","Oil spray"],"purpose":"Breadcrumbs"},{"ingredients":["2 small chicken breasts, (around 6-7oz/180-210g each)","Salt and pepper","4 slices swiss cheese (Note 1)","4 to 6 slices of ham, (about 2.5oz/75g (Note 2))"],"purpose":"Chicken"},{"ingredients":["3 tbsp mayonnaise","1 1/2 tbsp Dijon mustard"],"purpose":"Method 1: Super Easy"},{"ingredients":["1 egg","2 tsp plain flour"],"purpose":"Method 2: Quick Dredge"},{"ingredients":["1 1/2 tbsp butter","1 1/2 tbsp flour","1 1/4 cups milk (Note 3)","2 tbsp Dijon mustard","3 tbsp parmesan cheese, finely grated"],"purpose":"Dijon Cream Sauce (makes 1 cup)"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan).","images":[],"step":1},{"description":"Spread panko breadcrumbs on a baking tray and spray with oil. Bake for 3 minutes or until light golden. Remove and scrape into bowl straight away.","duration":3,"images":[],"step":2},{"description":"Cut a pocket into each chicken breast, as per the photo below.","images":[],"step":3},{"description":"Fold the cheese in half and place 2 pieces inside each pocket. Do the same with the ham. Close the pocket, seal with 2 toothpicks. Sprinkle with salt and pepper.","images":[],"step":4},{"description":"Super Easy Method","images":[],"step":5},{"description":"Mix the mayonnaise, mustard, salt and pepper in a bowl. Spread onto the top and sides of the chicken (not underside).","images":[],"step":6},{"description":"Sprinkle panko over the chicken, using your other hand to press the breadcrumbs onto the side of the chicken. Spray with oil.","images":[],"step":7},{"description":"Quick Dredge Method","images":[],"step":8},{"description":"Whisk egg and flour. Dip chicken into egg mixture, then into the panko breadcrumbs. Transfer to tray, spray with oil.","images":[],"step":9},{"description":"Bake for 25 to 30 minutes, or until golden brown and just cooked through. Remove toothpicks, serve with the Dijon Cream Sauce.","duration":27.5,"images":[],"step":10},{"description":"Dijon Cream Sauce","images":[],"step":11},{"description":"Melt butter over medium heat in a small saucepan. Add flour and cook for 1 minute.","duration":1,"images":[],"step":12},{"description":"Add half the milk and whisk until the flour mixture is blended in.","images":[],"step":13},{"description":"Add remaining milk, mustard and cheese. Cook for 3 minutes, whisking constantly, until thickened. It will thicken as it cools.","duration":3,"images":[],"step":14},{"description":"Remove from heat, add salt and pepper to taste. Serve with chicken.","images":[],"step":15}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French(ish)"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mains","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bc3d0c16ae60', 'en', 'US', 'Roast Chicken', 'RECIPE VIDEO ABOVE. Slathered with a garlic-herb-lemon butter, this roast chicken is juicy on the inside with crispy golden skin on the outside. An all round flavour bomb with the most incredible liquid gold pan juices to use as the sauce! See notes for gravy option and cook times for other chicken sizes.', 'https://www.recipetineats.com/tachyon/2016/05/Roast-Chicken_6a.jpg', 15, 90, 105, 5, '[{"id": "ing_chicken", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_sage", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1.75 - 2 kg / 3.5 - 4lb whole chicken (, patted dry)","Salt and pepper","2 tsp olive oil","1 lemon, quartered","3 rosemary sprigs"]},{"ingredients":["100 g / 1 stick unsalted butter (, melted)","3 garlic cloves (, minced)","1 tbsp sage (, finely chopped (Note 1))","2 tsp rosemary (, finely chopped (Note 1))","1 tbsp parsley (, finely chopped (Note 1))","1/2 tsp each salt and black pepper"],"purpose":"Butter:"},{"ingredients":["1 cup / 250 ml dry white wine (, or low sodium chicken broth)","1 onion (, quartered (Note 2))","1 garlic bulb (, halved horizontally (Note 2))"],"purpose":"Under Chook:"}]', '[{"description":"Take the chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Preheat oven to 220C/450F (standard) or 200C/430F (fan/convection). Put shelf in the middle.","images":[],"step":2},{"description":"Mix together Butter ingredients. Add juice from 2 wedges of lemon.","images":[],"step":3},{"description":"Place chicken in a roasting pan. Use a dessert spoon to loosen skin from chicken (see video). Do the top (the breast) and the drumsticks – not the underside.","images":[],"step":4},{"description":"Prop chicken upright, drizzle butter under skin, using most of the garlic/herb sludge, but saving a bit of butter for the skin (Note 3).","images":[],"step":5},{"description":"Drizzle / smear remaining butter all over surface of the chicken. Squeeze over juice of 2 lemon wedges.","images":[],"step":6},{"description":"Stuff used lemon wedges and rosemary inside chicken.","images":[],"step":7},{"description":"Tie drumstick ends with string and tuck wing tips under the chicken.","images":[],"step":8},{"description":"Sprinkle all over with salt and pepper.","images":[],"step":9},{"description":"Place onion and garlic in the pan, place chicken on top. Pour wine around, drizzle chicken with oil.","images":[],"step":10},{"description":"Transfer to oven. Roast for 10 minutes, then turn oven down to 180C/350F (all oven types). Roast for a further 1 hr 15 minutes, or until the internal temperature is 75C/165F or until juices run clear when pierced at the join between the drumstick and the body. Baste twice (30 min then at 1 hr), spooning pan juices over skin.","duration":10,"images":[],"step":11},{"title":"Rest for 15 minutes","description":"don’t cover, skin becomes wet.","duration":15,"images":[],"step":12},{"description":"Serve with pan juices (see video for how to carve). I discard onion but use the garlic in the pan. See notes for side suggestions & how to use carcass for incredible homemade broth!","images":[],"step":13}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","easter-mains","easter-recipes","gluten-free-recipes","iconic-dishes","main-dishes","roasts","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca72e08ec8df', 'en', 'US', 'Chicken Stroganoff', 'Recipe video above. You love Beef Stroganoff...now try CHICKEN! Golden seared chicken with a creamy mushroom Stroganoff gravy, I like making this with whole chicken thighs so I can brown it nicely which leaves brown bits in the pan that makes an incredible flavour base for the sauce!', 'https://www.recipetineats.com/tachyon/2018/11/Chicken-Stroganoff_8.jpg', 5, 15, 20, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.4, "unit": "tub of 250g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 250.0, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600g / 1.2 lb chicken thighs (4 - 5) (, boneless skinless (or breast or tenderloin, Note 1))","1 tsp garlic powder","Salt and pepper","1 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["1 large onion (, chopped)","300g / 10oz mushrooms (, sliced (not too thin))","40g / 3 tbsp butter","2 tbsp flour (Note 2)","2 cups / 500 ml beef broth/stock (, salt reduced)","1 tbsp Dijon mustard","2/3 cup (150g) sour cream (or yogurt)"],"purpose":"Gravy:"},{"ingredients":["250 - 300 g / 8 - 10 oz pasta or egg noodles of choice (Note 3)","Chopped parsley or chives (, for garnish (optional))"],"purpose":"Serving:"}]', '[{"description":"Sprinkle chicken with garlic powder, salt and pepper on both sides.","images":[],"step":1},{"description":"Heat oil in a large skillet over medium heat. Place chicken in skillet smooth side down.","images":[],"step":2},{"description":"Press down lightly with with spatula. Cook for 4 minutes until golden.","duration":4,"images":[],"step":3},{"description":"Turn and press lightly with spatula. Cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Remove chicken onto a plate.","images":[],"step":5},{"description":"Turn heat up to medium high. Add butter, melt. Then add onions, cook for 1 minute, then add mushrooms.","duration":1,"images":[],"step":6},{"description":"Cook mushrooms until golden. Scrape bottom of fry pan to get all the golden bits off (this is flavour!).","images":[],"step":7},{"description":"Add flour, cook, stirring, for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add half the broth while stirring. Once incorporated, add remaining broth.","images":[],"step":9},{"description":"Stir, then add sour cream and mustard. Stir until incorporated (don''t worry if it looks split, sour cream will \"melt\" as it heats).","images":[],"step":10},{"description":"Bring to simmer ,then reduce heat to medium low. Once it thickens to the consistency of pouring cream (3 minutes), adjust salt and pepper to taste.","images":[],"step":11},{"description":"Add chicken back in (including plate juices). Simmer for 1 minute, then remove from stove.","duration":1,"images":[],"step":12},{"description":"Serve over pasta or egg noodles, sprinkled with parsley or chives if desired.","images":[],"step":13}]', '["egg","gluten","milk","mustard"]', '["high_protein","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mains","mushroom-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fcceea8f8ac8', 'en', 'US', 'Juicy Roast Turkey', 'Recipe video above. This is still the only way I roast a whole turkey - dry brined with a seasoned salt. Start it in a hot oven upside down, then finish in a lower oven right side up. Brush with lots of butter, but only add minced garlic and fresh herbs towards the end else it burns. The turkey flesh is juicy, the skin is crisply golden, it''s simple, practical and foolproof. No buckets of liquid brine! You can even start it while the turkey is still partially frozen - it will brine as it thaws. Dry brined meats also cook faster - a 5kg/10lb turkey takes under 2 hours. Useful, when there''s lots of oven demand!Start this recipe two days before cooking. You can brine up to 3 days, but 4 days doesn''t add anything and I worry about food safety. Use the RECIPE SCALER to change ingredients to the weight of your turkey (click/tap on servings and slide!).', 'https://www.recipetineats.com/tachyon/2018/11/Juicy-Roast-Turkey_Dry-Brined_2.jpg', 20, 120, 140, 10, '[{"id": "ing_whole_turkey", "quantity": {"value": 4.536, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mixed_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 10.0, "unit": "block of 250g"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.5, "unit": "bottle of 750ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["10 lb / 5kg whole turkey (, thawed (plain not pre brined) (Note 1))"]},{"ingredients":["2 1/2 tbsp kosher salt / cooking salt (Note 2)","2 tsp dried thyme (, or other herb of choice)","1 tsp paprika (, sweet or ordinary)","1 tsp garlic powder (optional)","1/2 tsp black pepper"],"purpose":"Dry Brine Salt Rub:"},{"ingredients":["2 heads of garlic (, halved horizontally (ie 4 halves))","1 onion (, halved - skin on is fine (brown, yellow, white))","2 small bunch mixed herbs (, sage, rosemary, thyme, parsley (optional, Note 3))","10 tbsp (150g) unsalted butter (, melted)","1 tbsp (in total) sage, rosemary and thyme (, finely chopped - equal amounts of each (Note 3))","3 garlic cloves (, minced)","1 1/2 cups dry white wine (, or water (Note 4))","Salt & pepper"],"purpose":"For Roasting"},{"ingredients":["4 cups chicken broth / stock (, low sodium)","5 tbsp flour (, plain / all purpose)","Salt and pepper"],"purpose":"Gravy (~ 4 cups/1L)"}]', '[{"description":"Rub turkey with the Salt Rub, wrap mummy-like in cling wrap. Fridge 48 hrs, flipping halfway. Stuff, roast upside down 30min in hot 220°C/425°F (200°C fan) oven, flip, garlic-herb-butter baste, finish roasting in lower oven 165°C/325°F (150°C fan).","images":[],"step":1},{"description":"Dry Brining Preparation","images":[],"step":2},{"title":"Salt Rub","description":"Mix together the Rub ingredients.","images":[],"step":3},{"title":"Prep Turkey","description":"Pat the turkey dry with paper towels, inside and out. Remove giblets or anything else inside the turkey. (Note 5)","images":[],"step":4},{"title":"Sprinkle","description":"Sprinkle 1 teaspoon of the Salt Rub inside the turkey and use you hand to spread it (roughly is fine). Turn the turkey upside down, then rub 1 teaspoon of the Salt Rub on the underside.","images":[],"step":5},{"description":"Turn the turkey upright and rub the remaining Salt Rub on the turkey, using most on the breast - even some under the skin if you can.","images":[],"step":6},{"description":"Wrap turkey mummy-like in lots of cling wrap (works best, I find) or place the turkey in a sealable plastic bag (Note 6).","images":[],"step":7},{"description":"Brining (Note 7):","images":[],"step":8},{"description":"Place turkey upside down in baking pan. Refrigerate 2 days (minimum) up to 3 days (4 days adds nothing, I find).","images":[],"step":9},{"title":"24 hours later","description":"Flip turkey so it''s right side up.","images":[],"step":10},{"title":"24 (to 48 hours) later","description":"unwrap turkey. The skin should be moist but not wet. If wet, pat dry. Leave out for 30 min before roasting.","duration":30,"images":[],"step":11},{"description":"Prepare for roasting:","images":[],"step":12},{"description":"Preheat oven to 220°C/425°F (200°C fan-forced)","images":[],"step":13},{"title":"Prep for roasting","description":"Place the onions and garlic in a roasting pan. Place a roasting rack on top - if you have one (Note 8 for sub).","images":[],"step":14},{"description":"Stuff bunch of herbs + 2 garlic halves + 3 tbsp butter (45g) inside the turkey. Tie drumsticks together with kitchen twine (optional).","images":[],"step":15},{"description":"Place turkey UPSIDE DOWN on the rack. Twist the wings so they are on top - see video. Brush with a bit of melted butter. Sprinkle with a tiny bit of salt and pepper.","images":[],"step":16},{"title":"Wine","description":"Pour wine in roasting pan.","images":[],"step":17},{"description":"Roast for 30 minutes.","duration":30,"images":[],"step":18},{"title":"Flip & brush","description":"Use a tea towel to turn the turkey over so it''s right side up. Brush with butter, sprinkle with a tiny bit of salt and pepper.","images":[],"step":19},{"description":"Turn oven down to 165°C/325°F (150°C fan).","images":[],"step":20},{"description":"Roast turkey 45 minutes.","images":[],"step":21},{"title":"Garlic herb butter","description":"Mix remaining butter with garlic and herbs. Brush turkey generously with butter.","images":[],"step":22},{"description":"Roast turkey for a further 30 minutes or until a) the thermometer that comes with the turkey pops up; or b) a thermometer inserted between the breast and leg reads 165°F/75°C. (Notes 9, 10). Cover loosely with foil if browning too much.","images":[],"step":23},{"title":"Rest","description":"Remove turkey onto serving plate, cover loosely with foil and rest for 30 minutes before transferring to platter for presentation and carving (see in post for styling idea).","duration":30,"images":[],"step":24},{"description":"Serve turkey with gravy and/or Cranberry Sauce.","images":[],"step":25},{"description":"Place roasting pan (with garlic, onion etc still in it) on the stove over medium high heat. Add flour and cook for 2 minutes.","duration":2,"images":[],"step":26},{"description":"Add broth and use a potato masher to mash the onion and garlic into the mixture. Use a wooden spoon to scrap the bottom of the pan. Cook for 3 to 5 minutes or until thickened.","duration":4,"images":[],"step":27},{"description":"Strain into a bowl, pressing down to extract all the flavour out of the onion and garlic. Transfer to gravy boat.","images":[],"step":28}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","dietary","gluten-free-recipes","iconic-dishes","main-dishes","roasts","turkey-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_004c57a252d8', 'en', 'US', 'Chicken Pot Pie', 'Recipe video above. Everybody''s favourite Chicken Pot Pie! A creamy chicken and vegetable filling with a hint of thyme, topped with puff pastry. The smell when this is baking is SO GOOD! Makes 4 large, 6 medium or 1 large pie. Brilliant freezer standby meal.', 'https://www.recipetineats.com/tachyon/2018/10/Chicken-Pot-Pie_2.jpg', 15, 60, 75, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}]', '[{"ingredients":["600 g/1.2lb chicken breast (or boneless thighs)","2 cups milk (, any fat % (Note 1))","1 cup chicken broth (stock)","2 tsp chicken or vegetable stock powder (Note 2)","2 sprigs thyme (, optional)"],"purpose":"Chicken & broth:"},{"ingredients":["1 large onion (, chopped)","2 large carrots ((3 small). chopped)","3 celery ribs (, chopped)","2 garlic cloves (, minced)","50g / 3 tbsp butter","1 tsp dried thyme","1/3 cup white wine (sub more chicken stock)","1/3 cup flour","1/2 cup grated parmesan","1/2 tsp black pepper","1 cup frozen peas (, no need to thaw)","2 sheets puff pastry (enough to cover pots, with drape)","1 egg (, lightly whisked)"],"purpose":"Chicken Pot Pie:"}]', '[{"description":"Place milk, broth and stock powder in a large saucepan. Bring to a very gentle simmer over medium heat, add chicken and thyme.","images":[],"step":1},{"description":"Place lid on, simmer gently on medium low for 15 minutes (do not boil, can make milk split).","duration":15,"images":[],"step":2},{"description":"Remove chicken, shred or dice (don''t worry if inside a bit uncooked). Cover pot and set poaching liquid aside.","images":[],"step":3},{"description":"Chicken Pot Pie:","images":[],"step":4},{"description":"Melt butter in a large pot over medium high heat. Add garlic and onion, cook for 2 minutes. Add thyme, carrot and celery, cook for 3 minutes or until carrot is softened.","duration":2,"images":[],"step":5},{"description":"Add wine. Stir, scraping the bottom of the pot, and cook for 1 1/2 minutes or until wine is mostly evaporated.","images":[],"step":6},{"description":"Add flour and stir for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add about half the reserved poaching liquid and stir until all flour is incorporated - it will be a thick sludge.","images":[],"step":8},{"description":"Add remaining milk broth, parmesan, pepper. Stir.","images":[],"step":9},{"description":"Add chicken and peas, stir.","images":[],"step":10},{"description":"Once mixture is heated (you''ll see steam), cook for 3 minutes to thicken the sauce, stirring regularly. (Note 3)","duration":3,"images":[],"step":11},{"title":"Remove from heat. Spoon into oven proof pots","description":"4 large or 6 small (Note 4). Cool in fridge at least 30 minutes. (Note 5)","images":[],"step":12},{"description":"Assembly & Baking:","images":[],"step":13},{"description":"Meanwhile, remove puff pastry from freezer to partially thaw. Then use a bowl as a guide to cut rounds from the pastry about 2.5cm / 1\" wider (all the way around) than the pots - be generous!","images":[],"step":14},{"description":"Preheat oven to 180C/350F.","images":[],"step":15},{"description":"Brush edge of pots with egg. Top with puff pastry, folding down the edges.","images":[],"step":16},{"description":"Brush pastry with egg. Cut a 2cm / 2/3\" slide in the middle with a small knife.","images":[],"step":17},{"title":"Bake 35","description":"40 minutes until deep golden.","images":[],"step":18},{"description":"Serve immediately!","images":[],"step":19}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2aeecf3c299e', 'en', 'US', 'Greek Chicken', 'Recipe video above. Yogurt is a magical marinade! This chicken is golden on the outside, beautifully tenderised on the inside and infused with terrific garlic-oregano flavours. Serve this with a Greek Salad and flatbread - or see in post for a full Greek Feast menu! Marinade time: Overnight, min 3 hrs.', 'https://www.recipetineats.com/tachyon/2018/09/Greek-Feast_3.jpg', 8, 50, 58, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}]', '[{"ingredients":["1.25 kg / 2.5 lb drumsticks and chicken thighs (, bone in skin on (Note 1))"]},{"ingredients":["6 garlic cloves (, minced (~ 2 tbsp))","2 tbsp white wine vinegar (or red wine or apple cider vinegar)","1/2 cup / 125 ml lemon juice","2 tbsp extra virgin olive oil","3/4 cup Greek yogurt (I use Farmers Union)","1 1/2 tbsp dried oregano","1 tsp salt","1/2 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["Plain Greek yogurt or Tzatziki","Fresh oregano leaves (optional)"],"purpose":"Serving (optional):"}]', '[{"description":"Mix Marinade ingredients in a large bowl.","images":[],"step":1},{"description":"Add chicken and coat well. Marinade for 24 hours (3 hours minimum).","images":[],"step":2},{"description":"Preheat oven to 180C.350F.","images":[],"step":3},{"description":"Line a tray with foil (trust me), place rack on tray (optional).","images":[],"step":4},{"description":"Place chicken on rack (reserve marinade), skin side up. Bake 30 minutes,","images":[],"step":5},{"title":"Remove from oven. Brush with marinade","description":"do not flip.","images":[],"step":6},{"description":"Return to oven for 20 minutes or until golden and a bit crispy. Give it a spray of olive oil just before it''s done if you want an extra crispy, shiny coat.","duration":20,"images":[],"step":7},{"description":"Rest for a few minutes before serving. Juicy and tasty enough to serve plain but extra great with tzatziki or even some plain yogurt.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["chicken-breast-recipes","chicken-recipes","greek-recipes","main-dishes","mediterranean-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
